function debugLogClient(msg) {
  if (window.BIWA_ENABLE_REMOTE_DEBUG === true) {
    try {
      fetch('/api/debug-log', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ message: msg }) }).catch(() => {});
    } catch (e) {}
  }
  console.log(msg);
}

function visualFieldDebugClient(stage, payload) {
  const enabled = window.BIWA_VISUAL_FIELD_DEBUG === true || /(?:^|[?&])debugVisualFields=1(?:&|$)/.test(String(window.location && window.location.search || ''));
  if (!enabled) return;
  try { console.debug('[' + String(stage || 'VISUAL FIELD') + '] ' + JSON.stringify(payload || {})); }
  catch (error) { console.log('[' + String(stage || 'VISUAL FIELD') + '] ' + String(payload || '')); }
}

function visualFieldPerformanceClient(stage, payload) {
  const perf = window.__BIWA_FIELD_PERF__ = window.__BIWA_FIELD_PERF__ || { events: [], actions: {} };
  const entry = { stage: String(stage || 'FIELD'), at: Date.now(), ...(payload || {}) };
  perf.events.push(entry);
  if (perf.events.length > 240) perf.events.splice(0, perf.events.length - 240);
  if (entry.action && entry.visualId) perf.actions[String(entry.visualId) + '::' + String(entry.action)] = entry;
  if (window.BIWA_VISUAL_FIELD_PERF === true) console.debug('[VISUAL FIELD PERF]', entry);
  return entry;
}

