    secondaryColor: style.secondaryColor || '#ef4444',
    showTitle: style.showTitle !== false,
    titleBgColor: style.titleBgColor || '#ffffff',
    titleTextColor: style.titleTextColor || style.textColor || '#0f172a',
    titleFontSize: Number(style.titleFontSize) || 14,
    titleAlign: style.titleAlign || 'left',
    tableDensity: style.tableDensity || 'compact',
    headerBgColor: style.headerBgColor || '#eef4fb',
    footerBgColor: style.footerBgColor || style.headerBgColor || '#eef4fb',
    headerTextColor: style.headerTextColor || '#172033',
    footerTextColor: style.footerTextColor || style.headerTextColor || '#172033',
    headerFontSize: Number(style.headerFontSize) || 12,
    bodyFontSize: Number(style.bodyFontSize) || 12,
    textAlign,
