  setCheckValue('visualShowPercentToggle', style.showPercent);
  setInputValue('visualSecondaryColor', style.secondaryColor);
  setCheckValue('visualShowTitleToggle', style.showTitle);
  setInputValue('visualTitleBgColor', style.titleBgColor);
  setInputValue('visualTitleTextColor', style.titleTextColor);
  setInputValue('visualTitleFontSize', style.titleFontSize);
