function visualTypeDisplayName(visualization) {
  const names = {
    table: 'Tabela', matrix: 'Matriz', bar: 'Barras', stackedbar: 'Barras empilhadas',
    column: 'Colunas', stackedcolumn: 'Colunas empilhadas', line: 'Linha', area: 'Área',
    pie: 'Pizza', donut: 'Rosca', scatter: 'Dispersão', funnel: 'Funil', gauge: 'Medidor',
    card: 'Cartão', kpi: 'KPI', map: 'Mapa', slicer: 'Filtro', textbox: 'Texto', image: 'Imagem'
  };
  const key = String(visualization || '').toLowerCase();
  return names[key] || 'Visual';
}

function selectedReportVisual() {
  if (!state.activeVisualId) return null;
  return state.reportVisuals.find((item) => String(item.id) === String(state.activeVisualId)) || null;
}

function updateVisualContextRibbon(visual) {
  const contextualTab = $('#ribbonTabVisual');
  const measureTab = $('#ribbonTabMeasure');
  const contextTitle = $('#ribbonContextTitle');
  const selected = visual && state.activeVisualId && String(visual.id) === String(state.activeVisualId) ? visual : null;
  if (contextualTab) contextualTab.hidden = !selected;
  if (measureTab) measureTab.hidden = !state.measureEditorOpen;
  if (contextTitle) contextTitle.textContent = state.measureEditorOpen
    ? 'Ferramentas de medida'
    : selected
      ? 'Ferramentas do visual · ' + visualTypeDisplayName(selected.visualization)
      : 'Ferramentas do construtor';
  if (!selected) {
    if ($('#mainRibbon') && $('#mainRibbon').dataset.activeRibbonTab === 'visual') {
      setMainRibbonTab(state.measureEditorOpen ? 'measure' : 'home');
    }
    return;
  }
  const style = normalizeVisualStyle(selected.style);
  setInputValue('ribbonVisualTitleInput', selected.title || '');
  setCheckValue('ribbonVisualShowTitleToggle', style.showTitle);
  setInputValue('ribbonVisualBgColor', style.background);
  setInputValue('ribbonVisualTextColor', style.textColor);
  setInputValue('ribbonVisualAccentColor', style.accentColor);
  setCheckValue('ribbonVisualBorderToggle', style.showBorder);
  setCheckValue('ribbonVisualShadowToggle', style.showShadow);
  const typeLabel = $('#ribbonSelectedVisualType');
  if (typeLabel) typeLabel.textContent = visualTypeDisplayName(selected.visualization);
}

function refreshSelectedVisualAppearance(visual, rerenderContent) {
  const frame = visual && getVisualFrame(visual.id);
  if (!frame) return;
  const style = normalizeVisualStyle(visual.style);
  frame.style.cssText = visualFrameStyle(visual.layout, style);
  frame.classList.toggle('has-border', style.showBorder);
  frame.classList.toggle('no-border', !style.showBorder);
  frame.classList.toggle('has-shadow', style.showShadow);
  frame.classList.toggle('no-shadow', !style.showShadow);
  const isStatic = ['textbox', 'image'].includes(String(visual.visualization || '').toLowerCase());
  frame.classList.toggle('show-title', !isStatic && style.showTitle);
  frame.classList.toggle('hide-title', isStatic || !style.showTitle);
  const title = frame.querySelector('.visual-title-preview');
  if (title) title.textContent = visual.title || '';
  if (rerenderContent && !isStatic && Array.isArray(visual.rows) && visual.rows.length) renderVisualFromCachedRows(visual);
}

function applyRibbonVisualCustomization(event) {
  const visual = selectedReportVisual();
  if (!visual) return;
  const style = normalizeVisualStyle(visual.style);
  const titleInput = $('#ribbonVisualTitleInput');
  visual.title = titleInput ? titleInput.value.trim() : visual.title || '';
  visual.style = normalizeVisualStyle({
    ...style,
    showTitle: $('#ribbonVisualShowTitleToggle') ? $('#ribbonVisualShowTitleToggle').checked : style.showTitle,
    background: ($('#ribbonVisualBgColor') && $('#ribbonVisualBgColor').value) || style.background,
    textColor: ($('#ribbonVisualTextColor') && $('#ribbonVisualTextColor').value) || style.textColor,
    accentColor: ($('#ribbonVisualAccentColor') && $('#ribbonVisualAccentColor').value) || style.accentColor,
    showBorder: $('#ribbonVisualBorderToggle') ? $('#ribbonVisualBorderToggle').checked : style.showBorder,
    showShadow: $('#ribbonVisualShadowToggle') ? $('#ribbonVisualShadowToggle').checked : style.showShadow
  });
  applyVisualStyleControls(visual);
  const rerenderContent = Boolean(event && event.target && event.target.type === 'color');
  refreshSelectedVisualAppearance(visual, rerenderContent);
  updateVisualContextRibbon(visual);
}

function openVisualFormatInsideBuilder() {
  const visual = selectedReportVisual();
  if (!visual) {
    toast('Selecione um visual para personalizar.', 'error');
    return;
  }
  setMainRibbonTab('visual');
  const pane = $('#visualizationsPane');
  if (pane && pane.classList.contains('collapsed')) {
    const collapseButton = pane.querySelector('[data-collapse-pane="visualizationsPane"]');
    if (collapseButton) collapseButton.click();
  }
  collapseVisualFormatCards();
  setVisualPaneMode('format');
}

function setMainRibbonTab(tabName, options = {}) {
  const ribbon = $('#mainRibbon');
  if (!ribbon) return;
  const tabs = Array.from(ribbon.querySelectorAll('[data-ribbon-tab]')).filter((tab) => !tab.hidden);
  const panels = Array.from(ribbon.querySelectorAll('[data-ribbon-panel]'));
  const requested = String(tabName || 'home');
  const selectedTab = tabs.find((tab) => tab.dataset.ribbonTab === requested) || tabs[0];
  if (!selectedTab) return;
  const activeName = selectedTab.dataset.ribbonTab;
  ribbon.dataset.activeRibbonTab = activeName;
  tabs.forEach((tab) => {
    const active = tab === selectedTab;
    tab.classList.toggle('active', active);
    tab.setAttribute('aria-selected', active ? 'true' : 'false');
    tab.tabIndex = active ? 0 : -1;
  });
  panels.forEach((panel) => {
    const active = panel.dataset.ribbonPanel === activeName;
    panel.hidden = !active;
    panel.classList.toggle('active', active);
  });
  if (options.focus) selectedTab.focus();
}

function applyVisualControls(visual) {
  updateRibbonOrganizarVisibility();
  updateVisualContextRibbon(visual);
  if (!visual) {
    state.visualControlsOwnerId = '';
    // Desselecao: limpa badge e icones, mantem os controles
    $$('.visual-icon').forEach((item) => item.classList.remove('active'));
    updateFormatSelectedBadge();
    updateDesignerStatusStrip();
    updateVisualFieldDropZones();
    return;
  }
  state.visualControlsOwnerId = String(visual.id || '');
  recoverTableFieldsFromColumnOrder(visual);
  visual.selectedFields = normalizeSelectedFields(visual.selectedFields);
  // Garante que dimension/value do visual salvo aparecam nos selectedFields
  if (visual.dimension && !visual.selectedFields.some(function(f) { return f.name === visual.dimension; })) {
    var dimCol = (state.builderColumns || []).find(function(item) { return item.name === visual.dimension; });
    visual.selectedFields.push({ name: visual.dimension, table: (dimCol && dimCol.table) || visual.table || '', type: dimCol ? (dimCol.columnType || dimCol.dataType || '') : '', displayName: null, aggregation: null, showValueAs: null });
  }
  if (visual.value && !visual.selectedFields.some(function(f) { return f.name === visual.value; })) {
    var valueMeasure = (state.model && state.model.measures || []).find(function(m) { return m.name === visual.value; });
    var valueCol = valueMeasure ? null : (state.builderColumns || []).find(function(item) { item.name === visual.value; });
    visual.selectedFields.push({ name: visual.value, table: (valueMeasure && valueMeasure.table) || (valueCol && valueCol.table) || visual.table || '', type: valueMeasure ? 'measure' : (valueCol ? (valueCol.columnType || valueCol.dataType || '') : ''), displayName: null, aggregation: null, showValueAs: null });
  }
  if (visual.secondaryValue && !visual.selectedFields.some(function(f) { return f.name === visual.secondaryValue; })) {
    var secMeasure = (state.model && state.model.measures || []).find(function(m) { return m.name === visual.secondaryValue; });
    var secCol = secMeasure ? null : (state.builderColumns || []).find(function(item) { return item.name === visual.secondaryValue; });
    visual.selectedFields.push({ name: visual.secondaryValue, table: (secMeasure && secMeasure.table) || (secCol && secCol.table) || visual.table || '', type: secMeasure ? 'measure' : (secCol ? (secCol.columnType || secCol.dataType || '') : ''), displayName: null, aggregation: null, showValueAs: null });
  }
  const set = (id, value) => { const el = document.getElementById(id); if (el) el.value = value || ''; };
  set('reportViz', visual.visualization || 'table');
  updateVisualFieldLabels();
  set('builderTableSelect', visual.table || (($('#builderTableSelect') && $('#builderTableSelect').value) || ''));
  set('builderDimensionSelect', visual.dimension || '');
  set('builderValueSelect', visual.value || '');
  set('builderSecondaryValueSelect', visual.secondaryValue || '');
  set('builderAggregationSelect', visual.aggregation || 'SUM');
  set('builderOrderSelect', visual.order || 'DESC');
  normalizeVisualBucketsForType(visual);
  renderVisualFilterCards(visual);
  $$('.visual-icon').forEach((item) => item.classList.toggle('active', item.dataset.viz === (visual.visualization || 'table')));
  syncBuilderFieldChecks();
  applyVisualStyleControls(visual);
  updateDesignerStatusStrip();
  updateFormatSelectedBadge();
  const v = String(visual.visualization || '').toLowerCase();
  const cardTextbox = $('#formatCardTextbox');
  const cardImage = $('#formatCardImage');
  const cardMetric = $('#formatCardCard');
  if (cardTextbox) cardTextbox.style.display = v === 'textbox' ? '' : 'none';
  if (cardImage) cardImage.style.display = v === 'image' ? '' : 'none';
  if (cardMetric) cardMetric.style.display = v === 'card' ? '' : 'none';
  var cardTable = $('#formatCardTable');
  var cardColumnRules = $('#formatCardColumnRules');
  var isTableMatrix = v === 'table' || v === 'matrix';
  var cardChart = $('#formatCardChart');
  var isChart = v === 'pie' || v === 'donut' || v === 'funnel';
  var funnelOptions = $('#chartFunnelOptions');
  if (cardTable) cardTable.style.display = isTableMatrix ? '' : 'none';
  if (cardColumnRules) cardColumnRules.style.display = isTableMatrix ? '' : 'none';
  if (cardChart) cardChart.style.display = isChart ? '' : 'none';
  if (funnelOptions) funnelOptions.style.display = v === 'funnel' ? '' : 'none';
  if (v === 'textbox') {
    set('visualTextContent', visual.content || '');
    set('visualTextboxAlign', (visual.style && visual.style.textAlign) || 'left');
    syncAlignmentButtonGroup('visualTextboxAlign');
  }
  if (v === 'image') { set('visualImageSrc', visual.src || ''); set('visualImageFit', visual.fit || 'contain'); }
}

function updateFormatSelectedBadge() {
  const badge = document.getElementById('formatSelectedVisualBadge');
  if (!badge) return;
  if (state.activeVisualId === null) {
    badge.textContent = 'Nenhum';
    return;
  }
  const visual = state.reportVisuals.find((item) => item.id === state.activeVisualId);
  badge.textContent = visual ? (visual.visualization || 'Visual') : 'Nenhum';
}


function renderReportPageVisuals() {
  const page = $('#reportPage');
  if (!page) return;
  disposeEChartsWithin(page);
  ensureReportVisuals();
  page.dataset.theme = state.reportTheme || 'light';
  applyCanvasZoomToDom();
  ensureReportPages();
  renderReportPageTabs();
  updateDesignerStatusStrip();
  function renderNoDataVizBody(visual) {
    const v = String(visual.visualization || '').toLowerCase();
    if (v === 'textbox') return `<div class="textbox-content" data-textbox-id="${escapeHtml(visual.id)}" data-placeholder="Digite seu texto">${visual.content || ''}</div>`;
    if (v === 'image') {
      const src = visual.src || '';
      if (!src) return '<div class="empty-state">Clique para configurar a imagem.</div>';
      return `<div class="image-fit-${visual.fit || 'contain'}"><img src="${escapeHtml(src)}" alt="${escapeHtml(visual.title || 'Imagem')}" draggable="false" /></div>`;
    }
    return '<div class="empty-state">Selecione ou arraste campos do painel Dados para renderizar automaticamente.</div>';
  }
  const pageVisuals = currentPageVisuals();
  page.innerHTML = pageVisuals.length ? pageVisuals.map((visual) => {
    const layout = visual.layout || { x: 32, y: 32, width: 560, height: 360 };
    const active = visual.id === state.activeVisualId;
    const rows = Array.isArray(visual.rows) ? visual.rows : [];
    const style = normalizeVisualStyle(visual.style);
    const v = String(visual.visualization || 'table').toLowerCase();
    const isStatic = v === 'textbox' || v === 'image';
    const rendersConfiguredEmptyStructure = ['table', 'matrix'].includes(v) && normalizeSelectedFields(visual.selectedFields).length > 0;
    const frameClasses = visualFrameClassNames(visual, style, active ? ['selected', 'active-visual'] : []);
    const body = isStatic
      ? renderNoDataVizBody(visual)
      : (rows.length || rendersConfiguredEmptyStructure
        ? ''
        : '<div class="empty-state">Selecione ou arraste campos do painel Dados para renderizar automaticamente.</div>');
    return `
      <div class="visual-frame ${frameClasses}" data-visual-id="${escapeHtml(visual.id)}" data-size="${Math.round(Number(layout.width)||560)} x ${Math.round(Number(layout.height)||360)}" tabindex="0" style="${visualFrameStyle(layout, style)}">
        <span class="visual-move-edge visual-move-edge-top" data-visual-move-edge title="Arrastar visual"></span>
        <span class="visual-move-edge visual-move-edge-right" data-visual-move-edge title="Arrastar visual"></span>
        <span class="visual-move-edge visual-move-edge-bottom" data-visual-move-edge title="Arrastar visual"></span>
        <span class="visual-move-edge visual-move-edge-left" data-visual-move-edge title="Arrastar visual"></span>
        <div class="visual-frame-head">
          <strong class="visual-title-preview">${escapeHtml(visual.title || '')}</strong>
        </div>
        <div class="result visual-content ${isStatic ? 'visual-static-content' : (rows.length || rendersConfiguredEmptyStructure ? '' : 'empty-state')}">${body}</div>
        <button type="button" class="visual-resize-handle visual-resize-handle-nw" data-visual-resize-corner="nw" title="Redimensionar pelo canto superior esquerdo" aria-label="Redimensionar pelo canto superior esquerdo"></button>
        <button type="button" class="visual-resize-handle visual-resize-handle-ne" data-visual-resize-corner="ne" title="Redimensionar pelo canto superior direito" aria-label="Redimensionar pelo canto superior direito"></button>
        <button type="button" class="visual-resize-handle visual-resize-handle-sw" data-visual-resize-corner="sw" title="Redimensionar pelo canto inferior esquerdo" aria-label="Redimensionar pelo canto inferior esquerdo"></button>
        <button type="button" class="visual-resize-handle visual-resize-handle-se" data-visual-resize-corner="se" title="Redimensionar pelo canto inferior direito" aria-label="Redimensionar pelo canto inferior direito"></button>
      </div>`;
  }).join('') : '<div class="report-empty-canvas"><span class="report-empty-canvas-icon">+</span><strong>Página em branco</strong><small>Insira um visual pela aba Inserir ou pelo painel Visualizações.</small></div>';
  pageVisuals.forEach((visual) => {
    const v = String(visual.visualization || 'table').toLowerCase();
    const rows = Array.isArray(visual.rows) ? visual.rows : [];
    const rendersConfiguredEmptyStructure = ['table', 'matrix'].includes(v) && normalizeSelectedFields(visual.selectedFields).length > 0;
    if ((!rows.length && !rendersConfiguredEmptyStructure) || v === 'textbox' || v === 'image') return;
    const frame = Array.from(page.querySelectorAll('.visual-frame')).find((item) => item.dataset.visualId === String(visual.id));
    const content = frame && frame.querySelector('.visual-content');
    if (content) renderViz(content, rows, v, visual);
  });
  setupReportCanvasDesigner(true);
  setupProgressiveVisualTables(page);
}

function renderVisualFromCachedRows(visual) {
  if (!visual) return;
  const frame = getVisualFrame(visual.id);
  const result = frame && frame.querySelector('.visual-content');
  if (!result) return;
  const currentWrap = result.querySelector('.visual-table-wrap');
  const scrollLeft = currentWrap ? currentWrap.scrollLeft : 0;
  const scrollTop = currentWrap ? currentWrap.scrollTop : 0;
  const rows = Array.isArray(visual.rows) ? visual.rows : [];
  const rendersConfiguredEmptyStructure = ['table', 'matrix'].includes(String(visual.visualization || '').toLowerCase())
    && normalizeSelectedFields(visual.selectedFields).length > 0;
  disposeEChartsWithin(result);
  result.className = 'result visual-content' + (rows.length || rendersConfiguredEmptyStructure ? '' : ' empty-state');
  renderViz(result, rows, visual.visualization || 'table', visual);
  const nextWrap = result.querySelector('.visual-table-wrap');
  if (nextWrap) {
    nextWrap.scrollLeft = scrollLeft;
    nextWrap.scrollTop = scrollTop;
    maybeAppendProgressiveVisualTableRows(nextWrap);
  }
}

function reorderRenderedVisualTableColumns(visual) {
  if (!visual || String(visual.visualization || '').toLowerCase() !== 'table') return false;
  const frame = getVisualFrame(visual.id);
  const table = frame && frame.querySelector('.visual-table');
  if (!table) return false;
  const headers = Array.from(table.querySelectorAll('thead tr:first-child > th'));
  const currentOrder = headers.map((header) => String(header.dataset.col || '').trim());
  if (!currentOrder.length) return false;
  const requestedOrder = normalizeSelectedFields(visual.selectedFields).map((field) => field.name);
  const desiredOrder = requestedOrder.filter((column) => currentOrder.includes(column));
  currentOrder.forEach((column) => { if (!desiredOrder.includes(column)) desiredOrder.push(column); });
  if (desiredOrder.length !== currentOrder.length) return false;
  const indexes = desiredOrder.map((column) => currentOrder.indexOf(column));
  const rows = Array.from(table.querySelectorAll('thead tr, tbody tr, tfoot tr'));
  const rowCells = rows.map((row) => Array.from(row.children));
  const colgroup = table.querySelector('colgroup');
  const cols = colgroup ? Array.from(colgroup.children) : [];
  if (colgroup && cols.length === currentOrder.length) {
    indexes.forEach((index) => colgroup.appendChild(cols[index]));
  }
  rows.forEach((row, rowIndex) => {
    const cells = rowCells[rowIndex];
    if (cells.length !== currentOrder.length) return;
    indexes.forEach((index) => row.appendChild(cells[index]));
  });
  const totalCells = Array.from(table.querySelectorAll('tfoot tr:first-child > td'));
  if (totalCells.length) {
    totalCells.forEach((cell) => { if (cell.textContent.trim() === 'Total') cell.textContent = ''; });
    totalCells[0].textContent = 'Total';
  }
  const wrap = table.closest('[data-progressive-table-key]');
  const progressiveContext = wrap ? visualTableProgressiveContexts.get(wrap.dataset.progressiveTableKey || '') : null;
  if (progressiveContext) progressiveContext.columns = desiredOrder.slice();
  return true;
}

function updateActiveVisualFrameSelection(id) {
  const page = $('#reportPage');
  if (!page) return;
  page.querySelectorAll('.visual-frame').forEach(function(frame) {
    const selected = String(frame.dataset.visualId || '') === String(id || '');
    frame.classList.toggle('selected', selected);
    frame.classList.toggle('active-visual', selected);
    frame.setAttribute('aria-selected', selected ? 'true' : 'false');
  });
}

async function setActiveReportVisual(id, options = {}) {
  ensureReportVisuals();
  const visual = state.reportVisuals.find((item) => item.id === id);
  if (!visual) return;
  if (String(state.activeVisualId || '') !== String(id)) {
    syncActiveVisualFromControls();
    invalidateVisualAutoUpdate();
  }
  state.activeVisualId = id;
  if (options.preserveCanvas) updateActiveVisualFrameSelection(id);
  else renderReportPageVisuals();
  applyVisualControls(visual);
  const table = visual.table || ($('#builderTableSelect') && $('#builderTableSelect').value) || '';
  if (table) {
    try { await loadBuilderColumns(table, { expectedVisualId: id, updateVisualControls: false }); } catch (err) { console.error(err); }
    if (state.activeVisualId === id) applyVisualControls(visual);
  }
  if (options.autoRender) scheduleVisualAutoUpdate('select-visual');
}

function addReportVisual(viz = 'table', layout = {}, options = {}) {
  if (state.activeVisualId != null) syncActiveVisualFromControls();
  invalidateVisualAutoUpdate();
  ensureReportPages();
  const offset = currentPageVisuals().length * 26;
  const visual = defaultReportVisual(viz, {
    x: layout.x ?? (32 + offset),
    y: layout.y ?? (32 + offset),
    width: layout.width ?? 560,
    height: layout.height ?? 360
  });
  visual.visualization = viz || 'table';
  visual.pageId = state.activeReportPageId;
  state.reportEditorBlank = false;
  state.reportVisuals.push(visual);
  state.activeVisualId = visual.id;
  renderReportPageVisuals();
  applyVisualControls(visual);
  if (!options.silent) toast('Novo visual criado. Arraste campos para preencher.');
  return visual;
}

function removeReportVisual(id) {
  ensureReportVisuals();
  invalidateVisualAutoUpdate();
  state.reportVisuals = state.reportVisuals.filter((item) => item.id !== id);
  const pageVisuals = currentPageVisuals();
  state.activeVisualId = pageVisuals.length ? pageVisuals[0].id : null;
  if (!state.reportVisuals.length) state.reportEditorBlank = true;
  renderReportPageVisuals();
  applyVisualControls(pageVisuals[0] || null);
  syncBuilderFieldChecks();
  toast('Visual removido.');
}

function isNumericColumn(col) {
  const type = String((col && (col.dataType || col.columnType)) || '').toLowerCase();
  return /(int|decimal|double|float|real|numeric|bigint|smallint|mediumint|tinyint)/.test(type);
}

function safeSqlIdent(name) {
  const value = String(name || '').trim();
  if (!value) throw new Error('Nome SQL vazio.');
  if (/[\0]/.test(value)) throw new Error('Nome inválido para SQL: ' + value);
  return '`' + value.replace(/`/g, '``') + '`';
}

function safeSqlValue(value, operator) {
  const raw = String(value || '');
  const text = operator === 'LIKE' ? '%' + raw + '%' : raw;
  return "'" + text.replace(/'/g, "''") + "'";
}

function builderOptionHtml(columns, selected = '', allowNone = false, noneLabel = 'Sem campo') {
  const items = [];
  if (allowNone) items.push(`<option value="">${escapeHtml(noneLabel)}</option>`);
  for (const col of columns || []) {
    const name = col.name || '';
    items.push(`<option value="${escapeHtml(name)}" ${name === selected ? 'selected' : ''}>${escapeHtml(name)} - ${escapeHtml(displayColumnType(col))}</option>`);
  }
  return items.join('') || '<option value="">Sem colunas</option>';
}

function builderResourceOptionsHtml(selected = '') {
  if (!state.resources.length) return '<option value="">Nenhuma tabela/view encontrada</option>';
  return state.resources.map((item) => `<option value="${escapeHtml(item.name)}" ${item.name === selected ? 'selected' : ''}>${escapeHtml(item.name)}</option>`).join('');
}

function renderBuilderResourceSelect() {
  const el = $('#builderTableSelect');
  if (!el) return;
  if (!state.resources.length) {
    const html = '<option value="">Nenhuma tabela/view encontrada</option>';
    el.innerHTML = html;
    return;
  }
  const previous = el.value || state.selectedTable || '';
  const selected = state.resources.some((item) => item.name === previous) ? previous : state.resources[0].name;
  const html = builderResourceOptionsHtml(selected);
  el.innerHTML = html;
  el.value = selected;
}

async function ensureBuilderDataLoaded() {
  if (isOnlineMode()) return;
  if (!state.resources.length && !state.resourcesLoading) await loadTables();
  renderBuilderResourceSelect();
  const table = $('#builderTableSelect') && $('#builderTableSelect').value;
  if (table) await loadBuilderColumns(table);
}

async function loadBuilderColumns(table, options = {}) {
  if (!table) return [];
  const updateVisualControls = options.updateVisualControls !== false;
  const renderOnlineFilters = options.renderOnlineFilters !== false;
  const selectedAtStart = selectedReportVisual();
  const expectedVisualId = String(options.expectedVisualId || (selectedAtStart && selectedAtStart.id) || '');
  const requestSequence = ++state.builderColumnsSequence;
  const columns = await loadModelColumns(table);
  if (requestSequence !== state.builderColumnsSequence) return columns || [];
  if (expectedVisualId && String(state.activeVisualId || '') !== expectedVisualId) return columns || [];
  state.builderColumns = (columns || []).map(function(col) {
    return Object.assign({}, col, { table: col.table || table });
  });
  renderBuilderFieldList();
  if (updateVisualControls) {
    renderBuilderColumnSelects();
  } else {
    syncBuilderFieldChecks();
  }
  if (renderOnlineFilters && onlineFilterDesignerIsOpen()) {
    renderOnlineFilterBuilder().catch((err) => toast(err.message, 'error'));
  }
  return state.builderColumns;
}


function visualFieldInstanceHash(value) {
  var text = String(value || '');
  var hash = 2166136261;
  for (var i = 0; i < text.length; i += 1) {
    hash ^= text.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(36);
}

function newVisualFieldInstanceId() {
  if (window.crypto && typeof window.crypto.randomUUID === 'function') return 'field_' + window.crypto.randomUUID();
  return 'field_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 10);
}

function normalizeVisualFieldFormat(format) {
  if (!format || typeof format !== 'object' || Array.isArray(format)) return null;
  var type = String(format.type || '').toLowerCase();
  if (!['number', 'decimal', 'integer', 'currency', 'percentage'].includes(type)) type = '';
  var places = Number(format.decimalPlaces);
  var decimalPlaces = Number.isFinite(places) ? Math.max(0, Math.min(10, Math.round(places))) : null;
  if (!type && decimalPlaces === null) return null;
  return {
    type: type || 'decimal',
    decimalPlaces: decimalPlaces,
    prefix: String(format.prefix || '').slice(0, 24),
    suffix: String(format.suffix || '').slice(0, 24),
    percentOfTotal: Boolean(format.percentOfTotal)
  };
}

function normalizeVisualFieldWidth(value) {
  if (value === null || value === undefined || String(value).trim() === '') return null;
  const numericWidth = Number(value);
  return Number.isFinite(numericWidth) ? Math.max(32, Math.min(1200, Math.round(numericWidth))) : null;
}

function visualStyleColumnWidth(style, key) {
  const name = String(key || '').trim();
  if (!name || !style || !style.columnWidths) return null;
  return normalizeVisualFieldWidth(style.columnWidths[name]);
}

function visualUsesLegacyMinimumWidthBug(fields, style) {
  const list = Array.isArray(fields) ? fields : [];
  if (list.length < 2 || !list.every(function(field) { return normalizeVisualFieldWidth(field && field.width) === 32; })) return false;
  return Object.values(style && style.columnWidths || {}).some(function(width) {
    const normalized = normalizeVisualFieldWidth(width);
    return normalized !== null && normalized !== 32;
  });
}

function resolvedVisualFieldWidth(field, style, renderKey, legacyMinimumWidthBug) {
  const fieldWidth = normalizeVisualFieldWidth(field && field.width);
  const instanceWidth = visualStyleColumnWidth(style, visualFieldRef(field));
  const renderWidth = visualStyleColumnWidth(style, renderKey);
  const sourceWidth = visualStyleColumnWidth(style, field && field.name);
  if (instanceWidth !== null) return instanceWidth;
  const savedReportWidth = renderWidth ?? sourceWidth;
  if (fieldWidth === 32 && savedReportWidth !== null && savedReportWidth !== 32) return savedReportWidth;
  if (legacyMinimumWidthBug) return savedReportWidth ?? fieldWidth;
  return fieldWidth ?? savedReportWidth;
}

function visualFieldNeedsLegacyWidthRecovery(field, style, renderKey) {
  const fieldWidth = normalizeVisualFieldWidth(field && field.width);
  const instanceWidth = visualStyleColumnWidth(style, visualFieldRef(field));
  const savedReportWidth = visualStyleColumnWidth(style, renderKey) ?? visualStyleColumnWidth(style, field && field.name);
  return fieldWidth === 32 && instanceWidth === null && savedReportWidth !== null && savedReportWidth !== 32;
}

function visualFieldRef(field) {
  return String(field && field.instanceId || field && field.name || '').trim();
}

function selectedVisualFieldByRef(fields, ref) {
  var list = normalizeSelectedFields(fields);
  var key = String(ref || '').trim();
  return list.find(function(field) { return visualFieldRef(field) === key; })
    || list.find(function(field) { return field.name === key; })
    || null;
}

function normalizeSelectedFields(fields) {
  const seen = new Set();
  const occurrences = new Map();
  const out = [];
  (Array.isArray(fields) ? fields : []).forEach((item) => {
    const name = String(typeof item === 'string' ? item : (item && item.name) || '').trim();
    if (!name) return;
    const table = String((item && item.table) || '').trim();
    const type = String((item && item.type) || '').trim();
    const displayName = String((item && item.displayName) || '').trim();
    const aggregation = String((item && item.aggregation) || '').trim();
    const showValueAs = String((item && item.showValueAs) || '').trim();
    const occurrenceKey = table + '::' + name;
    const occurrence = occurrences.get(occurrenceKey) || 0;
    occurrences.set(occurrenceKey, occurrence + 1);
    const suppliedInstanceId = String(item && item.instanceId || '').replace(/[^a-zA-Z0-9_.:-]/g, '').slice(0, 96);
    const instanceId = suppliedInstanceId || ('field_' + visualFieldInstanceHash(occurrenceKey + '::' + occurrence));
    if (seen.has(instanceId)) return;
    const alignmentValue = String(item && item.alignment || '').toLowerCase();
    const alignment = ['left', 'center', 'right'].includes(alignmentValue) ? alignmentValue : null;
    const width = normalizeVisualFieldWidth(item && item.width);
    seen.add(instanceId);
    out.push({
      instanceId,
      measureId: String(item && item.measureId || (type.toLowerCase() === 'measure' ? name : '')).trim() || null,
      name,
      table,
      type,
      displayName: displayName || null,
      aggregation: aggregation || null,
      showValueAs: showValueAs || null,
      format: normalizeVisualFieldFormat(item && item.format),
      alignment,
      width
    });
  });
  return out.slice(0, 60);
}

function visualOrderedSelectedFields(visual) {
  const fields = normalizeSelectedFields(visual && visual.selectedFields);
  const requestedOrder = Array.isArray(visual && visual.style && visual.style.columnOrder)
    ? visual.style.columnOrder.map((name) => String(name || '').trim()).filter(Boolean)
    : [];
  if (!requestedOrder.length) return fields;
  const remaining = fields.slice();
  const ordered = [];
  requestedOrder.forEach((ref) => {
    const index = remaining.findIndex((field) => visualFieldRef(field) === ref || field.name === ref);
    if (index >= 0) ordered.push(remaining.splice(index, 1)[0]);
  });
  ordered.push.apply(ordered, remaining);
  return ordered;
}

function recoverTableFieldsFromColumnOrder(visual) {
  if (!visual || !['table', 'matrix'].includes(String(visual.visualization || '').toLowerCase())) return visual;
  const requestedOrder = Array.isArray(visual.style && visual.style.columnOrder)
    ? visual.style.columnOrder.map((name) => String(name || '').trim()).filter(Boolean)
    : [];
  if (!requestedOrder.length) return visual;
  const fields = normalizeSelectedFields(visual.selectedFields);
  const recoveredNames = new Set();
  const measures = new Map((state.model && state.model.measures || []).map((measure) => [String(measure.name || ''), measure]));
  const remaining = fields.slice();
  const recovered = [];
  requestedOrder.forEach((ref) => {
    let existingIndex = remaining.findIndex((field) => visualFieldRef(field) === ref);
    // Relatorios anteriores guardavam nomes em columnOrder. Depois da adocao
    // de instanceId, alguns arquivos ficaram temporariamente com ambos. O nome
    // legado e apenas um alias da instancia ja recuperada e nunca deve criar
    // outra coluna ao carregar ou ao perder a selecao do visual.
    if (existingIndex < 0 && !recoveredNames.has(ref)) {
      existingIndex = remaining.findIndex((field) => field.name === ref);
    }
    if (existingIndex >= 0) {
      const existing = remaining.splice(existingIndex, 1)[0];
      recovered.push(existing);
      recoveredNames.add(existing.name);
      return;
    }
    if (recoveredNames.has(ref)) return;
    const measure = measures.get(ref);
    const column = (state.builderColumns || []).find((item) => item.name === ref);
    if (!measure && !column) return;
    const recoveredField = normalizeSelectedFields([{
      instanceId: newVisualFieldInstanceId(),
      measureId: measure ? ref : null,
      name: ref,
      table: String((measure && measure.table) || (column && column.table) || visual.table || '').trim(),
      type: measure ? 'measure' : String((column && (column.columnType || column.dataType)) || '').trim(),
      displayName: null,
      aggregation: null,
      showValueAs: null
    }])[0];
    recovered.push(recoveredField);
    recoveredNames.add(recoveredField.name);
  });
  recovered.push.apply(recovered, remaining);
  visual.selectedFields = recovered;
  visual.style = normalizeVisualStyle(visual.style);
  visual.style.columnOrder = recovered.map(visualFieldRef);
  return visual;
}

function normalizeVisualBucketNames(fields) {
  const seen = new Set();
  return (Array.isArray(fields) ? fields : [])
    .map((item) => String(typeof item === 'string' ? item : (item && item.name) || '').trim())
    .filter((name) => {
      if (!name || seen.has(name)) return false;
      seen.add(name);
      return true;
    })
    .slice(0, 60);
}

function normalizeMatrixVisualBuckets(visual) {
  if (!visual) return null;
  let fields = normalizeSelectedFields(visual.selectedFields);
  const fieldByRef = new Map();
  fields.forEach(function(field) {
    fieldByRef.set(visualFieldRef(field), field);
    if (!fieldByRef.has(field.name)) fieldByRef.set(field.name, field);
  });
  const explicitRows = normalizeVisualBucketNames(visual.matrixRows);
  const explicitColumns = normalizeVisualBucketNames(visual.matrixColumns);
  const explicitValues = normalizeVisualBucketNames(visual.matrixValues);
  const hasExplicitBuckets = explicitRows.length || explicitColumns.length || explicitValues.length;
  let rows = explicitRows;
  let columns = explicitColumns;
  let values = explicitValues;

  if (!hasExplicitBuckets && fields.length) {
    const legacyValue = String(visual.value || '').trim();
    values = fields
      .filter((field) => field.name === legacyValue || String(field.type || '').toLowerCase() === 'measure' || measureFieldName(field.name))
      .map(visualFieldRef);
    rows = fields.filter((field) => !values.includes(visualFieldRef(field))).map(visualFieldRef);
    const legacyDimensionField = selectedVisualFieldByRef(fields, String(visual.dimension || '').trim());
    const legacyDimension = legacyDimensionField ? visualFieldRef(legacyDimensionField) : String(visual.dimension || '').trim();
    if (legacyDimension && !rows.includes(legacyDimension) && !values.includes(legacyDimension)) rows.unshift(legacyDimension);
  }

  const used = new Set();
  const keepUnused = (name) => {
    if (used.has(name)) return false;
    used.add(name);
    return true;
  };
  rows = rows.filter(keepUnused);
  columns = columns.filter(keepUnused);
  values = values.filter(keepUnused);
  [...rows, ...columns, ...values].forEach((name) => {
    if (!fieldByRef.has(name)) {
      const field = selectedFieldForName(name, fields, '', visual.table || '');
      field.instanceId = field.instanceId || newVisualFieldInstanceId();
      fields.push(field);
      fieldByRef.set(visualFieldRef(field), field);
      fieldByRef.set(name, field);
    }
  });

  const orderedNames = [...rows, ...columns, ...values];
  visual.matrixRows = rows;
  visual.matrixColumns = columns;
  visual.matrixValues = values;
  visual.selectedFields = orderedNames.map((name) => fieldByRef.get(name)).filter(Boolean);
  const dimensionField = fieldByRef.get(rows[0] || columns[0] || '');
  const valueField = fieldByRef.get(values[0] || '');
  visual.dimension = dimensionField ? dimensionField.name : '';
  visual.value = valueField ? valueField.name : '';
  const dimensionSelect = $('#builderDimensionSelect');
  const valueSelect = $('#builderValueSelect');
  if (dimensionSelect) dimensionSelect.value = visual.dimension;
  if (valueSelect) valueSelect.value = visual.value;
  const secondaryValueSelect = $('#builderSecondaryValueSelect');
  if (secondaryValueSelect) {
    if (visual && visual.secondaryValue) secondaryValueSelect.value = visual.secondaryValue;
    else if (visual) visual.secondaryValue = secondaryValueSelect.value || '';
  }
  return visual;
}

function activeVisualSelectedFieldNames() {
  const visual = selectedReportVisual();
  return new Set(normalizeSelectedFields(visual && visual.selectedFields).map((item) => item.name));
}

function collectPreviewFields(visual = selectedReportVisual()) {
  const fields = normalizeSelectedFields(visual && visual.selectedFields);
  const origByName = {};
  fields.forEach(function(f) { origByName[f.name] = f; });
  const measureNames = new Set((state.model && state.model.measures || []).map(function(m) { return m.name; }));
  const add = (name) => {
    name = String(name || '').trim();
    if (!name || fields.some((item) => item.name === name)) return;
    const isMeasure = measureNames.has(name);
    const col = isMeasure ? null : (state.builderColumns || []).find((item) => item.name === name);
    var existing = origByName[name];
    fields.push({ name, table: (existing && existing.table) || (col && col.table) || '', type: isMeasure ? 'measure' : (col ? (col.columnType || col.dataType || '') : ''), displayName: (existing && existing.displayName) || null, aggregation: (existing && existing.aggregation) || null, showValueAs: (existing && existing.showValueAs) || null });
  };
  const useActiveControls = !visual || visual.id === state.activeVisualId;
  add((visual && visual.dimension) || (useActiveControls && $('#builderDimensionSelect') && $('#builderDimensionSelect').value));
  add((visual && visual.value) || (useActiveControls && $('#builderValueSelect') && $('#builderValueSelect').value));
  add((visual && visual.secondaryValue) || (useActiveControls && $('#builderSecondaryValueSelect') && $('#builderSecondaryValueSelect').value));
  // Corrige o type dos campos existentes: ao carregar relatorio salvo, os types
  // sao stripped pelo servidor. Medidas precisam ser re-identificadas como 'measure'
  // para que hasMeasureField seja true e o modelo seja enviado ao servidor.
  for (var i = 0; i < fields.length; i++) {
    if (measureNames.has(fields[i].name)) fields[i].type = 'measure';
  }
  return fields;
}

function rawPreviewVisualType(viz) {
  return ['table', 'matrix'].includes(String(viz || 'table').toLowerCase());
}

function valueOnlyVisualType(viz) {
  return ['card', 'kpi', 'gauge'].includes(String(viz || '').toLowerCase());
}

function dimensionOnlyVisualType(viz) {
  return ['slicer'].includes(String(viz || '').toLowerCase());
}

function measureFieldName(name) {
  return (state.model && state.model.measures || []).some(function(m) { return m.name === name; });
}

function builderColumnByName(name) {
  return (state.builderColumns || []).find(function(item) { return item.name === name; }) || null;
}

function fieldTypeByName(name, fallbackType) {
  if (measureFieldName(name)) return 'measure';
  var col = builderColumnByName(name);
  return col ? (col.columnType || col.dataType || '') : String(fallbackType || '');
}

function isNumericFieldName(name, fallbackType) {
  if (measureFieldName(name)) return true;
  var col = builderColumnByName(name);
  if (col) return isNumericColumn(col);
  return /(int|decimal|double|float|real|numeric|number|measure)/i.test(String(fallbackType || ''));
}

function selectedFieldForName(name, sourceFields, fallbackType, tableName) {
  name = String(name || '').trim();
  var existing = normalizeSelectedFields(sourceFields).find(function(item) { return item.name === name; });
  var col = builderColumnByName(name);
  return {
    name: name,
    table: String(tableName || (existing && existing.table) || (col && col.table) || '').trim(),
    type: (existing && existing.type) || fieldTypeByName(name, fallbackType),
    displayName: (existing && existing.displayName) || null,
    aggregation: (existing && existing.aggregation) || null,
    showValueAs: (existing && existing.showValueAs) || null
  };
}

function normalizeVisualBucketsForType(visual, options = {}) {
  if (!visual) return null;
  var viz = String(options.viz || visual.visualization || (($('#reportViz') && $('#reportViz').value) || 'table')).toLowerCase();
  var dimSel = $('#builderDimensionSelect');
  var valSel = $('#builderValueSelect');
  var aggSel = $('#builderAggregationSelect');
  var fields = visualOrderedSelectedFields(visual);
  var addField = function(name, fallbackType) {
    name = String(name || '').trim();
    if (!name || fields.some(function(item) { return item.name === name; })) return;
    fields.push(selectedFieldForName(name, fields, fallbackType));
  };
  addField(visual.dimension);
  addField(visual.value);
  addField(visual.secondaryValue);
  if (dimSel) addField(dimSel.value);
  if (valSel) addField(valSel.value);
  var secondarySel = $('#builderSecondaryValueSelect');
  if (secondarySel) addField(secondarySel.value);

  var setDimension = function(name) {
    visual.dimension = name || '';
    if (dimSel) dimSel.value = visual.dimension;
  };
  var setValue = function(name) {
    visual.value = name || '';
    if (valSel) valSel.value = visual.value;
  };
  var setAggregation = function(value) {
    visual.aggregation = value || 'SUM';
    if (aggSel) aggSel.value = visual.aggregation;
  };

  if (['textbox', 'image'].includes(viz)) {
    visual.selectedFields = fields;
    return visual;
  }

  if (viz === 'matrix') {
    visual.selectedFields = fields;
    return normalizeMatrixVisualBuckets(visual);
  }

  if (rawPreviewVisualType(viz)) {
    visual.selectedFields = fields;
    if (!visual.dimension && fields.length) setDimension(fields[0].name);
    if (visual.value && !fields.some(function(item) { return item.name === visual.value; })) setValue('');
    return visual;
  }

  var currentDimension = fields.some(function(item) { return item.name === visual.dimension; }) ? visual.dimension : '';
  var currentValue = fields.some(function(item) { return item.name === visual.value; }) ? visual.value : '';
  var isValueOnly = valueOnlyVisualType(viz);
  var isDimensionOnly = dimensionOnlyVisualType(viz);
  var nextDimension = isValueOnly ? '' : currentDimension;
  var nextValue = isDimensionOnly ? '' : currentValue;
  var numericCandidate = fields.find(function(item) {
    return item.name !== nextDimension && isNumericFieldName(item.name, item.type);
  }) || fields.find(function(item) { return isNumericFieldName(item.name, item.type); });

  if (nextValue && !isNumericFieldName(nextValue, selectedFieldForName(nextValue, fields).type)) {
    nextValue = numericCandidate ? numericCandidate.name : '';
  }
  if (!nextValue && !isDimensionOnly && numericCandidate) nextValue = numericCandidate.name;

  if (!nextDimension && !isValueOnly) {
    var dimensionCandidate = fields.find(function(item) {
      return item.name !== nextValue && !measureFieldName(item.name);
    }) || fields.find(function(item) { return item.name !== nextValue; });
    nextDimension = dimensionCandidate ? dimensionCandidate.name : '';
  }
  if (nextDimension && nextValue && nextDimension === nextValue) {
    var alternateDimension = fields.find(function(item) {
      return item.name !== nextValue && !measureFieldName(item.name);
    });
    nextDimension = alternateDimension ? alternateDimension.name : '';
  }

  if ((nextDimension && !nextValue && !isDimensionOnly) || (isValueOnly && !nextValue && fields.length) || isDimensionOnly) {
    setAggregation('COUNT');
  } else if (nextValue && options.preferNumericAggregation && isNumericFieldName(nextValue, selectedFieldForName(nextValue, fields).type) && ((aggSel && aggSel.value) || visual.aggregation) === 'COUNT') {
    setAggregation('SUM');
  }

  setDimension(nextDimension);
  setValue(nextValue);

  var keepNames = [];
  if (nextDimension) keepNames.push(nextDimension);
  if (nextValue && !keepNames.includes(nextValue)) keepNames.push(nextValue);
  if (!keepNames.length && fields.length && ((aggSel && aggSel.value) || visual.aggregation) === 'COUNT') keepNames.push(fields[0].name);
  var keepSet = new Set(keepNames);
  visual.selectedFields = fields
    .filter(function(field) { return keepSet.has(field.name); })
    .map(function(field) { return selectedFieldForName(field.name, fields); });
  return visual;
}

function insertStaticReportVisual(viz) {
  const visualization = viz === 'image' ? 'image' : 'textbox';
  const visual = addReportVisual(visualization, {}, { silent: true });
  if (visualization === 'textbox') {
    toast('Caixa de texto adicionada. Digite o conteúdo.');
    requestAnimationFrame(() => setTimeout(() => startTextboxEditing(visual.id), 0));
  } else {
    toast('Imagem adicionada. Selecione o formato para configurar a URL.');
  }
  return visual;
}

function addSelectedVisualField(field, type = '', tableName = '') {
  const visual = selectedReportVisual();
  if (!visual || !field) return;
  const current = normalizeSelectedFields(visual.selectedFields);
  if (!current.some((item) => item.name === field)) current.push({ instanceId: newVisualFieldInstanceId(), measureId: String(type || '').toLowerCase() === 'measure' ? field : null, name: field, table: String(tableName || '').trim(), type: String(type || ''), displayName: null, aggregation: null, showValueAs: null, format: null, alignment: null, width: null });
  visual.selectedFields = current;
}

function duplicateVisualMeasureInstance(fieldRef) {
  const visual = selectedReportVisual();
  if (!visual || !['table', 'matrix'].includes(String(visual.visualization || '').toLowerCase())) return;
  const fields = normalizeSelectedFields(visual.selectedFields);
  const source = selectedVisualFieldByRef(fields, fieldRef);
  if (!source || (String(source.type || '').toLowerCase() !== 'measure' && !measureFieldName(source.name))) {
    toast('Somente medidas podem ser adicionadas mais de uma vez.', 'error');
    return;
  }
  const duplicateNumber = fields.filter((field) => field.name === source.name).length + 1;
  const copy = {
    ...source,
    instanceId: newVisualFieldInstanceId(),
    measureId: source.measureId || source.name,
    displayName: (source.displayName || source.name) + ' ' + duplicateNumber,
    format: source.format ? { ...source.format } : null
  };
  const sourceIndex = fields.findIndex((field) => visualFieldRef(field) === visualFieldRef(source));
  fields.splice(sourceIndex + 1, 0, copy);
  visual.selectedFields = fields;
  visual.style = normalizeVisualStyle(visual.style);
  visual.style.columnOrder = fields.map(visualFieldRef);
  if (String(visual.visualization || '').toLowerCase() === 'matrix') {
    const values = normalizeVisualBucketNames(visual.matrixValues);
    const bucketSourceRef = values.find((ref) => ref === visualFieldRef(source) || ref === source.name);
    const insertAt = bucketSourceRef ? values.indexOf(bucketSourceRef) + 1 : values.length;
    values.splice(insertAt, 0, copy.instanceId);
    visual.matrixValues = values;
  }
  updateVisualFieldDropZones();
  renderVisualFromCachedRows(visual);
  toast('Nova instância da medida adicionada. Renomeie e formate de forma independente.');
}

function visualSelectedFieldIsMeasure(field) {
  return Boolean(field && (String(field.type || '').toLowerCase() === 'measure' || measureFieldName(field.name)));
}

function visualFieldRemovalNeedsQuery(visual, before, removedFields, remainingFields, filterChanged, cleanupKeys) {
  if (!remainingFields.length) return false;
  const viz = String(visual && visual.visualization || 'table').toLowerCase();
  const removedRefs = new Set(removedFields.map(visualFieldRef));
  const removedNames = new Set(removedFields.map(function(field) { return field.name; }));
  const remainingNames = new Set(remainingFields.map(function(field) { return field.name; }));
  const removedSourceNames = new Set(Array.from(removedNames).filter(function(name) { return !remainingNames.has(name); }));
  const removedPhysicalField = removedFields.some(function(field) { return !visualSelectedFieldIsMeasure(field); });
  const remainingMeasure = remainingFields.some(visualSelectedFieldIsMeasure);
  const removedBucketEntry = function(entries) {
    return normalizeVisualBucketNames(entries).some(function(name) { return removedRefs.has(name) || removedSourceNames.has(name); });
  };
  const sortChanged = cleanupKeys.has(String(before.sortColumn || ''));
  const valueChanged = removedSourceNames.has(String(before.value || ''));
  const dimensionChanged = removedSourceNames.has(String(before.dimension || ''));
  const secondaryChanged = removedSourceNames.has(String(before.secondaryValue || ''));
  if (viz === 'table') {
    return Boolean(filterChanged || sortChanged || valueChanged || (removedPhysicalField && remainingMeasure));
  }
  if (viz === 'matrix') {
    return Boolean(
      filterChanged || sortChanged || valueChanged || dimensionChanged ||
      removedBucketEntry(before.matrixRows) || removedBucketEntry(before.matrixColumns) ||
      (removedPhysicalField && remainingMeasure)
    );
  }
  if (['textbox', 'image'].includes(viz)) return false;
  return Boolean(filterChanged || sortChanged || valueChanged || dimensionChanged || secondaryChanged || remainingFields.length);
}

function removeVisualFieldState(visual, fieldRefOrName, options = {}) {
  if (!visual || !fieldRefOrName) return null;
  const fieldsBefore = normalizeSelectedFields(visual.selectedFields);
  const target = selectedVisualFieldByRef(fieldsBefore, fieldRefOrName);
  if (!target) return null;
  const removeAllByName = options.allByName === true;
  const removedFields = fieldsBefore.filter(function(field) {
    return removeAllByName ? field.name === target.name : visualFieldRef(field) === visualFieldRef(target);
  });
  if (!removedFields.length) return null;
  const removedRefs = new Set(removedFields.map(visualFieldRef));
  const remainingFields = fieldsBefore.filter(function(field) { return !removedRefs.has(visualFieldRef(field)); });
  const remainingNames = new Set(remainingFields.map(function(field) { return field.name; }));
  const removedSourceNames = new Set(removedFields.map(function(field) { return field.name; }).filter(function(name) { return !remainingNames.has(name); }));
  const before = {
    dimension: visual.dimension || '',
    value: visual.value || '',
    secondaryValue: visual.secondaryValue || '',
    matrixRows: normalizeVisualBucketNames(visual.matrixRows),
    matrixColumns: normalizeVisualBucketNames(visual.matrixColumns),
    matrixValues: normalizeVisualBucketNames(visual.matrixValues),
    sortColumn: String(visual.style && visual.style.sortColumn || '')
  };

  const renderKeysByRef = new Map();
  const occurrences = new Map();
  fieldsBefore.forEach(function(field) {
    const count = occurrences.get(field.name) || 0;
    occurrences.set(field.name, count + 1);
    renderKeysByRef.set(visualFieldRef(field), count === 0 ? field.name : '__biwa_instance_' + visualFieldInstanceHash(visualFieldRef(field)));
  });
  const cleanupKeys = new Set();
  removedFields.forEach(function(field) {
    cleanupKeys.add(visualFieldRef(field));
    cleanupKeys.add(renderKeysByRef.get(visualFieldRef(field)) || '');
    if (removedSourceNames.has(field.name)) cleanupKeys.add(field.name);
  });
  cleanupKeys.delete('');

  visual.selectedFields = remainingFields;
  const keepBucketEntry = function(name) {
    return !removedRefs.has(name) && !removedSourceNames.has(name);
  };
  visual.matrixRows = normalizeVisualBucketNames(visual.matrixRows).filter(keepBucketEntry);
  visual.matrixColumns = normalizeVisualBucketNames(visual.matrixColumns).filter(keepBucketEntry);
  visual.matrixValues = normalizeVisualBucketNames(visual.matrixValues).filter(keepBucketEntry);
  if (removedSourceNames.has(String(visual.dimension || ''))) visual.dimension = '';
  if (removedSourceNames.has(String(visual.value || ''))) visual.value = '';
  if (removedSourceNames.has(String(visual.secondaryValue || ''))) visual.secondaryValue = '';

  const dimSel = $('#builderDimensionSelect');
  const valSel = $('#builderValueSelect');
  const secondarySel = $('#builderSecondaryValueSelect');
  if (dimSel && removedSourceNames.has(dimSel.value)) dimSel.value = '';
  if (valSel && removedSourceNames.has(valSel.value)) valSel.value = '';
  if (secondarySel && removedSourceNames.has(secondarySel.value)) secondarySel.value = '';

  const filtersBefore = normalizeVisualFilters(visual.visualFilters);
  visual.visualFilters = filtersBefore.filter(function(filter) { return !removedSourceNames.has(filter.column); });
  const filterChanged = visual.visualFilters.length !== filtersBefore.length;

  visual.style = normalizeVisualStyle(visual.style);
  ['columnWidths', 'columnAlignments', 'conditionalFormat'].forEach(function(property) {
    const map = visual.style[property] && typeof visual.style[property] === 'object' ? { ...visual.style[property] } : {};
    cleanupKeys.forEach(function(key) { delete map[key]; });
    visual.style[property] = map;
  });
  visual.style.columnOrder = remainingFields.map(visualFieldRef);
  if (cleanupKeys.has(String(visual.style.sortColumn || ''))) visual.style.sortColumn = '';
  if (cleanupKeys.has(String(visual.style.chartFunnelReference || ''))) visual.style.chartFunnelReference = '';
  if (visual.totals && typeof visual.totals === 'object') cleanupKeys.forEach(function(key) { delete visual.totals[key]; });
  if (visual.columnFormats && typeof visual.columnFormats === 'object') cleanupKeys.forEach(function(key) { delete visual.columnFormats[key]; });
  visual.pendingTotalsSignature = '';
  visual.totalsPending = false;

  const viz = String(visual.visualization || 'table').toLowerCase();
  if (viz === 'matrix') normalizeMatrixVisualBuckets(visual);
  else if (viz === 'table') reapplyPillOrderToVisual({ skipSync: true });
  else normalizeVisualBucketsForType(visual);

  if (visual.serverPagePayload) {
    visual.serverPagePayload = {
      ...visual.serverPagePayload,
      dimension: visual.dimension || '',
      value: visual.value || '',
      secondaryValue: visual.secondaryValue || '',
      fields: collectPreviewFields(visual),
      visualFilters: getVisualFilters(visual)
    };
  }
  const normalizedRemaining = normalizeSelectedFields(visual.selectedFields);
  return {
    removedFields,
    remainingFields: normalizedRemaining,
    filterChanged,
    cleanupKeys,
    needsQuery: visualFieldRemovalNeedsQuery(visual, before, removedFields, normalizedRemaining, filterChanged, cleanupKeys)
  };
}

function removeVisualTableColumnsFromDom(visual, mutation) {
  if (!visual || !mutation || String(visual.visualization || '').toLowerCase() !== 'table') return false;
  const frame = getVisualFrame(visual.id);
  const wrap = frame && frame.querySelector('.visual-table-wrap');
  const table = wrap && wrap.querySelector('table.visual-table');
  if (!table) return false;
  const cleanupKeys = mutation.cleanupKeys instanceof Set ? mutation.cleanupKeys : new Set();
  const removedNames = new Set((mutation.removedFields || []).map(function(field) { return field.name; }));
  const headers = Array.from(table.querySelectorAll('thead tr:last-child > th'));
  const indexes = headers.map(function(header, index) {
    const ref = String(header.dataset.fieldRef || '');
    const column = String(header.dataset.col || '');
    return cleanupKeys.has(ref) || cleanupKeys.has(column) || removedNames.has(column) ? index : -1;
  }).filter(function(index) { return index >= 0; }).sort(function(left, right) { return right - left; });
  if (!indexes.length) return false;
  const previousIndexes = String(table.dataset.hiddenVisualColumns || '').split(',').filter(function(value) { return value !== ''; }).map(Number).filter(Number.isFinite);
  const hiddenIndexes = Array.from(new Set(previousIndexes.concat(indexes))).sort(function(left, right) { return left - right; });
  table.dataset.hiddenVisualColumns = hiddenIndexes.join(',');
  let projectionStyle = wrap.querySelector(':scope > style[data-visual-column-projection]');
  if (!projectionStyle) {
    projectionStyle = document.createElement('style');
    projectionStyle.dataset.visualColumnProjection = '1';
    wrap.prepend(projectionStyle);
  }
  const selectors = hiddenIndexes.flatMap(function(index) {
    const nth = index + 1;
    return [
      'table.visual-table[data-hidden-visual-columns] th:nth-child(' + nth + ')',
      'table.visual-table[data-hidden-visual-columns] td:nth-child(' + nth + ')',
      'table.visual-table[data-hidden-visual-columns] col:nth-child(' + nth + ')'
    ];
  });
  projectionStyle.textContent = selectors.join(',') + '{display:none!important;visibility:collapse!important}';
  indexes.forEach(function(index) { if (headers[index]) headers[index].setAttribute('aria-hidden', 'true'); });
  const currentWidth = Number.parseFloat(table.style.width || '');
  if (Number.isFinite(currentWidth)) {
    const removedWidth = indexes.reduce(function(total, index) {
      const col = table.querySelectorAll('colgroup > col')[index];
      const width = Number.parseFloat(col && col.style.width || '');
      return total + (Number.isFinite(width) ? width : 0);
    }, 0);
    if (removedWidth > 0) {
      const width = Math.max(32, Math.round(currentWidth - removedWidth));
      table.style.width = width + 'px';
      table.style.minWidth = width + 'px';
      table.style.maxWidth = width + 'px';
    }
  }
  return true;
}

function restoreVisualTableColumnFromProjection(visual, fieldName) {
  if (!visual || !fieldName || String(visual.visualization || '').toLowerCase() !== 'table') return false;
  const frame = getVisualFrame(visual.id);
  const wrap = frame && frame.querySelector('.visual-table-wrap');
  const table = wrap && wrap.querySelector('table.visual-table[data-hidden-visual-columns]');
  if (!table) return false;
  const headers = Array.from(table.querySelectorAll('thead tr:last-child > th'));
  const index = headers.findIndex(function(header) {
    const source = String(header.dataset.col || '');
    const ref = String(header.dataset.fieldRef || '');
    const selected = selectedVisualFieldByRef(visual.selectedFields, ref || source);
    return source === fieldName || (selected && selected.name === fieldName);
  });
  if (index < 0) return false;
  const hiddenIndexes = String(table.dataset.hiddenVisualColumns || '').split(',').filter(function(value) { return value !== ''; }).map(Number).filter(Number.isFinite).filter(function(item) { return item !== index; });
  const projectionStyle = wrap.querySelector(':scope > style[data-visual-column-projection]');
  if (hiddenIndexes.length) {
    table.dataset.hiddenVisualColumns = hiddenIndexes.join(',');
    const selectors = hiddenIndexes.flatMap(function(item) {
      const nth = item + 1;
      return [
        'table.visual-table[data-hidden-visual-columns] th:nth-child(' + nth + ')',
        'table.visual-table[data-hidden-visual-columns] td:nth-child(' + nth + ')',
        'table.visual-table[data-hidden-visual-columns] col:nth-child(' + nth + ')'
      ];
    });
    if (projectionStyle) projectionStyle.textContent = selectors.join(',') + '{display:none!important;visibility:collapse!important}';
  } else {
    delete table.dataset.hiddenVisualColumns;
    if (projectionStyle) projectionStyle.remove();
  }
  headers[index].removeAttribute('aria-hidden');
  const currentWidth = Number.parseFloat(table.style.width || '');
  const col = table.querySelectorAll('colgroup > col')[index];
  const restoredWidth = Number.parseFloat(col && col.style.width || '');
  if (Number.isFinite(currentWidth) && Number.isFinite(restoredWidth)) {
    const width = Math.round(currentWidth + restoredWidth);
    table.style.width = width + 'px';
    table.style.minWidth = width + 'px';
    table.style.maxWidth = width + 'px';
  }
  return true;
}

function appendVisualTablePendingColumn(visual, fieldName) {
  if (!visual || !fieldName || String(visual.visualization || '').toLowerCase() !== 'table') return false;
  const frame = getVisualFrame(visual.id);
  const table = frame && frame.querySelector('table.visual-table');
  if (!table) return false;
  const field = normalizeSelectedFields(visual.selectedFields).find(function(item) { return item.name === fieldName; });
  if (!field) return false;
  const fieldRef = visualFieldRef(field);
  const headerRow = table.querySelector('thead tr:last-child');
  if (!headerRow) return false;
  const alreadyRendered = Array.from(headerRow.querySelectorAll('th')).some(function(header) {
    return String(header.dataset.fieldRef || '') === fieldRef || String(header.dataset.col || '') === field.name;
  });
  if (alreadyRendered) return false;
  const style = normalizeVisualStyle(visual.style);
  const label = field.displayName || field.name;
  const configuredWidth = resolvedVisualFieldWidth(field, style, field.name, false);
  const width = Math.max(48, Number(configuredWidth) || visualTableInitialColumnWidth(label, style));
  const colgroup = table.querySelector('colgroup');
  if (colgroup) {
    const col = document.createElement('col');
    col.style.width = Math.round(width) + 'px';
    colgroup.appendChild(col);
  }
  headerRow.insertAdjacentHTML('beforeend', renderTableHeaderCell(field.name, visual, style, true, label, fieldRef));
  table.querySelectorAll('tbody tr').forEach(function(row) {
    const cell = document.createElement('td');
    cell.className = 'visual-table-pending-cell';
    cell.dataset.crossFilterField = field.name;
    cell.setAttribute('aria-label', 'Carregando ' + label);
    cell.textContent = '…';
    row.appendChild(cell);
  });
  table.querySelectorAll('tfoot tr').forEach(function(row) {
    const cell = document.createElement('td');
    cell.className = 'visual-table-pending-cell';
    cell.textContent = '…';
    row.appendChild(cell);
  });
  const currentWidth = Number.parseFloat(table.style.width || '');
  if (Number.isFinite(currentWidth)) {
    const nextWidth = Math.round(currentWidth + width);
    table.style.width = nextWidth + 'px';
    table.style.minWidth = nextWidth + 'px';
    table.style.maxWidth = nextWidth + 'px';
  }
  return true;
}

function removeVisualFilterCardsForMutation(mutation) {
  if (!mutation) return;
  const remainingNames = new Set((mutation.remainingFields || []).map(function(field) { return field.name; }));
  const removedNames = new Set((mutation.removedFields || []).map(function(field) { return field.name; }).filter(function(name) { return !remainingNames.has(name); }));
  removedNames.forEach(function(name) {
    document.querySelectorAll('#visualFilterCards .visual-filter-card').forEach(function(card) {
      if (String(card.dataset.filterColumn || '') === String(name)) card.remove();
    });
  });
}

function renderVisualFieldConfigurationImmediately(visual, action, details, startedAt) {
  if (!visual) return 0;
  const renderStartedAt = performance.now();
  clearVisualBuilderUpdating();
  const afterClearAt = performance.now();
  syncBuilderFieldChecks();
  const afterControlsAt = performance.now();
  const configuredFields = collectPreviewFields(visual);
  const fastTableRemoval = action === 'REMOVE_FIELD' && details && configuredFields.length
    ? removeVisualTableColumnsFromDom(visual, details.mutation)
    : false;
  const fastTableRestore = action === 'ADD_FIELD' && details && details.field
    ? restoreVisualTableColumnFromProjection(visual, details.field)
    : false;
  const fastTableAppend = action === 'ADD_FIELD' && details && details.field && !fastTableRestore
    ? appendVisualTablePendingColumn(visual, details.field)
    : false;
  if (details) details.fastTableProjection = Boolean(fastTableRemoval || fastTableRestore || fastTableAppend);
  if (!configuredFields.length) visualBuilderStatus('Selecione ou arraste um campo do painel Dados.');
  else if (!fastTableRemoval && !fastTableRestore && !fastTableAppend) renderVisualFromCachedRows(visual);
  const afterDomAt = performance.now();
  if (String(visual.id || '') === String(state.activeVisualId || '')) state.queryRows = Array.isArray(visual.rows) ? visual.rows : [];
  const uiMs = performance.now() - Number(startedAt || performance.now());
  const frame = getVisualFrame(visual.id);
  if (frame) {
    frame.dataset.fieldMutationAction = String(action || '');
    frame.dataset.fieldMutationUiMs = uiMs.toFixed(3);
    frame.dataset.fieldMutationQueryRequired = details && details.queryRequired ? '1' : '0';
    frame.dataset.fieldMutationClearMs = (afterClearAt - renderStartedAt).toFixed(3);
    frame.dataset.fieldMutationControlsMs = (afterControlsAt - afterClearAt).toFixed(3);
    frame.dataset.fieldMutationDomMs = (afterDomAt - afterControlsAt).toFixed(3);
    frame.dataset.fieldMutationRequestCount = '0';
    frame.dataset.fieldQueryStatus = 'idle';
    delete frame.dataset.fieldQueryMs;
    delete frame.dataset.fieldQueryVersion;
    delete frame.dataset.fieldTotalsStatus;
  }
  visualFieldPerformanceClient('FIELD MUTATION UI', {
    action,
    visualId: String(visual.id || ''),
    visualization: String(visual.visualization || ''),
    field: details && details.field || '',
    uiMs: Number(uiMs.toFixed(3)),
    queryRequired: Boolean(details && details.queryRequired),
    configuredFields: configuredFields.map(function(field) { return field.name; })
  });
  return uiMs;
}

function scheduleVisualCachedFieldReconciliation(visual) {
  if (!visual) return;
  const visualId = String(visual.id || '');
  const queryVersion = currentVisualQueryVersion(visualId);
  const configSignature = stableClientJson(visualDataQuerySignature(visual));
  const reconcile = function() {
    if (currentVisualQueryVersion(visualId) !== queryVersion) return;
    const current = state.reportVisuals.find(function(item) { return String(item.id || '') === visualId; });
    if (!current || stableClientJson(visualDataQuerySignature(current)) !== configSignature) return;
    renderVisualFromCachedRows(current);
  };
  if (typeof window.requestIdleCallback === 'function') window.requestIdleCallback(reconcile, { timeout: 1200 });
  else window.requestAnimationFrame(reconcile);
}

function removeSelectedVisualField(field, options = {}) {
  const visual = selectedReportVisual();
  if (!visual || !field) return null;
  const startedAt = performance.now();
  const mutation = removeVisualFieldState(visual, field, { allByName: options.allByName !== false });
  if (!mutation) return null;
  const afterStateAt = performance.now();
  cancelVisualInFlightWork(visual.id);
  const afterCancelAt = performance.now();
  removeVisualFilterCardsForMutation(mutation);
  const afterFilterAt = performance.now();
  const renderDetails = {
    field: mutation.removedFields.map(function(item) { return item.name; }).join(', '),
    queryRequired: mutation.needsQuery,
    mutation
  };
  renderVisualFieldConfigurationImmediately(visual, 'REMOVE_FIELD', renderDetails, startedAt);
  const frame = getVisualFrame(visual.id);
  if (frame) {
    frame.dataset.fieldMutationStateMs = (afterStateAt - startedAt).toFixed(3);
    frame.dataset.fieldMutationCancelMs = (afterCancelAt - afterStateAt).toFixed(3);
    frame.dataset.fieldMutationFilterMs = (afterFilterAt - afterCancelAt).toFixed(3);
  }
  if (mutation.needsQuery) {
    scheduleVisualAutoUpdate(options.reason || 'remove-field', { background: true, mutation: 'REMOVE_FIELD', preserveTotals: !mutation.filterChanged });
  } else {
    const meta = $('#queryMeta');
    if (meta) meta.textContent = (Array.isArray(visual.rows) ? visual.rows.length : 0) + ' linhas · campo removido localmente';
    visualFieldPerformanceClient('FIELD MUTATION COMPLETE', {
      action: 'REMOVE_FIELD', visualId: String(visual.id || ''), field: field,
      requestCount: 0, background: false
    });
    if (renderDetails.fastTableProjection && visual.style && visual.style.hideZeroRows === true) {
      scheduleVisualCachedFieldReconciliation(visual);
    }
  }
  return mutation;
}

function clearActiveVisualRows(message) {
  const visual = selectedReportVisual();
  if (visual) visual.rows = [];
  state.queryRows = [];
  visualBuilderStatus(message || 'Selecione ou arraste campos do painel Dados para renderizar automaticamente.');
  const meta = getActiveVisualPart('.query-meta') || $('#queryMeta');
  if (meta) meta.textContent = '';
}

function normalizeVisualFilters(filters) {
  if (!Array.isArray(filters)) return [];
  return filters
    .filter(function(f) { return f && f.column; })
    .map(function(f) {
      return {
        column: f.column,
        table: f.table || '',
        values: Array.isArray(f.values) ? f.values : [],
        availableValues: Array.isArray(f.availableValues) ? f.availableValues : [],
        locked: f.locked !== false
      };
    });
}

function visualFilterKey(filter) {
  return String((filter && filter.table) || '') + '::' + String((filter && filter.column) || '');
}

function getVisualFilters(visual) {
  if (!visual) return [];
  var vf = visual.visualFilters;
  if (Array.isArray(vf) && vf.length) return normalizeVisualFilters(vf);
  if (visual.filterColumn) {
    var values = String(visual.filterValue || '').split(',').map(function(s) { return s.trim(); }).filter(Boolean);
    return [{ column: visual.filterColumn, values: values, availableValues: [] }];
  }
  return [];
}

function collectVisualFiltersFromCards() {
  var cards = document.querySelectorAll('#visualFilterCards .visual-filter-card');
  var existingFilters = getVisualFilters(selectedReportVisual());
  if (!cards.length) return existingFilters;
  var existingByColumn = {};
  existingFilters.forEach(function(f) { existingByColumn[visualFilterKey(f)] = f; });
  var filters = [];
  cards.forEach(function(card) {
    var column = card.dataset.filterColumn;
    if (!column) return;
    var table = card.dataset.filterTable || '';
    var existing = existingByColumn[visualFilterKey({ table: table, column: column })];
    // Cards ainda carregando ou colapsados preservam filtros adicionados/ativos.
    var allCbs = card.querySelectorAll('[name="visualFilterValue"]');
    if (!allCbs.length) {
      if (existing) filters.push(existing);
      return;
    }
    var checked = Array.from(card.querySelectorAll('[name="visualFilterValue"]:checked')).map(function(cb) { return cb.value; });
    // Se todos/nenhum estao marcados, nao ha filtro ativo; preserva apenas campos
    // arrastados explicitamente para o bucket de filtro.
    if (checked.length === allCbs.length || !checked.length) {
      if (existing) filters.push({ column: column, table: table, values: [], availableValues: [], locked: existing.locked !== false });
      return;
    }
    filters.push({ column: column, table: table, values: checked, availableValues: [], locked: true });
  });
  return filters;
}

// Estado de quais filter cards estao expandidos (Power BI style)
var _filterCardExpandedState = {};

async function renderVisualFilterCards(visual) {
  var container = document.getElementById('visualFilterCards');
  if (!container) return;
  if (!visual) {
    container.innerHTML = '<div class="visual-filter-empty-msg">Selecione um visual para ver os filtros.</div>';
    return;
  }

  var table = ($('#builderTableSelect') && $('#builderTableSelect').value) || visual.table || '';
  var previewFields = collectPreviewFields(visual);
  var allCols = state.builderColumns || [];
  var activeFilters = getVisualFilters(visual);
  var measureNames = new Set((state.model && state.model.measures || []).map(function(measure) { return measure.name; }));
  var columns = [];
  var columnKeys = new Set();
  previewFields.forEach(function(field) {
    if (!field || !field.name || String(field.type || '').toLowerCase() === 'measure' || measureNames.has(field.name)) return;
    var fieldTable = field.table || table || '';
    var metadata = allCols.find(function(column) {
      return column.name === field.name && (!field.table || String(column.table || table || '') === String(field.table));
    }) || allCols.find(function(column) { return column.name === field.name; });
    var resolved = Object.assign({}, metadata || {}, field, {
      name: field.name,
      table: fieldTable || (metadata && metadata.table) || table || '',
      columnType: (metadata && metadata.columnType) || field.type || '',
      dataType: (metadata && metadata.dataType) || field.type || ''
    });
    var key = visualFilterKey({ table: resolved.table, column: resolved.name });
    if (!columnKeys.has(key)) {
      columnKeys.add(key);
      columns.push(resolved);
    }
  });
  activeFilters.forEach(function(f) {
    var key = visualFilterKey({ table: f.table || table, column: f.column });
    if (f.column && !columnKeys.has(key)) {
      columnKeys.add(key);
      columns.push({ name: f.column, table: f.table || table, columnType: '', dataType: '' });
    }
  });
  var activeFilterMap = {};
  activeFilters.forEach(function(f) { activeFilterMap[visualFilterKey(f)] = f; });

  if (!columns.length) {
    container.innerHTML = '<div class="visual-filter-empty-msg">Nenhuma coluna disponível. Selecione uma tabela.</div>';
    return;
  }

  activeFilters.forEach(function(f) {
    var expandedKey = visualFilterKey(f);
    if (!(expandedKey in _filterCardExpandedState)) {
      _filterCardExpandedState[expandedKey] = true;
    }
  });

  container.innerHTML = '';
  columns.forEach(function(col) {
    var colName = col.name;
    var colTable = col.table || table || '';
    var filterKey = visualFilterKey({ table: colTable, column: colName });
    var isActive = Boolean(activeFilterMap[filterKey]);
    var activeFilter = activeFilterMap[filterKey];
    var isExpanded = Boolean(_filterCardExpandedState[filterKey]);
    var type = col.columnType || col.dataType || '';
    var kind = isNumericColumn(col) ? 'numérico' : (/date|time/i.test(String(type)) ? 'data' : 'texto');
    var icon = kind === 'numérico' ? '∑' : (kind === 'data' ? '◷' : 'abc');

    var card = document.createElement('div');
    card.className = 'visual-filter-card' + (isExpanded ? ' expanded' : ' collapsed') + (isActive ? ' filter-active' : '');
    card.dataset.filterColumn = colName;
    card.dataset.filterTable = colTable;
    card.dataset.filterKey = filterKey;

    var activeCount = isActive && activeFilter.values.length ? activeFilter.values.length : 0;
    var badgeHtml = isActive && activeCount > 0 ? '<span class="filter-card-badge" title="' + activeCount + ' valor(es) selecionado(s)">' + activeCount + '</span>' : '';
    var clearBtnHtml = isActive && can('reportEditing') ? '<button type="button" class="filter-card-clear" data-clear-single-filter="' + escapeHtml(colName) + '" title="Limpar filtro">✕</button>' : '';
    var summaryText = activeCount > 0 ? activeCount + ' selecionado(s)' : 'Todos';

    card.innerHTML = '<div class="visual-filter-card-header">' +
      '<span class="filter-card-caret">' + (isExpanded ? '▾' : '▸') + '</span>' +
      '<i class="field-type-icon filter-type-icon">' + escapeHtml(icon) + '</i>' +
      '<span class="filter-card-heading"><span class="filter-card-title" title="' + escapeHtml(colName) + '">' + escapeHtml(colName) + '</span><small>' + escapeHtml(summaryText) + '</small></span>' +
      badgeHtml +
      clearBtnHtml +
      '</div>' +
      '<div class="visual-filter-card-body"' + (isExpanded ? '' : ' style="display:none"') + '>' +
      '<div class="empty-state small filter-card-loading">Carregando valores...</div>' +
      '</div>';
    container.appendChild(card);

    if (isExpanded) {
      var selectedVals = isActive ? activeFilter.values : [];
      loadVisualFilterCardValues(card, colName, selectedVals, colTable || table);
    }

    var header = card.querySelector('.visual-filter-card-header');
    if (header) {
      header.addEventListener('click', function(ev) {
        if (ev.target.closest('[data-clear-single-filter]')) return;
        ev.stopPropagation();
        var targetCard = ev.currentTarget.closest('.visual-filter-card');
        if (!targetCard) return;
        var col = targetCard.dataset.filterColumn;
        var stateKey = targetCard.dataset.filterKey || visualFilterKey({ table: targetCard.dataset.filterTable || table, column: col });
        var isCurrentlyExpanded = targetCard.classList.contains('expanded');
        if (isCurrentlyExpanded) {
          targetCard.classList.remove('expanded');
          targetCard.classList.add('collapsed');
          _filterCardExpandedState[stateKey] = false;
          var caret = targetCard.querySelector('.filter-card-caret');
          if (caret) caret.textContent = '▸';
          var bodyEl = targetCard.querySelector('.visual-filter-card-body');
          if (bodyEl) bodyEl.style.display = 'none';
        } else {
          targetCard.classList.remove('collapsed');
          targetCard.classList.add('expanded');
          _filterCardExpandedState[stateKey] = true;
          var caret = targetCard.querySelector('.filter-card-caret');
          if (caret) caret.textContent = '▾';
          var bodyEl = targetCard.querySelector('.visual-filter-card-body');
          if (bodyEl) bodyEl.style.display = '';
          var hasCheckboxes = bodyEl && bodyEl.querySelectorAll('[name="visualFilterValue"]').length;
          if (!hasCheckboxes) {
            var vis = selectedReportVisual();
            var vfilters = getVisualFilters(vis);
            var tableForFilter = targetCard.dataset.filterTable || table || '';
            var filt = vfilters.find(function(fa) { return visualFilterKey(fa) === visualFilterKey({ table: tableForFilter, column: col }); });
            var vals = filt ? filt.values : [];
            loadVisualFilterCardValues(targetCard, col, vals, tableForFilter);
          }
        }
      });
    }

    var clearBtn = card.querySelector('.filter-card-clear');
    if (clearBtn) {
      clearBtn.addEventListener('click', function(ev) {
        ev.stopPropagation();
        removeVisualFilterEntry(colName, colTable);
      });
    }
  });
}

async function loadFilterCardDistinctValues(table, column, selectedValues) {
  var tableSource = String(table || '').trim();
  var field = String(column || '').trim();
  if (!tableSource || !field) throw new Error('Tabela e campo do filtro são obrigatórios.');
  var context = {};
  var current = state.dashboardFilters[designerReportId()] || {};
  currentOnlineFilters().forEach(function(filter) {
    if (!filter || !filter.table || !filter.field) return;
    if (String(filter.table) === tableSource && String(filter.field) === field) return;
    var value = dashboardFilterValueFromState(current, filter);
    if (value !== null && value !== undefined && String(value) !== '') {
      context[filter.table + '.' + filter.field] = value;
    }
  });
  var loaded = await loadFilterOptions(
    { table: tableSource, field: field },
    2000,
    Object.keys(context).length ? context : null
  );
  var unique = new Map();
  (selectedValues || []).forEach(function(value) {
    if (value !== null && value !== undefined && String(value) !== '') unique.set(String(value), value);
  });
  (loaded || []).forEach(function(value) {
    if (value !== null && value !== undefined && String(value) !== '') unique.set(String(value), value);
  });
  return Array.from(unique.values());
}

function filterCardValuesFromLoadedRows(column, selectedValues) {
  var visual = selectedReportVisual();
  var rows = visual && Array.isArray(visual.rows) && visual.rows.length
    ? visual.rows
    : (Array.isArray(state.queryRows) ? state.queryRows : []);
  var unique = new Map();

  (selectedValues || []).forEach(function(value) {
    if (value !== null && value !== undefined && String(value) !== '') unique.set(String(value), value);
  });

  for (var index = 0; index < rows.length && unique.size < 2000; index += 1) {
    var row = rows[index];
    var value = row && row[column];
    if (value !== null && value !== undefined && String(value) !== '') unique.set(String(value), value);
  }

  return Array.from(unique.values());
}

async function loadVisualFilterCardValues(card, column, selectedValues, table) {
  if (!card || !column) return;
  var body = card.querySelector('.visual-filter-card-body');
  if (!body) return;

  var selected = new Set((selectedValues || []).map(function(s) { return String(s); }));
  var tableSource = table || ($('#builderTableSelect') && $('#builderTableSelect').value) || '';
  var requestVersion = Number(card.dataset.filterInteractionVersion || 0);
  var localValues = filterCardValuesFromLoadedRows(column, selectedValues);
  var renderedLocalValues = localValues.length > 0;

  function renderValues(values) {
    renderFilterCheckboxList(body, column, selected, values, 'visualFilterValue', function() {
      card.dataset.filterInteractionVersion = String(Number(card.dataset.filterInteractionVersion || 0) + 1);
      updateVisualFilterCardCount(body, values.length);
      scheduleVisualAutoUpdate('filter-card-change');
    });
  }

  if (renderedLocalValues) renderValues(localValues);

  try {
    var values = await loadFilterCardDistinctValues(tableSource, column, selectedValues);
    if (!card.isConnected) return;
    if (Number(card.dataset.filterInteractionVersion || 0) !== requestVersion) return;
    if (values.length || !renderedLocalValues) renderValues(values);
  } catch (err) {
    if (!renderedLocalValues) {
      body.innerHTML = '<div class="visual-filter-card-empty">Erro: ' + escapeHtml(err.message || 'desconhecido') + '</div>';
    }
  }
}

function updateVisualFilterCardCount(body, totalValues) {
  var selectedCount = body.querySelectorAll('[name="visualFilterValue"]:checked').length;
  var labelEl = body.querySelector('.transform-values-label');
  if (labelEl) labelEl.textContent = totalValues + ' valor(es) | ' + selectedCount + ' sel.';
}

function renderFilterCheckboxList(body, columnName, selected, values, checkboxName, onChangeFn) {
  if (!values.length) {
    body.innerHTML = '<div class="visual-filter-card-empty">Nenhum valor encontrado.</div>';
    return;
  }
  var allChecked = selected.size === 0 || values.every(function(v) { return selected.has(String(v)); });
  var selectedCount = allChecked ? values.length : values.filter(function(v) { return selected.has(String(v)); }).length;
  var readOnly = !can('reportEditing');
  var disabled = readOnly ? ' disabled' : '';

  body.innerHTML = '<div class="filter-values-bar">' +
    '<span class="transform-values-label">' + values.length + ' valor(es) | ' + selectedCount + ' sel.</span>' +
    '<span class="actions"><button type="button" class="btn ghost mini" data-filter-select-all' + disabled + '>Todos</button><button type="button" class="btn ghost mini" data-filter-deselect-all' + disabled + '>Nenhum</button></span>' +
    '</div>' +
    '<input type="text" class="filter-values-search" placeholder="Pesquisar valor..." autocomplete="off">' +
    '<div class="filter-values-list">' + values.map(function(v) {
      var val = String(v != null ? v : '');
      var display = val.length > 50 ? val.slice(0, 47) + '...' : val;
      var checked = (allChecked || selected.has(val)) ? 'checked' : '';
      return '<label class="check-label filter-value-item"><input type="checkbox" name="' + checkboxName + '" value="' + escapeHtml(val) + '" ' + checked + disabled + '> ' + escapeHtml(display) + '</label>';
    }).join('') + '</div>';

  body.querySelector('[data-filter-select-all]').addEventListener('click', function() {
    body.querySelectorAll('[name="' + checkboxName + '"]').forEach(function(cb) { cb.checked = true; });
    updateCardFilterCount(body, values.length, checkboxName);
    if (onChangeFn) onChangeFn();
  });
  body.querySelector('[data-filter-deselect-all]').addEventListener('click', function() {
    body.querySelectorAll('[name="' + checkboxName + '"]').forEach(function(cb) { cb.checked = false; });
    updateCardFilterCount(body, values.length, checkboxName);
    if (onChangeFn) onChangeFn();
  });

  var searchInput = body.querySelector('.filter-values-search');
  if (searchInput) {
    searchInput.addEventListener('input', function() {
      var q = searchInput.value.toLowerCase();
      body.querySelectorAll('.filter-value-item').forEach(function(item) {
        item.style.display = q ? (item.textContent.toLowerCase().includes(q) ? '' : 'none') : '';
      });
    });
  }

  body.querySelectorAll('[name="' + checkboxName + '"]').forEach(function(cb) {
    cb.addEventListener('change', function() {
      updateCardFilterCount(body, values.length, checkboxName);
      if (onChangeFn) onChangeFn();
    });
  });
}

function updateCardFilterCount(body, totalValues, checkboxName) {
  var selectedCount = body.querySelectorAll('[name="' + checkboxName + '"]:checked').length;
  var labelEl = body.querySelector('.transform-values-label');
  if (labelEl) labelEl.textContent = totalValues + ' valor(es) | ' + selectedCount + ' sel.';
}

function removeVisualFilterEntry(column, table = '') {
  var visual = selectedReportVisual();
  if (!visual || !visualControlsMatch(visual)) return;
  var targetKey = visualFilterKey({ table: table, column: column });
  visual.visualFilters = normalizeVisualFilters(visual.visualFilters).filter(function(f) {
    return table ? visualFilterKey(f) !== targetKey : f.column !== column;
  });
  if (column in _filterCardExpandedState) {
    _filterCardExpandedState[column] = false;
  }
  renderVisualFilterCards(visual);
  updateVisualFieldDropZones();
  scheduleVisualAutoUpdate('remove-filter');
}

function clearVisualFilter() {
  var visual = selectedReportVisual();
  if (!visual || !visualControlsMatch(visual)) return;
  visual.visualFilters = [];
  _filterCardExpandedState = {};
  updateVisualFieldDropZones();
  renderVisualFilterCards(visual);
  scheduleVisualAutoUpdate('clear-filter');
}

function collectPageFiltersFromCards() {
  var cards = document.querySelectorAll('#pageFilterCards .visual-filter-card');
  var existingByKey = {};
  (state.pageFilters || []).forEach(function(filter) { existingByKey[visualFilterKey(filter)] = filter; });
  var filters = [];
  cards.forEach(function(card) {
    var column = card.dataset.filterColumn;
    if (!column) return;
    var table = card.dataset.filterTable || '';
    var allCbs = card.querySelectorAll('[name="pageFilterValue"]');
    var existing = existingByKey[visualFilterKey({ table: table, column: column })];
    if (!allCbs.length) {
      if (existing && Array.isArray(existing.values) && existing.values.length) filters.push(existing);
      return;
    }
    var checked = Array.from(card.querySelectorAll('[name="pageFilterValue"]:checked')).map(function(cb) { return cb.value; });
    if (checked.length === allCbs.length) return;
    if (!checked.length) return;
    filters.push({ column: column, table: table, values: checked, pageId: state.activeReportPageId });
  });
  return filters;
}

function updateFilterCardBadge(card, activeCount) {
  if (!card) return;
  const header = card.querySelector('.visual-filter-card-header');
  const clearButton = header && header.querySelector('.filter-card-clear');
  let badge = header && header.querySelector('.filter-card-badge');
  if (activeCount > 0) {
    if (!badge) {
      badge = document.createElement('span');
      badge.className = 'filter-card-badge';
      if (clearButton) header.insertBefore(badge, clearButton);
      else header.appendChild(badge);
    }
    badge.textContent = String(activeCount);
    badge.title = activeCount + ' valor(es) selecionado(s)';
  } else if (badge) {
    badge.remove();
  }
}

function collectAllPagesFiltersFromCards() {
  var cards = document.querySelectorAll('#allPagesFilterCards .visual-filter-card');
  var existingByKey = {};
  (state.allPagesFilters || []).forEach(function(filter) { existingByKey[visualFilterKey(filter)] = filter; });
  var filters = [];
  cards.forEach(function(card) {
    var column = card.dataset.filterColumn;
    if (!column) return;
    var table = card.dataset.filterTable || '';
    var allCbs = card.querySelectorAll('[name="allPagesFilterValue"]');
    var existing = existingByKey[visualFilterKey({ table: table, column: column })];
    if (!allCbs.length) {
      if (existing && Array.isArray(existing.values) && existing.values.length) filters.push(existing);
      return;
    }
    var checked = Array.from(card.querySelectorAll('[name="allPagesFilterValue"]:checked')).map(function(cb) { return cb.value; });
    if (checked.length === allCbs.length) return;
    if (!checked.length) return;
    filters.push({ column: column, table: table, values: checked });
  });
  return filters;
}

function renderPageFilterCards() {
  var container = document.getElementById('pageFilterCards');
  if (!container) return;
  var filters = state.pageFilters || [];
  var columns = state.builderColumns || [];
  var filterMap = {};
  filters.forEach(function(f) { filterMap[f.column] = f; });

  container.innerHTML = '';
  filters.forEach(function(f) {
    var colName = f.column;
    var filterTable = f.table || (($('#builderTableSelect') && $('#builderTableSelect').value) || '');
    var col = columns.find(function(c) { return c.name === colName && String(c.table || filterTable) === String(filterTable); });
    var type = col ? (col.columnType || col.dataType || '') : '';
    var kind = col && isNumericColumn(col) ? 'numérico' : (/date|time/i.test(String(type)) ? 'data' : 'texto');
    var icon = kind === 'numérico' ? '∑' : (kind === 'data' ? '◷' : 'abc');
    var isExpanded = Boolean(_filterCardExpandedState['page_' + colName]);

    var card = document.createElement('div');
    card.className = 'visual-filter-card' + (isExpanded ? ' expanded' : ' collapsed') + ' filter-active';
    card.dataset.filterColumn = colName;
    card.dataset.filterTable = filterTable;

    var activeCount = (f.values || []).length || 0;
    var badgeHtml = activeCount > 0 ? '<span class="filter-card-badge" title="' + activeCount + ' valor(es) selecionado(s)">' + activeCount + '</span>' : '';

    card.innerHTML = '<div class="visual-filter-card-header">' +
      '<span class="filter-card-caret">' + (isExpanded ? '▾' : '▸') + '</span>' +
      '<i class="field-type-icon filter-type-icon">' + escapeHtml(icon) + '</i>' +
      '<span class="filter-card-title" title="' + escapeHtml(colName) + '">' + escapeHtml(colName) + '</span>' +
      badgeHtml +
      '<button type="button" class="filter-card-clear" data-clear-page-filter-entry="' + escapeHtml(colName) + '" title="Remover filtro">✕</button>' +
      '</div>' +
      '<div class="visual-filter-card-body"' + (isExpanded ? '' : ' style="display:none"') + '>' +
      '<div class="empty-state small filter-card-loading">Carregando valores...</div>' +
      '</div>';
    container.appendChild(card);

    if (isExpanded) {
      loadPageFilterCardValues(card, colName, f.values || [], filterTable);
    }

    var header = card.querySelector('.visual-filter-card-header');
    if (header) {
      header.addEventListener('click', function(ev) {
        if (ev.target.closest('[data-clear-page-filter-entry]')) return;
        ev.stopPropagation();
        var targetCard = ev.currentTarget.closest('.visual-filter-card');
        if (!targetCard) return;
        var col = targetCard.dataset.filterColumn;
        var isCurrentlyExpanded = targetCard.classList.contains('expanded');
        if (isCurrentlyExpanded) {
          targetCard.classList.remove('expanded');
          targetCard.classList.add('collapsed');
          _filterCardExpandedState['page_' + col] = false;
          var caret = targetCard.querySelector('.filter-card-caret');
          if (caret) caret.textContent = '▸';
          var bodyEl = targetCard.querySelector('.visual-filter-card-body');
          if (bodyEl) bodyEl.style.display = 'none';
        } else {
          targetCard.classList.remove('collapsed');
          targetCard.classList.add('expanded');
          _filterCardExpandedState['page_' + col] = true;
          var caret = targetCard.querySelector('.filter-card-caret');
          if (caret) caret.textContent = '▾';
          var bodyEl = targetCard.querySelector('.visual-filter-card-body');
          if (bodyEl) bodyEl.style.display = '';
          var hasCheckboxes = bodyEl && bodyEl.querySelectorAll('[name="pageFilterValue"]').length;
          if (!hasCheckboxes) {
            var tableForFilter = targetCard.dataset.filterTable || '';
            var vals = (state.pageFilters || []).find(function(ff) { return visualFilterKey(ff) === visualFilterKey({ table: tableForFilter, column: col }); });
            loadPageFilterCardValues(targetCard, col, vals ? (vals.values || []) : [], tableForFilter);
          }
        }
      });
    }

    var clearBtn = card.querySelector('.filter-card-clear');
    if (clearBtn) {
      clearBtn.addEventListener('click', function(ev) {
        ev.stopPropagation();
        removePageFilterEntry(colName, filterTable);
      });
    }
  });
}

