function updateVisualFieldDropZones() {
  var viz = String(($('#reportViz') && $('#reportViz').value) || 'table').toLowerCase();
  var isTable = viz === 'table';
  var isMatrix = viz === 'matrix';

  // Desselecionado: limpa todas as zonas de drop e mostra mensagem
  if (state.activeVisualId === null) {
    $$('[data-field-drop-target]').forEach(function(zone) {
      zone.classList.remove('has-field', 'has-pills');
      var text = zone.querySelector('[data-field-drop-value]');
      if (text) text.textContent = '';
      var pills = zone.querySelector('.visual-field-pills');
      if (pills) pills.innerHTML = '';
    });
    var grid = $('#visualFieldDropGrid');
    var heading = $('#visualFieldsHeading');
    var empty = $('#visualFieldsEmpty');
    var aggLabel = $('#aggregationLabel');
    var orderLabel = $('#orderLabel');
    if (grid) grid.style.display = 'none';
    if (empty) empty.style.display = '';
    if (aggLabel) aggLabel.style.display = 'none';
    if (orderLabel) orderLabel.style.display = 'none';
    var filterGrid = document.getElementById('visualFilterDropGrid');
    if (filterGrid) filterGrid.style.display = 'none';
    var filterEmpty = document.getElementById('visualFilterEmpty');
    if (filterEmpty) filterEmpty.style.display = '';
    var filterZone = document.getElementById('visualDropFilter');
    if (filterZone) filterZone.style.display = 'none';
    var filterCards = document.getElementById('visualFilterCards');
    if (filterCards) filterCards.innerHTML = '';
    return;
  }

  // Garante que grid e labels ficam visiveis quando ha visual selecionado
  var grid = $('#visualFieldDropGrid');
  var empty = $('#visualFieldsEmpty');
  if (grid) grid.style.display = '';
  if (empty) empty.style.display = 'none';

  var filterGrid = document.getElementById('visualFilterDropGrid');
  if (filterGrid) filterGrid.style.display = ['textbox', 'image'].includes(viz) ? 'none' : '';
  var filterEmpty = document.getElementById('visualFilterEmpty');
  if (filterEmpty) filterEmpty.style.display = 'none';
  var filterZone = document.getElementById('visualDropFilter');
  if (filterZone) filterZone.style.display = ['textbox', 'image'].includes(viz) ? 'none' : '';

  // Busca o visual ATIVO diretamente pelo ID, sem fallback
  var visual = state.reportVisuals.find(function(item) { return item.id === state.activeVisualId; });
  if (isMatrix && visual) normalizeMatrixVisualBuckets(visual);
  var dimVal = ($('#builderDimensionSelect') && $('#builderDimensionSelect').value) || '';
  var valVal = ($('#builderValueSelect') && $('#builderValueSelect').value) || '';
  var secondaryVal = ($('#builderSecondaryValueSelect') && $('#builderSecondaryValueSelect').value) || '';
  var visualFilters = getVisualFilters(visual);
  var filterVal = visualFilters.length ? visualFilters.map(function(f) { return f.column; }).join(', ') : '';

  // Para tabela, junta tudo num array unico de colunas.
  var columnsList = [];
  if (isTable) {
    var selectedColumnNames = new Set();
    if (visual) {
      normalizeSelectedFields(visual.selectedFields).forEach(function(f) {
        columnsList.push(visualFieldRef(f));
        selectedColumnNames.add(f.name);
      });
      if (visual.dimension && !normalizeSelectedFields(visual.selectedFields).some(function(f) { return f.name === visual.dimension; })) columnsList.push(visual.dimension);
      if (visual.value && !normalizeSelectedFields(visual.selectedFields).some(function(f) { return f.name === visual.value; })) columnsList.push(visual.value);
    }
    // Garante que os valores atuais dos selects ocultos tambem aparecam.
    if (dimVal && !selectedColumnNames.has(dimVal) && !columnsList.includes(dimVal)) columnsList.push(dimVal);
    if (valVal && !selectedColumnNames.has(valVal) && !columnsList.includes(valVal)) columnsList.push(valVal);
  }

  // Para rosca/pizza e outros graficos, coleta medidas dos selectedFields como pills no bucket de valor
  var chartValuePills = [];
  var chartSecondaryPills = [];
  var isChart = !isTable && !isMatrix;
  if (isChart && visual) {
    visualOrderedSelectedFields(visual).forEach(function(f) {
      if (f.name === dimVal) return;
      if (f.name === secondaryVal) return;
      chartValuePills.push(f.name);
    });
    if (secondaryVal && !chartValuePills.includes(secondaryVal)) chartSecondaryPills.push(secondaryVal);
    if (!chartValuePills.length && valVal) chartValuePills.push(valVal);
  }

  var matrixBuckets = isMatrix && visual ? {
    dimension: normalizeVisualBucketNames(visual.matrixRows),
    matrixColumns: normalizeVisualBucketNames(visual.matrixColumns),
    value: normalizeVisualBucketNames(visual.matrixValues)
  } : {};

  $$('[data-field-drop-target]').forEach(function(zone) {
    var kind = zone.dataset.fieldDropTarget;
    var current = '';
    var pillFields = [];
    if (kind === 'dimension' && isTable) {
      current = columnsList.length ? columnsList.join(', ') : '';
      pillFields = columnsList;
    } else if (isMatrix && Object.prototype.hasOwnProperty.call(matrixBuckets, kind)) {
      pillFields = matrixBuckets[kind];
      current = pillFields.length ? pillFields.join(', ') : '';
    } else if (kind === 'dimension') {
      current = dimVal;
      pillFields = isChart && dimVal ? [dimVal] : [];
    } else if (kind === 'value') {
      pillFields = isChart ? chartValuePills : [];
      current = pillFields.length ? pillFields.join(', ') : valVal;
    } else if (kind === 'secondaryValue') {
      pillFields = isChart ? chartSecondaryPills : [];
      current = pillFields.length ? pillFields.join(', ') : secondaryVal;
    } else if (kind === 'filter') {
      current = filterVal;
    }
    zone.classList.toggle('has-field', Boolean(current));
    var text = zone.querySelector('[data-field-drop-value]');
    if (text) {
      if (current) {
        text.textContent = current;
      } else {
        text.textContent = kind === 'dimension'
          ? (isTable ? 'Adicionar colunas ou medidas' : 'Adicionar campos')
          : (kind === 'matrixColumns' ? 'Adicionar campos' : (kind === 'value' ? (isMatrix ? 'Adicionar campos' : 'Adicionar campo num\u00e9rico') : (kind === 'secondaryValue' ? 'Adicionar campo num\u00e9rico (2)' : 'Adicionar campo')));
      }
    }

    // Tabela, matriz e graficos (rosca/pizza) usam pills individuais.
    if (pillFields.length && ((kind === 'dimension' && isTable) || isMatrix || isChart)) {
      zone.classList.add('has-pills');
      var pillsContainer = zone.querySelector('.visual-field-pills');
      if (!pillsContainer) {
        pillsContainer = document.createElement('div');
        pillsContainer.className = 'visual-field-pills';
        zone.insertBefore(pillsContainer, zone.querySelector('.drop-clear') || null);
      }
      pillsContainer.innerHTML = pillFields.map(function(fieldRef, idx) {
        var sf = selectedVisualFieldByRef(visual.selectedFields, fieldRef);
        var displayName = (sf && sf.displayName) || (sf && sf.name) || fieldRef;
        return '<div class="visual-field-pill" draggable="true" data-pill-field="' + escapeHtml(fieldRef) + '" data-pill-index="' + idx + '" data-pill-bucket="' + escapeHtml(kind) + '">' +
          '<span class="pill-name">' + escapeHtml(displayName) + '</span>' +
          '<button type="button" class="pill-menu-btn" data-pill-menu="' + escapeHtml(fieldRef) + '" title="Op\u00e7\u00f5es da coluna">\u25bc</button>' +
          '<button type="button" class="pill-remove" data-remove-pill="' + escapeHtml(fieldRef) + '" title="Remover ' + escapeHtml(displayName) + '">&times;</button>' +
        '</div>';
      }).join('');
      // Oculta o <strong> placeholder e o drop-clear nativo em favor dos pills
      if (text) text.style.display = 'none';
      var clearBtn = zone.querySelector('.drop-clear');
      if (clearBtn) clearBtn.style.display = 'none';
    } else {
      zone.classList.remove('has-pills');
      // Remove pills se existirem (ex: mudou de tabela/matriz para grafico)
      var pillsContainer = zone.querySelector('.visual-field-pills');
      if (pillsContainer) pillsContainer.innerHTML = '';
      if (text) text.style.display = '';
      var clearBtn = zone.querySelector('.drop-clear');
      if (clearBtn) clearBtn.style.display = '';
    }
  });

  // Liga eventos de reordenacao e remocao nos pills
  bindVisualFieldPillEvents();
}

function bindVisualFieldPillEvents() {
  $$('.visual-field-pill').forEach(function(pill) {
    if (pill.dataset.pillBound === '1') return;
    pill.dataset.pillBound = '1';

    // Remove button
    var removeBtn = pill.querySelector('[data-remove-pill]');
    if (removeBtn) {
      removeBtn.addEventListener('click', function(ev) {
        ev.stopPropagation();
        ev.preventDefault();
        var fieldName = removeBtn.dataset.removePill;
        if (removeBtn.dataset.removePillType === 'filter') {
          removeVisualFilterEntry(fieldName);
        } else {
          removePillFromVisual(fieldName, pill.dataset.pillBucket || '');
        }
      });
    }

    // Filter pills don't support drag/drop reorder
    if (pill.dataset.pillType === 'filter') {
      // ▼ dropdown menu button for filter pills
      var menuBtn = pill.querySelector('.pill-menu-btn');
      if (menuBtn) {
        menuBtn.addEventListener('click', function(ev) {
          ev.stopPropagation();
          ev.preventDefault();
          togglePillMenu(pill.dataset.pillField, menuBtn);
        });
      }
      return;
    }

    // Drag to reorder
    pill.addEventListener('dragstart', function(ev) {
      ev.dataTransfer.setData('text/biwa-pill-field', pill.dataset.pillField || '');
      ev.dataTransfer.setData('text/biwa-pill-index', pill.dataset.pillIndex || '');
      ev.dataTransfer.setData('text/biwa-pill-bucket', pill.dataset.pillBucket || '');
      ev.dataTransfer.effectAllowed = 'move';
      pill.classList.add('dragging-pill');
      setTimeout(function() { pill.classList.remove('dragging-pill'); }, 0);
    });

    pill.addEventListener('dragend', function(ev) {
      pill.classList.remove('dragging-pill');
      $$('.visual-field-pill').forEach(function(p) { p.classList.remove('pill-drag-over'); });
    });

    pill.addEventListener('dragover', function(ev) {
      ev.preventDefault();
      var hasCustomType = false;
      try { hasCustomType = ev.dataTransfer.types.some ? ev.dataTransfer.types.some(function(t) { return t === 'text/biwa-pill-field'; }) : (Array.prototype.indexOf.call(ev.dataTransfer.types, 'text/biwa-pill-field') >= 0); } catch(e) {}
      if (!hasCustomType) return;
      ev.dataTransfer.dropEffect = 'move';
      var dragPillField = ev.dataTransfer.getData('text/biwa-pill-field') || '';
      if (!dragPillField || dragPillField === pill.dataset.pillField) return;
      pill.classList.add('pill-drag-over');
    });

    pill.addEventListener('dragleave', function() {
      pill.classList.remove('pill-drag-over');
    });

    pill.addEventListener('drop', function(ev) {
      ev.preventDefault();
      ev.stopPropagation();
      pill.classList.remove('pill-drag-over');
      var fromField = ev.dataTransfer.getData('text/biwa-pill-field');
      var toField = pill.dataset.pillField;
      if (!fromField || fromField === toField) return;

      // Reordena no selectedFields do visual e no style.columnOrder
      var visual = selectedReportVisual();
      if (!visual || !visualControlsMatch(visual)) return;
      var fromBucket = ev.dataTransfer.getData('text/biwa-pill-bucket') || '';
      var toBucket = pill.dataset.pillBucket || '';
      if (String(visual.visualization || '').toLowerCase() === 'matrix' && fromBucket && fromBucket === toBucket) {
        var matrixBucketProperty = fromBucket === 'dimension' ? 'matrixRows' : (fromBucket === 'matrixColumns' ? 'matrixColumns' : 'matrixValues');
        var bucketFields = normalizeVisualBucketNames(visual[matrixBucketProperty]);
        var bucketFromPos = bucketFields.indexOf(fromField);
        var bucketToPos = bucketFields.indexOf(toField);
        if (bucketFromPos < 0 || bucketToPos < 0) return;
        bucketFields.splice(bucketToPos, 0, bucketFields.splice(bucketFromPos, 1)[0]);
        visual[matrixBucketProperty] = bucketFields;
        normalizeMatrixVisualBuckets(visual);
        updateVisualFieldDropZones();
        renderVisualFromCachedRows(visual);
        return;
      }
      var fields = normalizeSelectedFields(visual.selectedFields);
      var fromPos = fields.findIndex(function(f) { return visualFieldRef(f) === fromField || f.name === fromField; });
      var toPos = fields.findIndex(function(f) { return visualFieldRef(f) === toField || f.name === toField; });
      if (fromPos < 0 || toPos < 0) return;
      var moved = fields.splice(fromPos, 1)[0];
      fields.splice(toPos, 0, moved);
      visual.selectedFields = fields;

      // Atualiza columnOrder no style
      if (!visual.style) visual.style = {};
      var columnOrder = fields.map(visualFieldRef);
      visual.style.columnOrder = columnOrder;

      // Atualiza selectedFields no visual
      reapplyPillOrderToVisual();
      updateVisualFieldDropZones();
      if (!reorderRenderedVisualTableColumns(visual)) renderVisualFromCachedRows(visual);
    });

    // ▼ dropdown menu button
    var menuBtn = pill.querySelector('.pill-menu-btn');
    if (menuBtn) {
      menuBtn.addEventListener('click', function(ev) {
        ev.stopPropagation();
        ev.preventDefault();
        togglePillMenu(pill.dataset.pillField, menuBtn);
      });
    }
  });
}

function togglePillMenu(fieldName, btnElement) {
  // If menu for this field is already open, close it (toggle off)
  var openMenus = document.querySelectorAll('.pill-context-menu');
  for (var m = 0; m < openMenus.length; m++) {
    if (openMenus[m].getAttribute('data-pill-menu-field') === fieldName) {
      closeAllPillMenus();
      return;
    }
  }
  closeAllPillMenus();
  if (!fieldName || !btnElement) return;

  // Check if this is a filter pill
  var pillEl = btnElement.closest('.visual-field-pill');
  var isFilter = pillEl && pillEl.dataset.pillType === 'filter';

  if (isFilter) {
    showFilterPillMenu(fieldName, btnElement);
    return;
  }

  var visual = activeVisual();
  if (!visual) return;
  var fields = normalizeSelectedFields(visual.selectedFields);
  var idx = fields.findIndex(function(f) { return visualFieldRef(f) === fieldName || f.name === fieldName; });
  if (idx < 0) return;
  var sf = fields[idx];

  var menu = document.createElement('div');
  menu.className = 'pill-context-menu';
  menu.setAttribute('data-pill-menu-field', fieldName);

  var currentAgg = (sf && sf.aggregation) || '';

  var aggOptions = [
    { value: '',            label: 'N\u00e3o resumir' },
    { value: 'FIRST',       label: 'Primeiro' },
    { value: 'LAST',        label: '\u00daltimo' },
    { value: 'DISTINCTCOUNT', label: 'Contagem (distinta)' },
    { value: 'COUNT',       label: 'Contagem' }
  ];

  function aggRadio(opt) {
    var checked = currentAgg === opt.value ? ' checked' : '';
    return '<button type="button" class="pill-menu-item pill-menu-radio' + checked + '" data-pill-action="set-aggregation" data-pill-field="' + escapeHtml(fieldName) + '" data-agg-value="' + escapeHtml(opt.value) + '"><span class="pill-radio-dot"></span>' + escapeHtml(opt.label) + '</button>';
  }

  var items = [];
  items.push('<button type="button" class="pill-menu-item danger" data-pill-action="remove" data-pill-field="' + escapeHtml(fieldName) + '">\u2715 Remover campo</button>');
  items.push('<button type="button" class="pill-menu-item" data-pill-action="rename" data-pill-field="' + escapeHtml(fieldName) + '">\u270E Renomear coluna neste visual</button>');
  if (['table', 'matrix'].includes(String(visual.visualization || '').toLowerCase()) && (String(sf.type || '').toLowerCase() === 'measure' || measureFieldName(sf.name))) {
    items.push('<button type="button" class="pill-menu-item" data-pill-action="duplicate-measure" data-pill-field="' + escapeHtml(fieldName) + '">\u29c9 Duplicar medida no visual</button>');
  }
  items.push('<button type="button" class="pill-menu-item" data-pill-action="instance-format" data-pill-field="' + escapeHtml(fieldName) + '">123 Formato desta inst\u00e2ncia</button>');
  items.push('<div class="pill-menu-separator"></div>');

  // Formatação condicional submenu
  items.push('<button type="button" class="pill-menu-item pill-menu-has-sub" data-pill-action="toggle-sub" data-sub="cond-format"><span>Formata\u00e7\u00e3o condicional</span><span class="pill-sub-arrow">\u25b6</span></button>');

  items.push('<div class="pill-menu-separator"></div>');

  // Aggregation radio group
  aggOptions.forEach(function(opt) {
    items.push(aggRadio(opt));
  });

  items.push('<div class="pill-menu-separator"></div>');

  // Mostrar valor como submenu
  items.push('<button type="button" class="pill-menu-item pill-menu-has-sub" data-pill-action="toggle-sub" data-sub="show-value-as"><span>Mostrar valor como</span><span class="pill-sub-arrow">\u25b6</span></button>');

  menu.innerHTML = items.join('');
  document.body.appendChild(menu);

  // Position the menu relative to the button, keeping it inside the viewport
  var rect = btnElement.getBoundingClientRect();
  var menuHeight = menu.scrollHeight || menu.offsetHeight || 300;
  var menuWidth = menu.offsetWidth || 240;
  var viewportW = window.innerWidth;
  var viewportH = window.innerHeight;
  var margin = 8;

  // Horizontal: prefer aligned with button left edge, clamp within viewport
  var menuLeft = Math.min(Math.max(rect.left, margin), viewportW - menuWidth - margin);

  // Vertical: try below the button first, flip above if it would overflow
  var spaceBelow = viewportH - rect.bottom - margin;
  var spaceAbove = rect.top - margin;
  var menuTop;
  if (spaceBelow >= menuHeight || spaceBelow >= spaceAbove) {
    // Enough space below, or more space below than above
    menuTop = rect.bottom + 4;
    // Clamp so it doesn't go past the viewport bottom (scroll will handle the rest via max-height)
    if (menuTop + menuHeight > viewportH - margin) {
      menuTop = viewportH - menuHeight - margin;
    }
  } else {
    // Not enough space below, flip above
    menuTop = rect.top - menuHeight - 4;
  }
  // Never let the menu go above the viewport
  if (menuTop < margin) menuTop = margin;

  menu.style.left = menuLeft + 'px';
  menu.style.top = menuTop + 'px';

  // Bind menu item actions
  menu.querySelectorAll('.pill-menu-item[data-pill-action]').forEach(function(item) {
    item.addEventListener('click', function(ev) {
      ev.stopPropagation();
      var action = item.dataset.pillAction;
      var fName = item.dataset.pillField;

      if (action === 'remove') {
        removePillFromVisual(fName);
        closeAllPillMenus();
      } else if (action === 'rename') {
        renamePillField(fName);
        closeAllPillMenus();
      } else if (action === 'duplicate-measure') {
        duplicateVisualMeasureInstance(fName);
        closeAllPillMenus();
      } else if (action === 'instance-format') {
        openVisualFieldInstanceFormat(fName);
        closeAllPillMenus();
      } else if (action === 'set-aggregation') {
        setPillAggregation(fName, item.dataset.aggValue);
        closeAllPillMenus();
      } else if (action === 'set-show-value-as') {
        setPillShowValueAs(fName, item.dataset.showasValue);
        closeAllPillMenus();
      } else if (action === 'toggle-sub') {
        togglePillSubmenu(item, menu);
      } else if (action === 'cond-format') {
        applyPillConditionalFormat(fName, item.dataset.cfType);
        closeAllPillMenus();
      }
    });
  });

  // Close menu on outside click
  setTimeout(function() {
    document.addEventListener('click', closeAllPillMenusOnOutside, { once: true });
  }, 0);
}

function showFilterPillMenu(fieldName, btnElement) {
  var menu = document.createElement('div');
  menu.className = 'pill-context-menu';
  menu.setAttribute('data-pill-menu-field', fieldName);

  var items = [];
  items.push('<button type="button" class="pill-menu-item" data-pill-action="edit-filter" data-pill-field="' + escapeHtml(fieldName) + '">\u270E Editar filtro</button>');
  items.push('<div class="pill-menu-separator"></div>');
  items.push('<button type="button" class="pill-menu-item danger" data-pill-action="clear-filter" data-pill-field="' + escapeHtml(fieldName) + '">\u2715 Remover filtro</button>');

  menu.innerHTML = items.join('');
  document.body.appendChild(menu);

  // Position
  var rect = btnElement.getBoundingClientRect();
  var menuHeight = menu.scrollHeight || menu.offsetHeight || 120;
  var menuWidth = menu.offsetWidth || 200;
  var viewportW = window.innerWidth;
  var viewportH = window.innerHeight;
  var margin = 8;
  var menuLeft = Math.min(Math.max(rect.left, margin), viewportW - menuWidth - margin);
  var spaceBelow = viewportH - rect.bottom - margin;
  var spaceAbove = rect.top - margin;
  var menuTop;
  if (spaceBelow >= menuHeight || spaceBelow >= spaceAbove) {
    menuTop = rect.bottom + 4;
    if (menuTop + menuHeight > viewportH - margin) menuTop = viewportH - menuHeight - margin;
  } else {
    menuTop = rect.top - menuHeight - 4;
  }
  if (menuTop < margin) menuTop = margin;
  menu.style.left = menuLeft + 'px';
  menu.style.top = menuTop + 'px';

  menu.querySelectorAll('.pill-menu-item').forEach(function(item) {
    item.addEventListener('click', function(ev) {
      ev.stopPropagation();
      var action = item.dataset.pillAction;
      if (action === 'edit-filter') {
        var filterSection = document.getElementById('visualFilterCards') || document.querySelector('[data-visual-pane-section="build"]');
        if (filterSection) filterSection.scrollIntoView({ behavior: 'smooth', block: 'center' });
      } else if (action === 'clear-filter') {
        removeVisualFilterEntry(fieldName);
      }
      closeAllPillMenus();
    });
  });

  setTimeout(function() {
    document.addEventListener('click', closeAllPillMenusOnOutside, { once: true });
  }, 0);
}

function closeAllPillMenusOnOutside(ev) {
  var menu = document.querySelector('.pill-context-menu');
  var flyout = document.querySelector('.pill-flyout-menu');
  var clickedInside = (menu && menu.contains(ev.target)) || (flyout && flyout.contains(ev.target));
  if (!clickedInside) {
    closeAllPillMenus();
  } else {
    document.addEventListener('click', closeAllPillMenusOnOutside, { once: true });
  }
}

function closeAllPillMenus() {
  var menus = document.querySelectorAll('.pill-context-menu');
  menus.forEach(function(m) { m.remove(); });
  closeFlyoutMenu();
}

function closeFlyoutMenu() {
  var flyouts = document.querySelectorAll('.pill-flyout-menu');
  flyouts.forEach(function(f) { f.remove(); });
}

function togglePillSubmenu(btn, menu) {
  var subName = btn.dataset.sub;
  var arrow = btn.querySelector('.pill-sub-arrow');

  // Close any existing flyout
  var existingFlyout = document.querySelector('.pill-flyout-menu');
  if (existingFlyout) {
    var existingSub = existingFlyout.getAttribute('data-flyout-sub');
    // If clicking the same submenu, just close it (toggle off)
    if (existingSub === subName) {
      closeFlyoutMenu();
      // Reset arrow on the triggering button
      var allArrows = menu.querySelectorAll('.pill-sub-arrow');
      allArrows.forEach(function(a) { a.textContent = '\u25b6'; });
      return;
    }
    closeFlyoutMenu();
  }

  // Reset all arrows
  menu.querySelectorAll('.pill-sub-arrow').forEach(function(a) { a.textContent = '\u25b6'; });
  if (arrow) arrow.textContent = '\u25bc';

  // Build flyout content based on submenu type
  var visual = activeVisual();
  var fieldName = menu.getAttribute('data-pill-menu-field');
  var fields = normalizeSelectedFields(visual && visual.selectedFields);
  var sf = fields.find(function(f) { return f.name === fieldName; });
  var flyoutItems = [];

  if (subName === 'cond-format') {
    flyoutItems.push('<button type="button" class="pill-menu-item" data-pill-action="cond-format" data-pill-field="' + escapeHtml(fieldName) + '" data-cf-type="fontColor">Cor da fonte</button>');
    flyoutItems.push('<button type="button" class="pill-menu-item" data-pill-action="cond-format" data-pill-field="' + escapeHtml(fieldName) + '" data-cf-type="bgColor">Cor do fundo</button>');
    flyoutItems.push('<button type="button" class="pill-menu-item" data-pill-action="cond-format" data-pill-field="' + escapeHtml(fieldName) + '" data-cf-type="dataBar">Barras de dados</button>');
  } else if (subName === 'show-value-as') {
    var currentShowAs = (sf && sf.showValueAs) || '';
    var showValueAsOptions = [
      { value: '',                  label: 'Nenhum c\u00e1lculo' },
      { value: 'PCT_GRAND_TOTAL',   label: 'Porcentagem do total geral' },
      { value: 'PCT_COLUMN_TOTAL',  label: 'Porcentagem do total da coluna' },
      { value: 'PCT_ROW_TOTAL',     label: 'Porcentagem do total da linha' }
    ];
    showValueAsOptions.forEach(function(opt) {
      var checked = currentShowAs === opt.value ? ' checked' : '';
      flyoutItems.push('<button type="button" class="pill-menu-item pill-menu-radio' + checked + '" data-pill-action="set-show-value-as" data-pill-field="' + escapeHtml(fieldName) + '" data-showas-value="' + escapeHtml(opt.value) + '"><span class="pill-radio-dot"></span>' + escapeHtml(opt.label) + '</button>');
    });
  }

  if (!flyoutItems.length) return;

  var flyout = document.createElement('div');
  flyout.className = 'pill-flyout-menu';
  flyout.setAttribute('data-flyout-sub', subName);
  flyout.innerHTML = flyoutItems.join('');
  document.body.appendChild(flyout);

  // Position flyout to the right of the triggering menu item
  var btnRect = btn.getBoundingClientRect();
  var flyoutLeft = btnRect.right + 4;
  var flyoutTop = btnRect.top - 4;
  var flyoutHeight = flyout.scrollHeight || flyout.offsetHeight || 120;
  var flyoutWidth = flyout.offsetWidth || 200;
  var viewportW = window.innerWidth;
  var viewportH = window.innerHeight;
  var margin = 8;

  // If flyout would go off-screen to the right, flip to the left
  if (flyoutLeft + flyoutWidth > viewportW - margin) {
    flyoutLeft = btnRect.left - flyoutWidth - 4;
  }
  // Clamp within viewport
  if (flyoutLeft < margin) flyoutLeft = margin;
  if (flyoutTop + flyoutHeight > viewportH - margin) {
    flyoutTop = viewportH - flyoutHeight - margin;
  }
  if (flyoutTop < margin) flyoutTop = margin;

  flyout.style.left = flyoutLeft + 'px';
  flyout.style.top = flyoutTop + 'px';

  // Bind actions on flyout items
  flyout.querySelectorAll('.pill-menu-item[data-pill-action]').forEach(function(item) {
    item.addEventListener('click', function(ev) {
      ev.stopPropagation();
      var action = item.dataset.pillAction;
      var fName = item.dataset.pillField;
      if (action === 'cond-format') {
        applyPillConditionalFormat(fName, item.dataset.cfType);
      } else if (action === 'set-show-value-as') {
        setPillShowValueAs(fName, item.dataset.showasValue);
      }
      closeAllPillMenus();
      closeFlyoutMenu();
    });
  });
}

function setPillAggregation(fieldName, aggValue) {
  var visual = selectedReportVisual();
  if (!visual || !visualControlsMatch(visual) || !fieldName) return;
  var fields = normalizeSelectedFields(visual.selectedFields);
  var target = selectedVisualFieldByRef(fields, fieldName);
  fields.forEach(function(f) {
    if (target && visualFieldRef(f) === visualFieldRef(target)) f.aggregation = aggValue || null;
  });
  visual.selectedFields = fields;
  if (aggValue && aggValue !== '') {
    // Se definiu agregação, move para o bucket Valores se ainda não estiver
    var valSel = $('#builderValueSelect');
    var sourceName = target ? target.name : fieldName;
    if (valSel && valSel.value !== sourceName) {
      // Mantém no dimension mas também adiciona como value
      if (!visual.value || visual.value === sourceName) {
        visual.value = sourceName;
        if (valSel) valSel.value = sourceName;
        var aggMap = { FIRST: 'FIRST', LAST: 'LAST', DISTINCTCOUNT: 'DISTINCTCOUNT', COUNT: 'COUNT' };
        visual.aggregation = aggMap[aggValue] || 'SUM';
        var aggSel = $('#builderAggregationSelect');
        if (aggSel && aggMap[aggValue]) aggSel.value = aggMap[aggValue];
      }
    }
  }
  updateVisualFieldDropZones();
  scheduleVisualAutoUpdate('set-aggregation');
}

function setPillShowValueAs(fieldName, showAsValue) {
  var visual = selectedReportVisual();
  if (!visual || !visualControlsMatch(visual) || !fieldName) return;
  var fields = normalizeSelectedFields(visual.selectedFields);
  var target = selectedVisualFieldByRef(fields, fieldName);
  fields.forEach(function(f) {
    if (target && visualFieldRef(f) === visualFieldRef(target)) f.showValueAs = showAsValue || null;
  });
  visual.selectedFields = fields;
  updateVisualFieldDropZones();
  scheduleVisualAutoUpdate('set-show-value-as');
}

function applyPillConditionalFormat(fieldName, cfType) {
  var visual = selectedReportVisual();
  if (!visual || !visualControlsMatch(visual) || !fieldName) return;
  var selected = selectedVisualFieldByRef(visual.selectedFields, fieldName);
  openVisualColumnFormatEditor(selected ? visualFieldRef(selected) : fieldName);
  const focusTarget = cfType === 'dataBar'
    ? $('#visualColumnDataBarsEnabled')
    : (cfType === 'bgColor' ? $('#visualColumnDefaultBgColor') : $('#visualColumnDefaultTextColor'));
  if (focusTarget) setTimeout(() => focusTarget.focus(), 180);
}

function openVisualFieldInstanceFormat(fieldRef) {
  var visual = selectedReportVisual();
  if (!visual || !visualControlsMatch(visual) || !fieldRef) return;
  var fields = normalizeSelectedFields(visual.selectedFields);
  var field = selectedVisualFieldByRef(fields, fieldRef);
  if (!field) return;
  var format = normalizeVisualFieldFormat(field.format) || { type: 'decimal', decimalPlaces: 2, prefix: '', suffix: '', percentOfTotal: false };
  var overlay = showSimpleModal(`
    <div class="form-grid compact visual-instance-format-form">
      <label>Formato
        <select id="visualInstanceFormatType">
          <option value="decimal">N\u00famero decimal</option>
          <option value="integer">N\u00famero inteiro</option>
          <option value="currency">Moeda (R$)</option>
          <option value="percentage">Percentual</option>
        </select>
      </label>
      <label>Casas decimais<input id="visualInstanceDecimalPlaces" type="number" min="0" max="10" step="1" value="${Number(format.decimalPlaces == null ? 2 : format.decimalPlaces)}" /></label>
      <label>Alinhamento
        <select id="visualInstanceAlignment"><option value="">Autom\u00e1tico</option><option value="left">Esquerda</option><option value="center">Centro</option><option value="right">Direita</option></select>
      </label>
      <label>Largura (px)<input id="visualInstanceWidth" type="number" min="32" max="1200" step="1" value="${field.width || ''}" placeholder="Autom\u00e1tica" /></label>
      <label class="check-label"><input id="visualInstancePercentTotal" type="checkbox" ${format.percentOfTotal ? 'checked' : ''} /> Calcular percentual do total</label>
    </div>
    <p class="meta" style="margin:8px 0 14px">A apar\u00eancia desta coluna \u00e9 independente das outras inst\u00e2ncias da medida. Alterar apenas a apar\u00eancia n\u00e3o executa uma nova consulta.</p>
    <div style="display:flex;justify-content:space-between;gap:8px;flex-wrap:wrap">
      <button type="button" class="btn ghost" id="resetVisualInstanceFormatBtn">Restaurar padr\u00e3o</button>
      <span style="display:flex;gap:8px"><button type="button" class="btn ghost" id="cancelVisualInstanceFormatBtn">Cancelar</button><button type="button" class="btn primary" id="applyVisualInstanceFormatBtn">Aplicar</button></span>
    </div>
  `, 'Formatar: ' + (field.displayName || field.name));
  var typeInput = overlay.querySelector('#visualInstanceFormatType');
  var alignmentInput = overlay.querySelector('#visualInstanceAlignment');
  if (typeInput) typeInput.value = format.type === 'number' ? 'decimal' : format.type;
  if (alignmentInput) alignmentInput.value = field.alignment || '';
  function saveInstanceFormat(reset) {
    var index = fields.findIndex(function(item) { return visualFieldRef(item) === visualFieldRef(field); });
    if (index < 0) return;
    if (reset) {
      fields[index].format = null;
      fields[index].alignment = null;
      fields[index].width = null;
    } else {
      var type = String(typeInput && typeInput.value || 'decimal');
      var places = Math.max(0, Math.min(10, Math.round(Number(overlay.querySelector('#visualInstanceDecimalPlaces').value) || 0)));
      fields[index].format = {
        type: type,
        decimalPlaces: type === 'integer' ? 0 : places,
        prefix: type === 'currency' ? 'R$ ' : '',
        suffix: type === 'percentage' ? '%' : '',
        percentOfTotal: Boolean(overlay.querySelector('#visualInstancePercentTotal').checked)
      };
      fields[index].alignment = String(alignmentInput && alignmentInput.value || '') || null;
      var width = Number(overlay.querySelector('#visualInstanceWidth').value);
      fields[index].width = Number.isFinite(width) && width >= 32 ? Math.max(32, Math.min(1200, Math.round(width))) : null;
    }
    visual.selectedFields = fields;
    visual.style = normalizeVisualStyle(visual.style);
    var instanceRef = visualFieldRef(fields[index]);
    if (fields[index].width !== null) visual.style.columnWidths[instanceRef] = fields[index].width;
    else delete visual.style.columnWidths[instanceRef];
    updateVisualFieldDropZones();
    renderVisualFromCachedRows(visual);
    overlay.remove();
    toast(reset ? 'Formato da inst\u00e2ncia restaurado.' : 'Formato da inst\u00e2ncia aplicado.');
  }
  overlay.querySelector('#applyVisualInstanceFormatBtn').addEventListener('click', function() { saveInstanceFormat(false); });
  overlay.querySelector('#resetVisualInstanceFormatBtn').addEventListener('click', function() { saveInstanceFormat(true); });
  overlay.querySelector('#cancelVisualInstanceFormatBtn').addEventListener('click', function() { overlay.remove(); });
}

function renamePillField(fieldName) {
  var visual = selectedReportVisual();
  if (!visual || !visualControlsMatch(visual) || !fieldName) return;
  var fields = normalizeSelectedFields(visual.selectedFields);
  var sf = selectedVisualFieldByRef(fields, fieldName);
  var currentName = (sf && sf.displayName) || (sf && sf.name) || fieldName;
  var overlay = showSimpleModal(`
    <label for="renameVisualColumnInput">Nome exibido no cabeçalho
      <input id="renameVisualColumnInput" type="text" maxlength="120" value="${escapeHtml(currentName)}" autocomplete="off" />
    </label>
    <p class="meta" style="margin:8px 0 14px">O nome da fonte de dados não será alterado.</p>
    <div style="display:flex;justify-content:flex-end;gap:8px">
      <button type="button" class="btn ghost" id="cancelVisualColumnRenameBtn">Cancelar</button>
      <button type="button" class="btn primary" id="applyVisualColumnRenameBtn">Aplicar</button>
    </div>
  `, 'Renomear coluna neste visual');
  var input = overlay.querySelector('#renameVisualColumnInput');
  var applyRename = function() {
    var newName = String(input && input.value || '').trim().slice(0, 120);
    if (!newName) {
      toast('Informe o nome da coluna.', 'error');
      if (input) input.focus();
      return;
    }
    var duplicateName = fields.some(function(f) {
      return visualFieldRef(f) !== visualFieldRef(sf) && String(f.displayName || f.name).trim().toLocaleLowerCase('pt-BR') === newName.toLocaleLowerCase('pt-BR');
    });
    if (duplicateName) {
      toast('Já existe uma coluna com esse nome neste visual.', 'error');
      if (input) input.focus();
      return;
    }
    fields.forEach(function(f) {
      if (visualFieldRef(f) === visualFieldRef(sf)) f.displayName = newName === f.name ? null : newName;
    });
    visual.selectedFields = fields;
    updateVisualFieldDropZones();
    renderVisualFromCachedRows(visual);
    renderVisualTableAlignmentEditor(visual);
    renderVisualColumnFormatEditor(visual);
    overlay.remove();
    toast(newName === fieldName ? 'Nome original da coluna restaurado.' : 'Coluna renomeada neste visual.');
  };
  overlay.querySelector('#applyVisualColumnRenameBtn').addEventListener('click', applyRename);
  overlay.querySelector('#cancelVisualColumnRenameBtn').addEventListener('click', function() { overlay.remove(); });
  if (input) {
    input.addEventListener('keydown', function(ev) {
      if (ev.key === 'Enter') { ev.preventDefault(); applyRename(); }
      if (ev.key === 'Escape') overlay.remove();
    });
    setTimeout(function() { input.focus(); input.select(); }, 0);
  }
}

function removePillFromVisual(fieldName, bucketKind = '') {
  if (!fieldName) return;
  const visual = activeVisual();
  if (!visual || !visualControlsMatch(visual)) return;
  removeSelectedVisualField(fieldName, { allByName: false, reason: 'remove-pill' });
}

// Reaplica a ordem dos pills ao visual (dimension/value selects) apos reordenacao
function reapplyPillOrderToVisual(options = {}) {
  var visual = activeVisual();
  if (!visual || !visualControlsMatch(visual)) return;
  var fields = visualOrderedSelectedFields(visual);
  visual.selectedFields = fields;
  var viz = String(($('#reportViz') && $('#reportViz').value) || (visual && visual.visualization) || 'table').toLowerCase();
  if (viz === 'matrix') {
    normalizeMatrixVisualBuckets(visual);
  } else if (viz === 'table') {
    var dimSel = $('#builderDimensionSelect');
    var valSel = $('#builderValueSelect');
    var dimensionField = fields.find(function(f) {
      return String(f.type || '').toLowerCase() !== 'measure' && !measureFieldName(f.name);
    });
    var measureField = fields.find(function(f) {
      return String(f.type || '').toLowerCase() === 'measure' || measureFieldName(f.name);
    });
    visual.dimension = dimensionField ? dimensionField.name : '';
    visual.value = measureField ? measureField.name : '';
    if (dimSel) dimSel.value = visual.dimension;
    if (valSel) valSel.value = visual.value;
  }
  if (!options.skipSync) syncBuilderFieldChecks();
}

function updateVisualFieldLabels() {
  const viz = String(($('#reportViz') && $('#reportViz').value) || 'table').toLowerCase();
  const isTable = viz === 'table';
  const isMatrix = viz === 'matrix';
  const heading = document.getElementById('visualFieldsHeading');
  const dropDim = document.getElementById('visualDropDimension');
  const dropMatrixColumns = document.getElementById('visualDropMatrixColumns');
  const dropVal = document.getElementById('visualDropValue');
  const dropSecondaryVal = document.getElementById('visualDropSecondaryValue');
  const aggLabel = document.getElementById('aggregationLabel');
  const orderLabel = document.getElementById('orderLabel');
  const isDonut = viz === 'donut';

  if (heading) heading.textContent = isTable ? 'Colunas' : (isMatrix ? 'Campos da matriz' : 'Campos');

  if (dropDim) {
    dropDim.style.display = '';
    const lbl = dropDim.querySelector('.drop-label');
    if (lbl) lbl.textContent = isTable ? 'Colunas' : (isMatrix ? 'Linhas' : 'Eixo');
    const placeholder = dropDim.querySelector('[data-field-drop-value]');
    if (placeholder && placeholder.textContent.trim().startsWith('Adicionar')) {
      placeholder.textContent = isTable ? 'Adicionar colunas' : 'Adicionar campos';
    }
  }

  if (dropMatrixColumns) dropMatrixColumns.style.display = isMatrix ? '' : 'none';
  if (dropVal) dropVal.style.display = isTable ? 'none' : '';
  if (dropSecondaryVal) dropSecondaryVal.style.display = isDonut ? '' : 'none';
  [dropDim, dropMatrixColumns, dropVal, dropSecondaryVal].forEach((drop) => {
    if (drop) drop.classList.toggle('matrix-bucket', isMatrix);
  });

  if (aggLabel) aggLabel.style.display = (isTable || isMatrix) ? 'none' : '';
  if (orderLabel) orderLabel.style.display = (isTable || isMatrix) ? 'none' : '';
}

function assignBuilderField(kind, field, type = '', tableName = '') {
  if (!field) return;
  const mutationStartedAt = performance.now();
  const visual = selectedReportVisual();
  if (!visual || !visualControlsMatch(visual)) return;
  const activeVizType = String((visual && visual.visualization) || (($('#reportViz') && $('#reportViz').value) || 'table')).toLowerCase();
  const hadAssignedFields = visualHasAssignedFields(visual);
  const isNewVisualField = Boolean(visual && !normalizeSelectedFields(visual.selectedFields).some((item) => item.name === field));
  const isMeasure = type === 'measure' || ((state.model && state.model.measures || []).some(function(m) { return m.name === field; }));
  const col = isMeasure ? null : (state.builderColumns || []).find((item) => item.name === field);
  const fieldTable = tableName || (col && col.table) || (($('#builderTableSelect') && $('#builderTableSelect').value) || '');
  const colType = isMeasure ? 'measure' : (col ? (col.columnType || col.dataType || '') : String(type || ''));
  const isNumber = isMeasure || (col ? isNumericColumn(col) : /(int|decimal|double|float|real|numeric|number)/i.test(colType));
  if (!['filter', 'pageFilter', 'allPagesFilter'].includes(kind)) {
    if (visual && fieldTable && (!visual.table || !hadAssignedFields)) visual.table = fieldTable;
    addSelectedVisualField(field, colType, fieldTable);
    visualFieldDebugClient('ADD FIELD TO VISUAL', {
      visualId: visual && visual.id,
      name: field,
      type: colType,
      table: fieldTable,
      success: Boolean(visual && normalizeSelectedFields(visual.selectedFields).some(function(item) { return item.name === field; }))
    });
    if (isNewVisualField && visual) {
      visual.style = normalizeVisualStyle(visual.style);
      delete visual.style.columnWidths[field];
      if (activeVizType === 'table') {
        // columnOrder usa somente a identidade da instancia. Misturar nomes
        // com instanceId fazia o carregamento interpretar o alias legado como
        // uma nova coluna e duplicar medidas ao clicar fora do visual.
        visual.style.columnOrder = visualOrderedSelectedFields(visual).map(visualFieldRef);
      }
    }
  }
  if (kind === 'auto') {
    const viz = (($('#reportViz') && $('#reportViz').value) || (visual && visual.visualization) || 'table');
    if (viz === 'matrix') {
      kind = isNumber ? 'value' : 'dimension';
    } else if (['table','card','kpi'].includes(viz)) {
      kind = isNumber && (($('#builderDimensionSelect') && $('#builderDimensionSelect').value) || '').trim() ? 'value' : (isMeasure ? 'value' : 'dimension');
    } else {
      kind = isNumber ? 'value' : 'dimension';
    }
  }
  if (visual && activeVizType === 'matrix' && ['dimension', 'matrixColumns', 'value'].includes(kind)) {
    const targetProperty = kind === 'dimension' ? 'matrixRows' : (kind === 'matrixColumns' ? 'matrixColumns' : 'matrixValues');
    visual.matrixRows = normalizeVisualBucketNames(visual.matrixRows).filter(function(name) { return name !== field; });
    visual.matrixColumns = normalizeVisualBucketNames(visual.matrixColumns).filter(function(name) { return name !== field; });
    visual.matrixValues = normalizeVisualBucketNames(visual.matrixValues).filter(function(name) { return name !== field; });
    visual[targetProperty].push(field);
  }
  if (kind === 'dimension') {
    const el = $('#builderDimensionSelect');
    if (activeVizType === 'table') {
      if (!visual.dimension) visual.dimension = field;
      if (el) el.value = visual.dimension;
    } else if (el && (!el.value || activeVizType === 'matrix')) {
      el.value = activeVizType === 'matrix' ? normalizeVisualBucketNames(visual.matrixRows)[0] || field : field;
    }
  } else if (kind === 'matrixColumns') {
    if (visual && !visual.dimension) visual.dimension = field;
  } else if (kind === 'value') {
    const el = $('#builderValueSelect');
    if (activeVizType === 'table') {
      if (!visual.value) visual.value = field;
      if (el) el.value = visual.value;
    } else if (el) {
      el.value = activeVizType === 'matrix' ? normalizeVisualBucketNames(visual.matrixValues)[0] || field : field;
    }
  } else if (kind === 'secondaryValue') {
    const el = $('#builderSecondaryValueSelect');
    if (el) el.value = field;
    if (visual) visual.secondaryValue = field;
  } else if (kind === 'filter') {
    var vf = normalizeVisualFilters(visual.visualFilters || []);
    if (!vf.some(function(f) { return visualFilterKey(f) === visualFilterKey({ table: fieldTable, column: field }); })) {
      vf.push({ column: field, table: fieldTable, values: [], availableValues: [], locked: true });
    }
    visual.visualFilters = vf;
    renderVisualFilterCards(visual);
  } else if (kind === 'pageFilter') {
    state.pageFilters = state.pageFilters || [];
    if (!state.pageFilters.some(function(f) { return visualFilterKey(f) === visualFilterKey({ table: fieldTable, column: field }); })) {
      state.pageFilters.push({ column: field, values: [], pageId: state.activeReportPageId, table: fieldTable });
    }
    _filterCardExpandedState['page_' + field] = true;
    renderPageFilterCards();
  } else if (kind === 'allPagesFilter') {
    state.allPagesFilters = state.allPagesFilters || [];
    if (!state.allPagesFilters.some(function(f) { return visualFilterKey(f) === visualFilterKey({ table: fieldTable, column: field }); })) {
      state.allPagesFilters.push({ column: field, values: [], table: fieldTable });
    }
    _filterCardExpandedState['all_' + field] = true;
    renderAllPagesFilterCards();
  }
  if (!['filter', 'pageFilter', 'allPagesFilter'].includes(kind)) {
    normalizeVisualBucketsForType(visual, { preferNumericAggregation: kind === 'value' && isNumber });
    visualFieldDebugClient('VISUAL STATE', {
      visualId: visual && visual.id,
      dimension: visual && visual.dimension,
      value: visual && visual.value,
      fields: normalizeSelectedFields(visual && visual.selectedFields).map(function(item) {
        return { name: item.name, type: item.type, table: item.table, measureId: item.measureId };
      })
    });
    renderVisualFilterCards(visual);
  }
  syncBuilderFieldChecks();
  if (!['filter', 'pageFilter', 'allPagesFilter'].includes(kind)) {
    renderVisualFieldConfigurationImmediately(visual, 'ADD_FIELD', { field, queryRequired: true }, mutationStartedAt);
    scheduleVisualAutoUpdate('assign-field-' + kind, { background: false, mutation: 'ADD_FIELD', field });
  } else {
    scheduleVisualAutoUpdate('assign-field-' + kind);
  }
}

function setupVisualFieldDropZones() {
  $$('[data-field-drop-target]').forEach((zone) => {
    if (zone.dataset.boundDrop === '1') return;
    zone.dataset.boundDrop = '1';
    zone.addEventListener('dragover', (ev) => {
      if (ev.dataTransfer.types.includes('text/biwa-field') || ev.dataTransfer.types.includes('text/biwa-pill-field')) {
        ev.preventDefault();
        zone.classList.add('drag-over');
        ev.dataTransfer.dropEffect = ev.dataTransfer.types.includes('text/biwa-pill-field') ? 'move' : 'copy';
      }
    });
    zone.addEventListener('dragleave', () => zone.classList.remove('drag-over'));
    zone.addEventListener('drop', (ev) => {
      const field = ev.dataTransfer.getData('text/biwa-field');
      const pillField = ev.dataTransfer.getData('text/biwa-pill-field');
      const type = ev.dataTransfer.getData('text/biwa-type');
      const table = ev.dataTransfer.getData('text/biwa-table');
      if (!field && !pillField) return;
      ev.preventDefault();
      zone.classList.remove('drag-over');
      if (pillField) {
        const visual = selectedReportVisual();
        if (!visual || !visualControlsMatch(visual)) return;
        const targetKind = zone.dataset.fieldDropTarget;
        if (visual && String(visual.visualization || '').toLowerCase() === 'matrix' && ['dimension', 'matrixColumns', 'value'].includes(targetKind)) {
          const targetProperty = targetKind === 'dimension' ? 'matrixRows' : (targetKind === 'matrixColumns' ? 'matrixColumns' : 'matrixValues');
          visual.matrixRows = normalizeVisualBucketNames(visual.matrixRows).filter(function(name) { return name !== pillField; });
          visual.matrixColumns = normalizeVisualBucketNames(visual.matrixColumns).filter(function(name) { return name !== pillField; });
          visual.matrixValues = normalizeVisualBucketNames(visual.matrixValues).filter(function(name) { return name !== pillField; });
          visual[targetProperty].push(pillField);
          normalizeMatrixVisualBuckets(visual);
          syncBuilderFieldChecks();
          renderVisualFromCachedRows(visual);
        }
        return;
      }
      assignBuilderField(zone.dataset.fieldDropTarget, field, type, table);
    });
  });
}

function syncBuilderFieldChecks() {
  const dimValue = $('#builderDimensionSelect') && $('#builderDimensionSelect').value;
  const valueValue = $('#builderValueSelect') && $('#builderValueSelect').value;
  const secondaryValue = $('#builderSecondaryValueSelect') && $('#builderSecondaryValueSelect').value;
  const selectedFields = activeVisualSelectedFieldNames();
  var visual = selectedReportVisual();
  var filterNames = new Set(getVisualFilters(visual).map(function(f) { return f.column; }));
  $$('[data-builder-field-check]').forEach((check) => {
    const field = check.dataset.builderFieldCheck;
    check.checked = Boolean(field && (selectedFields.has(field) || field === dimValue || field === valueValue || field === secondaryValue || filterNames.has(field)));
  });
  updateVisualFieldDropZones();
}

function clearVisualField(kind) {
  var visual = selectedReportVisual();
  if (!visual || !visualControlsMatch(visual)) return;
  const startedAt = performance.now();
  var viz = String(visual.visualization || 'table').toLowerCase();
  var isTable = viz === 'table';
  var isMatrix = viz === 'matrix';
  if (kind === 'filter') {
    clearVisualFilter();
    renderVisualFilterCards(visual);
    toast('Filtro removido do visual.');
    return;
  }
  var refs = [];
  if (isMatrix && ['dimension', 'matrixColumns', 'value'].includes(kind)) {
    var bucketProperty = kind === 'dimension' ? 'matrixRows' : (kind === 'matrixColumns' ? 'matrixColumns' : 'matrixValues');
    refs = normalizeVisualBucketNames(visual[bucketProperty]);
  } else if (isTable && kind === 'dimension') {
    refs = normalizeSelectedFields(visual.selectedFields).map(visualFieldRef);
  } else {
    var sourceName = kind === 'dimension'
      ? visual.dimension
      : (kind === 'value' ? visual.value : visual.secondaryValue);
    refs = normalizeSelectedFields(visual.selectedFields)
      .filter(function(field) { return field.name === sourceName; })
      .map(visualFieldRef);
  }
  var mutations = refs.map(function(ref) { return removeVisualFieldState(visual, ref, { allByName: false }); }).filter(Boolean);
  if (!mutations.length) return;
  const needsQuery = mutations.some(function(mutation) { return mutation.needsQuery; });
  cancelVisualInFlightWork(visual.id);
  mutations.forEach(removeVisualFilterCardsForMutation);
  renderVisualFieldConfigurationImmediately(visual, 'REMOVE_FIELD', { field: refs.join(', '), queryRequired: needsQuery, mutation: mutations.length === 1 ? mutations[0] : null }, startedAt);
  if (needsQuery) scheduleVisualAutoUpdate('clear-field', { background: true, mutation: 'REMOVE_FIELD', preserveTotals: !mutations.some(function(mutation) { return mutation.filterChanged; }) });
  else visualFieldPerformanceClient('FIELD MUTATION COMPLETE', { action: 'REMOVE_FIELD', visualId: String(visual.id || ''), field: refs.join(', '), requestCount: 0, background: false });
}


function collapseVisualFormatCards() {
  $$('#visualFormatPane .format-card').forEach((card) => { card.open = false; });
}

function setVisualPaneMode(mode) {
  const allowed = new Set(['build', 'format', 'analytics']);
  const previousMode = state.visualPaneMode;
  state.visualPaneMode = allowed.has(mode) ? mode : 'build';
  if (state.visualPaneMode === 'format') {
    if (previousMode !== 'format') collapseVisualFormatCards();
    const visual = selectedReportVisual();
    if (visual) applyVisualStyleControls(visual);
  }
  $$('[data-visual-pane-tab]').forEach((btn) => {
    const active = btn.dataset.visualPaneTab === state.visualPaneMode;
    btn.classList.toggle('active', active);
    btn.setAttribute('aria-selected', active ? 'true' : 'false');
  });
  $$('[data-visual-pane-section]').forEach((section) => {
    section.classList.toggle('hidden-pane-section', section.dataset.visualPaneSection !== state.visualPaneMode);
  });
}

function toggleBuilderTableCollapse(tableName) {
  const name = String(tableName || '').trim();
  if (!name) return;
  state.builderCollapsedTables = state.builderCollapsedTables || {};
  state.builderCollapsedTables[name] = !state.builderCollapsedTables[name];
  renderBuilderFieldList();
}

function isBuilderTableCollapsed(tableName) {
  return Boolean(state.builderCollapsedTables && state.builderCollapsedTables[String(tableName || '')]);
}

function builderTableHeaderHtml(resource, expanded, attrs = '') {
  const icon = expanded ? '▾' : '▸';
  const type = resource && resource.type === 'view' ? 'view' : 'tabela';
  return `<button type="button" class="field-table-title clean-field-title ${expanded ? 'expanded' : 'collapsed'}" ${attrs} title="${expanded ? 'Ocultar campos' : 'Mostrar campos'}">
    <span class="table-caret">${icon}</span><span class="table-name">${escapeHtml(resource.name || '')}</span><small>${escapeHtml(type)}</small>
  </button>`;
}

function renderBuilderFieldList() {
  const el = $('#builderFieldList');
  if (!el) return;
  const search = ($('#dataSearchInput') && $('#dataSearchInput').value || '').toLowerCase().trim();
  if (state.resourcesLoading) {
    el.className = 'field-list powerbi-field-list empty-state';
    el.textContent = 'Carregando tabelas e views...';
    return;
  }
  if (state.resourcesError) {
    el.className = 'field-list powerbi-field-list empty-state';
    el.innerHTML = `<div class="error-box"><b>Erro ao carregar dados</b><br>${escapeHtml(state.resourcesError)}</div>`;
    return;
  }
  if (!state.resources.length) {
    el.className = 'field-list powerbi-field-list empty-state';
    el.textContent = 'Nenhuma tabela ou view encontrada. Verifique a conexão MySQL e permissões.';
    return;
  }
  const table = $('#builderTableSelect') && $('#builderTableSelect').value;
  const resource = getResource(table) || state.resources[0];
  if (!resource) {
    el.className = 'field-list powerbi-field-list empty-state';
    el.textContent = 'Selecione uma tabela ou view.';
    return;
  }
  const selectedName = resource.name;
  const selectedCollapsed = isBuilderTableCollapsed(selectedName);
  el.className = 'field-list powerbi-field-list powerbi-data-tree';
  var columns = (state.builderColumns || []).filter(function(col) { return !search || String(col.name || '').toLowerCase().includes(search); });
  var selectedColumnsHtml = selectedCollapsed ? '<div class="field-table-collapsed-note">Campos ocultos. Clique no nome da tabela para mostrar.</div>' : (columns.length ? columns.map(function(col) {
    var type = col.columnType || col.dataType || '';
    var kind = isNumericColumn(col) ? 'numérico' : (/date|time/i.test(String(type)) ? 'data' : 'texto');
    var icon = kind === 'numérico' ? '∑' : (kind === 'data' ? '◷' : 'abc');
    return '\n      <label class="field-row clean-field-row enhanced-field-row" draggable="true" data-builder-field-row="' + escapeHtml(col.name) + '" data-builder-field-type="' + escapeHtml(type) + '" data-builder-field-table="' + escapeHtml(col.table || selectedName) + '" title="Arraste para Eixo, Valores ou Filtro">\n        <input type="checkbox" data-builder-field-check="' + escapeHtml(col.name) + '" />\n        <span class="field-name"><i class="field-type-icon">' + escapeHtml(icon) + '</i>' + escapeHtml(col.name) + '</span>\n        <small>' + escapeHtml(kind) + '</small>\n      </label>';
  }).join('') : '<div class="empty-state small">Nenhuma coluna encontrada para a busca.</div>');

  var otherHtml = state.resources.filter(function(item) { return item.name !== selectedName; }).map(function(item) {
    return '\n    ' + builderTableHeaderHtml(item, false, 'data-switch-builder-table="' + escapeHtml(item.name) + '"');
  }).join('');

  var allMeasures = (state.model && state.model.measures ? state.model.measures : []);
  var measures = search ? allMeasures.filter(function(m) { return String(m.name || '').toLowerCase().includes(search); }) : allMeasures;
  var measuresHtml = '\n    <div class="field-table-title clean-field-title ' + (state.builderCollapsedMeasures ? 'collapsed' : 'expanded') + '" style="margin-top:0; cursor:pointer;" data-toggle-measures>\n      <span class="table-caret">' + (state.builderCollapsedMeasures ? '▸' : '▾') + '</span>\n      <span class="table-name">Medidas</span>\n      <button type="button" class="icon-btn mini" data-create-measure-inline title="Nova medida DAX" style="position: static; margin: 0; align-self: center;">+</button>\n    </div>\n    <div class="builder-table-fields ' + (state.builderCollapsedMeasures ? 'collapsed' : '') + '" style="margin-bottom: 10px;">\n      ' + (measures.length ? measures.map(function(m, mi) {
    var tbl = String(m.table || '').trim();
    var tableBadge = tbl ? ' <small class="measure-table-badge">' + escapeHtml(tbl) + '</small>' : '';
    return '\n        <div class="builder-measure-row" data-builder-measure-index="' + mi + '" title="' + escapeHtml((m.table ? m.table + ': ' : '') + (m.formula || '')) + '">\n          <div class="field-row clean-field-row enhanced-field-row" draggable="true" data-builder-field-row="' + escapeHtml(m.name) + '" data-builder-field-type="measure" data-builder-field-table="' + escapeHtml(tbl) + '">\n            <input type="checkbox" data-builder-field-check="' + escapeHtml(m.name) + '" aria-label="Adicionar ou remover a medida ' + escapeHtml(m.name) + ' do visual" />\n            <button type="button" class="field-name measure-edit-trigger" data-builder-measure-open="' + mi + '" title="Editar medida DAX"><i class="field-type-icon">ƒx</i><span>' + escapeHtml(m.name) + '</span></button>\n            <small>DAX' + tableBadge + '</small>\n          </div>\n          <div class="measure-row-actions">\n            <button type="button" class="measure-actions-btn" data-builder-measure-actions="' + mi + '">···</button>\n            <div class="measure-actions-menu" data-builder-measure-menu="' + mi + '" onclick="event.stopPropagation()">\n              <button data-builder-measure-edit="' + mi + '">Editar</button>\n              <button class="danger" data-builder-measure-delete="' + mi + '">Excluir</button>\n            </div>\n          </div>\n        </div>';
  }).join('') : '<div class="empty-state small" style="padding:4px 8px;">Nenhuma medida criada. Use o botao + para criar.</div>') + '\n    </div>\n  ';

  el.innerHTML = '\n    ' + measuresHtml + '\n    ' + builderTableHeaderHtml(resource, !selectedCollapsed, 'data-toggle-builder-table="' + escapeHtml(selectedName) + '"') + '\n    <div class="builder-table-fields ' + (selectedCollapsed ? 'collapsed' : '') + '">' + selectedColumnsHtml + '</div>\n    <div class="other-data-sources powerbi-other-tables">\n      <h4>Tabelas</h4>\n      ' + (otherHtml || '<div class="empty-state small">Nenhuma outra tabela/view.</div>') + '\n    </div>\n  ';
  el.querySelectorAll('[data-builder-measure-open]').forEach(function(button) {
    var measure = measures[Number(button.dataset.builderMeasureOpen)];
    if (measure) button.title = 'Editar medida: ' + String(measure.name || '');
  });
  if (state.activeMeasureIndex >= 0) {
    var selectedRow = el.querySelector('.builder-measure-row[data-builder-measure-index="' + state.activeMeasureIndex + '"]');
    if (selectedRow) selectedRow.classList.add('selected');
  }
  el.querySelectorAll('[data-toggle-builder-table]').forEach((btn) => btn.addEventListener('click', () => toggleBuilderTableCollapse(btn.dataset.toggleBuilderTable)));
  el.querySelectorAll('[data-toggle-measures]').forEach((btn) => btn.addEventListener('click', (ev) => {
    if (ev.target.closest('[data-create-measure-inline]')) return;
    state.builderCollapsedMeasures = !state.builderCollapsedMeasures;
    renderBuilderFieldList();
  }));
  el.querySelectorAll('[data-create-measure-inline]').forEach((btn) => btn.addEventListener('click', (ev) => {
    ev.stopPropagation();
    openDaxMeasureInlineEditor();
  }));
  el.querySelectorAll('[data-builder-measure-actions]').forEach(function(btn) {
    btn.addEventListener('click', function(ev) {
      ev.stopPropagation();
      var idx = btn.dataset.builderMeasureActions;
      var menu = el.querySelector('[data-builder-measure-menu="' + idx + '"]');
      if (!menu) return;
      var open = menu.classList.toggle('open');
      if (open) {
        var close = function(ev2) {
          if (!menu.contains(ev2.target)) {
            menu.classList.remove('open');
            document.removeEventListener('click', close);
          }
        };
        setTimeout(function() { document.addEventListener('click', close); }, 0);
      }
    });
  });
  el.querySelectorAll('[data-builder-measure-edit]').forEach(function(btn) {
    btn.addEventListener('click', function() {
      var idx = Number(btn.dataset.builderMeasureEdit);
      closeAllMeasureMenus();
      openDaxMeasureInlineEditor(idx);
    });
  });
  el.querySelectorAll('[data-builder-measure-delete]').forEach(function(btn) {
    btn.addEventListener('click', function() {
      var idx = Number(btn.dataset.builderMeasureDelete);
      closeAllMeasureMenus();
      state.model.measures.splice(idx, 1);
      renderBuilderFieldList();
      if (typeof renderMeasureList === 'function') renderMeasureList();
      saveModel().catch(function(err) { toast(err.message || 'Erro ao salvar modelo.', 'error'); });
    });
  });
  el.querySelectorAll('[data-switch-builder-table]').forEach((btn) => btn.addEventListener('click', async () => {
    const select = $('#builderTableSelect');
    if (select) select.value = btn.dataset.switchBuilderTable;
    state.builderCollapsedTables[btn.dataset.switchBuilderTable] = false;
    closeMeasureToolsRibbon();
    await loadBuilderColumns(btn.dataset.switchBuilderTable, { updateVisualControls: !visualHasAssignedFields(activeVisual()) });
  }));
  el.querySelectorAll('[data-builder-field-check]').forEach((check) => check.addEventListener('change', () => {
    const field = check.dataset.builderFieldCheck;
    const row = check.closest('[data-builder-field-row]');
    let col = state.builderColumns.find((item) => item.name === field);
    if (!col && state.model && state.model.measures) {
      const m = state.model.measures.find(x => x.name === field);
      if (m) col = { name: m.name, table: m.table || '', columnType: 'measure', isMeasure: true };
    }
    if (!col) return;
    const fieldTable = (row && row.dataset.builderFieldTable) || col.table || currentBuilderTable();
    if (check.checked) {
      assignBuilderField('auto', field, col.columnType || col.dataType || '', fieldTable);
      return;
    } else {
      removeSelectedVisualField(field, { allByName: true, reason: 'field-check' });
      return;
    }
  }));
  syncBuilderFieldChecks();
  el.querySelectorAll('.builder-measure-row').forEach(function(row) {
    row.addEventListener('click', function(ev) {
      if (ev.target.closest('.measure-actions-btn') || ev.target.closest('.measure-actions-menu') || ev.target.closest('[data-builder-field-check]')) return;
      var idx = Number(row.dataset.builderMeasureIndex);
      if (!isNaN(idx)) openMeasureToolsRibbon(idx);
    });
  });
  el.querySelectorAll('[data-builder-field-row]').forEach((row) => {
    row.addEventListener('dragstart', (ev) => {
      const table = row.dataset.builderFieldTable || ($('#builderTableSelect') && $('#builderTableSelect').value);
      ev.dataTransfer.setData('text/biwa-table', table || '');
      ev.dataTransfer.setData('text/biwa-field', row.dataset.builderFieldRow || '');
      ev.dataTransfer.setData('text/biwa-type', row.dataset.builderFieldType || '');
      ev.dataTransfer.effectAllowed = 'copy';
    });
    row.addEventListener('dblclick', (ev) => {
      if (row.dataset.builderFieldType === 'measure') {
        ev.preventDefault();
        return;
      }
      assignBuilderField('auto', row.dataset.builderFieldRow || '', row.dataset.builderFieldType || '', row.dataset.builderFieldTable || '');
    });
  });
}

function openMeasureToolsRibbon(idx) {
  openDaxMeasureInlineEditor(idx);
}

function closeMeasureToolsRibbon() {
  const mainRibbon = $('#mainRibbon');
  const wasMeasureTabActive = mainRibbon && mainRibbon.dataset.activeRibbonTab === 'measure';
  state.activeMeasureIndex = -1;
  state.measureEditorOpen = false;
  $$('.builder-measure-row.selected').forEach(function(el) { el.classList.remove('selected'); });
  const measureTab = $('#ribbonTabMeasure');
  if (measureTab) measureTab.hidden = true;
  var formulaBar = $('#measureFormulaBar');
  if (formulaBar) formulaBar.hidden = true;
  const visual = selectedReportVisual();
  updateVisualContextRibbon(visual);
  if (wasMeasureTabActive) setMainRibbonTab(visual ? 'visual' : 'home');
}

function positionMeasureFormulaBar() {
  const formulaBar = $('#measureFormulaBar');
  if (!formulaBar || formulaBar.hidden) return;
  const panel = formulaBar.closest('.report-canvas-panel');
  const ribbon = $('#mainRibbon');
  if (!panel || !ribbon) return;
  const panelRect = panel.getBoundingClientRect();
  const ribbonRect = ribbon.getBoundingClientRect();
  const top = Math.max(0, Math.round(ribbonRect.bottom - panelRect.top - 1));
  formulaBar.style.setProperty('--measure-formula-top', top + 'px');
}

function saveMeasureFromRibbon() {
  var idx = state.activeMeasureIndex;
  var measures = state.model && state.model.measures;
  if (idx < 0 || !measures || idx >= measures.length) return;
  var m = measures[idx];
  var formatEl = $('#ribbonMeasureFormat');
  var decimalsEl = $('#ribbonMeasureDecimals');
  var categoryEl = $('#ribbonMeasureCategory');
  var changed = false;
  // Nome e formula sao confirmados somente pelo botao de aplicar. Alterar a
  // formatacao nao pode salvar/validar um rascunho DAX ainda incompleto.
  if (formatEl && formatEl.value !== (m.format || '')) { m.format = formatEl.value; changed = true; }
  if (decimalsEl) { var d = parseInt(decimalsEl.value); if (!isNaN(d) && d !== m.decimals) { m.decimals = d; changed = true; } }
  if (categoryEl && categoryEl.value !== (m.dataCategory || '')) { m.dataCategory = categoryEl.value; changed = true; }
  if (changed) {
    renderBuilderFieldList();
    if (typeof renderMeasureList === 'function') renderMeasureList();
    saveModel().catch(function(err) { toast(err.message || 'Erro ao salvar modelo.', 'error'); });
  }
}

function renderBuilderColumnSelects() {
  const columns = (state.builderColumns || []).slice();
  const visual = selectedReportVisual();
  const knownNames = new Set(columns.map((column) => column.name));
  normalizeSelectedFields(visual && visual.selectedFields).forEach((field) => {
    if (knownNames.has(field.name)) return;
    const measure = (state.model && state.model.measures || []).find((item) => item.name === field.name);
    columns.push({
      name: field.name,
      table: field.table || (measure && measure.table) || (visual && visual.table) || '',
      columnType: measure || field.type === 'measure' ? 'measure' : (field.type || '')
    });
    knownNames.add(field.name);
  });
  const dim = $('#builderDimensionSelect');
  const val = $('#builderValueSelect');
  const secondary = $('#builderSecondaryValueSelect');
  const names = new Set(columns.map((c) => c.name));
  if (dim) {
    const selected = names.has(dim.value) ? dim.value : '';
    dim.innerHTML = builderOptionHtml(columns, selected, true, 'Sem eixo/dimensão');
    dim.value = selected;
  }
  const numeric = columns.filter((column) => String(column.columnType || column.dataType || '').toLowerCase() === 'measure' || isNumericColumn(column));
  const numericSource = numeric.length ? numeric : columns;
  if (val) {
    const selected = numericSource.some((c) => c.name === val.value) ? val.value : '';
    val.innerHTML = builderOptionHtml(numericSource, selected, true, 'Sem valor');
    val.value = selected;
  }
  if (secondary) {
    const selected = numericSource.some((c) => c.name === secondary.value) ? secondary.value : '';
    secondary.innerHTML = builderOptionHtml(numericSource, selected, true, 'Sem segundo valor');
    secondary.value = selected;
  }
  syncBuilderFieldChecks();
}


function visualBuilderStatus(message, isError = false) {
  const result = getActiveVisualPart('.visual-content') || $('#queryResult');
  if (!result) return;
  result.className = 'result visual-content empty-state' + (isError ? ' error-state' : '');
  result.innerHTML = escapeHtml(message || 'Selecione campos no painel Dados para renderizar automaticamente.');
}

function visualBuilderUpdating(message = 'Atualizando filtro...') {
  const result = getActiveVisualPart('.visual-content') || $('#queryResult');
  if (!result) return;
  const visual = selectedReportVisual();
  const hasCurrentResult = Boolean(
    (visual && Array.isArray(visual.rows) && visual.rows.length) ||
    (result.childElementCount && !result.classList.contains('empty-state'))
  );
  if (!hasCurrentResult) {
    visualBuilderStatus('Carregando dados do visual...');
    return;
  }
  result.classList.add('visual-content-updating');
  result.setAttribute('aria-busy', 'true');
  let badge = result.querySelector(':scope > .visual-loading-badge');
  if (!badge) {
    badge = document.createElement('div');
    badge.className = 'visual-loading-badge';
    badge.setAttribute('role', 'status');
    badge.innerHTML = '<span class="visual-loading-spinner" aria-hidden="true"></span>';
    result.appendChild(badge);
  }
  badge.setAttribute('aria-label', message);
  badge.title = message;
}

function clearVisualBuilderUpdating() {
  const result = getActiveVisualPart('.visual-content') || $('#queryResult');
  if (!result) return;
  result.classList.remove('visual-content-updating');
  result.removeAttribute('aria-busy');
  const badge = result.querySelector(':scope > .visual-loading-badge');
  if (badge) badge.remove();
}

function setVisualFilterUpdating(visual, message = 'Aplicando filtro...') {
  const frame = visual && getVisualFrame(visual.id);
  const result = frame && frame.querySelector('.visual-content');
  if (!result) return;
  const hasCurrentResult = Boolean(
    (Array.isArray(visual.rows) && visual.rows.length) ||
    (result.childElementCount && !result.classList.contains('empty-state'))
  );
  if (!hasCurrentResult) {
    result.className = 'result visual-content empty-state';
    result.textContent = 'Carregando dados do visual...';
    return;
  }
  result.classList.add('visual-content-updating');
  result.setAttribute('aria-busy', 'true');
  let badge = result.querySelector(':scope > .visual-loading-badge');
  if (!badge) {
    badge = document.createElement('div');
    badge.className = 'visual-loading-badge';
    badge.setAttribute('role', 'status');
    badge.innerHTML = '<span class="visual-loading-spinner" aria-hidden="true"></span>';
    result.appendChild(badge);
  }
  badge.setAttribute('aria-label', message);
  badge.title = message;
}

function clearVisualFilterUpdating(visual) {
  const frame = visual && getVisualFrame(visual.id);
  const result = frame && frame.querySelector('.visual-content');
  if (!result) return;
  result.classList.remove('visual-content-updating');
  result.removeAttribute('aria-busy');
  const badge = result.querySelector(':scope > .visual-loading-badge');
  if (badge) badge.remove();
}

function visualFilterRefreshPayload(visual, sharedFilters) {
  const fields = collectPreviewFields(visual);
  const visualization = String(visual && visual.visualization || 'table').toLowerCase();
  return {
    table: visualTableForQuery(visual),
    visualId: visual.id || '',
    pageId: visual.pageId || state.activeReportPageId || 'page_1',
    dimension: visual.dimension || '',
    value: visual.value || '',
    secondaryValue: visual.secondaryValue || '',
    fields: fields,
    visualization: visual.visualization || 'table',
    aggregation: visual.aggregation || 'SUM',
    order: visual.order || 'DESC',
    limit: DEFAULT_REPORT_LIMIT,
    page: 1,
    pageSize: ['table', 'matrix'].includes(visualization) ? VISUAL_TABLE_SERVER_PAGE_SIZE : undefined,
    deferTotals: ['table', 'matrix'].includes(visualization),
    visualFilters: getVisualFilters(visual),
    pageFilters: sharedFilters.pageFilters,
    allPagesFilters: sharedFilters.allPagesFilters,
    filters: sharedFilters.dashboardFilters,
    onlineFilters: sharedFilters.onlineFilters,
    name: sharedFilters.reportName,
    model: state.model
  };
}

function applyVisualFilterQueryData(visual, data) {
  visual.rows = Array.isArray(data && data.rows) ? data.rows : [];
  visual.serverPageInfo = data && data.pageInfo && typeof data.pageInfo === 'object' ? { ...data.pageInfo } : null;
  const baseSql = String(data && data.baseSql || '');
  if (baseSql) visual.sql = baseSql;
  if (data && data.table) visual.table = String(data.table);
  if (data && data.columnFormats) {
    setVisualRuntimeColumnFormats(visual, data.columnFormats);
  } else if (visual.table) {
    const imported = (state.importedTables || []).find((item) => item.name === visual.table || item.sourceTable === visual.table);
    if (imported && Array.isArray(imported.steps) && imported.steps.length) {
      visual.columnFormats = buildColumnFormatMapFromSteps(imported.steps);
    }
  }
  if (data && data.totals && typeof data.totals === 'object' && !Array.isArray(data.totals)) {
    visual.totals = { ...data.totals };
    visual.totalsError = String(data.totalsError || '');
    visual.totalsAuthoritative = Boolean(data.totalsAuthoritative === true && !visual.totalsError);
    visual.rowsComplete = Boolean(data.rowsComplete === true);
  }
  visual.totalsPending = Boolean(data && data.totalsPending === true);
  renderVisualFromCachedRows(visual);
  if (visual.id === state.activeVisualId) {
    state.queryRows = visual.rows;
    const editor = $('#sqlEditor');
    if (editor) editor.value = visual.sql || baseSql;
    const meta = $('#queryMeta');
    if (meta) meta.textContent = visual.rows.length + ' linhas';
  }
  if (data && Array.isArray(data.filterWarnings) && data.filterWarnings.length) {
    debugLogClient('[FILTER-VISUALS] ' + data.filterWarnings.join('; '));
  }
}

function scheduleVisualAuthoritativeTotals(visual, payload, queryVersion = 0, options = {}) {
  if (!visual || !payload || payload.deferTotals !== true || !['table', 'matrix'].includes(String(payload.visualization || '').toLowerCase())) return;
  const visualId = String(visual.id || '');
  if (!visualId) return;
  const previous = visualTotalsControllers.get(visualId);
  if (previous) previous.abort();
  const controller = new AbortController();
  visualTotalsControllers.set(visualId, controller);
  const totalsPayload = { ...payload, totalsOnly: true, deferTotals: false, page: 1, pageSize: Number(payload.pageSize) || VISUAL_TABLE_SERVER_PAGE_SIZE, model: state.model };
  const signature = stableClientJson({ ...totalsPayload, model: undefined });
  visual.pendingTotalsSignature = signature;
  Promise.resolve().then(async function() {
    const cacheKey = 'totals|' + signature;
    let data = getCachedVisualPreview(cacheKey);
    if (!data) {
      const mutationFrame = queryVersion ? getVisualFrame(visualId) : null;
      if (mutationFrame && mutationFrame.dataset.fieldQueryVersion === String(queryVersion)) {
        mutationFrame.dataset.fieldMutationRequestCount = String((Number(mutationFrame.dataset.fieldMutationRequestCount) || 0) + 1);
        mutationFrame.dataset.fieldTotalsStatus = 'running';
      }
      data = await api('/api/visual-query', { method: 'POST', body: JSON.stringify(totalsPayload), signal: controller.signal });
      setCachedVisualPreview(cacheKey, data);
    }
    const current = state.reportVisuals.find(function(item) { return String(item.id || '') === visualId; });
    if (!current || current.pendingTotalsSignature !== signature || controller.signal.aborted) return;
    if (queryVersion && currentVisualQueryVersion(visualId) !== queryVersion) return;
    const responseTotals = data && data.totals && typeof data.totals === 'object' ? data.totals : {};
    const mergeFields = Array.isArray(options.mergeFields) ? options.mergeFields.filter(Boolean) : [];
    if (mergeFields.length) {
      const incrementalTotals = {};
      mergeFields.forEach(function(field) {
        if (Object.prototype.hasOwnProperty.call(responseTotals, field)) incrementalTotals[field] = responseTotals[field];
      });
      current.totals = { ...(current.totals || {}), ...incrementalTotals };
    } else {
      current.totals = { ...responseTotals };
    }
    current.totalsError = String(data && data.totalsError || '');
    current.totalsAuthoritative = Boolean(data && data.totalsAuthoritative === true && !current.totalsError);
    current.rowsComplete = Boolean(data && data.rowsComplete === true);
    current.totalsPending = false;
    renderVisualFromCachedRows(current);
    const mutationFrame = queryVersion ? getVisualFrame(visualId) : null;
    if (mutationFrame && mutationFrame.dataset.fieldQueryVersion === String(queryVersion)) mutationFrame.dataset.fieldTotalsStatus = 'complete';
  }).catch(function(err) {
    const mutationFrame = queryVersion ? getVisualFrame(visualId) : null;
    if (mutationFrame && mutationFrame.dataset.fieldQueryVersion === String(queryVersion) && !isCancelledRequest(err)) mutationFrame.dataset.fieldTotalsStatus = 'error';
    if (!isCancelledRequest(err)) debugLogClient('[VISUAL-TOTALS] visual=' + visualId + ' error=' + (err && err.message ? err.message : String(err)));
  }).finally(function() {
    if (visualTotalsControllers.get(visualId) === controller) visualTotalsControllers.delete(visualId);
  });
}

function visualDataQuerySignature(visual) {
  return {
    id: String(visual && visual.id || ''),
    table: String(visual && visual.table || ''),
    visualization: String(visual && visual.visualization || 'table'),
    dimension: String(visual && visual.dimension || ''),
    value: String(visual && visual.value || ''),
    secondaryValue: String(visual && visual.secondaryValue || ''),
    matrixRows: normalizeVisualBucketNames(visual && visual.matrixRows),
    matrixColumns: normalizeVisualBucketNames(visual && visual.matrixColumns),
    matrixValues: normalizeVisualBucketNames(visual && visual.matrixValues),
    aggregation: String(visual && visual.aggregation || 'SUM'),
    order: String(visual && visual.order || 'DESC'),
    fields: normalizeSelectedFields(visual && visual.selectedFields).map((field) => ({
      instanceId: visualFieldRef(field),
      measureId: field.measureId || '',
      name: field.name,
      table: field.table || '',
      type: field.type || '',
      aggregation: field.aggregation || '',
      showValueAs: field.showValueAs || ''
    })),
    filters: getVisualFilters(visual).map((filter) => ({
      table: filter.table || '',
      column: filter.column || '',
      values: Array.isArray(filter.values) ? filter.values : []
    }))
  };
}

function canUseSavedReportFilterRefresh(reason) {
  if (reason !== 'online-filter-change' || !state.editingReportId) return null;
  const report = (state.reports || []).find((item) => String(item.id) === String(state.editingReportId));
  if (!report) return null;
  const savedVisuals = Array.isArray(report.visuals) ? report.visuals : [];
  if (savedVisuals.length !== state.reportVisuals.length) return null;
  if (stableClientJson(state.reportVisuals.map(visualDataQuerySignature)) !== stableClientJson(savedVisuals.map(visualDataQuerySignature))) return null;
  const filterSignature = (filters) => (filters || []).map(normalizeOnlineFilterConfig).filter(Boolean).map((filter) => ({
    id: filter.id || '',
    table: filter.table || '',
    field: filter.field || '',
    domainTable: filter.domainTable || '',
    operator: filter.operator || '=',
    type: filter.type || 'text',
    ui: filter.ui || 'dropdown',
    multiSelect: Boolean(filter.multiSelect)
  }));
  if (stableClientJson(filterSignature(currentOnlineFilters())) !== stableClientJson(filterSignature(report.onlineFilters))) return null;
  if (stableClientJson(normalizeVisualFilters(state.pageFilters)) !== stableClientJson(normalizeVisualFilters(report.pageFilters || []))) return null;
  if (stableClientJson(normalizeVisualFilters(state.allPagesFilters)) !== stableClientJson(normalizeVisualFilters(report.allPagesFilters || []))) return null;
  return report;
}

async function refreshSavedReportVisualsForFilters(report, visuals, requestSequence) {
  const visualGuards = new Map((visuals || []).map(function(visual) {
    return [String(visual.id || ''), { version: currentVisualQueryVersion(visual.id), signature: stableClientJson(visualDataQuerySignature(visual)) }];
  }));
  const existingResult = state.dashboard && state.dashboard[report.id];
  if (existingResult && existingResult.runtimeFilterSignature && dashboardResultMatchesReportDefinition(report, existingResult, activeOnlineReportPageId(report))) {
    setCachedSavedReportFilterResult(report.id + '|' + existingResult.runtimeFilterSignature + '|' + existingResult.reportDefinitionSignature, existingResult);
  }
  const targetSignature = dashboardRuntimeFilterSignature(editorReportRuntimePayload(report.id, report));
  const targetDefinitionSignature = reportRuntimeDefinitionSignature(report, activeOnlineReportPageId(report));
  const targetCacheKey = report.id + '|' + targetSignature + '|' + targetDefinitionSignature;
  let result = getCachedSavedReportFilterResult(targetCacheKey);
  if (result && !dashboardResultMatchesReportDefinition(report, result, activeOnlineReportPageId(report))) result = null;
  if (!result) {
    await runSingleReport(report.id, { silent: true, ignoreCrossFilters: true, skipDashboardRender: true });
    result = state.dashboard && state.dashboard[report.id];
    if (result) setCachedSavedReportFilterResult(targetCacheKey, result);
  }
  if (requestSequence !== state.reportFilterVisualSequence) return;
  const visualResults = result && Array.isArray(result.visualResults) ? result.visualResults : [];
  state.reportVisuals.filter(function(visual) {
    return String(visual.pageId || 'page_1') === String(state.activeReportPageId || 'page_1');
  }).forEach((visual, index) => {
    const guard = visualGuards.get(String(visual.id || ''));
    if (guard && (currentVisualQueryVersion(visual.id) !== guard.version || stableClientJson(visualDataQuerySignature(visual)) !== guard.signature)) return;
    const visualResult = visualResults.find((item) => String(item && item.id || '') === String(visual.id || '')) || visualResults[index];
    if (visualResult) applyVisualFilterQueryData(visual, visualResult);
  });
}

async function refreshCurrentPageVisualsForFilters(reason, requestSequence) {
  const visuals = currentPageVisuals().filter((visual) => {
    const type = String(visual && visual.visualization || '').toLowerCase();
    return visual && !['textbox', 'image'].includes(type) && visualTableForQuery(visual) && collectPreviewFields(visual).length;
  });
  if (!visuals.length) return;
  const savedReport = canUseSavedReportFilterRefresh(reason);
  if (savedReport) {
    try {
      await refreshSavedReportVisualsForFilters(savedReport, visuals, requestSequence);
    } finally {
      if (requestSequence === state.reportFilterVisualSequence) visuals.forEach(clearVisualFilterUpdating);
    }
    return;
  }
  const sharedFilters = {
    pageFilters: collectPageFiltersFromCards(),
    allPagesFilters: collectAllPagesFiltersFromCards(),
    dashboardFilters: state.dashboardFilters[designerReportId()] || {},
    onlineFilters: currentOnlineFilters(),
    reportName: ($('#reportName') && $('#reportName').value) || ''
  };
  let firstError = null;
  await Promise.all(visuals.map(async (visual) => {
    const visualVersion = currentVisualQueryVersion(visual.id);
    const visualSignature = stableClientJson(visualDataQuerySignature(visual));
    const payload = visualFilterRefreshPayload(visual, sharedFilters);
    const previewCacheKey = stableClientJson(payload);
    try {
      let data = getCachedVisualPreview(previewCacheKey);
      if (!data) {
        data = await api('/api/visual-query', { method: 'POST', body: JSON.stringify(payload), signal: state.reportFilterAbortController && state.reportFilterAbortController.signal });
        setCachedVisualPreview(previewCacheKey, data);
      }
      if (requestSequence !== state.reportFilterVisualSequence) return;
      if (currentVisualQueryVersion(visual.id) !== visualVersion || stableClientJson(visualDataQuerySignature(visual)) !== visualSignature) return;
      visual.serverPagePayload = data && data.pageInfo ? { ...payload, model: state.model } : null;
      applyVisualFilterQueryData(visual, data);
      if (data && data.totalsPending === true) scheduleVisualAuthoritativeTotals(visual, payload);
    } catch (err) {
      if (isCancelledRequest(err)) return;
      if (!firstError) firstError = err;
      debugLogClient('[FILTER-VISUALS] ' + reason + ' visual=' + visual.id + ' error=' + (err && err.message ? err.message : String(err)));
    } finally {
      if (requestSequence === state.reportFilterVisualSequence) clearVisualFilterUpdating(visual);
    }
  }));
  if (requestSequence === state.reportFilterVisualSequence && firstError) {
    toast(firstError.message || 'Não foi possível atualizar todos os visuais.', 'error');
  }
}

function scheduleReportFilterVisualUpdate(reason = 'filter-change') {
  if (state.reportFilterVisualTimer) clearTimeout(state.reportFilterVisualTimer);
  if (state.reportFilterAbortController) state.reportFilterAbortController.abort();
  state.reportFilterAbortController = new AbortController();
  syncActiveVisualFromControls();
  const requestSequence = ++state.reportFilterVisualSequence;
  currentPageVisuals().forEach((visual) => {
    const type = String(visual && visual.visualization || '').toLowerCase();
    if (!['textbox', 'image'].includes(type)) setVisualFilterUpdating(visual, 'Aplicando filtro...');
  });
  state.reportFilterVisualTimer = setTimeout(() => {
    state.reportFilterVisualTimer = null;
    refreshCurrentPageVisualsForFilters(reason, requestSequence).catch((err) => {
      if (requestSequence !== state.reportFilterVisualSequence) return;
      currentPageVisuals().forEach(clearVisualFilterUpdating);
      toast(err.message || 'Erro ao aplicar filtros nos visuais.', 'error');
    });
  }, 0);
}

function visualBuilderReady() {
  const visual = syncActiveVisualFromControls();
  if (!visual || !visualControlsMatch(visual)) return { ok: false, message: 'Selecione novamente o visual para editar os campos.' };
  const table = visualTableForQuery(visual);
  const dimension = visual.dimension || '';
  const value = visual.value || '';
  const agg = visual.aggregation || 'SUM';
  const selectedFields = collectPreviewFields(visual);
  const viz = visual.visualization || 'table';
  if (!table) return { ok: false, message: 'Selecione uma tabela ou view no painel Dados.' };
  if (selectedFields.length && rawPreviewVisualType(viz)) return { ok: true, rawFields: true };
  var hasMeasureInFields = selectedFields.some(function(f) { return f.type === 'measure'; });
  if (hasMeasureInFields && (dimension || value)) return { ok: true };
  if (!selectedFields.length && !dimension && !value) return { ok: false, message: 'Selecione ou arraste um campo do painel Dados.' };
  if (!dimension && value && agg !== 'COUNT' && !hasMeasureInFields) return { ok: true };
  if (!dimension && agg !== 'COUNT' && !hasMeasureInFields) return { ok: false, message: 'Selecione ou arraste um campo para o eixo/dimensão.' };
  if (!value && agg !== 'COUNT' && !hasMeasureInFields) return { ok: false, message: 'Selecione ou arraste um campo numérico para Valores.' };
  return { ok: true };
}

function scheduleVisualAutoUpdate(reason = 'change', options = {}) {
  const ready = visualBuilderReady();
  const targetVisual = selectedReportVisual();
  if (!targetVisual || !visualControlsMatch(targetVisual)) return;
  const targetVisualId = String(targetVisual.id || '');
  cancelVisualInFlightWork(targetVisualId, { bumpVersion: false });
  const queryVersion = nextVisualQueryVersion(targetVisualId);
  if (!ready.ok) {
    state.visualAutoPending = false;
    state.visualAutoPendingTargetId = '';
    state.visualAutoPendingReason = '';
    clearVisualBuilderUpdating();
    visualBuilderStatus(ready.message);
    return;
  }
  const configSignature = stableClientJson(visualDataQuerySignature(targetVisual));
  state.visualAutoPending = true;
  state.visualAutoPendingTargetId = targetVisualId;
  state.visualAutoPendingReason = reason;
  const delayMs = Number.isFinite(Number(options.delayMs)) ? Math.max(0, Number(options.delayMs)) : (options.background ? 0 : 20);
  const timer = setTimeout(async function runVisualAutoUpdate() {
    visualAutoTimersById.delete(targetVisualId);
    if (currentVisualQueryVersion(targetVisualId) !== queryVersion) return;
    const requestController = new AbortController();
    const requestEntry = { controller: requestController, version: queryVersion, signature: configSignature, reason };
    visualAutoRequestsById.set(targetVisualId, requestEntry);
    state.visualAutoAbortController = requestController;
    state.visualAutoBusy = true;
    state.visualAutoPending = false;
    state.visualAutoPendingTargetId = '';
    state.visualAutoPendingReason = '';
    const queryStartedAt = performance.now();
    const targetFrame = getVisualFrame(targetVisualId);
    if (targetFrame) {
      targetFrame.dataset.fieldMutationRequestCount = '1';
      targetFrame.dataset.fieldQueryStatus = 'running';
      targetFrame.dataset.fieldQueryVersion = String(queryVersion);
    }
    const meta = $('#queryMeta');
    if (meta) meta.textContent = options.background ? 'Sincronizando dados em segundo plano...' : 'Atualizando automaticamente...';
    if (!options.background) visualBuilderUpdating(reason === 'online-filter-change' ? 'Aplicando filtro...' : 'Atualizando visual...');
    visualFieldPerformanceClient('FIELD QUERY START', {
      action: options.mutation || 'UPDATE_FIELD', visualId: targetVisualId, field: options.field || '',
      reason, queryVersion, background: Boolean(options.background)
    });
    try {
      await buildVisualPreview({
        silent: true,
        targetVisualId,
        signal: requestController.signal,
        queryVersion,
        configSignature,
        reason,
        mutation: options.mutation || '',
        field: options.field || '',
        background: Boolean(options.background),
        preserveTotals: options.preserveTotals === true
      });
      if (currentVisualQueryVersion(targetVisualId) === queryVersion) {
        if (targetFrame) {
          targetFrame.dataset.fieldQueryStatus = 'complete';
          targetFrame.dataset.fieldQueryMs = (performance.now() - queryStartedAt).toFixed(3);
        }
        visualFieldPerformanceClient('FIELD MUTATION COMPLETE', {
          action: options.mutation || 'UPDATE_FIELD', visualId: targetVisualId, field: options.field || '',
          requestCount: 1, background: Boolean(options.background), queryMs: Number((performance.now() - queryStartedAt).toFixed(3))
        });
      }
    } catch (err) {
      if (isCancelledRequest(err)) return;
      if (currentVisualQueryVersion(targetVisualId) === queryVersion) {
        const message = err.message || 'Erro ao atualizar visual automaticamente.';
        const currentMeta = $('#queryMeta');
        if (currentMeta) currentMeta.textContent = 'Erro na atualização: ' + message;
        if (options.background) toast(message, 'error');
        else visualBuilderStatus(message, true);
        visualFieldPerformanceClient('FIELD QUERY ERROR', {
          action: options.mutation || 'UPDATE_FIELD', visualId: targetVisualId, reason,
          queryVersion, message, queryMs: Number((performance.now() - queryStartedAt).toFixed(3))
        });
        if (targetFrame) {
          targetFrame.dataset.fieldQueryStatus = 'error';
          targetFrame.dataset.fieldQueryMs = (performance.now() - queryStartedAt).toFixed(3);
        }
      }
    } finally {
      if (visualAutoRequestsById.get(targetVisualId) === requestEntry) visualAutoRequestsById.delete(targetVisualId);
      if (state.visualAutoAbortController === requestController) state.visualAutoAbortController = null;
      state.visualAutoBusy = visualAutoRequestsById.size > 0;
      if (currentVisualQueryVersion(targetVisualId) === queryVersion && !options.background) clearVisualBuilderUpdating();
    }
  }, delayMs);
  visualAutoTimersById.set(targetVisualId, timer);
  state.visualAutoTimer = timer;
}

async function refreshVisualBuilder(options = {}) {
  renderBuilderResourceSelect();
  const table = $('#builderTableSelect') && $('#builderTableSelect').value;
  try {
    await loadBuilderColumns(table);
    // Carregar/recarregar metadados do construtor nao deve executar o visual.
    // A consulta pertence a uma acao explicita do usuario (campo/filtro/refresh),
    // evitando que inicializacoes concorrentes disparem consultas duplicadas.
    if (options.autoQuery === true) scheduleVisualAutoUpdate('refresh');
  } catch (err) {
    const el = $('#builderFieldList');
    if (el) {
      el.className = 'field-list empty-state';
      el.textContent = err.message;
    }
  }
}

function generateVisualSql(showToast = true) {
  const viz = syncActiveVisualFromControls();
  if (!viz || !visualControlsMatch(viz)) throw new Error('Selecione um visual antes de gerar o SQL.');
  const v = String(viz && viz.visualization || '').toLowerCase();
  if (['textbox', 'image'].includes(v)) throw new Error('Este tipo de visual não utiliza consulta SQL.');
  const table = visualTableForQuery(viz);
  const dimension = $('#builderDimensionSelect') && $('#builderDimensionSelect').value;
  const value = $('#builderValueSelect') && $('#builderValueSelect').value;
  const agg = ($('#builderAggregationSelect') && $('#builderAggregationSelect').value) || 'SUM';
  const order = ($('#builderOrderSelect') && $('#builderOrderSelect').value) || 'DESC';
  if (!table) throw new Error('Selecione uma tabela ou view.');
  if (!dimension && !value && agg !== 'COUNT') throw new Error('Selecione o eixo/dimensão ou o valor.');
  if (!value && agg !== 'COUNT') throw new Error('Selecione o valor/coluna numérica.');
  const tableSql = safeSqlIdent(table);
  const dimSql = dimension ? safeSqlIdent(dimension) : '';
  const valueSql = value ? safeSqlIdent(value) : '*';
  const measureName = ($('#reportName') && $('#reportName').value ? $('#reportName').value : agg + '_' + (value || 'linhas')).replace(/[^A-Za-z0-9_À-ÿ\s-]/g, '').trim() || 'medida';
  let aggSql = 'COUNT(*)';
  if (agg === 'SUM') aggSql = `SUM(${valueSql})`;
  else if (agg === 'AVG') aggSql = `AVG(${valueSql})`;
  else if (agg === 'MIN') aggSql = `MIN(${valueSql})`;
  else if (agg === 'MAX') aggSql = `MAX(${valueSql})`;
  else if (agg === 'COUNT') aggSql = value ? `COUNT(${valueSql})` : 'COUNT(*)';
  else if (agg === 'DISTINCTCOUNT') aggSql = `COUNT(DISTINCT ${valueSql})`;
  const selectParts = dimension ? [`${dimSql} AS ${safeSqlIdent(dimension)}`, `${aggSql} AS ${safeSqlIdent(measureName)}`] : [`${aggSql} AS ${safeSqlIdent(measureName)}`];
  let sql = `SELECT ${selectParts.join(', ')}\nFROM ${tableSql}`;
  var visual = viz;
  let visualFilters = collectVisualFiltersFromCards();
  if (!visualFilters.length && visual) visualFilters = getVisualFilters(visual);
  if (visualFilters.length) {
    const whereParts = [];
    visualFilters.forEach(function(f) {
      if (!f.column || !f.values || !f.values.length) return;
      var escapedVals = f.values.map(function(v) { return safeSqlValue(v, '='); }).join(', ');
      whereParts.push(`${safeSqlIdent(f.column)} IN (${escapedVals})`);
    });
    if (whereParts.length) sql += `\nWHERE ${whereParts.join(' AND ')}`;
  }
  if (dimension) sql += `\nGROUP BY ${dimSql}`;
  sql += `\nORDER BY ${safeSqlIdent(measureName)} ${order === 'ASC' ? 'ASC' : 'DESC'}`;
  sql += `\nLIMIT ${DEFAULT_REPORT_LIMIT}`;
  const editor = $('#sqlEditor');
  if (editor) editor.value = sql;
  if (showToast) toast('SQL gerado pelo criador visual.');
  return sql;
}

// REGRA_CRITICA_FONTE_DADOS_CONSTRUTOR:
// O construtor envia os campos para /api/visual-query que consulta APENAS o cache PostgreSQL.
// MySQL e usado EXCLUSIVAMENTE para sincronizar o PostgreSQL.
// REGRA_CRITICA_TABELA_MATRIZ_COLUNAS_DIRETAS:
// Tabela/Matriz tratam colunas como diretas (raw preview), sem agregacao automatica.
function incrementalMeasureQueryPlan(visual, configuredFields, options = {}) {
  const reject = function(reason, details) {
    visualFieldDebugClient('INCREMENTAL PLAN', {
      visualId: visual && visual.id,
      accepted: false,
      reason,
      ...(details || {})
    });
    return null;
  };
  if (!visual || options.mutation !== 'ADD_FIELD' || !options.field) return reject('not-add-field');
  const visualization = String(visual.visualization || '').toLowerCase();
  if (!['table', 'matrix'].includes(visualization)) return reject('visual-not-supported', { visualization });
  const previousRows = Array.isArray(visual.rows) && visual.rows.length
    ? visual.rows
    : (String(visual.id || '') === String(state.activeVisualId || '') && Array.isArray(state.queryRows) && state.queryRows.length ? state.queryRows : []);
  if (!previousRows.length) return reject('no-current-rows');
  const fields = normalizeSelectedFields(configuredFields);
  const addedField = fields.find(function(field) { return field.name === String(options.field || ''); });
  if (!addedField || !visualSelectedFieldIsMeasure(addedField)) return reject('field-is-not-a-measure', { field: String(options.field || '') });
  const dimensions = fields.filter(function(field) { return !visualSelectedFieldIsMeasure(field); });
  if (!dimensions.length) return reject('no-physical-dimensions');
  const dimensionNames = Array.from(new Set(dimensions.map(function(field) { return field.name; }).filter(Boolean)));
  if (!dimensionNames.length || dimensionNames.some(function(name) {
    return previousRows.some(function(row) { return !row || !Object.prototype.hasOwnProperty.call(row, name); });
  })) return reject('dimension-not-in-current-rows', { dimensions: dimensionNames });
  visualFieldDebugClient('INCREMENTAL PLAN', {
    visualId: visual.id,
    accepted: true,
    field: addedField.name,
    dimensions: dimensionNames,
    currentRows: previousRows.length
  });
  return {
    field: addedField,
    fields: dimensions.concat(addedField),
    dimensionNames,
    previousRows: previousRows.slice(),
    previousServerPageInfo: visual.serverPageInfo && typeof visual.serverPageInfo === 'object' ? { ...visual.serverPageInfo } : null,
    previousServerPagePayload: visual.serverPagePayload && typeof visual.serverPagePayload === 'object' ? { ...visual.serverPagePayload } : null
  };
}

function incrementalMeasureRowKey(row, dimensionNames) {
  return stableClientJson((dimensionNames || []).map(function(name) {
    const value = row && Object.prototype.hasOwnProperty.call(row, name) ? row[name] : null;
    return value === undefined ? null : value;
  }));
}

function mergeIncrementalMeasureRows(plan, queryRows) {
  if (!plan || !Array.isArray(queryRows)) return { complete: false, rows: [] };
  const byKey = new Map();
  for (const row of queryRows) {
    const key = incrementalMeasureRowKey(row, plan.dimensionNames);
    if (byKey.has(key)) return { complete: false, rows: [] };
    byKey.set(key, row);
  }
  let missing = 0;
  const rows = plan.previousRows.map(function(row) {
    const match = byKey.get(incrementalMeasureRowKey(row, plan.dimensionNames));
    if (!match) {
      missing += 1;
      return row;
    }
    return {
      ...row,
      [plan.field.name]: Object.prototype.hasOwnProperty.call(match, plan.field.name) ? match[plan.field.name] : null
    };
  });
  return { complete: missing === 0, rows, missing };
}

async function buildVisualPreview(options = {}) {
  const activeViz = syncActiveVisualFromControls();
  if (!activeViz || !visualControlsMatch(activeViz)) return;
  const targetVisualId = String(options.targetVisualId || activeViz.id || '');
  if (!targetVisualId || String(activeViz.id) !== targetVisualId) return;
  if (options.queryVersion && currentVisualQueryVersion(targetVisualId) !== options.queryVersion) return;
  const vizType = String(activeViz.visualization || 'table').toLowerCase();
  if (['textbox', 'image'].includes(vizType)) {
    const visual = state.reportVisuals.find((item) => String(item.id) === targetVisualId);
    if (visual) {
      visual.rows = [];
    }
    renderReportPageVisuals();
    return;
  }
  let sql = '';
  let data;
  var visualFields = collectPreviewFields(activeViz);
  const tableForQuery = visualTableForQuery(activeViz);
  const payload = {
    table: tableForQuery,
    visualId: targetVisualId,
    pageId: activeViz.pageId || state.activeReportPageId || 'page_1',
    dimension: activeViz.dimension || '',
    value: activeViz.value || '',
    secondaryValue: activeViz.secondaryValue || '',
    fields: visualFields,
    visualization: vizType,
    aggregation: activeViz.aggregation || 'SUM',
    order: activeViz.order || 'DESC',
    limit: DEFAULT_REPORT_LIMIT,
    page: 1,
    pageSize: ['table', 'matrix'].includes(vizType) ? VISUAL_TABLE_SERVER_PAGE_SIZE : undefined,
    deferTotals: ['table', 'matrix'].includes(vizType),
    visualFilters: collectVisualFiltersFromCards(),
    pageFilters: collectPageFiltersFromCards(),
    allPagesFilters: collectAllPagesFiltersFromCards(),
    filters: state.dashboardFilters[designerReportId()] || {},
    onlineFilters: currentOnlineFilters(),
    name: ($('#reportName') && $('#reportName').value) || '',
    model: state.model
  };
  const incrementalPlan = incrementalMeasureQueryPlan(activeViz, visualFields, options);
  const requestPayload = incrementalPlan ? {
    ...payload,
    dimension: incrementalPlan.dimensionNames[0] || payload.dimension,
    value: incrementalPlan.field.name,
    secondaryValue: '',
    fields: incrementalPlan.fields,
    limit: 500,
    page: 1,
    pageSize: 500,
    deferTotals: true
  } : payload;
  visualFieldDebugClient('QUERY REQUEST', {
    visualId: targetVisualId,
    reason: options.reason || '',
    visualization: vizType,
    dimension: requestPayload.dimension,
    value: requestPayload.value,
    incrementalField: incrementalPlan ? incrementalPlan.field.name : '',
    fields: requestPayload.fields.map(function(field) { return { name: field.name, type: field.type, table: field.table }; }),
    filters: requestPayload.filters,
    visualFilters: requestPayload.visualFilters,
    pageFilters: requestPayload.pageFilters,
    allPagesFilters: requestPayload.allPagesFilters
  });
  const previewCacheKey = stableClientJson(requestPayload);
  const cachedPreview = options.forceRefresh ? null : getCachedVisualPreview(previewCacheKey);
  const fromPreviewCache = Boolean(cachedPreview);
  let requestElapsedMs = 0;
  data = cachedPreview;
  if (!data) {
    const requestStartedAt = performance.now();
    data = await api('/api/visual-query', { method: 'POST', body: JSON.stringify(requestPayload), signal: options.signal });
    requestElapsedMs += performance.now() - requestStartedAt;
    setCachedVisualPreview(previewCacheKey, data);
  }
  let incrementalApplied = false;
  if (incrementalPlan) {
    const incrementalQueryRowCount = Array.isArray(data && data.rows) ? data.rows.length : 0;
    const merged = mergeIncrementalMeasureRows(incrementalPlan, Array.isArray(data && data.rows) ? data.rows : []);
    if (merged.complete) {
      data = { ...data, rows: merged.rows };
      incrementalApplied = true;
      visualFieldPerformanceClient('FIELD QUERY INCREMENTAL', {
        action: options.mutation || '', visualId: targetVisualId, field: incrementalPlan.field.name,
        queriedFields: incrementalPlan.fields.map(function(field) { return field.name; }),
        queryRows: incrementalQueryRowCount,
        mergedRows: merged.rows.length
      });
    } else {
      const mutationFrame = getVisualFrame(targetVisualId);
      if (mutationFrame && mutationFrame.dataset.fieldQueryVersion === String(options.queryVersion || '')) {
        mutationFrame.dataset.fieldMutationRequestCount = String((Number(mutationFrame.dataset.fieldMutationRequestCount) || 1) + 1);
      }
      visualFieldPerformanceClient('FIELD QUERY INCREMENTAL FALLBACK', {
        action: options.mutation || '', visualId: targetVisualId, field: incrementalPlan.field.name,
        missingRows: Number(merged.missing || incrementalPlan.previousRows.length)
      });
      const fullCacheKey = stableClientJson(payload);
      data = options.forceRefresh ? null : getCachedVisualPreview(fullCacheKey);
      if (!data) {
        const fallbackRequestStartedAt = performance.now();
        data = await api('/api/visual-query', { method: 'POST', body: JSON.stringify(payload), signal: options.signal });
        requestElapsedMs += performance.now() - fallbackRequestStartedAt;
        setCachedVisualPreview(fullCacheKey, data);
      }
    }
  }
  visualFieldDebugClient('QUERY RESULT', {
    visualId: targetVisualId,
    columns: data && Array.isArray(data.rows) && data.rows.length ? Object.keys(data.rows[0]) : ((data && data.fields) || []).map(function(field) { return field && field.name; }).filter(Boolean),
    rowCount: data && Array.isArray(data.rows) ? data.rows.length : 0,
    fields: data && data.fields,
    requestElapsedMs: Number(requestElapsedMs.toFixed(3)),
    serverPerformance: data && data.performance
  });
  if (options.queryVersion && currentVisualQueryVersion(targetVisualId) !== options.queryVersion) return;
  const visual = state.reportVisuals.find((item) => String(item.id) === targetVisualId);
  if (!visual) return;
  if (options.configSignature && stableClientJson(visualDataQuerySignature(visual)) !== options.configSignature) return;
  sql = incrementalApplied ? String(activeViz.sql || '') : (data.baseSql || data.sql || '');
  const responseRows = Array.isArray(data.rows) ? data.rows : [];
  const isActiveTarget = String(state.activeVisualId || '') === targetVisualId && visualControlsMatch(selectedReportVisual());
  if (isActiveTarget) {
    const editor = $('#sqlEditor');
    if (editor) editor.value = sql;
    state.queryRows = responseRows;
  }
  if (visual) {
    if (data.table) visual.table = String(data.table);
    visual.selectedFields = normalizeSelectedFields(visualFields);
    visual.rows = responseRows;
    visual.serverPageInfo = incrementalApplied
      ? incrementalPlan.previousServerPageInfo
      : (data.pageInfo && typeof data.pageInfo === 'object' ? { ...data.pageInfo } : null);
    visual.serverPagePayload = incrementalApplied
      ? (visual.serverPageInfo ? { ...payload, model: state.model } : incrementalPlan.previousServerPagePayload)
      : (visual.serverPageInfo ? { ...payload, model: state.model } : null);
    if (!incrementalApplied) visual.sql = sql;
    if (incrementalApplied) {
      visual.totalsPending = Boolean(data && data.totalsPending === true);
    } else if (options.preserveTotals === true) {
      visual.totalsPending = false;
      visual.pendingTotalsSignature = '';
    } else if (data && data.totals && typeof data.totals === 'object' && !Array.isArray(data.totals)) {
      visual.totals = { ...data.totals };
      visual.totalsError = String(data.totalsError || '');
      visual.totalsAuthoritative = Boolean(data.totalsAuthoritative === true && !visual.totalsError);
      visual.rowsComplete = Boolean(data.rowsComplete === true);
    } else {
      visual.totals = {};
      visual.totalsError = String(data && data.totalsError || '');
      visual.totalsAuthoritative = false;
      visual.rowsComplete = false;
    }
    if (!incrementalApplied && options.preserveTotals !== true) visual.totalsPending = Boolean(data && data.totalsPending === true);
    if (data.columnFormats) setVisualRuntimeColumnFormats(visual, incrementalApplied ? { ...(visual.runtimeColumnFormats || {}), ...data.columnFormats } : data.columnFormats);
    else if (visual.table) {
      var vImpItem = (state.importedTables || []).find(function(t) { return t.name === visual.table || t.sourceTable === visual.table; });
      if (vImpItem && Array.isArray(vImpItem.steps) && vImpItem.steps.length) {
        visual.columnFormats = buildColumnFormatMapFromSteps(vImpItem.steps);
      }
    }
    var hasMeasureField = visualFields.some(function(f) { return f.type === 'measure'; });
    if (!visual.value && hasMeasureField) {
      var measureField = visualFields.find(function(f) { return f.type === 'measure'; });
      if (measureField) {
        visual.value = measureField.name;
        var valEl = document.getElementById('builderValueSelect');
        if (valEl) valEl.value = measureField.name;
      }
    }
    visual.title = visual.title || '';
  }
  const targetFrame = getVisualFrame(targetVisualId);
  if (targetFrame) {
    targetFrame.dataset.fieldRequestMs = requestElapsedMs.toFixed(3);
    const serverPerformance = data && data.performance && typeof data.performance === 'object' ? data.performance : null;
    if (serverPerformance) {
      targetFrame.dataset.fieldServerMs = Number(serverPerformance.totalServerMs || 0).toFixed(3);
      targetFrame.dataset.fieldDatabaseMs = Number(serverPerformance.databaseMs || 0).toFixed(3);
      targetFrame.dataset.fieldDaxMs = Number(serverPerformance.daxMs || 0).toFixed(3);
      targetFrame.dataset.fieldQueryBuildMs = Number(serverPerformance.queryBuildMs || 0).toFixed(3);
    }
  }
  const resultEl = (targetFrame && targetFrame.querySelector('.visual-content')) || $('#queryResult');
  if (resultEl) {
    if (isActiveTarget && !options.background) clearVisualBuilderUpdating();
    const rendersConfiguredEmptyStructure = visual
      && ['table', 'matrix'].includes(String(visual.visualization || '').toLowerCase())
      && normalizeSelectedFields(visual.selectedFields).length > 0;
    resultEl.className = 'result visual-content' + (responseRows.length || rendersConfiguredEmptyStructure ? '' : ' empty-state');
    renderViz(resultEl, responseRows, (visual && visual.visualization) || 'table', visual);
  }
  if (isActiveTarget) {
    const meta = $('#queryMeta');
    if (meta) meta.textContent = `${responseRows.length} linhas${fromPreviewCache ? ' · instantâneo' : ''}`;
    const title = getActiveVisualPart('.visual-title-preview') || $('#visualTitlePreview');
    if (title) title.textContent = (visual && visual.title) || '';
    updateVisualFieldDropZones();
  }
  if (options.preserveTotals !== true && visual && data && data.totalsPending === true) {
    scheduleVisualAuthoritativeTotals(visual, incrementalApplied ? requestPayload : payload, options.queryVersion || 0, incrementalApplied ? { mergeFields: [incrementalPlan.field.name] } : {});
  }
}

function clampNumber(value, min, max, fallback) {
  const n = Number(value);
  if (!Number.isFinite(n)) return fallback;
  return Math.max(min, Math.min(max, n));
}

function getVisualLayout() {
  const frame = getActiveVisualFrame() || $('#visualFrame');
  const visual = selectedReportVisual();
  const layout = (visual && visual.layout) || state.visualLayout || { x: 32, y: 32, width: 560, height: 360 };
  if (frame) {
    const valueOrFallback = (value, fallback) => Number.isFinite(Number.parseFloat(value)) ? Number.parseFloat(value) : fallback;
    return normalizeVisualLayout({
      x: valueOrFallback(frame.style.left, Number(layout.x)),
      y: valueOrFallback(frame.style.top, Number(layout.y)),
      width: valueOrFallback(frame.style.width, Number(layout.width)),
      height: valueOrFallback(frame.style.height, Number(layout.height)),
      zIndex: valueOrFallback(frame.style.zIndex, Number(layout.zIndex) || 1)
    });
  }
  return normalizeVisualLayout(layout);
}

function applyVisualLayout(layout) {
  ensureReportVisuals();
  const visual = selectedReportVisual();
  const frame = getActiveVisualFrame() || $('#visualFrame');
  const next = normalizeVisualLayout({
    ...(layout || {}),
    zIndex: Number.isFinite(Number(layout && layout.zIndex)) ? Number(layout.zIndex) : ((visual && visual.layout && visual.layout.zIndex) || 1)
  });
  state.visualLayout = next;
  if (visual) visual.layout = next;
  if (frame) {
    frame.style.left = next.x + 'px';
    frame.style.top = next.y + 'px';
    frame.style.width = next.width + 'px';
    frame.style.height = next.height + 'px';
    frame.style.zIndex = String(next.zIndex || 1);
  }
}

function setupPaneCollapse() {
  $$('.pane-collapse-btn').forEach((btn) => {
    if (btn.dataset.bound === '1') return;
    btn.dataset.bound = '1';
    btn.addEventListener('click', () => {
      const connPanel = btn.dataset.collapseConnectionPanel;
      if (connPanel) {
        toggleConnectionPanel(connPanel);
        const layout = $('#connectionsLayout');
        const collapsed = layout && layout.classList.contains(connPanel === 'relationship' ? 'relationship-collapsed' : 'resources-collapsed');
        btn.textContent = collapsed ? '»' : '«';
        btn.setAttribute('aria-expanded', collapsed ? 'false' : 'true');
        return;
      }
      const paneId = btn.dataset.collapsePane;
      const pane = document.getElementById(paneId);
      const shell = $('#reportDesignerShell');
      if (!pane || !shell) return;

      if (shell.classList.contains('designer-fullscreen')) {
        const isOpening = pane.classList.contains('collapsed');
        const otherPaneId = paneId === 'visualizationsPane' ? 'dataPane' : 'visualizationsPane';
        const otherPane = document.getElementById(otherPaneId);
        if (otherPane) {
          otherPane.classList.add('collapsed');
          const otherBtn = otherPane.querySelector('.pane-collapse-btn');
          if (otherBtn) {
            otherBtn.textContent = '«';
            otherBtn.setAttribute('aria-expanded', 'false');
          }
          shell.classList.add(otherPaneId === 'visualizationsPane' ? 'visuals-collapsed' : 'data-collapsed');
        }
        pane.classList.toggle('collapsed', !isOpening);
        btn.textContent = isOpening ? '»' : '«';
        btn.setAttribute('aria-expanded', isOpening ? 'true' : 'false');
        shell.classList.toggle(paneId === 'visualizationsPane' ? 'visuals-collapsed' : 'data-collapsed', !isOpening);
        return;
      }

      const collapsed = pane.classList.toggle('collapsed');
      btn.textContent = collapsed ? '«' : '»';
      btn.setAttribute('aria-expanded', collapsed ? 'false' : 'true');
      shell.classList.toggle(paneId === 'visualizationsPane' ? 'visuals-collapsed' : 'data-collapsed', collapsed);
    });
  });
}

function setupSidebarCollapse() {
  const btn = $('#sidebarCollapseBtn');
  const expandBtn = $('#sidebarExpandFab');
  if (!btn) return;

  const applySidebarState = (collapsed) => {
    document.body.classList.toggle('sidebar-collapsed', Boolean(collapsed));
    try { localStorage.setItem('biwa.sidebarCollapsed', collapsed ? '1' : '0'); } catch (err) {}
    btn.setAttribute('title', collapsed ? 'Expandir menu lateral' : 'Recolher menu lateral');
    if (expandBtn) expandBtn.hidden = !collapsed;
  };

  if (btn.dataset.bound !== '1') {
    btn.dataset.bound = '1';
    btn.addEventListener('click', () => applySidebarState(!document.body.classList.contains('sidebar-collapsed')));
  }

  if (expandBtn && expandBtn.dataset.bound !== '1') {
    expandBtn.dataset.bound = '1';
    expandBtn.addEventListener('click', () => applySidebarState(false));
  }

  let storedCollapsed = false;
  try { storedCollapsed = localStorage.getItem('biwa.sidebarCollapsed') === '1'; } catch (err) {}
  applySidebarState(storedCollapsed);
}

function nextVisualZIndex() {
  const list = Array.isArray(state.reportVisuals) ? state.reportVisuals : [];
  return list.reduce((max, item) => Math.max(max, Number(item && item.layout && item.layout.zIndex) || 0), 0) + 1;
}

function normalizeVisualLayout(layout = {}, options = {}) {
  const resizeFromTopLeft = Boolean(options.resizeFromTopLeft);
  let width = clampNumber(layout.width, VISUAL_MIN_WIDTH, REPORT_CANVAS_WIDTH, 560);
  let height = clampNumber(layout.height, VISUAL_MIN_HEIGHT, REPORT_CANVAS_HEIGHT, 360);
  let x = Number.isFinite(Number(layout.x)) ? Number(layout.x) : 32;
  let y = Number.isFinite(Number(layout.y)) ? Number(layout.y) : 32;
  if (resizeFromTopLeft) {
    x = clampNumber(x, 0, REPORT_CANVAS_WIDTH - VISUAL_MIN_WIDTH, 32);
    y = clampNumber(y, 0, REPORT_CANVAS_HEIGHT - VISUAL_MIN_HEIGHT, 32);
    width = clampNumber(width, VISUAL_MIN_WIDTH, REPORT_CANVAS_WIDTH - x, Math.min(560, REPORT_CANVAS_WIDTH - x));
    height = clampNumber(height, VISUAL_MIN_HEIGHT, REPORT_CANVAS_HEIGHT - y, Math.min(360, REPORT_CANVAS_HEIGHT - y));
  } else {
    x = clampNumber(x, 0, REPORT_CANVAS_WIDTH - width, 32);
    y = clampNumber(y, 0, REPORT_CANVAS_HEIGHT - height, 32);
  }
  return {
    x: Math.round(x),
    y: Math.round(y),
    width: Math.round(width),
    height: Math.round(height),
    zIndex: Math.max(1, Math.round(Number.isFinite(Number(layout.zIndex)) ? Number(layout.zIndex) : 1))
  };
}

function resizeVisualLayoutFromCorner(layout, corner, deltaX, deltaY) {
  const start = normalizeVisualLayout(layout || {});
  const direction = ['nw', 'ne', 'sw', 'se'].includes(String(corner || '').toLowerCase())
    ? String(corner).toLowerCase()
    : 'se';
  const dx = Number.isFinite(Number(deltaX)) ? Number(deltaX) : 0;
  const dy = Number.isFinite(Number(deltaY)) ? Number(deltaY) : 0;
  const startRight = start.x + start.width;
  const startBottom = start.y + start.height;
  let left = start.x;
  let right = startRight;
  let top = start.y;
  let bottom = startBottom;

  if (direction.includes('w')) {
    left = clampNumber(applySnap(start.x + dx), 0, startRight - VISUAL_MIN_WIDTH, start.x);
  } else {
    right = clampNumber(applySnap(startRight + dx), start.x + VISUAL_MIN_WIDTH, REPORT_CANVAS_WIDTH, startRight);
  }

  if (direction.includes('n')) {
    top = clampNumber(applySnap(start.y + dy), 0, startBottom - VISUAL_MIN_HEIGHT, start.y);
  } else {
    bottom = clampNumber(applySnap(startBottom + dy), start.y + VISUAL_MIN_HEIGHT, REPORT_CANVAS_HEIGHT, startBottom);
  }

  return normalizeVisualLayout({
    x: left,
    y: top,
    width: right - left,
    height: bottom - top,
    zIndex: start.zIndex
  }, { resizeFromTopLeft: true });
}

function pageCanvasSize() {
  return { width: REPORT_CANVAS_WIDTH, height: REPORT_CANVAS_HEIGHT };
}

function selectedVisualForLayout() {
  const visual = selectedReportVisual();
  if (!visual) return null;
  visual.layout = normalizeVisualLayout(visual.layout || {});
  return visual;
}

function updateActiveVisualLayout(mutator, message) {
  const visual = selectedVisualForLayout();
  if (!visual) return toast('Selecione um visual no canvas.', 'error');
  visual.layout = normalizeVisualLayout(mutator({ ...visual.layout }) || visual.layout);
  renderReportPageVisuals();
  applyVisualControls(visual);
  setMainRibbonTab('visual');
  if (message) toast(message);
}

function alignActiveVisual(edge) {
  updateActiveVisualLayout((layout) => {
    if (edge === 'left') layout.x = 24;
    if (edge === 'top') layout.y = 24;
    return layout;
  }, edge === 'left' ? 'Visual alinhado a esquerda.' : 'Visual alinhado ao topo.');
}

function centerActiveVisual() {
  const size = pageCanvasSize();
  updateActiveVisualLayout((layout) => {
    layout.x = applySnap((size.width - layout.width) / 2);
    layout.y = applySnap((size.height - layout.height) / 2);
    return layout;
  }, 'Visual centralizado na pagina.');
}

function bringActiveVisualToFront() {
  updateActiveVisualLayout((layout) => {
    layout.zIndex = nextVisualZIndex();
    return layout;
  }, 'Visual trazido para frente.');
}

function sendActiveVisualToBack() {
  const list = Array.isArray(state.reportVisuals) ? state.reportVisuals : [];
  const minZ = list.reduce((min, item) => Math.min(min, Number(item && item.layout && item.layout.zIndex) || 1), Infinity);
  updateActiveVisualLayout((layout) => {
    layout.zIndex = Math.max(1, (isFinite(minZ) ? minZ : 1) - 1);
    return layout;
  }, 'Visual enviado para o fundo.');
}

function bringActiveVisualForward() {
  const visual = selectedVisualForLayout();
  if (!visual) return toast('Selecione um visual no canvas.', 'error');
  const list = Array.isArray(state.reportVisuals) ? state.reportVisuals : [];
  const currentZ = visual.layout.zIndex || 1;
  const nexts = list
    .filter((v) => v.id !== visual.id && Number(v.layout && v.layout.zIndex) > currentZ)
    .sort((a, b) => Number(a.layout.zIndex) - Number(b.layout.zIndex));
  if (!nexts.length) { toast('Visual ja esta na posicao mais a frente.', 'info'); return; }
  const targetZ = Number(nexts[0].layout.zIndex);
  nexts[0].layout.zIndex = currentZ;
  updateActiveVisualLayout((layout) => { layout.zIndex = targetZ; return layout; }, 'Visual avancado uma posicao.');
}

function sendActiveVisualBackward() {
  const visual = selectedVisualForLayout();
  if (!visual) return toast('Selecione um visual no canvas.', 'error');
  const list = Array.isArray(state.reportVisuals) ? state.reportVisuals : [];
  const currentZ = visual.layout.zIndex || 1;
  const prevs = list
    .filter((v) => v.id !== visual.id && Number(v.layout && v.layout.zIndex) < currentZ)
    .sort((a, b) => Number(b.layout.zIndex) - Number(a.layout.zIndex));
  if (!prevs.length) { toast('Visual ja esta na posicao mais ao fundo.', 'info'); return; }
  const targetZ = Number(prevs[0].layout.zIndex);
  prevs[0].layout.zIndex = currentZ;
  updateActiveVisualLayout((layout) => { layout.zIndex = targetZ; return layout; }, 'Visual recuado uma posicao.');
}

function cloneReportVisualSnapshot(visual) {
  if (!visual || typeof visual !== 'object') return null;
  try {
    if (typeof structuredClone === 'function') return structuredClone(visual);
  } catch (err) {
    // Visuals are persisted as JSON; use the same representation as a safe fallback.
  }
  try {
    return JSON.parse(JSON.stringify(visual));
  } catch (err) {
    return null;
  }
}

function createVisualCopy(source, options = {}) {
  const snapshot = cloneReportVisualSnapshot(source);
  if (!snapshot) return null;
  const layout = normalizeVisualLayout(snapshot.layout || {});
  const offsetStep = Math.max(1, Number(options.offsetStep) || 1);
  snapshot.id = newVisualId();
  snapshot.title = snapshot.title ? snapshot.title + ' - cópia' : '';
  snapshot.layout = normalizeVisualLayout({
    ...layout,
    x: applySnap(layout.x + (32 * offsetStep)),
    y: applySnap(layout.y + (32 * offsetStep)),
    zIndex: nextVisualZIndex()
  });
  snapshot.style = normalizeVisualStyle(snapshot.style);
  snapshot.pageId = options.pageId || state.activeReportPageId;
  return snapshot;
}

function insertVisualCopy(source, options = {}) {
  const copy = createVisualCopy(source, options);
  if (!copy) return null;
  state.reportVisuals.push(copy);
  state.activeVisualId = copy.id;
  renderReportPageVisuals();
  applyVisualControls(copy);
  return copy;
}

function duplicateActiveVisual() {
  const source = syncActiveVisualFromControls();
  if (source && !visualControlsMatch(source)) return toast('Selecione novamente o visual para duplicar.', 'error');
  if (!source) return toast('Selecione um visual para duplicar.', 'error');
  if (!insertVisualCopy(source)) return toast('Não foi possível duplicar o visual.', 'error');
  toast('Visual duplicado.');
}

function copyActiveVisualToClipboard() {
  const source = syncActiveVisualFromControls();
  if (source && !visualControlsMatch(source)) return toast('Selecione novamente o visual para copiar.', 'error');
  if (!source) return toast('Selecione um visual para copiar.', 'error');
  const snapshot = cloneReportVisualSnapshot(source);
  if (!snapshot) return toast('Não foi possível copiar o visual.', 'error');
  state.visualClipboard = { visual: snapshot, pasteCount: 0 };
  toast('Visual copiado. Use Ctrl+V para colar.');
}

function pasteVisualFromClipboard() {
  const clipboard = state.visualClipboard;
  if (!clipboard || !clipboard.visual) return toast('Copie um visual primeiro com Ctrl+C.', 'error');
  const nextPasteCount = (Number(clipboard.pasteCount) || 0) + 1;
  const copy = insertVisualCopy(clipboard.visual, {
    offsetStep: nextPasteCount,
    pageId: state.activeReportPageId
  });
  if (!copy) return toast('Não foi possível colar o visual.', 'error');
  clipboard.pasteCount = nextPasteCount;
  toast('Visual colado.');
}

function nudgeActiveVisual(dx, dy, resize = false) {
  const visual = selectedVisualForLayout();
  if (!visual) return;
  const layout = { ...visual.layout };
  if (resize) {
    layout.width = Math.max(VISUAL_MIN_WIDTH, applySnap(layout.width + dx));
    layout.height = Math.max(VISUAL_MIN_HEIGHT, applySnap(layout.height + dy));
  } else {
    layout.x = Math.max(0, applySnap(layout.x + dx));
    layout.y = Math.max(0, applySnap(layout.y + dy));
  }
  visual.layout = normalizeVisualLayout(layout, { resizeFromTopLeft: resize });
  const frame = getActiveVisualFrame();
  if (frame) {
    frame.style.left = visual.layout.x + 'px';
    frame.style.top = visual.layout.y + 'px';
    frame.style.width = visual.layout.width + 'px';
    frame.style.height = visual.layout.height + 'px';
    frame.style.zIndex = String(visual.layout.zIndex || 1);
    frame.dataset.size = visual.layout.width + ' x ' + visual.layout.height;
  }
  updateDesignerStatusStrip();
}

function normalizeCanvasZoom(value) {
  return Math.max(REPORT_CANVAS_MIN_ZOOM, Math.min(REPORT_CANVAS_MAX_ZOOM, Number(value) || 1));
}

function applyCanvasZoomToDom() {
  const zoom = normalizeCanvasZoom(state.reportCanvasZoom || 1);
  const zoomPercent = Math.round(zoom * 100);
  state.reportCanvasZoom = zoom;
  const page = $('#reportPage');
  const stage = $('#reportCanvasStage');
  if (page) {
    page.style.setProperty('--canvas-zoom', String(zoom));
    page.dataset.canvasZoom = String(zoom);
  }
  if (stage) {
    stage.style.width = Math.round(REPORT_CANVAS_WIDTH * zoom) + 'px';
    stage.style.height = Math.round(REPORT_CANVAS_HEIGHT * zoom) + 'px';
    stage.style.setProperty('--canvas-zoom', String(zoom));
  }
  const zoomValueBtn = $('#canvasZoomResetBtn');
  if (zoomValueBtn) {
    zoomValueBtn.textContent = zoomPercent + '%';
    zoomValueBtn.title = 'Zoom atual: ' + zoomPercent + '%. Clique para restaurar 100%.';
  }
}

function updateCanvasZoom(nextZoom) {
  const viewport = $('#reportCanvasViewport');
  const stage = $('#reportCanvasStage');
  const previousZoom = normalizeCanvasZoom(state.reportCanvasZoom || 1);
  const anchorX = viewport && stage ? (viewport.scrollLeft + (viewport.clientWidth / 2) - stage.offsetLeft) / previousZoom : REPORT_CANVAS_WIDTH / 2;
  const anchorY = viewport && stage ? (viewport.scrollTop + (viewport.clientHeight / 2) - stage.offsetTop) / previousZoom : REPORT_CANVAS_HEIGHT / 2;
  state.reportCanvasZoom = normalizeCanvasZoom(nextZoom);
  applyCanvasZoomToDom();
  if (viewport && stage) {
    requestAnimationFrame(() => {
      viewport.scrollLeft = Math.max(0, stage.offsetLeft + (anchorX * state.reportCanvasZoom) - (viewport.clientWidth / 2));
      viewport.scrollTop = Math.max(0, stage.offsetTop + (anchorY * state.reportCanvasZoom) - (viewport.clientHeight / 2));
    });
  }
}

function fitCanvasToViewport() {
  const viewport = $('#reportCanvasViewport');
  if (!viewport) return updateCanvasZoom(1);
  const pad = 32;
  const maxW = Math.max(320, viewport.clientWidth - pad);
  const maxH = Math.max(240, viewport.clientHeight - pad);
  const zoomW = maxW / REPORT_CANVAS_WIDTH;
  const zoomH = maxH / REPORT_CANVAS_HEIGHT;
  updateCanvasZoom(Math.min(zoomW, zoomH));
}

function setReportFullscreenUi(active) {
  const shell = $('#reportDesignerShell');
  const fullscreenBtn = $('#fullscreenCanvasBtn');
  if (!shell) return;
  shell.classList.toggle('designer-fullscreen', Boolean(active));
  document.body.classList.toggle('report-designer-fullscreen-active', Boolean(active));
  if (fullscreenBtn) {
    fullscreenBtn.textContent = '⛶';
    fullscreenBtn.title = active ? 'Sair da tela cheia' : 'Abrir editor em tela cheia';
    fullscreenBtn.setAttribute('aria-label', fullscreenBtn.title);
    fullscreenBtn.setAttribute('aria-pressed', active ? 'true' : 'false');
  }

  const visualsPane = $('#visualizationsPane');
  const dataPane = $('#dataPane');
  if (active) {
    [visualsPane, dataPane].forEach((pane) => {
      if (!pane) return;
      pane.classList.add('collapsed');
      const btn = pane.querySelector('.pane-collapse-btn');
      if (btn) {
        btn.textContent = '«';
        btn.setAttribute('aria-expanded', 'false');
      }
    });
    shell.classList.add('visuals-collapsed', 'data-collapsed');
    setTimeout(fitCanvasToViewport, 120);
  } else {
    setTimeout(() => renderReportPageVisuals(), 80);
  }
}

async function toggleCanvasFullscreen() {
  const shell = $('#reportDesignerShell');
  if (!shell) return;
  if (document.fullscreenElement) {
    await document.exitFullscreen().catch(() => {});
    return;
  }
  if (shell.classList.contains('designer-fullscreen')) {
    setReportFullscreenUi(false);
    return;
  }
  if (shell.requestFullscreen) {
    try {
      await shell.requestFullscreen();
      if (!document.fullscreenElement) setReportFullscreenUi(true);
      return;
    } catch (_) {}
  }
  setReportFullscreenUi(true);
}

function toggleModelVisualFullscreen() {
  const panel = document.querySelector('.connections-canvas-panel');
  if (!panel) return;
  if (!document.fullscreenElement) {
    panel.requestFullscreen().catch(() => {});
  } else {
    document.exitFullscreen().catch(() => {});
  }
}


function updateDesignerStatusStrip() {
  const el = $('#designerStatusStrip');
  if (!el) return;
  ensureReportPages();
  const page = state.reportPages.find((item) => item.id === state.activeReportPageId) || state.reportPages[0] || { name: 'Página 1' };
  if (state.activeVisualId === null) {
    el.innerHTML = [
      'Página: ' + escapeHtml(page.name || 'Página 1'),
      'Visual: Nenhum selecionado',
      'Campos: clique em um visual ou crie um novo'
    ].map((text) => `<span>${text}</span>`).join('');
    return;
  }
  const visual = selectedReportVisual();
  if (!visual) {
    el.innerHTML = [
      'Página: ' + escapeHtml(page.name || 'Página 1'),
      'Visual: Nenhum selecionado',
      'Campos: crie um visual para começar'
    ].map((text) => `<span>${text}</span>`).join('');
    return;
  }
  const fields = [];
  if (visual.table) fields.push('Fonte: ' + visual.table);
  if (visual.dimension) fields.push('Eixo: ' + visual.dimension);
  if (visual.value) fields.push('Valor: ' + visual.value);
  if (visual.secondaryValue) fields.push('Valor 2: ' + visual.secondaryValue);
  const selectedFields = normalizeSelectedFields(visual.selectedFields).map((item) => item.name);
  if (selectedFields.length) fields.push('Campos: ' + selectedFields.join(', '));
  if (visual.aggregation) fields.push('Agregação: ' + visual.aggregation);
  el.innerHTML = [
    'Página: ' + escapeHtml(page.name || 'Página 1'),
    'Visual: ' + escapeHtml(visual.title || 'Sem título') + ' / ' + escapeHtml(visual.visualization || (($('#reportViz') && $('#reportViz').value) || 'table')),
    'Campos: ' + escapeHtml(fields.length ? fields.join(' · ') : 'aguardando seleção')
  ].map((text) => `<span>${text}</span>`).join('');
}

function flashDesignerTarget(target) {
  if (!target) return;
  target.classList.remove('focus-flash');
  void target.offsetWidth;
  target.classList.add('focus-flash');
  setTimeout(() => target.classList.remove('focus-flash'), 1300);
}



async function openOnlinePortalPreview(reportId = '', returnTab = 'onlineTab') {
  await loadOnlineCustomization();
  state.onlinePortalPreview = true;
  state.onlinePortalPreviewReturnTab = returnTab;
  if (reportId && state.reports.some((report) => String(report.id) === String(reportId))) state.onlineActiveReportId = String(reportId);
  ensureOnlinePortalSelection();
  document.body.classList.add('online-portal-preview-mode');
  // setActiveTab cria a assinatura do relatório ativo; renderize o cache
  // existente enquanto essa única execução real é processada pelo servidor.
  setActiveTab('dashboardTab');
  renderDashboard();
}

async function resumeDashboardUpdates() {
  if (!isAdminSession()) return null;
  return api('/api/dashboard/resume-updates', {
    method: 'POST',
    body: JSON.stringify({}),
    timeoutMs: 60 * 60 * 1000
  });
}

function previewCurrentReportOnline() {
  if (state.editingReportId) {
    openOnlinePortalPreview(state.editingReportId, 'sqlTab').catch((err) => toast(err.message, 'error'));
    toast('Prévia aberta no portal Online.');
    return;
  }
  toast('Salve o relatório primeiro para visualizar no Online.', 'error');
}

async function publishFromEditor() {
  if (!state.editingReportId) {
    toast('Salve o relatório antes de publicar no Online.', 'error');
    return;
  }
  await publishReports();
}

