      const step = ev.shiftKey ? 24 : 8;
      const resize = ev.altKey;
      if (ev.key === 'ArrowLeft') { ev.preventDefault(); nudgeActiveVisual(-step, 0, resize); }
      if (ev.key === 'ArrowRight') { ev.preventDefault(); nudgeActiveVisual(step, 0, resize); }
