function startTextboxEditing(visualId) {
  const frame = getVisualFrame(visualId);
  const visual = state.reportVisuals.find((item) => String(item.id) === String(visualId));
  const contentEl = frame && frame.querySelector('.textbox-content');
  if (!visual || !contentEl || String(visual.visualization || '').toLowerCase() !== 'textbox' || contentEl.contentEditable === 'true') return false;
  contentEl.contentEditable = 'true';
  contentEl.focus();
  const selection = window.getSelection();
  if (selection) {
    const range = document.createRange();
    range.selectNodeContents(contentEl);
    range.collapse(false);
    selection.removeAllRanges();
    selection.addRange(range);
  }
  const finish = () => {
    contentEl.contentEditable = 'false';
    const nextContent = String(contentEl.innerText || '').trim() ? contentEl.innerHTML : '';
    contentEl.innerHTML = nextContent;
    visual.content = nextContent;
    const textControl = $('#visualTextContent');
    if (textControl) textControl.value = nextContent;
    contentEl.removeEventListener('keydown', handleKeydown);
  };
  const handleKeydown = (event) => {
    if (event.key === 'Escape') contentEl.blur();
  };
  contentEl.addEventListener('blur', finish, { once: true });
  contentEl.addEventListener('keydown', handleKeydown);
  return true;
}

function setupReportCanvasDesigner(skipRender = false) {
  if (!skipRender) renderReportPageVisuals();
  const page = $('#reportPage');
  if (!page) return;
  if (page.dataset.multiDesignerBound !== '1') {
    page.dataset.multiDesignerBound = '1';
    page.addEventListener('pointerdown', (ev) => {
      if (ev.button !== undefined && ev.button !== 0) return;
      const frame = ev.target.closest && ev.target.closest('.visual-frame');
      if (!frame || !frame.dataset.visualId || state.activeVisualId === frame.dataset.visualId) return;
      // Captura antes do ECharts/canvas consumir o evento, sem recriar o gráfico
      // durante o clique. Assim rosca, funil e demais gráficos também selecionam.
      setActiveReportVisual(frame.dataset.visualId, { preserveCanvas: true });
    }, true);
    page.addEventListener('click', (ev) => {
      const remove = ev.target.closest('[data-remove-visual]');
      if (remove) { ev.stopPropagation(); removeReportVisual(remove.dataset.removeVisual); return; }
      const frame = ev.target.closest('.visual-frame');
      if (frame && frame.dataset.visualId) {
        if (state.activeVisualId !== frame.dataset.visualId) setActiveReportVisual(frame.dataset.visualId);
      }
      else if (ev.target.closest('#reportPage')) {
        invalidateVisualAutoUpdate();
        state.activeVisualId = null;
        renderReportPageVisuals();
        applyVisualControls(null);
      }
    });
    const canvasViewport = $('#reportCanvasViewport');
    if (canvasViewport && !canvasViewport.dataset.canvasClickBound) {
      canvasViewport.dataset.canvasClickBound = '1';
      canvasViewport.addEventListener('click', (ev) => {
        if (!ev.target.closest('.report-page') && !ev.target.closest('.visual-frame')) {
          invalidateVisualAutoUpdate();
          state.activeVisualId = null;
          renderReportPageVisuals();
          applyVisualControls(null);
        }
      });
    }
    page.addEventListener('dragover', (ev) => ev.preventDefault());
    page.addEventListener('drop', async (ev) => {
      ev.preventDefault();
      const pageRect = page.getBoundingClientRect();
      const z = state.reportCanvasZoom || 1;
      const dropLayout = { x: (ev.clientX - pageRect.left) / z - 80, y: (ev.clientY - pageRect.top) / z - 30, width: 560, height: 360 };
      const viz = ev.dataTransfer.getData('text/biwa-viz');
      if (viz) { addReportVisual(viz, dropLayout); return; }
      const table = ev.dataTransfer.getData('text/biwa-table');
      const field = ev.dataTransfer.getData('text/biwa-field');
      const type = ev.dataTransfer.getData('text/biwa-type');
      const targetFrame = ev.target.closest('.visual-frame');
      if (targetFrame && targetFrame.dataset.visualId) {
        await setActiveReportVisual(targetFrame.dataset.visualId, { preserveCanvas: true });
      } else if (!getActiveVisualFrame()) {
        addReportVisual('table', dropLayout);
      }
      const targetVisual = selectedReportVisual();
      const targetVisualId = String(targetVisual && targetVisual.id || '');
      if (!targetVisualId || !visualControlsMatch(targetVisual)) return;
      if (table && $('#builderTableSelect')) $('#builderTableSelect').value = table;
      if (field) {
        const after = async () => {
          if (table) await loadBuilderColumns(table, { expectedVisualId: targetVisualId });
          const current = selectedReportVisual();
          if (!current || String(current.id) !== targetVisualId || !visualControlsMatch(current)) return;
          assignBuilderField('auto', field, type, table);
          toast('Campo adicionado ao visual. Atualizando automaticamente...');
        };
        after().catch((err) => toast(err.message, 'error'));
      }
    });
  }
  page.querySelectorAll('.visual-frame').forEach((frame) => {
    if (frame.dataset.bound === '1') return;
    frame.dataset.bound = '1';
    const head = frame.querySelector('.visual-frame-head');
    const resizeHandles = frame.querySelectorAll('[data-visual-resize-corner]');
    const moveEdges = frame.querySelectorAll('[data-visual-move-edge]');
    const visualId = frame.dataset.visualId;
    const startVisualMove = (ev) => {
      if (ev.button !== 0 || ev.target.closest('button')) return;
      ev.preventDefault();
      if (String(state.activeVisualId || '') !== String(visualId)) {
        setActiveReportVisual(visualId, { preserveCanvas: true });
      }
      frame.focus({ preventScroll: true });
      const visual = state.reportVisuals.find((item) => String(item.id) === String(visualId));
      if (!visual) return;
      const start = normalizeVisualLayout(visual && visual.layout ? visual.layout : getVisualLayout());
      const sx = ev.clientX;
      const sy = ev.clientY;
      const z = normalizeCanvasZoom(state.reportCanvasZoom || 1);
      frame.classList.add('dragging', 'selected');
      const move = (e) => {
        const next = normalizeVisualLayout({ ...start, x: applySnap(start.x + (e.clientX - sx) / z), y: applySnap(start.y + (e.clientY - sy) / z) });
        if (visual) visual.layout = next;
        frame.style.left = next.x + 'px';
        frame.style.top = next.y + 'px';
      };
      const up = () => {
        frame.classList.remove('dragging');
        window.removeEventListener('mousemove', move);
        window.removeEventListener('mouseup', up);
      };
      window.addEventListener('mousemove', move);
      window.addEventListener('mouseup', up);
    };
    if (head) head.addEventListener('mousedown', startVisualMove);
    moveEdges.forEach((edge) => edge.addEventListener('mousedown', startVisualMove));
    resizeHandles.forEach((handle) => handle.addEventListener('mousedown', (ev) => {
      const corner = handle.dataset.visualResizeCorner || 'se';
      if (ev.button !== 0) return;
      ev.preventDefault();
      ev.stopPropagation();
      if (String(state.activeVisualId || '') !== String(visualId)) {
        setActiveReportVisual(visualId, { preserveCanvas: true });
      }
      frame.focus({ preventScroll: true });
      const visual = state.reportVisuals.find((item) => String(item.id) === String(visualId));
      if (!visual) return;
      const start = normalizeVisualLayout(visual && visual.layout ? visual.layout : getVisualLayout());
      const sx = ev.clientX;
      const sy = ev.clientY;
      const z = normalizeCanvasZoom(state.reportCanvasZoom || 1);
      let chartResizeFrame = 0;
      frame.classList.add('resizing', 'selected', 'active-visual');
      const resizeChart = () => {
        if (chartResizeFrame) return;
        chartResizeFrame = requestAnimationFrame(() => {
          chartResizeFrame = 0;
          resizeEChartsWithin(frame);
        });
      };
      const move = (e) => {
        const next = resizeVisualLayoutFromCorner(start, corner, (e.clientX - sx) / z, (e.clientY - sy) / z);
        if (visual) visual.layout = next;
        frame.style.left = next.x + 'px';
        frame.style.top = next.y + 'px';
        frame.style.width = next.width + 'px';
        frame.style.height = next.height + 'px';
        frame.dataset.size = next.width + ' x ' + next.height;
        resizeChart();
      };
      const up = () => {
        frame.classList.remove('resizing');
        resizeEChartsWithin(frame);
        updateDesignerStatusStrip();
        window.removeEventListener('mousemove', move);
        window.removeEventListener('mouseup', up);
        window.removeEventListener('blur', up);
      };
      window.addEventListener('mousemove', move);
      window.addEventListener('mouseup', up);
      window.addEventListener('blur', up);
    }));
    frame.addEventListener('dblclick', (ev) => {
      if (ev.target.closest('button')) return;
      if (String(state.activeVisualId || '') !== String(visualId)) {
        setActiveReportVisual(visualId, { preserveCanvas: true });
      }
      const visual = state.reportVisuals.find((item) => item.id === visualId);
      if (!visual || String(visual.visualization || '').toLowerCase() !== 'textbox') return;
      ev.stopPropagation();
      startTextboxEditing(visualId);
    });
  });
  
  if (typeof setupTableInteractivity === 'function') {
    setupTableInteractivity();
  }
}

function modelResourceOptionsHtml(selected = '') {
  if (!state.resources.length) return '<option value="">Nenhuma tabela/view encontrada</option>';
  return state.resources.map((item) => `<option value="${escapeHtml(item.name)}" ${item.name === selected ? 'selected' : ''}>${escapeHtml(item.name)} - ${escapeHtml(resourceBadge(item))}</option>`).join('');
}

async function loadModel() {
  if (isOnlineMode()) return;
  try {
    const data = await api('/api/model');
    state.model = data.model || { tables: [], tablePositions: {}, selectedColumns: [], relationships: [], measures: [] };
  } catch (err) {
    state.model = { tables: [], tablePositions: {}, selectedColumns: [], relationships: [], measures: [] };
  }
  renderModelDesigner();
}

function nativeCalendarColumns() {
  return [
    ['Data', 'DATE'], ['DataKey', 'INT'], ['Ano', 'INT'], ['MesNumero', 'INT'], ['MesNome', 'VARCHAR(20)'],
    ['MesNomeCurto', 'VARCHAR(10)'], ['AnoMes', 'VARCHAR(7)'], ['AnoMesNome', 'VARCHAR(20)'], ['Dia', 'INT'],
    ['DiaSemanaNumero', 'INT'], ['DiaSemanaNome', 'VARCHAR(20)'], ['DiaDoAno', 'INT'], ['SemanaAno', 'INT'],
    ['Trimestre', 'INT'], ['TrimestreNome', 'VARCHAR(20)'], ['Semestre', 'INT'], ['InicioMes', 'DATE'],
    ['FimMes', 'DATE'], ['UltimoDiaMes', 'INT'], ['EhFimSemana', 'TINYINT(1)'], ['DiaUtil', 'TINYINT(1)']
  ].map(([name, columnType]) => ({ name, dataType: columnType.toLowerCase(), columnType, columnKey: name === 'Data' ? 'PRI' : '' }));
}

function columnNameOf(col) {
  return String(col && (col.name || col.Field || col) || '').trim();
}

function normalizeColumnMetadataList(columns) {
  return (Array.isArray(columns) ? columns : []).map(function(col) {
    if (typeof col === 'string') return { name: col, dataType: '', columnType: '' };
    return {
      ...col,
      name: columnNameOf(col),
      dataType: String((col && (col.dataType || col.Type || col.type)) || ''),
      columnType: String((col && (col.columnType || col.Type || col.type)) || '')
    };
  }).filter(function(col) { return col.name; });
}

function columnNames(columns) {
  return (Array.isArray(columns) ? columns : []).map(columnNameOf).filter(Boolean);
}

function invalidateModelColumnCache() {
  if (!state.modelColumnCache) state.modelColumnCache = {};
  Array.from(arguments).forEach(function(name) {
    var key = String(name || '').trim();
    if (key) delete state.modelColumnCache[key];
  });
}

async function loadModelColumns(table) {
  if (!table) return [];
  const cached = state.modelColumnCache[table];
  if (Array.isArray(cached) && cached.length && typeof cached[0] !== 'string') {
    state.modelColumnCache[table] = normalizeColumnMetadataList(cached);
    return state.modelColumnCache[table];
  }
  if (table === 'Calendario') {
    state.modelColumnCache[table] = nativeCalendarColumns();
    return state.modelColumnCache[table];
  }
  try {
    const data = await api('/api/tables/' + encodeURIComponent(table) + '/columns');
    state.modelColumnCache[table] = normalizeColumnMetadataList(data.columns || []);
  } catch (err) {
    state.modelColumnCache[table] = [];
  }
  return state.modelColumnCache[table];
}

function renderModelResourceSelects() {
  const main = $('#modelResourceSelect');
  if (main) {
    const current = main.value || (state.resources[0] && state.resources[0].name) || '';
    main.innerHTML = modelResourceOptionsHtml(current);
  }
  ['relFromTable', 'relToTable'].forEach((id) => {
    const el = document.getElementById(id);
    if (el) {
      const current = el.value || (state.resources[0] && state.resources[0].name) || '';
      el.innerHTML = modelResourceOptionsHtml(current);
    }
  });
}

async function renderModelColumnPicker() {
  const select = $('#modelResourceSelect');
  const container = $('#modelColumnList');
  if (!select || !container) return;
  const table = select.value;
  if (state._lastPreviewTable && state._lastPreviewTable !== table) {
    state.previewColumns = [];
  }
  state._lastPreviewTable = table;
  if (!table) {
    container.className = 'column-picker empty-state';
    container.textContent = 'Nenhuma tabela/view encontrada.';
    return;
  }
  try {
    const columns = await loadModelColumns(table);

    var typeOverrides = buildTypeOverridesFromTransform(table);

    container.className = 'column-picker';
    var tableName = select.value;
    container.innerHTML = columns.map((col) => {
      var colName = String(col && (col.name || '')).trim();
      var displayType = displayColumnType(col);
      var overridden = false;
      if (colName && typeOverrides[colName] !== undefined) {
        var override = normalizeDataType(typeOverrides[colName]);
        displayType = DISPLAY_TYPE_MAP[override] || override.toUpperCase();
        overridden = true;
      }
      var typeStyle = overridden ? ' style="color:#174ea6;font-weight:600"' : '';
      var isPreview = state.previewColumns.some(function(p) { return p.table === tableName && p.column === colName; });
      return '<label class="check-label model-check' + (isPreview ? ' preview-active' : '') + '">' +
        '<input type="checkbox" data-model-column="' + escapeHtml(colName) + '" disabled />' +
        '<span data-preview-column="' + escapeHtml(colName) + '"><b>' + escapeHtml(colName) + '</b> <em' + typeStyle + '>' + escapeHtml(displayType) + '</em></span>' +
        '</label>';
    }).join('') || '<div class="empty-state">Nenhuma coluna encontrada.</div>';
    container.querySelectorAll('[data-preview-column]').forEach(function(span) {
      span.addEventListener('click', function(ev) {
        ev.stopPropagation();
        var colName = span.dataset.previewColumn;
        var tableName = select.value;
        var existing = state.previewColumns.findIndex(function(p) { return p.table === tableName && p.column === colName; });
        if (existing >= 0) {
          state.previewColumns.splice(existing, 1);
        } else {
          var cols = state.modelColumnCache[tableName] || [];
          var colMeta = cols.find(function(c) { return c.name === colName; });
          var colType = colMeta ? displayColumnType(colMeta) : '';
          state.previewColumns.push({ table: tableName, column: colName, type: colType });
        }
        renderModelColumnPicker();
        renderSelectedModelColumns();
      });
    });
  } catch (err) {
    container.className = 'column-picker empty-state';
    container.textContent = err.message;
  }
}

function buildTypeOverridesFromTransform(table) {
  var overrides = {};
  if (!table) return overrides;
  var steps = state.transform.steps || [];
  if (!steps.length) return overrides;
  var source = ($('#transformSourceSelect') && $('#transformSourceSelect').value) || state.transform.source || '';
  if (source !== table) return overrides;
  steps.forEach(function (step) {
    if (step.kind === 'changeType' && step.column && step.dataType) {
      overrides[step.column] = step.dataType;
    }
  });
  return overrides;
}

async function renderRelationshipColumnSelect(tableSelectId, columnSelectId) {
  const tableEl = document.getElementById(tableSelectId);
  const colEl = document.getElementById(columnSelectId);
  if (!tableEl || !colEl) return;
  const table = tableEl.value;
  if (!table) {
    colEl.innerHTML = '<option value="">Selecione</option>';
    return;
  }
  try {
    const columns = await loadModelColumns(table);
    colEl.innerHTML = columns.map((c) => `<option value="${escapeHtml(c.name)}">${escapeHtml(c.name)}</option>`).join('') || '<option value="">Sem colunas</option>';
  } catch (err) {
    colEl.innerHTML = '<option value="">Erro ao carregar</option>';
  }
}

async function refreshRelationshipColumns() {
  await renderRelationshipColumnSelect('relFromTable', 'relFromColumn');
  await renderRelationshipColumnSelect('relToTable', 'relToColumn');
}

function renderSelectedModelColumns() {
  const el = $('#modelSelectedColumns');
  if (!el) return;
  const items = state.model.selectedColumns || [];
  const previews = state.previewColumns || [];
  if (!items.length && !previews.length) {
    el.className = 'model-list empty-state';
    el.textContent = 'Nenhuma coluna selecionada.';
    return;
  }
  el.className = 'model-list';
  el.innerHTML = items.map((item, idx) => `
    <div class="model-item">
      <div><b>${escapeHtml(item.alias || item.column)}</b><small>${escapeHtml(item.table)}[${escapeHtml(item.column)}]</small></div>
    </div>
  `).join('') + (previews.length ? '<div class="model-preview-divider">Pré-visualização</div>' : '') + previews.map(function(p) {
    var typeInfo = p.type ? ' <span class="badge-type">' + escapeHtml(p.type) + '</span>' : '';
    return '<div class="model-item model-item-preview">' +
      '<div><b>' + escapeHtml(p.column) + '</b><small>' + escapeHtml(p.table) + '[' + escapeHtml(p.column) + ']' + typeInfo + ' <span class="badge-preview">prévia</span></small></div>' +
      '</div>';
  }).join('');
  updateModelStats();
}

function renderRelationshipList() {
  const el = $('#relationshipList');
  if (!el) return;
  const items = state.model.relationships || [];
  if (!items.length) {
    el.className = 'model-list empty-state';
    el.textContent = 'Nenhum relacionamento criado.';
    return;
  }
  el.className = 'model-list rel-list';
  el.innerHTML = items.map((r, idx) => {
    var card = r.active === false ? ' rel-inactive' : '';
    var icons = [];
    icons.push('<span class="rel-badge" title="Tipo: ' + escapeHtml(r.joinType || 'LEFT') + '">' + escapeHtml(r.joinType || 'LEFT') + '</span>');
    if (r.cardinality) icons.push('<span class="rel-badge" title="Cardinalidade: ' + escapeHtml(r.cardinality) + '">' + escapeHtml(r.cardinality === 'many-to-one' ? '*:1' : r.cardinality === 'one-to-many' ? '1:*' : r.cardinality === 'one-to-one' ? '1:1' : '*:*') + '</span>');
    icons.push('<span class="rel-badge" title="Filtro: ' + escapeHtml(r.filterDirection || 'single') + '">' + escapeHtml(r.filterDirection === 'both' ? '⇄' : '→') + '</span>');
    if (r.active === false) icons.push('<span class="rel-badge rel-badge-warn">inativo</span>');
    return '<div class="model-item rel-item' + card + '">' +
      '<div class="rel-item-body">' +
        '<div class="rel-path">' +
          '<span class="rel-table">' + escapeHtml(r.fromTable) + '</span>' +
          '<span class="rel-col">[' + escapeHtml(r.fromColumn) + ']</span>' +
          '<span class="rel-arrow">→</span>' +
          '<span class="rel-table">' + escapeHtml(r.toTable) + '</span>' +
          '<span class="rel-col">[' + escapeHtml(r.toColumn) + ']</span>' +
        '</div>' +
        '<div class="rel-meta">' + icons.join(' ') + '</div>' +
      '</div>' +
    '</div>';
  }).join('');
  updateModelStats();
}

function closeAllMeasureMenus() {
  document.querySelectorAll('.measure-actions-menu.open').forEach(function(m) { m.classList.remove('open'); });
}

function renderMeasureList() {
  const el = $('#measureList');
  if (!el) return;
  const items = state.model.measures || [];
  if (!items.length) {
    el.className = 'model-measure-cards empty-state';
    el.textContent = 'Nenhuma medida criada.';
    const revalidateSelectedButton = $('#revalidateSelectedMeasureBtn');
    if (revalidateSelectedButton) revalidateSelectedButton.disabled = true;
    updateModelStats();
    return;
  }
  const selectedName = state.selectedMeasure && state.selectedMeasure.name;
  el.className = 'model-measure-cards';
  el.innerHTML = items.map((m) => {
    const formula = String(m.formula || '').trim();
    const status = String(m.diagnosticStatus || (formula ? 'nao_validada' : 'sem_formula'));
    const valid = ['valido', 'validado', 'ok', 'ok_com_dependencia'].includes(status);
    const invalid = ['funcao_nao_suportada', 'erro_conversao', 'dependencia_ausente', 'tabela_ausente', 'coluna_ausente', 'invalida'].includes(status);
    const validating = status === 'validando';
    const compatibility = status === 'sem_formula' || !formula;
    const statusLabel = valid ? 'ok' : (invalid ? 'invalid' : (validating ? 'validating' : (compatibility ? 'compatibility' : 'unvalidated')));
    const statusText = valid ? 'Válida' : (invalid ? 'Inválida' : (validating ? 'Validando' : (compatibility ? 'Aviso de compatibilidade' : 'Não validada')));
    const sel = selectedName === m.name ? ' selected' : '';
    return `<div class="model-measure-card${sel}" data-measure-name="${escapeHtml(m.name)}" title="${escapeHtml(m.lastDiagnostic || statusText)}">
      <span class="measure-card-name">${escapeHtml(m.displayName || m.name)}</span>
      <span class="measure-card-status ${statusLabel}">${escapeHtml(statusText)}</span>
    </div>`;
  }).join('');
  el.querySelectorAll('[data-measure-name]').forEach((card) => {
    card.addEventListener('click', () => showMeasureFormula(card.dataset.measureName));
  });
  // Se ja havia uma medida selecionada, mostra a formula
  if (selectedName) {
    const found = items.find((m) => m.name === selectedName);
    if (found) showMeasureFormula(selectedName);
  }
  const revalidateSelectedButton = $('#revalidateSelectedMeasureBtn');
  if (revalidateSelectedButton) revalidateSelectedButton.disabled = !state.selectedMeasure;
  updateModelStats();
}

function showMeasureFormula(name) {
  const items = state.model.measures || [];
  const m = items.find((item) => item.name === name);
  const display = $('#measureFormulaDisplay');
  if (!display) return;
  state.selectedMeasure = m || null;
  const revalidateSelectedButton = $('#revalidateSelectedMeasureBtn');
  if (revalidateSelectedButton) revalidateSelectedButton.disabled = !m;
  // Atualiza selecao visual nos cards
  document.querySelectorAll('[data-measure-name]').forEach((card) => {
    card.classList.toggle('selected', card.dataset.measureName === name);
  });
  if (!m) {
    display.className = 'measure-formula-display empty-state';
    display.textContent = 'Selecione uma medida ao lado para ver sua fórmula.';
    return;
  }
  display.className = 'measure-formula-display';
  const formula = String(m.formula || '').trim();
  if (!formula) {
    display.innerHTML = '<span style="color:#94a3b8;font-style:italic">Fórmula DAX pendente/importada do PBIX.</span>';
    return;
  }
  // Destaca a formula com syntax highlighting
  try {
    const highlighted = window.highlightDax(formula);
    display.innerHTML = highlighted + '<br>';
  } catch (e) {
    display.textContent = formula;
  }
}

function selectedConnectionTableNames() {
  const names = new Set();
  const modelTables = Array.isArray(state.model.tables) ? state.model.tables : [];
  modelTables.forEach((item) => {
    const name = typeof item === 'string' ? item : item && item.name;
    if (name) names.add(name);
  });
  (state.model.relationships || []).forEach((rel) => {
    if (rel.fromTable) names.add(rel.fromTable);
    if (rel.toTable) names.add(rel.toTable);
  });
  if (state.model.tablePositions && typeof state.model.tablePositions === 'object') {
    Object.keys(state.model.tablePositions).filter(Boolean).forEach((name) => names.add(name));
  }
  return Array.from(names);
}

function selectedConnectionResources() {
  const names = selectedConnectionTableNames();
  const byName = new Map((state.resources || []).map((item) => [item.name, item]));
  return names.map((name) => byName.get(name) || { name, type: 'table', source: 'model', readonly: true, label: 'modelo salvo' });
}

function connectionRelationshipResources() {
  const selected = selectedConnectionResources();
  return selected.length ? selected : state.resources;
}

function ensureModelTablesArray() {
  if (!Array.isArray(state.model.tables)) state.model.tables = [];
}

function setModelTableIncluded(name, included) {
  ensureModelTablesArray();
  const exists = state.model.tables.some((item) => (typeof item === 'string' ? item : item.name) === name);
  if (included && !exists) state.model.tables.push({ name });
  if (!included) {
    state.model.tables = state.model.tables.filter((item) => (typeof item === 'string' ? item : item.name) !== name);
    state.model.relationships = (state.model.relationships || []).filter((rel) => rel.fromTable !== name && rel.toTable !== name);
    if (state.model.tablePositions) delete state.model.tablePositions[name];
  }
  renderConnectionsDesigner();
}

function ensureConnectionPositions(resources) {
  if (!state.model.tablePositions || typeof state.model.tablePositions !== 'object') state.model.tablePositions = {};
  resources.forEach((item, idx) => {
    if (!state.model.tablePositions[item.name]) {
      const col = idx % 3;
      const row = Math.floor(idx / 3);
      state.model.tablePositions[item.name] = { x: 24 + col * 300, y: 24 + row * 390 };
    }
  });
}

function getConnectionCardPosition(name, idx = 0) {
  if (!state.model.tablePositions || typeof state.model.tablePositions !== 'object') state.model.tablePositions = {};
  if (!state.model.tablePositions[name]) {
    const col = idx % 3;
    const row = Math.floor(idx / 3);
    state.model.tablePositions[name] = { x: 24 + col * 300, y: 24 + row * 390 };
  }
  return state.model.tablePositions[name];
}

function clampConnectionCardPosition(x, y) {
  return {
    x: Math.max(0, Math.min(3200, Math.round(Number(x) || 0))),
    y: Math.max(0, Math.min(3200, Math.round(Number(y) || 0)))
  };
}

function toggleConnectionPanel(which) {
  const layout = $('#connectionsLayout');
  if (!layout) return;
  const cls = which === 'relationship' ? 'relationship-collapsed' : 'resources-collapsed';
  layout.classList.toggle(cls);
  requestAnimationFrame(function() {
    requestAnimationFrame(function() { drawConnectionRelationshipLines(); });
  });
}

function connectionResourceOptionsHtml(selected = '') {
  const resources = connectionRelationshipResources();
  if (!resources.length) return '<option value="">Nenhuma tabela/view selecionada</option>';
  return resources.map((item) => `<option value="${escapeHtml(item.name)}" ${item.name === selected ? 'selected' : ''}>${escapeHtml(item.name)} - ${escapeHtml(resourceBadge(item))}</option>`).join('');
}

function renderConnectionResourceList() {
  const el = $('#connectionResourceList');
  if (!el) return;
  if (state.resourcesLoading) {
    el.className = 'connection-resource-list empty-state';
    el.textContent = 'Carregando tabelas e views...';
    return;
  }
  if (state.resourcesError) {
    el.className = 'connection-resource-list empty-state';
    el.innerHTML = `<div class="error-box"><b>Erro ao carregar tabelas/views.</b><br>${escapeHtml(state.resourcesError)}</div>`;
    return;
  }
  if (!state.resources.length) {
    el.className = 'connection-resource-list empty-state';
    el.textContent = 'Nenhuma tabela ou view encontrada.';
    return;
  }
  const selected = new Set(selectedConnectionTableNames());
  const groupHtml = (title, items) => items.length ? `
    <div class="resource-group-title">${escapeHtml(title)}</div>
    ${items.map((item) => `
      <label class="connection-resource-row ${item.name === 'Calendario' ? 'native-row' : ''}${item.manual ? ' manual-row' : ''}" draggable="true" data-connection-resource-drag="${escapeHtml(item.name)}" title="Arraste para o modelo visual">
        <input type="checkbox" data-connection-resource="${escapeHtml(item.name)}" ${selected.has(item.name) ? 'checked' : ''} />
        <span>${escapeHtml(item.name)}</span>
        <small>${escapeHtml(resourceBadge(item))}</small>
      </label>
    `).join('')}
  ` : '';
  const native = state.resources.filter((item) => item.nativeCalendar || item.source === 'native');
  const tables = state.resources.filter((item) => item.type !== 'view' && !(item.nativeCalendar || item.source === 'native'));
  const views = state.resources.filter((item) => item.type === 'view');
  el.className = 'connection-resource-list';
  el.innerHTML = groupHtml('Nativas', native) + groupHtml('Tabelas', tables) + groupHtml('Views', views);
  el.querySelectorAll('[data-connection-resource]').forEach((check) => check.addEventListener('change', () => {
    setModelTableIncluded(check.dataset.connectionResource, check.checked);
  }));
  el.querySelectorAll('[data-connection-resource-drag]').forEach((row) => row.addEventListener('dragstart', (ev) => {
    ev.dataTransfer.setData('application/x-biwa-resource', row.dataset.connectionResourceDrag);
    ev.dataTransfer.effectAllowed = 'copy';
  }));
}

async function renderConnectionDiagram() {
  const el = $('#connectionDiagram');
  if (!el) return;
  const resources = selectedConnectionResources();
  if (resources.length) {
    ensureModelTablesArray();
    resources.forEach((item) => {
      if (!state.model.tables.some((existing) => (typeof existing === 'string' ? existing : existing.name) === item.name)) {
        state.model.tables.push({ name: item.name });
      }
    });
  }
  if (!resources.length) {
    el.className = 'connection-diagram empty-state connection-drop-zone';
    el.innerHTML = '<b>Arraste tabelas/views para cá</b><br><small>Use o Calendário para relacionar campos de data.</small>';
    setupConnectionDiagramDrop(el);
    return;
  }
  const relationships = state.model.relationships || [];
  ensureConnectionPositions(resources);
  const columnsByTable = {};
  await Promise.all(resources.map(async (item) => {
    try { columnsByTable[item.name] = await loadModelColumns(item.name); }
    catch (err) { columnsByTable[item.name] = []; }
  }));
  el.className = 'connection-diagram connection-drop-zone';
  var zoom = state.connectionZoom || 100;
  el.innerHTML = `
    <div class="diagram-toolbar-inline">
      <span>Arraste tabelas para a area e arraste uma coluna ate outra para criar relacionamento.</span>
      <span>${resources.length} tabela(s)/view(s) no modelo &nbsp;
        <button class="btn mini ghost zoom-btn" data-zoom-out title="Diminuir zoom">-</button>
        <span class="zoom-label">${zoom}%</span>
        <button class="btn mini ghost zoom-btn" data-zoom-in title="Aumentar zoom">+</button>
      </span>
    </div>
    <div class="diagram-model-area" id="connectionModelArea" style="transform:scale(${zoom/100});transform-origin:0 0">
      <svg class="relationship-svg" id="connectionRelationshipSvg" aria-hidden="true"></svg>
      <div class="diagram-card-board">${resources.map((item, idx) => {
          const cols = columnsByTable[item.name] || [];
          const pos = getConnectionCardPosition(item.name, idx);
          const type = String(item.type || 'table').toLowerCase();
          const isNative = item.nativeCalendar || item.source === 'native';
          var accentClass = 'card-accent-table';
          var letterClass = 'letter-table';
          var letter = String(item.name || 'T').charAt(0).toUpperCase();
          if (isNative || item.name === 'Calendario') { accentClass = 'card-accent-calendar'; letterClass = 'letter-calendar'; }
          else if (item.manual) { accentClass = 'card-accent-manual'; letterClass = 'letter-manual'; }
          else if (type === 'view') { accentClass = 'card-accent-view'; letterClass = 'letter-view'; }
          else if (item.transform) { accentClass = 'card-accent-transform'; letterClass = 'letter-transform'; }
          var relCount = relationships.filter(function(r) { return r.fromTable === item.name || r.toTable === item.name; }).length;
          var relBadge = relCount ? '<span class="card-rel-badge">' + relCount + '</span>' : '';
  return `
            <div class="diagram-table-card powerbi-model-card ${accentClass}" data-connection-card="${escapeHtml(item.name)}" style="left:${pos.x}px; top:${pos.y}px;" draggable="true">
              <div class="diagram-table-head" data-card-drag-handle="${escapeHtml(item.name)}" title="Arraste para reposicionar o card">
                <span class="card-type-letter ${letterClass}">${escapeHtml(letter)}</span>
                <span class="card-title-area">
                  <b>${escapeHtml(item.name)}</b>
                  <span class="card-subtitle">${escapeHtml(resourceBadge(item))}</span>
                </span>
                ${relBadge}
              </div>
              <div class="diagram-table-columns">
                ${cols.length ? cols.map((col) => `
                  <div class="diagram-column-row" draggable="true" data-rel-table="${escapeHtml(item.name)}" data-rel-column="${escapeHtml(col.name)}" title="Arraste para outra coluna para relacionar">
                    <span class="col-dot"></span>
                    <span class="col-name">${escapeHtml(col.name)}</span>
                    <small>${escapeHtml(displayColumnType(col))}</small>
                  </div>
                `).join('') : '<div class="empty-state small">Nenhuma coluna carregada.</div>'}
              </div>
            </div>`;
        }).join('')}
      </div>      </div>
    </div>
  `;
  setupConnectionDiagramDrop(el);
  setupConnectionColumnDrag(el);
  setupConnectionCardDrag(el);
  setupConnectionDiagramScroll(el);
  // Zoom controls
  el.querySelector('[data-zoom-in]') && el.querySelector('[data-zoom-in]').addEventListener('click', function() {
    state.connectionZoom = Math.min(200, (state.connectionZoom || 100) + 10);
    renderConnectionDiagram();
  });
  el.querySelector('[data-zoom-out]') && el.querySelector('[data-zoom-out]').addEventListener('click', function() {
    state.connectionZoom = Math.max(30, (state.connectionZoom || 100) - 10);
    renderConnectionDiagram();
  });
  requestAnimationFrame(function() {
    requestAnimationFrame(function() { drawConnectionRelationshipLines(el); });
  });
  setTimeout(function() { drawConnectionRelationshipLines(el); }, 150);
  // Click on relationship line opens edit panel
  var svgEl = el.querySelector('#connectionRelationshipSvg');
  if (svgEl && !svgEl.dataset.clickBound) {
    svgEl.dataset.clickBound = '1';
    svgEl.addEventListener('click', function(ev) {
      var group = ev.target.closest && ev.target.closest('.relationship-group[data-rel-line]');
      if (!group) return;
      var idx = Number(group.dataset.relLine);
      if (idx >= 0 && state.model.relationships && state.model.relationships[idx]) {
        editRelationship(idx);
      }
    });
    svgEl.addEventListener('pointerover', function(ev) {
      var group = ev.target.closest && ev.target.closest('.relationship-group[data-rel-line]');
      if (!group || group.contains(ev.relatedTarget)) return;
      setConnectionRelationshipHover(el, Number(group.dataset.relLine), true);
    });
    svgEl.addEventListener('pointerout', function(ev) {
      var group = ev.target.closest && ev.target.closest('.relationship-group[data-rel-line]');
      if (!group || group.contains(ev.relatedTarget)) return;
      setConnectionRelationshipHover(el, Number(group.dataset.relLine), false);
    });
    svgEl.addEventListener('pointerleave', function() {
      clearConnectionRelationshipHover(el);
    });
  }
}

function setupConnectionDiagramDrop(el) {
  el.addEventListener('dragover', (ev) => {
    if (ev.dataTransfer.types.includes('application/x-biwa-resource')) ev.preventDefault();
  });
  el.addEventListener('drop', (ev) => {
    const name = ev.dataTransfer.getData('application/x-biwa-resource');
    if (!name) return;
    ev.preventDefault();
    setModelTableIncluded(name, true);
    toast(`${name} adicionado ao modelo.`);
  });
}


function setupConnectionDiagramScroll(el) {
  if (!el) return;
  if (el.dataset.relationshipScrollReady !== '1') {
    el.dataset.relationshipScrollReady = '1';
    el.addEventListener('scroll', function() {
      // O SVG e os cards pertencem ao mesmo conteudo rolavel. Redesenhar todas
      // as rotas aqui causava atraso e uma defasagem visual durante o scroll.
      clearConnectionRelationshipHover(el);
    }, { passive: true });
    window.addEventListener('resize', function() {
      scheduleConnectionRelationshipDraw(el, 40);
    });
  }
  el.querySelectorAll('.diagram-table-columns').forEach((columns) => {
    if (columns.dataset.relationshipScrollReady === '1') return;
    columns.dataset.relationshipScrollReady = '1';
    columns.addEventListener('scroll', function() {
      // As linhas pertencem ao card, nao ao trecho atualmente visivel da lista.
      // Recalcular a rota durante o scroll fazia as conexoes mudarem de lado e
      // de posicao. Mantemos o desenho estavel e apenas removemos o destaque.
      clearConnectionRelationshipHover(el);
    }, { passive: true });
  });
  if (el.connectionRelationshipResizeObserver) el.connectionRelationshipResizeObserver.disconnect();
  if (typeof ResizeObserver === 'function') {
    el.connectionRelationshipResizeObserver = new ResizeObserver(function() {
      scheduleConnectionRelationshipDraw(el, 48);
    });
    el.querySelectorAll('[data-connection-card]').forEach((card) => el.connectionRelationshipResizeObserver.observe(card));
  }
}

function scheduleConnectionRelationshipDraw(root, delay = 0) {
  if (!root) return;
  if (root.connectionRelationshipTimer) {
    clearTimeout(root.connectionRelationshipTimer);
    root.connectionRelationshipTimer = 0;
  }
  const queueFrame = function() {
    if (root.connectionRelationshipFrame) return;
    root.connectionRelationshipFrame = requestAnimationFrame(function() {
      root.connectionRelationshipFrame = 0;
      drawConnectionRelationshipLines(root);
    });
  };
  if (delay > 0) {
    root.connectionRelationshipTimer = setTimeout(function() {
      root.connectionRelationshipTimer = 0;
      queueFrame();
    }, delay);
    return;
  }
  queueFrame();
}

function findConnectionColumnRow(root, table, column) {
  return Array.from(root.querySelectorAll('[data-rel-table][data-rel-column]')).find((row) => row.dataset.relTable === table && row.dataset.relColumn === column) || null;
}

function drawConnectionRelationshipLinesLegacy(root) {
  const el = root || $('#connectionDiagram');
  const area = el && el.querySelector('#connectionModelArea');
  const svg = el && el.querySelector('#connectionRelationshipSvg');
  if (!el || !area || !svg) return;
  const rels = state.model.relationships || [];
  var totalW = Math.max(area.scrollWidth, area.clientWidth, 1200);
  var totalH = Math.max(area.scrollHeight, area.clientHeight, 800);
  svg.setAttribute('width', totalW);
  svg.setAttribute('height', totalH);
  svg.setAttribute('viewBox', '0 0 ' + totalW + ' ' + totalH);
  var lines = [];

  // Helper: get element position relative to area (uses offsetLeft/offsetTop, immune to scroll)
  function areaOffset(el) {
    var x = 0, y = 0, cur = el;
    while (cur && cur !== area) {
      x += cur.offsetLeft;
      y += cur.offsetTop;
      cur = cur.offsetParent;
    }
    return { x: x, y: y };
  }

  // Helper: get card rectangle in area-local coordinates
  function cardRect(tableName) {
    var card = area.querySelector('[data-connection-card="' + tableName.replace(/"/g, '&quot;') + '"]');
    if (!card) return null;
    var o = areaOffset(card);
    return {
      left: o.x,
      right: o.x + card.offsetWidth,
      top: o.y,
      bottom: o.y + card.offsetHeight,
      centerX: o.x + card.offsetWidth / 2,
      centerY: o.y + card.offsetHeight / 2
    };
  }

  // Helper: clamp Y within card visible bounds
  function clampY(y, cardR) {
    if (!cardR) return y;
    return Math.max(cardR.top + 24, Math.min(cardR.bottom - 24, y));
  }

  // Helper: clamp X within card visible bounds
  function clampX(x, cardR) {
    if (!cardR) return x;
    return Math.max(cardR.left + 24, Math.min(cardR.right - 24, x));
  }

  // ===== FIRST PASS: collect all connections =====
  var connData = [];
  var dotsByCard = {}; // 'cardName' => [{ci, side, edge, pos, x, y}]

  rels.forEach(function(rel, idx) {
    var fromRow = findConnectionColumnRow(area, rel.fromTable, rel.fromColumn);
    var toRow = findConnectionColumnRow(area, rel.toTable, rel.toColumn);
    var fromCard = cardRect(rel.fromTable);
    var toCard = cardRect(rel.toTable);
    if (!fromCard || !toCard) return;

    var dxCenter = Math.abs(fromCard.centerX - toCard.centerX);
    var dyCenter = Math.abs(fromCard.centerY - toCard.centerY);
    var connectHorizontal = dxCenter >= dyCenter;

    // Determine primary edge for each card
    function pickEdge(card, otherCard, isFrom) {
      if (connectHorizontal) {
        // Primary: horizontal (left/right)
        var useRight = card.centerX <= otherCard.centerX;
        return useRight ? 'right' : 'left';
      } else {
        // Primary: vertical (top/bottom)
        var useBottom = card.centerY <= otherCard.centerY;
        return useBottom ? 'bottom' : 'top';
      }
    }
    var fromEdge = pickEdge(fromCard, toCard, true);
    var toEdge = pickEdge(toCard, fromCard, false);

    var x1, y1, x2, y2;
    var aRow = fromRow, bRow = toRow;
    var isColumnLevel = aRow && bRow;

    // Position endpoints at the chosen edges
    function edgePoint(card, edge, row) {
      var x, y;
      if (edge === 'right')  { x = card.right; y = row ? clampY(areaOffset(row).y + row.offsetHeight / 2, card) : card.centerY; }
      else if (edge === 'left') { x = card.left; y = row ? clampY(areaOffset(row).y + row.offsetHeight / 2, card) : card.centerY; }
      else if (edge === 'bottom') { y = card.bottom; x = row ? clampX(areaOffset(row).x + row.offsetWidth / 2, card) : card.centerX; }
      else { y = card.top; x = row ? clampX(areaOffset(row).x + row.offsetWidth / 2, card) : card.centerX; }
      return { x: x, y: y };
    }
    var fromPt = edgePoint(fromCard, fromEdge, fromRow);
    var toPt = edgePoint(toCard, toEdge, toRow);
    x1 = fromPt.x; y1 = fromPt.y;
    x2 = toPt.x; y2 = toPt.y;

    var ci = connData.length;
    connData.push({ rel:rel, idx:idx, fromCard:fromCard, toCard:toCard, connectHorizontal:connectHorizontal,
      fromEdge:fromEdge, toEdge:toEdge, isColumnLevel:isColumnLevel, x1:x1, y1:y1, x2:x2, y2:y2,
      fromTable:rel.fromTable, toTable:rel.toTable });

    // Track dot positions per card (all edges together)
    function addDot(cardName, edge, cIdx, side, x, y) {
      if (!dotsByCard[cardName]) dotsByCard[cardName] = [];
      dotsByCard[cardName].push({ ci: cIdx, side: side, edge: edge, pos: (edge === 'top' || edge === 'bottom') ? x : y, x: x, y: y });
    }
    addDot(connData[ci].fromTable, connData[ci].fromEdge, ci, 'from', x1, y1);
    addDot(connData[ci].toTable, connData[ci].toEdge, ci, 'to', x2, y2);
  });

  // Redistribute overloaded edges based on card size
  var MIN_GAP = 26;
  Object.keys(dotsByCard).forEach(function(cardName) {
    var dots = dotsByCard[cardName];
    var countByEdge = {};
    dots.forEach(function(d) { countByEdge[d.edge] = (countByEdge[d.edge] || 0) + 1; });

    // Find any card to get dimensions (all dots on same card share same card rect)
    var sampleCard = connData[dots[0].ci].fromTable === cardName ? connData[dots[0].ci].fromCard : connData[dots[0].ci].toCard;
    var cardW = sampleCard.right - sampleCard.left;
    var cardH = sampleCard.bottom - sampleCard.top;
    var margin = 48; // 24px on each side
    var maxH = Math.max(1, Math.floor((cardW - margin) / MIN_GAP)); // capacity top/bottom
    var maxV = Math.max(1, Math.floor((cardH - margin) / MIN_GAP)); // capacity left/right

    Object.keys(countByEdge).forEach(function(edge) {
      var isHoriz = edge === 'top' || edge === 'bottom';
      var limit = isHoriz ? maxH : maxV;
      var count = countByEdge[edge];
      if (count <= limit) return;

      var excess = count - limit;
      var alts = isHoriz ? ['left', 'right'] : ['top', 'bottom'];
      // Filter alts that still have capacity
      var availableAlts = alts.filter(function(a) {
        var altLimit = (a === 'top' || a === 'bottom') ? maxH : maxV;
        return (countByEdge[a] || 0) < altLimit;
      });
      if (!availableAlts.length) return;

      var edgeDots = dots.filter(function(d) { return d.edge === edge; });
      edgeDots.sort(function(a, b) { return a.pos - b.pos; });

      // Move dots furthest from center to alternative edges
      var center = (cardW - margin) / 2; // approximate center for horizontal edges, but we use pos
      var altIdx = 0;
      for (var di = 0; di < edgeDots.length && excess > 0; di++) {
        var dot = edgeDots[di];
        var alt = availableAlts[altIdx % availableAlts.length];
        // Check alt still has capacity
        var altLimit = (alt === 'top' || alt === 'bottom') ? maxH : maxV;
        if ((countByEdge[alt] || 0) >= altLimit) {
          altIdx++;
          if (altIdx >= availableAlts.length * 2) break; // no more capacity
          continue;
        }
        var conn = connData[dot.ci];
        var card = dot.side === 'from' ? conn.fromCard : conn.toCard;
        if (alt === 'top') {
          conn[dot.side === 'from' ? 'y1' : 'y2'] = card.top;
          conn[dot.side === 'from' ? 'x1' : 'x2'] = card.centerX;
        } else if (alt === 'bottom') {
          conn[dot.side === 'from' ? 'y1' : 'y2'] = card.bottom;
          conn[dot.side === 'from' ? 'x1' : 'x2'] = card.centerX;
        } else if (alt === 'left') {
          conn[dot.side === 'from' ? 'x1' : 'x2'] = card.left;
          conn[dot.side === 'from' ? 'y1' : 'y2'] = card.centerY;
        } else {
          conn[dot.side === 'from' ? 'x1' : 'x2'] = card.right;
          conn[dot.side === 'from' ? 'y1' : 'y2'] = card.centerY;
        }
        countByEdge[edge]--;
        countByEdge[alt] = (countByEdge[alt] || 0) + 1;
        dot.edge = alt;
        dot.pos = (alt === 'top' || alt === 'bottom') ? conn[dot.side === 'from' ? 'x1' : 'x2'] : conn[dot.side === 'from' ? 'y1' : 'y2'];
        dot.x = conn[dot.side === 'from' ? 'x1' : 'x2'];
        dot.y = conn[dot.side === 'from' ? 'y1' : 'y2'];
        if (dot.side === 'from') conn.fromEdge = alt; else conn.toEdge = alt;
        excess--;
        altIdx++;
      }
    });
  });

  // Spread overlapping dots on the same card (any edge)
  var MIN_GAP = 26;
  Object.keys(dotsByCard).forEach(function(cardName) {
    var items = dotsByCard[cardName];
    if (items.length < 2) return;
    // Sort by position along the perimeter: top->right->bottom->left
    items.sort(function(a, b) {
      var order = { top: 0, right: 1, bottom: 2, left: 3 };
      var oa = order[a.edge] !== undefined ? order[a.edge] : 4;
      var ob = order[b.edge] !== undefined ? order[b.edge] : 4;
      if (oa !== ob) return oa - ob;
      return a.pos - b.pos;
    });
    // Check for conflicts (any dots closer than MIN_GAP regardless of edge)
    var conflicts = false;
    for (var j = 1; j < items.length; j++) {
      var prev = items[j-1], curr = items[j];
      if (prev.edge === curr.edge && Math.abs(curr.pos - prev.pos) < MIN_GAP) { conflicts = true; break; }
    }
    if (!conflicts) return;
    // Spread dots evenly along their respective edges
    // Group by edge, spread within each edge
    var byEdge = {};
    items.forEach(function(item) {
      if (!byEdge[item.edge]) byEdge[item.edge] = [];
      byEdge[item.edge].push(item);
    });
    Object.keys(byEdge).forEach(function(edge) {
      var group = byEdge[edge];
      if (group.length < 2) return;
      group.sort(function(a, b) { return a.pos - b.pos; });
      var center = (group[0].pos + group[group.length-1].pos) / 2;
      var start = center - (group.length - 1) * MIN_GAP / 2;
      group.forEach(function(item, i) {
        var np = start + i * MIN_GAP;
        var c = connData[item.ci];
        if (item.side === 'from') {
          if (c.connectHorizontal) c.y1 = np; else c.x1 = np;
        } else {
          if (c.connectHorizontal) c.y2 = np; else c.x2 = np;
        }
      });
    });
  });

   // ===== SECOND PASS: render =====
   var lines = [];
   lines.push('<defs><polygon id="arrow-shape" points="0,0 10,5 0,10" class="relationship-arrow" /><marker id="arrow-head" viewBox="0 0 10 10" refX="10" refY="5" markerWidth="10" markerHeight="10" markerUnits="userSpaceOnUse" orient="auto"><use href="#arrow-shape" /></marker></defs>');
   connData.forEach(function(conn) {
     var rel = conn.rel, idx = conn.idx;
     var x1 = conn.x1, y1 = conn.y1, x2 = conn.x2, y2 = conn.y2;
     var isColumnLevel = conn.isColumnLevel;
     var fromEdge = conn.fromEdge, toEdge = conn.toEdge;

     var pathD = 'M ' + x1 + ' ' + y1 + ' L ' + x2 + ' ' + y2;

     var cardinality = rel.cardinality || 'many-to-one';
     var fromLabel, toLabel;
     if (cardinality === 'one-to-one') { fromLabel = '1'; toLabel = '1'; }
     else if (cardinality === 'one-to-many') { fromLabel = '1'; toLabel = '*'; }
     else if (cardinality === 'many-to-many') { fromLabel = '*'; toLabel = '*'; }
     else { fromLabel = '*'; toLabel = '1'; }

     // Offset labels outward from card edge
     function labelOffset(x, y, edge, dist) {
       if (edge === 'right') return { x: x + dist, y: y };
       if (edge === 'left') return { x: x - dist, y: y };
       if (edge === 'bottom') return { x: x, y: y + dist };
       return { x: x, y: y - dist };
     }
     var flo = labelOffset(x1, y1, fromEdge, 14);
     var tlo = labelOffset(x2, y2, toEdge, 14);

     var midX = (x1 + x2) / 2, midY = (y1 + y2) / 2;
     var renderPathD = 'M ' + x1 + ' ' + y1 + ' L ' + midX + ' ' + midY + ' L ' + x2 + ' ' + y2;

     var lineClass = isColumnLevel ? 'relationship-path' : 'relationship-path card-level-fallback';

     if (rel.filterDirection === 'both') {
       var angleRad = Math.atan2(y2 - y1, x2 - x1);
       var cosA = Math.cos(angleRad), sinA = Math.sin(angleRad);
       var w = 10, h = 5, gap = 10;
       function rot(cx, cy, px, py) {
         return {
           x: cx + px * cosA - py * sinA,
           y: cy + px * sinA + py * cosA
         };
       }
       var cx1 = midX - cosA * gap / 2, cy1 = midY - sinA * gap / 2;
       var cx2 = midX + cosA * gap / 2, cy2 = midY + sinA * gap / 2;
       var a1l = rot(cx1, cy1, 0, -h), a1t = rot(cx1, cy1, -w, 0), a1r = rot(cx1, cy1, 0, h);
       var a2l = rot(cx2, cy2, 0, -h), a2t = rot(cx2, cy2, w, 0), a2r = rot(cx2, cy2, 0, h);
       lines.push('<path class="' + lineClass + '" data-rel-line="' + idx + '" d="' + renderPathD + '" />');
       lines.push('<polygon points="' + a1l.x + ',' + a1l.y + ' ' + a1t.x + ',' + a1t.y + ' ' + a1r.x + ',' + a1r.y + '" class="relationship-arrow" />');
       lines.push('<polygon points="' + a2l.x + ',' + a2l.y + ' ' + a2t.x + ',' + a2t.y + ' ' + a2r.x + ',' + a2r.y + '" class="relationship-arrow" />');
     } else {
       lines.push('<path class="' + lineClass + '" data-rel-line="' + idx + '" d="' + renderPathD + '" marker-mid="url(#arrow-head)" />');
     }
    lines.push('<circle class="card-border-dot" cx="' + x1 + '" cy="' + y1 + '" r="5" data-rel-card="' + escapeHtml(rel.fromTable) + '" />');
    lines.push('<circle class="card-border-dot" cx="' + x2 + '" cy="' + y2 + '" r="5" data-rel-card="' + escapeHtml(rel.toTable) + '" />');
    lines.push('<text class="relationship-card-label" x="' + flo.x + '" y="' + flo.y + '" text-anchor="middle" dominant-baseline="middle">' + escapeHtml(fromLabel) + '</text>');
    lines.push('<text class="relationship-card-label" x="' + tlo.x + '" y="' + tlo.y + '" text-anchor="middle" dominant-baseline="middle">' + escapeHtml(toLabel) + '</text>');
  });
  svg.innerHTML = lines.join('');
}

function connectionElementAreaRect(element, area) {
  if (!element || !area) return null;
  const areaBounds = area.getBoundingClientRect();
  const elementBounds = element.getBoundingClientRect();
  const scaleX = area.offsetWidth ? areaBounds.width / area.offsetWidth : 1;
  const scaleY = area.offsetHeight ? areaBounds.height / area.offsetHeight : scaleX;
  const safeScaleX = Number.isFinite(scaleX) && scaleX > 0 ? scaleX : 1;
  const safeScaleY = Number.isFinite(scaleY) && scaleY > 0 ? scaleY : safeScaleX;
  return {
    left: (elementBounds.left - areaBounds.left) / safeScaleX,
    right: (elementBounds.right - areaBounds.left) / safeScaleX,
    top: (elementBounds.top - areaBounds.top) / safeScaleY,
    bottom: (elementBounds.bottom - areaBounds.top) / safeScaleY,
    width: elementBounds.width / safeScaleX,
    height: elementBounds.height / safeScaleY,
    centerX: ((elementBounds.left + elementBounds.right) / 2 - areaBounds.left) / safeScaleX,
    centerY: ((elementBounds.top + elementBounds.bottom) / 2 - areaBounds.top) / safeScaleY
  };
}

function connectionColumnAnchor(area, card, row, edge) {
  const cardRect = connectionElementAreaRect(card, area);
  if (!cardRect) return null;
  const columns = card.querySelector('.diagram-table-columns');
  const columnsRect = connectionElementAreaRect(columns, area) || cardRect;
  const rowRect = connectionElementAreaRect(row, area);
  const visibleTop = Math.max(cardRect.top + 36, columnsRect.top + 3);
  const visibleBottom = Math.min(cardRect.bottom - 3, columnsRect.bottom - 3);
  // getBoundingClientRect() desconta o scroll interno da lista. Somar o
  // scrollTop recupera a posicao estrutural da coluna e deixa a ancora imune
  // ao movimento do conteudo dentro do card.
  const columnScrollTop = columns ? Math.max(0, Number(columns.scrollTop) || 0) : 0;
  const desiredY = rowRect ? rowRect.centerY + columnScrollTop : cardRect.centerY;
  const anchorY = Math.max(visibleTop, Math.min(visibleBottom, desiredY));
  const clamped = !rowRect || desiredY < visibleTop || desiredY > visibleBottom;
  if (edge === 'left') return { x: cardRect.left, y: anchorY, clamped, cardRect };
  if (edge === 'right') return { x: cardRect.right, y: anchorY, clamped, cardRect };
  if (edge === 'top') return { x: cardRect.centerX, y: cardRect.top, clamped, cardRect };
  return { x: cardRect.centerX, y: cardRect.bottom, clamped, cardRect };
}

function connectionRelationshipEdges(fromRect, toRect) {
  const horizontalGap = fromRect.centerX <= toRect.centerX
    ? toRect.left - fromRect.right
    : fromRect.left - toRect.right;
  const verticalGap = fromRect.centerY <= toRect.centerY
    ? toRect.top - fromRect.bottom
    : fromRect.top - toRect.bottom;
  let horizontal;
  if (horizontalGap >= 0 && verticalGap >= 0) horizontal = horizontalGap >= verticalGap;
  else if (horizontalGap >= 0) horizontal = true;
  else if (verticalGap >= 0) horizontal = false;
  else horizontal = Math.abs(toRect.centerX - fromRect.centerX) >= Math.abs(toRect.centerY - fromRect.centerY);
  if (horizontal) {
    return fromRect.centerX <= toRect.centerX
      ? { from: 'right', to: 'left' }
      : { from: 'left', to: 'right' };
  }
  return fromRect.centerY <= toRect.centerY
    ? { from: 'bottom', to: 'top' }
    : { from: 'top', to: 'bottom' };
}

function connectionPortPoint(anchor, edge, distance) {
  if (edge === 'left') return { x: anchor.x - distance, y: anchor.y };
  if (edge === 'right') return { x: anchor.x + distance, y: anchor.y };
  if (edge === 'top') return { x: anchor.x, y: anchor.y - distance };
  return { x: anchor.x, y: anchor.y + distance };
}

function connectionRelationshipEdgeCandidates(preferred) {
  const candidates = [];
  const add = (from, to, penalty) => {
    if (candidates.some((item) => item.from === from && item.to === to)) return;
    candidates.push({ from, to, penalty });
  };
  add(preferred.from, preferred.to, 0);
  add('right', 'left', 18);
  add('left', 'right', 18);
  add('bottom', 'top', 18);
  add('top', 'bottom', 18);
  return candidates;
}

function connectionPointInsideObstacle(point, obstacle) {
  const epsilon = 0.5;
  return point.x > obstacle.left + epsilon && point.x < obstacle.right - epsilon
    && point.y > obstacle.top + epsilon && point.y < obstacle.bottom - epsilon;
}

function connectionSegmentBlocked(a, b, obstacles) {
  const epsilon = 0.5;
  if (Math.abs(a.y - b.y) < epsilon) {
    const left = Math.min(a.x, b.x);
    const right = Math.max(a.x, b.x);
    return obstacles.some((rect) => a.y > rect.top + epsilon && a.y < rect.bottom - epsilon
      && right > rect.left + epsilon && left < rect.right - epsilon);
  }
  if (Math.abs(a.x - b.x) < epsilon) {
    const top = Math.min(a.y, b.y);
    const bottom = Math.max(a.y, b.y);
    return obstacles.some((rect) => a.x > rect.left + epsilon && a.x < rect.right - epsilon
      && bottom > rect.top + epsilon && top < rect.bottom - epsilon);
  }
  return true;
}

function connectionUniqueCoordinates(values, min, max) {
  const seen = new Set();
  return values
    .map((value) => Math.max(min, Math.min(max, Number(value) || 0)))
    .map((value) => Math.round(value * 10) / 10)
    .filter((value) => {
      const key = value.toFixed(1);
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    })
    .sort((a, b) => a - b);
}

function connectionSimplifyPolyline(points) {
  const clean = [];
  (points || []).forEach((point) => {
    if (!point) return;
    const previous = clean[clean.length - 1];
    if (!previous || Math.abs(previous.x - point.x) > 0.1 || Math.abs(previous.y - point.y) > 0.1) {
      clean.push({ x: Math.round(point.x * 10) / 10, y: Math.round(point.y * 10) / 10 });
    }
  });
  let changed = true;
  while (changed && clean.length > 2) {
    changed = false;
    for (let i = 1; i < clean.length - 1; i += 1) {
      const a = clean[i - 1];
      const b = clean[i];
      const c = clean[i + 1];
      if ((Math.abs(a.x - b.x) < 0.1 && Math.abs(b.x - c.x) < 0.1)
        || (Math.abs(a.y - b.y) < 0.1 && Math.abs(b.y - c.y) < 0.1)) {
        clean.splice(i, 1);
        changed = true;
        break;
      }
    }
  }
  return clean;
}

function routeConnectionOrthogonally(start, end, obstacles, bounds) {
  const xs = [8, bounds.width - 8, start.x, end.x, (start.x + end.x) / 2];
  const ys = [8, bounds.height - 8, start.y, end.y, (start.y + end.y) / 2];
  obstacles.forEach((rect) => {
    xs.push(rect.left, rect.right);
    ys.push(rect.top, rect.bottom);
  });
  const xValues = connectionUniqueCoordinates(xs, 2, Math.max(2, bounds.width - 2));
  const yValues = connectionUniqueCoordinates(ys, 2, Math.max(2, bounds.height - 2));
  const pointKey = (x, y) => x.toFixed(1) + ',' + y.toFixed(1);
  const nodes = new Map();
  yValues.forEach((y) => xValues.forEach((x) => {
    const point = { x, y };
    if (!obstacles.some((rect) => connectionPointInsideObstacle(point, rect))) {
      nodes.set(pointKey(x, y), point);
    }
  }));
  const startKey = pointKey(start.x, start.y);
  const endKey = pointKey(end.x, end.y);
  nodes.set(startKey, { x: start.x, y: start.y });
  nodes.set(endKey, { x: end.x, y: end.y });
  const graph = new Map();
  const connect = (a, b) => {
    if (!a || !b || connectionSegmentBlocked(a, b, obstacles)) return;
    const aKey = pointKey(a.x, a.y);
    const bKey = pointKey(b.x, b.y);
    if (!graph.has(aKey)) graph.set(aKey, []);
    if (!graph.has(bKey)) graph.set(bKey, []);
    const cost = Math.abs(a.x - b.x) + Math.abs(a.y - b.y);
    graph.get(aKey).push({ key: bKey, cost, direction: Math.abs(a.x - b.x) > 0.1 ? 'h' : 'v' });
    graph.get(bKey).push({ key: aKey, cost, direction: Math.abs(a.x - b.x) > 0.1 ? 'h' : 'v' });
  };
  yValues.forEach((y) => {
    const row = Array.from(nodes.values()).filter((point) => Math.abs(point.y - y) < 0.1).sort((a, b) => a.x - b.x);
    for (let i = 1; i < row.length; i += 1) connect(row[i - 1], row[i]);
  });
  xValues.forEach((x) => {
    const column = Array.from(nodes.values()).filter((point) => Math.abs(point.x - x) < 0.1).sort((a, b) => a.y - b.y);
    for (let i = 1; i < column.length; i += 1) connect(column[i - 1], column[i]);
  });

  const stateKey = (key, direction) => key + '|' + direction;
  const open = [{ key: startKey, direction: 'n', cost: 0 }];
  const distances = new Map([[stateKey(startKey, 'n'), 0]]);
  const parents = new Map();
  let finalState = '';
  while (open.length) {
    open.sort((a, b) => a.cost - b.cost);
    const current = open.shift();
    const currentState = stateKey(current.key, current.direction);
    if (current.cost !== distances.get(currentState)) continue;
    if (current.key === endKey) {
      finalState = currentState;
      break;
    }
    (graph.get(current.key) || []).forEach((edge) => {
      const bendCost = current.direction !== 'n' && current.direction !== edge.direction ? 28 : 0;
      const nextCost = current.cost + edge.cost + bendCost;
      const nextState = stateKey(edge.key, edge.direction);
      if (nextCost >= (distances.get(nextState) ?? Infinity)) return;
      distances.set(nextState, nextCost);
      parents.set(nextState, currentState);
      open.push({ key: edge.key, direction: edge.direction, cost: nextCost });
    });
  }
  if (!finalState) {
    const viaX = { x: start.x, y: end.y };
    const viaY = { x: end.x, y: start.y };
    if (!connectionSegmentBlocked(start, viaX, obstacles) && !connectionSegmentBlocked(viaX, end, obstacles)) return [start, viaX, end];
    if (!connectionSegmentBlocked(start, viaY, obstacles) && !connectionSegmentBlocked(viaY, end, obstacles)) return [start, viaY, end];
    return null;
  }
  const routed = [];
  let cursor = finalState;
  while (cursor) {
    const separator = cursor.lastIndexOf('|');
    const key = cursor.slice(0, separator);
    const point = nodes.get(key);
    if (point) routed.push(point);
    cursor = parents.get(cursor) || '';
  }
  return connectionSimplifyPolyline(routed.reverse());
}

function connectionPolylineScore(points) {
  let length = 0;
  let bends = 0;
  let previousDirection = '';
  for (let i = 1; i < points.length; i += 1) {
    const from = points[i - 1];
    const to = points[i];
    const direction = Math.abs(to.x - from.x) > 0.1 ? 'h' : 'v';
    length += Math.abs(to.x - from.x) + Math.abs(to.y - from.y);
    if (previousDirection && previousDirection !== direction) bends += 1;
    previousDirection = direction;
  }
  return length + bends * 22;
}

function connectionPolylineMidpoint(points) {
  const segments = [];
  let total = 0;
  for (let i = 1; i < points.length; i += 1) {
    const from = points[i - 1];
    const to = points[i];
    const length = Math.abs(to.x - from.x) + Math.abs(to.y - from.y);
    if (!length) continue;
    segments.push({ from, to, length });
    total += length;
  }
  let target = total / 2;
  for (const segment of segments) {
    if (target <= segment.length) {
      const ratio = target / segment.length;
      return {
        x: segment.from.x + (segment.to.x - segment.from.x) * ratio,
        y: segment.from.y + (segment.to.y - segment.from.y) * ratio,
        angle: Math.atan2(segment.to.y - segment.from.y, segment.to.x - segment.from.x) * 180 / Math.PI
      };
    }
    target -= segment.length;
  }
  const fallback = points[points.length - 1] || { x: 0, y: 0 };
  return { x: fallback.x, y: fallback.y, angle: 0 };
}

function clearConnectionRelationshipHover(root) {
  if (!root) return;
  root.querySelectorAll('.relationship-group.is-hovered').forEach((group) => group.classList.remove('is-hovered'));
  root.querySelectorAll('.diagram-column-row.relationship-column-highlight').forEach((row) => row.classList.remove('relationship-column-highlight'));
}

function setConnectionRelationshipHover(root, relationshipIndex, active) {
  clearConnectionRelationshipHover(root);
  if (!active) return;
  const index = Number(relationshipIndex);
  const relationship = state.model.relationships && state.model.relationships[index];
  if (!relationship) return;
  const group = root.querySelector('.relationship-group[data-rel-line="' + index + '"]');
  if (group) group.classList.add('is-hovered');
  const fromRow = findConnectionColumnRow(root, relationship.fromTable, relationship.fromColumn);
  const toRow = findConnectionColumnRow(root, relationship.toTable, relationship.toColumn);
  if (fromRow) fromRow.classList.add('relationship-column-highlight');
  if (toRow) toRow.classList.add('relationship-column-highlight');
}

function drawConnectionRelationshipLines(root) {
  const el = root || $('#connectionDiagram');
  const area = el && el.querySelector('#connectionModelArea');
  const svg = el && el.querySelector('#connectionRelationshipSvg');
  if (!el || !area || !svg) return;
  const relationships = state.model.relationships || [];
  const cards = Array.from(area.querySelectorAll('[data-connection-card]'));
  const cardRects = new Map();
  cards.forEach((card) => cardRects.set(card.dataset.connectionCard, connectionElementAreaRect(card, area)));
  const maxCardRight = Math.max(0, ...Array.from(cardRects.values()).map((rect) => rect ? rect.right : 0));
  const maxCardBottom = Math.max(0, ...Array.from(cardRects.values()).map((rect) => rect ? rect.bottom : 0));
  const totalW = Math.max(area.scrollWidth, area.clientWidth, maxCardRight + 90, 1200);
  const totalH = Math.max(area.scrollHeight, area.clientHeight, maxCardBottom + 90, 820);
  svg.setAttribute('width', totalW);
  svg.setAttribute('height', totalH);
  svg.setAttribute('viewBox', '0 0 ' + totalW + ' ' + totalH);
  svg.setAttribute('preserveAspectRatio', 'xMinYMin meet');
  // Mantem uma unidade SVG igual a um pixel do modelo. O CSS antigo em 100%
  // achatava o desenho quando os cards ultrapassavam a altura minima da area.
  svg.style.width = totalW + 'px';
  svg.style.height = totalH + 'px';
  const clearance = 26;
  const obstacles = Array.from(cardRects.values()).filter(Boolean).map((rect) => ({
    left: Math.max(2, rect.left - clearance),
    right: Math.min(totalW - 2, rect.right + clearance),
    top: Math.max(2, rect.top - clearance),
    bottom: Math.min(totalH - 2, rect.bottom + clearance)
  }));
  const output = [];

  relationships.forEach((relationship, index) => {
    const fromCard = area.querySelector('[data-connection-card="' + CSS.escape(relationship.fromTable) + '"]');
    const toCard = area.querySelector('[data-connection-card="' + CSS.escape(relationship.toTable) + '"]');
    const fromRect = cardRects.get(relationship.fromTable);
    const toRect = cardRects.get(relationship.toTable);
    if (!fromCard || !toCard || !fromRect || !toRect) return;
    const fromRow = findConnectionColumnRow(area, relationship.fromTable, relationship.fromColumn);
    const toRow = findConnectionColumnRow(area, relationship.toTable, relationship.toColumn);
    const portDistance = 36 + (index % 3) * 5;
    const preferredEdges = connectionRelationshipEdges(fromRect, toRect);
    let selectedRoute = null;
    connectionRelationshipEdgeCandidates(preferredEdges).forEach((edges) => {
      const fromAnchor = connectionColumnAnchor(area, fromCard, fromRow, edges.from);
      const toAnchor = connectionColumnAnchor(area, toCard, toRow, edges.to);
      if (!fromAnchor || !toAnchor) return;
      const fromPort = connectionPortPoint(fromAnchor, edges.from, portDistance);
      const toPort = connectionPortPoint(toAnchor, edges.to, portDistance);
      if (obstacles.some((rect) => connectionPointInsideObstacle(fromPort, rect))
        || obstacles.some((rect) => connectionPointInsideObstacle(toPort, rect))) return;
      const route = routeConnectionOrthogonally(fromPort, toPort, obstacles, { width: totalW, height: totalH });
      if (!route) return;
      const points = connectionSimplifyPolyline([fromAnchor, fromPort, ...route, toPort, toAnchor]);
      const score = connectionPolylineScore(points) + edges.penalty;
      if (!selectedRoute || score < selectedRoute.score) {
        selectedRoute = { edges, fromAnchor, toAnchor, points, score };
      }
    });
    if (!selectedRoute) return;
    const edges = selectedRoute.edges;
    const fromAnchor = selectedRoute.fromAnchor;
    const toAnchor = selectedRoute.toAnchor;
    const points = selectedRoute.points;
    const path = points.map((point, pointIndex) => (pointIndex ? 'L ' : 'M ') + point.x + ' ' + point.y).join(' ');
    const midpoint = connectionPolylineMidpoint(points);
    const cardinality = relationship.cardinality || 'many-to-one';
    const fromLabel = cardinality === 'one-to-one' || cardinality === 'one-to-many' ? '1' : '*';
    const toLabel = cardinality === 'one-to-one' || cardinality === 'many-to-one' ? '1' : '*';
    const labelPoint = (anchor, edge) => connectionPortPoint(anchor, edge, 12);
    const fromLabelPoint = labelPoint(fromAnchor, edges.from);
    const toLabelPoint = labelPoint(toAnchor, edges.to);
    const inactive = relationship.active === false;
    const pathClasses = ['relationship-path'];
    if (inactive) pathClasses.push('relationship-path-inactive');
    const title = relationship.fromTable + '[' + relationship.fromColumn + '] → '
      + relationship.toTable + '[' + relationship.toColumn + ']';
    output.push('<g class="relationship-group" data-rel-line="' + index + '">');
    output.push('<title>' + escapeHtml(title) + '</title>');
    output.push('<path class="relationship-hit" data-rel-line="' + index + '" d="' + path + '" />');
    output.push('<path class="' + pathClasses.join(' ') + '" data-rel-line="' + index + '" d="' + path + '" />');
    if (relationship.filterDirection === 'both') {
      output.push('<path class="relationship-arrow" d="M -2 -4 L -9 0 L -2 4 Z M 2 -4 L 9 0 L 2 4 Z" transform="translate(' + midpoint.x + ' ' + midpoint.y + ') rotate(' + midpoint.angle + ')" />');
    } else {
      output.push('<path class="relationship-arrow" d="M -5 -4 L 5 0 L -5 4 Z" transform="translate(' + midpoint.x + ' ' + midpoint.y + ') rotate(' + midpoint.angle + ')" />');
    }
    output.push('<circle class="card-border-dot" cx="' + fromAnchor.x + '" cy="' + fromAnchor.y + '" r="4" />');
    output.push('<circle class="card-border-dot" cx="' + toAnchor.x + '" cy="' + toAnchor.y + '" r="4" />');
    output.push('<text class="relationship-card-label relationship-cardinality" x="' + fromLabelPoint.x + '" y="' + fromLabelPoint.y + '" text-anchor="middle" dominant-baseline="middle">' + fromLabel + '</text>');
    output.push('<text class="relationship-card-label relationship-cardinality" x="' + toLabelPoint.x + '" y="' + toLabelPoint.y + '" text-anchor="middle" dominant-baseline="middle">' + toLabel + '</text>');
    output.push('</g>');
  });
  svg.innerHTML = output.join('');
}


function setupConnectionCardDrag(root) {
  const area = root && root.querySelector('#connectionModelArea');
  if (!area) return;

  if (area.dataset.selectionBound !== '1') {
    area.dataset.selectionBound = '1';
    area.addEventListener('pointerdown', (ev) => {
      if (ev.target === area || ev.target.closest('#connectionRelationshipSvg')) {
        root.querySelectorAll('[data-connection-card].selected').forEach(c => c.classList.remove('selected'));
      }
    });
  }

  if (!window.connectionDeleteBound) {
    window.connectionDeleteBound = true;
    document.addEventListener('keydown', (ev) => {
      if (ev.key === 'Delete' || ev.key === 'Backspace') {
        const diagram = document.querySelector('#connectionDiagram');
        if (!diagram) return;
        const selected = diagram.querySelector('[data-connection-card].selected');
        if (selected && ev.target.tagName !== 'INPUT' && ev.target.tagName !== 'TEXTAREA') {
          const tableName = selected.dataset.connectionCard;
          setModelTableIncluded(tableName, false);
          toast(tableName + ' e suas conexões foram removidos.');
        }
      }
    });
  }

  root.querySelectorAll('[data-connection-card]').forEach((card) => {
    if (card.dataset.selectionBound === '1') return;
    card.dataset.selectionBound = '1';
    card.addEventListener('pointerdown', () => {
      root.querySelectorAll('[data-connection-card].selected').forEach(c => c.classList.remove('selected'));
      card.classList.add('selected');
    });
  });

  root.querySelectorAll('[data-card-drag-handle]').forEach((handle) => {
    const card = handle.closest('[data-connection-card]');
    if (!card) return;
    handle.addEventListener('pointerdown', (ev) => {
      if (ev.button !== 0) return;
      ev.preventDefault();
      const table = card.dataset.connectionCard;
      const startX = ev.clientX;
      const startY = ev.clientY;
      const current = getConnectionCardPosition(table);
      card.setPointerCapture(ev.pointerId);
      card.classList.add('moving-card');
      const onMove = (moveEv) => {
        const next = clampConnectionCardPosition(current.x + moveEv.clientX - startX, current.y + moveEv.clientY - startY);
        state.model.tablePositions[table] = next;
        card.style.left = next.x + 'px';
        card.style.top = next.y + 'px';
        scheduleConnectionRelationshipDraw(root);
      };
      const onUp = () => {
        card.classList.remove('moving-card');
        card.removeEventListener('pointermove', onMove);
        card.removeEventListener('pointerup', onUp);
        card.removeEventListener('pointercancel', onUp);
        scheduleConnectionRelationshipDraw(root);
      };
      card.addEventListener('pointermove', onMove);
      card.addEventListener('pointerup', onUp);
      card.addEventListener('pointercancel', onUp);
    });
  });
}

function setupConnectionColumnDrag(root) {
  root.querySelectorAll('[data-rel-table][data-rel-column]').forEach((row) => {
    row.addEventListener('dragstart', (ev) => {
      ev.dataTransfer.setData('application/x-biwa-column', JSON.stringify({ table: row.dataset.relTable, column: row.dataset.relColumn }));
      ev.dataTransfer.effectAllowed = 'link';
      row.classList.add('dragging-column');
    });
    row.addEventListener('dragend', () => row.classList.remove('dragging-column'));
    row.addEventListener('dragover', (ev) => {
      if (ev.dataTransfer.types.includes('application/x-biwa-column')) {
        ev.preventDefault();
        row.classList.add('drop-target-column');
      }
    });
    row.addEventListener('dragleave', () => row.classList.remove('drop-target-column'));
    row.addEventListener('drop', (ev) => {
      const raw = ev.dataTransfer.getData('application/x-biwa-column');
      if (!raw) return;
      ev.preventDefault();
      row.classList.remove('drop-target-column');
      let from;
      try { from = JSON.parse(raw); } catch (err) { return; }
      addConnectionRelationshipFromColumns(from.table, from.column, row.dataset.relTable, row.dataset.relColumn);
    });
  });
}

function isLikelyFactTableName(tableName) {
  return /faturamento|recebimento|contas|bordero|fluxo|movimento|venda/i.test(String(tableName || ''));
}

function inferRelationshipCardinality(fromTable, toTable) {
  if (fromTable === 'Calendario') return 'one-to-many';
  if (!isLikelyFactTableName(fromTable) && isLikelyFactTableName(toTable)) return 'one-to-many';
  return 'many-to-one';
}

function normalizeRelationshipDirection(fromTable, fromColumn, toTable, toColumn) {
  // Auto-order: Calendario is always the origin (dimension/filter side)
  if (toTable === 'Calendario' && fromTable !== 'Calendario') {
    return { fromTable: toTable, fromColumn: toColumn, toTable: fromTable, toColumn: fromColumn, cardinality: 'one-to-many' };
  }
  return { fromTable: fromTable, fromColumn: fromColumn, toTable: toTable, toColumn: toColumn, cardinality: inferRelationshipCardinality(fromTable, toTable) };
}

function addConnectionRelationshipFromColumns(fromTable, fromColumn, toTable, toColumn) {
  if (!fromTable || !fromColumn || !toTable || !toColumn) return;
  if (fromTable === toTable && fromColumn === toColumn) return toast('O relacionamento precisa ligar campos diferentes.', 'error');
  var norm = normalizeRelationshipDirection(fromTable, fromColumn, toTable, toColumn);
  const exists = (state.model.relationships || []).some((rel) =>
    rel.fromTable === norm.fromTable && rel.fromColumn === norm.fromColumn && rel.toTable === norm.toTable && rel.toColumn === norm.toColumn
  );
  if (exists) return toast('Esse relacionamento ja existe.', 'error');
  state.model.relationships = state.model.relationships || [];
  state.model.relationships.push({
    fromTable: norm.fromTable,
    fromColumn: norm.fromColumn,
    toTable: norm.toTable,
    toColumn: norm.toColumn,
    joinType: 'LEFT',
    cardinality: norm.cardinality,
    filterDirection: 'single',
    active: true,
    confidence: 'manual'
  });
  ensureModelTablesArray();
  [fromTable, toTable].forEach((name) => {
    if (!state.model.tables.some((item) => (typeof item === 'string' ? item : item.name) === name)) state.model.tables.push({ name });
  });
  renderConnectionsDesigner();
  renderRelationshipList();
  toast('Relacionamento criado. Clique em Salvar conexões para gravar.');
}

async function renderConnectionColumnSelect(tableSelectId, columnSelectId) {
  const tableEl = document.getElementById(tableSelectId);
  const colEl = document.getElementById(columnSelectId);
  if (!tableEl || !colEl) return;
  const table = tableEl.value;
  if (!table) {
    colEl.innerHTML = '<option value="">Selecione</option>';
    return;
  }
  try {
    const columns = await loadModelColumns(table);
    colEl.innerHTML = columns.map((c) => `<option value="${escapeHtml(c.name)}">${escapeHtml(c.name)} - ${escapeHtml(displayColumnType(c))}</option>`).join('') || '<option value="">Sem colunas</option>';
  } catch (err) {
    colEl.innerHTML = '<option value="">Erro ao carregar</option>';
  }
}

async function refreshConnectionColumns() {
  await renderConnectionColumnSelect('connFromTable', 'connFromColumn');
  await renderConnectionColumnSelect('connToTable', 'connToColumn');
}

function renderConnectionSelects() {
  const from = $('#connFromTable');
  const to = $('#connToTable');
  const resources = connectionRelationshipResources();
  if (from) {
    const current = from.value || (resources[0] && resources[0].name) || '';
    from.innerHTML = connectionResourceOptionsHtml(current);
    if (current) from.value = current;
  }
  if (to) {
    const current = to.value || (resources[1] && resources[1].name) || (resources[0] && resources[0].name) || '';
    to.innerHTML = connectionResourceOptionsHtml(current);
    if (current) to.value = current;
  }
  refreshConnectionColumns();
}

function renderConnectionRelationshipList() {
  const el = $('#connRelationshipList');
  if (!el) return;
  const items = state.model.relationships || [];
  if (!items.length) {
    el.className = 'model-list empty-state';
    el.textContent = 'Nenhum relacionamento criado.';
    return;
  }
  el.className = 'model-list';
  el.innerHTML = items.map((r, idx) => `
    <div class="model-item relationship-item">
      <div><b>${escapeHtml(r.fromTable)} → ${escapeHtml(r.toTable)}</b><small>${escapeHtml(r.fromColumn)} = ${escapeHtml(r.toColumn)} | ${escapeHtml(r.cardinality || 'muitos para um')} | filtro ${escapeHtml(r.filterDirection || 'unica')}</small></div>
      <button class="icon-btn" data-remove-conn-rel="${idx}">x</button>
    </div>
  `).join('');
  el.querySelectorAll('[data-remove-conn-rel]').forEach((btn) => btn.addEventListener('click', () => {
    state.model.relationships.splice(Number(btn.dataset.removeConnRel), 1);
    renderConnectionRelationshipList();
    renderConnectionDiagram();
    renderRelationshipList();
  }));
}

function renderConnectionsDesigner() {
  renderConnectionResourceList();
  renderConnectionDiagram().catch((err) => {
    const el = $('#connectionDiagram');
    if (el) {
      el.className = 'connection-diagram empty-state error-state';
      el.textContent = err.message || String(err);
    }
  });
}

function addConnectionRelationship() {
  var fromTableEl = $('#connFromTable');
  var fromColumnEl = $('#connFromColumn');
  var toTableEl = $('#connToTable');
  var toColumnEl = $('#connToColumn');
  if (!fromTableEl || !fromColumnEl || !toTableEl || !toColumnEl) return toast('Erro ao acessar os campos do relacionamento. Recarregue a pagina.', 'error');
  const rel = {
    fromTable: fromTableEl.value,
    fromColumn: fromColumnEl.value,
    toTable: toTableEl.value,
    toColumn: toColumnEl.value,
    joinType: ($('#connJoinType') && $('#connJoinType').value) || 'LEFT',
    cardinality: ($('#connCardinality') && $('#connCardinality').value) || 'many-to-one',
    filterDirection: ($('#connFilterDirection') && $('#connFilterDirection').value) || 'single',
    active: true,
    confidence: 'manual'
  };
  if (!rel.fromTable || !rel.fromColumn || !rel.toTable || !rel.toColumn) return toast('Preencha as tabelas/views e colunas do relacionamento.', 'error');
  if (rel.fromTable === rel.toTable && rel.fromColumn === rel.toColumn) return toast('O relacionamento precisa ligar campos diferentes.', 'error');
  state.model.relationships = state.model.relationships || [];
  state.model.relationships.push(rel);
  ensureModelTablesArray();
  [rel.fromTable, rel.toTable].forEach((name) => {
    if (!state.model.tables.some((item) => (typeof item === 'string' ? item : item.name) === name)) state.model.tables.push({ name });
  });
  renderConnectionsDesigner();
  renderRelationshipList();
  toast('Relacionamento adicionado ao modelo. Clique em Salvar conexoes para gravar.');
}

function editRelationship(idx) {
  var rel = (state.model.relationships || [])[idx];
  if (!rel) return;
  // Auto-correct: ensure Calendario is always the origin
  var norm = normalizeRelationshipDirection(rel.fromTable, rel.fromColumn, rel.toTable, rel.toColumn);
  if (norm.fromTable !== rel.fromTable || norm.toTable !== rel.toTable) {
    rel.fromTable = norm.fromTable;
    rel.fromColumn = norm.fromColumn;
    rel.toTable = norm.toTable;
    rel.toColumn = norm.toColumn;
    rel.cardinality = norm.cardinality;
  }
  var resources = connectionRelationshipResources();
  var fromTableOpts = resources.map(function(r) { return '<option value="' + escapeHtml(r.name) + '"' + (r.name === rel.fromTable ? ' selected' : '') + '>' + escapeHtml(r.name) + '</option>'; }).join('');
  var toTableOpts = resources.map(function(r) { return '<option value="' + escapeHtml(r.name) + '"' + (r.name === rel.toTable ? ' selected' : '') + '>' + escapeHtml(r.name) + '</option>'; }).join('');
  var panel = $('#connRelationshipEdit');
  if (!panel) return;
  panel.innerHTML =
    '<div class="edit-rel-header">' +
      '<span class="edit-rel-title">' + escapeHtml(rel.fromTable) + ' <span style="color:#1f6feb;font-weight:700">&rarr;</span> ' + escapeHtml(rel.toTable) + '</span>' +
    '</div>' +
    '<div class="edit-rel-fields">' +
      '<div class="edit-rel-row">' +
        '<label>Origem</label>' +
        '<select id="editConnFromTable">' + fromTableOpts + '</select>' +
        '<select id="editConnFromColumn"><option value="' + escapeHtml(rel.fromColumn) + '">' + escapeHtml(rel.fromColumn) + '</option></select>' +
      '</div>' +
      '<div class="edit-rel-arrow" style="display:flex;align-items:center;justify-content:center;gap:8px"><span>&darr;</span><button id="editConnSwapBtn" class="btn mini ghost" title="Inverter direcao" style="font-size:11px;padding:2px 6px">&#8645; Inverter</button></div>' +
      '<div class="edit-rel-row">' +
        '<label>Destino</label>' +
        '<select id="editConnToTable">' + toTableOpts + '</select>' +
        '<select id="editConnToColumn"><option value="' + escapeHtml(rel.toColumn) + '">' + escapeHtml(rel.toColumn) + '</option></select>' +
      '</div>' +
      '<div class="edit-rel-inline">' +
        '<div class="edit-rel-row">' +
          '<label>Cardinalidade</label>' +
          '<select id="editConnCardinality">' +
            '<option value="many-to-one"' + (rel.cardinality === 'many-to-one' ? ' selected' : '') + '>*:1  (Muitos p/ Um)</option>' +
            '<option value="one-to-one"' + (rel.cardinality === 'one-to-one' ? ' selected' : '') + '>1:1  (Um p/ Um)</option>' +
            '<option value="one-to-many"' + (rel.cardinality === 'one-to-many' ? ' selected' : '') + '>1:*  (Um p/ Muitos)</option>' +
            '<option value="many-to-many"' + (rel.cardinality === 'many-to-many' ? ' selected' : '') + '>*:*  (Muitos p/ Muitos)</option>' +
          '</select>' +
        '</div>' +
        '<div class="edit-rel-row">' +
          '<label>Filtro</label>' +
          '<select id="editConnFilterDirection">' +
            '<option value="single"' + (rel.filterDirection === 'single' ? ' selected' : '') + '>Unico</option>' +
            '<option value="both"' + (rel.filterDirection === 'both' ? ' selected' : '') + '>Ambos</option>' +
          '</select>' +
        '</div>' +
      '</div>' +
      '<label class="edit-rel-toggle">' +
        '<input type="checkbox" id="editConnActive"' + (rel.active !== false ? ' checked' : '') + ' />' +
        '<span>Relacionamento ativo</span>' +
      '</label>' +
    '</div>' +
    '<div class="edit-rel-actions">' +
      '<button id="editConnSaveBtn" class="btn primary">Salvar alteracoes</button>' +
      '<button id="editConnDeleteBtn" class="btn ghost" style="color:#d33">Remover</button>' +
      '<button id="editConnCancelBtn" class="btn ghost">Fechar</button>' +
    '</div>';

  // Setup column dropdowns
  function setupEditCols(tableId, colId, currentCol) {
    var tel = panel.querySelector('#' + tableId);
    var cel = panel.querySelector('#' + colId);
    if (!tel || !cel) return;
    tel.addEventListener('change', async function() {
      var t = tel.value;
      if (!t) { cel.innerHTML = '<option value="">-</option>'; return; }
      try {
        var cols = await loadModelColumns(t);
        cel.innerHTML = cols.map(function(c) { return '<option value="' + escapeHtml(c.name) + '"' + (c.name === currentCol ? ' selected' : '') + '>' + escapeHtml(c.name) + '</option>'; }).join('');
      } catch(e) { cel.innerHTML = '<option value="">Erro</option>'; }
    });
  }
  setupEditCols('editConnFromTable', 'editConnFromColumn', rel.fromColumn);
  setupEditCols('editConnToTable', 'editConnToColumn', rel.toColumn);

  // Swap direction
  panel.querySelector('#editConnSwapBtn').addEventListener('click', function() {
    var tmpTable = rel.fromTable;
    var tmpCol = rel.fromColumn;
    rel.fromTable = rel.toTable;
    rel.fromColumn = rel.toColumn;
    rel.toTable = tmpTable;
    rel.toColumn = tmpCol;
    if (rel.cardinality === 'one-to-many') rel.cardinality = 'many-to-one';
    else if (rel.cardinality === 'many-to-one') rel.cardinality = 'one-to-many';
    editRelationship(idx);
  });

  // Save
  panel.querySelector('#editConnSaveBtn').addEventListener('click', function() {
    var ft = panel.querySelector('#editConnFromTable').value;
    var fc = panel.querySelector('#editConnFromColumn').value;
    var tt = panel.querySelector('#editConnToTable').value;
    var tc = panel.querySelector('#editConnToColumn').value;
    var norm = normalizeRelationshipDirection(ft, fc, tt, tc);
    rel.fromTable = norm.fromTable;
    rel.fromColumn = norm.fromColumn;
    rel.toTable = norm.toTable;
    rel.toColumn = norm.toColumn;
    rel.cardinality = panel.querySelector('#editConnCardinality').value;
    rel.filterDirection = panel.querySelector('#editConnFilterDirection').value;
    rel.active = panel.querySelector('#editConnActive').checked;
    if (rel.fromTable === rel.toTable && rel.fromColumn !== rel.toColumn) {
      toast('Atencao: relacionamento da tabela ' + rel.fromTable + ' com ela mesma. Verifique se isso e intencional.', 'error');
    }
    renderConnectionsDesigner();
    renderRelationshipList();
    editRelationship(idx);
    toast('Relacionamento atualizado.');
  });

  // Delete
  panel.querySelector('#editConnDeleteBtn').addEventListener('click', function() {
    state.model.relationships.splice(idx, 1);
    renderConnectionsDesigner();
    renderRelationshipList();
    panel.innerHTML = '<div class="empty-state small">Relacionamento removido.</div>';
  });

  // Cancel
  panel.querySelector('#editConnCancelBtn').addEventListener('click', function() {
    panel.innerHTML = '<div class="empty-state small">Selecione um relacionamento no diagrama ou no modal.</div>';
  });
}

async function saveConnectionsModel() {
  const saveBtn = $('#saveConnectionsModelBtn');
  if (saveBtn) { saveBtn.disabled = true; saveBtn.dataset.originalText = saveBtn.textContent; saveBtn.textContent = 'Salvando...'; }
  try {
  ensureModelTablesArray();
  selectedConnectionTableNames().forEach((name) => {
    if (!state.model.tables.some((item) => (typeof item === 'string' ? item : item.name) === name)) state.model.tables.push({ name });
  });
  // Coleta avisos de validacao local (nao bloqueia o salvamento)
  var warnings = [];
  var validResources = new Set((state.resources || []).map(function(r) { return r.name; }));
  var rels = state.model.relationships || [];
  for (var i = 0; i < rels.length; i++) {
    var r = rels[i];
    if (r.fromTable && !validResources.has(r.fromTable)) {
      warnings.push('Tabela nao encontrada: ' + r.fromTable + ' (relacionamento ' + (i + 1) + ')');
    }
    if (r.toTable && !validResources.has(r.toTable)) {
      warnings.push('Tabela nao encontrada: ' + r.toTable + ' (relacionamento ' + (i + 1) + ')');
    }
  }
  // Valida colunas selecionadas
  var selectedColumns = state.model.selectedColumns || [];
  for (var j = 0; j < selectedColumns.length; j++) {
    var sc = selectedColumns[j];
    if (sc.table && !validResources.has(sc.table)) {
      warnings.push('Coluna selecionada referencia tabela inexistente: ' + sc.table + '[' + (sc.column || '?') + ']');
    }
  }
  const data = await api('/api/model', {
    method: 'PUT',
    body: JSON.stringify({ model: state.model }),
    timeoutMs: MODEL_SAVE_API_TIMEOUT_MS
  });
  state.model = data.model || state.model;
  renderConnectionsDesigner();
  renderModelDesigner();
  // Garante que as linhas sejam redesenhadas apos o layout se estabilizar
  setTimeout(function() { drawConnectionRelationshipLines(); }, 300);
  setTimeout(function() { drawConnectionRelationshipLines(); }, 600);
  if (data.warnings && data.warnings.length) {
    warnings = warnings.concat(data.warnings);
  }
  if (warnings.length) {
    toast('Conexoes salvas com avisos: ' + warnings.join('; '));
  } else {
    toast('Conexoes, cards e relacionamentos salvos.');
  }
  } finally {
    if (saveBtn) { saveBtn.disabled = false; saveBtn.textContent = saveBtn.dataset.originalText || 'Salvar conexoes'; }
  }
}

function renderModelCardsGrid() {
  const container = $('#modelCardsGrid');
  if (!container) return;
  const modelTables = Array.isArray(state.model && state.model.tables) ? state.model.tables : [];
  const resources = state.resources || [];
  const relationships = Array.isArray(state.model && state.model.relationships) ? state.model.relationships : [];
  if (!modelTables.length) {
    container.innerHTML = '<div class="empty-state">Nenhuma tabela no modelo. Use <b>Inserir Dados</b> para adicionar tabelas.</div>';
    return;
  }
  // Resolve column count: prefer modelColumnCache, then resource.columns, fallback load
  const colCache = state.modelColumnCache || {};
  const resolveColCount = function(tblName) {
    if (colCache[tblName] && colCache[tblName].length) return colCache[tblName].length;
    var res = resources.find(function(r) { return r.name === tblName; });
    if (res && res.columnCount) return res.columnCount;
    if (res && Array.isArray(res.columns)) return res.columns.length;
    return null;
  };
  container.innerHTML = modelTables.map(function(tbl) {
    const res = resources.find(function(r) { return r.name === tbl.name; }) || {};
    const type = String(res.type || 'table').toLowerCase();
    const known = resolveColCount(tbl.name);
    const colCount = known != null ? known : -1;
    const colText = known != null ? Number(known).toLocaleString('pt-BR') + ' colunas' : 'carregando...';
    const relCount = relationships.filter(function(r) { return r.fromTable === tbl.name || r.toTable === tbl.name; }).length;
    const iconLetter = String(tbl.name || 'T').charAt(0).toUpperCase();
    const iconClass = type === 'view' ? 'view-icon' : (tbl.name === 'Calendario' ? 'calendar-icon' : 'table-icon');
    return '<div class="model-card" data-model-card="' + escapeHtml(tbl.name) + '">'
      + '<div class="model-card-header">'
      + '<div class="model-card-icon ' + iconClass + '">' + escapeHtml(iconLetter) + '</div>'
      + '<div class="model-card-info">'
      + '<div class="model-card-name">' + escapeHtml(tbl.name) + '</div>'
      + '<div class="model-card-type">' + escapeHtml(type) + (res.imported ? ' • importada' : '') + '</div>'
      + '</div></div>'
      + '<div class="model-card-meta">'
      + '<span class="' + (known == null ? 'model-col-loading' : '') + '" data-model-col-count="' + escapeHtml(tbl.name) + '">' + colText + '</span>'
      + (relCount > 0 ? '<span>' + relCount + ' relacionamento(s)</span>' : '')
      + (res.sourceTable ? '<span>Origem: ' + escapeHtml(res.sourceTable) + '</span>' : '')
      + '</div>'
      + '</div>';
  }).join('');
  container.querySelectorAll('.model-card').forEach(function(card) {
    card.addEventListener('click', function(ev) {
      if (ev.target.closest('button')) return;
      var name = card.dataset.modelCard;
      var select = $('#modelResourceSelect');
      if (select) { select.value = name; renderModelColumnPicker(); }
    });
  });
  // Load column counts for tables not yet cached
  var toLoad = modelTables.filter(function(t) { return resolveColCount(t.name) == null; });
  if (toLoad.length) {
    Promise.all(toLoad.map(function(t) {
      return loadModelColumns(t.name).catch(function() { return []; });
    })).then(function() {
      container.querySelectorAll('[data-model-col-count]').forEach(function(span) {
        var name = span.dataset.modelColCount;
        var cols = state.modelColumnCache && state.modelColumnCache[name];
        if (cols && cols.length) {
          span.textContent = Number(cols.length).toLocaleString('pt-BR') + ' colunas';
          span.classList.remove('model-col-loading');
        }
      });
      updateModelStats();
    });
  }
}

function openInsertDataModal() {
  var modal = $('#insertDataModal');
  if (!modal) {
    modal = document.createElement('div');
    modal.id = 'insertDataModal';
    modal.className = 'modal-backdrop';
    modal.style.cssText = 'display:flex;align-items:flex-start;justify-content:center;z-index:9990;padding-top:40px;overflow-y:auto';
    var content = document.getElementById('schemaTab');
    if (content) {
      var clone = content.cloneNode(true);
      clone.id = 'insertDataModalContent';
      clone.className = 'tab active';
      clone.style.cssText = 'display:block;max-width:1100px;width:100%;background:var(--bg,#f4f7fb);border-radius:16px;padding:32px;margin-bottom:40px;box-shadow:0 20px 60px rgba(0,0,0,.2)';
      clone.querySelector('.page-head') && clone.querySelector('.page-head').insertAdjacentHTML('beforeend', '<button class="btn ghost modal-close-btn" onclick="closeInsertDataModal()" style="margin-left:auto" title="Fechar">✕</button>');
      modal.appendChild(clone);
      document.body.appendChild(modal);
      loadInsertDataResources();
    }
  } else {
    modal.style.display = 'flex';
  }
  document.body.style.overflow = 'hidden';
}

function closeInsertDataModal() {
  var modal = $('#insertDataModal');
  if (modal) modal.style.display = 'none';
  document.body.style.overflow = '';
}

function loadInsertDataResources() {
  if (typeof loadTables === 'function') loadTables().catch(function(){});
  if (typeof loadImportedTables === 'function') loadImportedTables().catch(function(){});
  if (typeof renderInsertDataPanel === 'function') renderInsertDataPanel();
}

function renderModelErrors() {
  var container = $('#modelErrorsContainer');
  if (!container) return;
  var errors = [];
  var model = state.model || {};
  var tables = Array.isArray(model.tables) ? model.tables.map(function(t) { return typeof t === 'string' ? t : t.name; }) : [];
  var tableNames = new Set(tables.filter(Boolean));
  var cache = state.modelColumnCache || {};

  // Column errors
  (model.selectedColumns || []).forEach(function(col) {
    if (col.table && !tableNames.has(col.table)) {
      errors.push({ type: 'coluna', message: 'Coluna "' + col.column + '" referência tabela "' + col.table + '" que não existe no modelo.' });
    }
    if (col.column && col.table && cache[col.table]) {
      var found = cache[col.table].some(function(c) { return c.name === col.column; });
      if (!found) {
        errors.push({ type: 'coluna', message: 'Coluna "' + col.column + '" não encontrada na tabela "' + col.table + '".' });
      }
    }
  });

  // Relationship errors
  (model.relationships || []).forEach(function(rel, i) {
    if (rel.fromTable && !tableNames.has(rel.fromTable)) {
      errors.push({ type: 'relacionamento', message: 'Relacionamento #' + (i + 1) + ': tabela origem "' + rel.fromTable + '" não existe no modelo.' });
    }
    if (rel.toTable && !tableNames.has(rel.toTable)) {
      errors.push({ type: 'relacionamento', message: 'Relacionamento #' + (i + 1) + ': tabela destino "' + rel.toTable + '" não existe no modelo.' });
    }
    if (rel.fromTable && rel.toTable && rel.fromTable === rel.toTable && rel.fromColumn && rel.fromColumn === rel.toColumn) {
      errors.push({ type: 'relacionamento', message: 'Relacionamento #' + (i + 1) + ': origem e destino são o mesmo campo.' });
    }
    if (rel.fromTable && rel.fromColumn && cache[rel.fromTable]) {
      var found = cache[rel.fromTable].some(function(c) { return c.name === rel.fromColumn; });
      if (!found) errors.push({ type: 'relacionamento', message: 'Relacionamento #' + (i + 1) + ': coluna "' + rel.fromColumn + '" não existe na tabela "' + rel.fromTable + '".' });
    }
    if (rel.toTable && rel.toColumn && cache[rel.toTable]) {
      var found = cache[rel.toTable].some(function(c) { return c.name === rel.toColumn; });
      if (!found) errors.push({ type: 'relacionamento', message: 'Relacionamento #' + (i + 1) + ': coluna "' + rel.toColumn + '" não existe na tabela "' + rel.toTable + '".' });
    }
  });

  // Measure errors
  (model.measures || []).forEach(function(m, i) {
    var status = String(m.diagnosticStatus || (m.formula ? 'nao_validada' : 'sem_formula'));
    if (status === 'sem_formula' || !m.formula) {
      errors.push({ type: 'medida', message: 'Medida "' + (m.displayName || m.name) + '" não possui fórmula DAX.' });
    } else if (status === 'funcao_nao_suportada') {
      var unsupported = Array.isArray(m.unsupportedFunctions) ? m.unsupportedFunctions.join(', ') : '';
      errors.push({ type: 'medida', message: 'Medida "' + (m.displayName || m.name) + '" contém funções não suportadas: ' + unsupported });
    } else if (status === 'dependencia_ausente') {
      errors.push({ type: 'medida', message: 'Medida "' + (m.displayName || m.name) + '" depende de colunas/tabelas ausentes.' });
    } else if (status === 'erro_conversao') {
      errors.push({ type: 'medida', message: 'Medida "' + (m.displayName || m.name) + '" teve erro na conversão DAX→SQL.' });
    } else if (status === 'tabela_ausente' || status === 'coluna_ausente') {
      errors.push({ type: 'medida', message: 'Medida "' + (m.displayName || m.name) + '": ' + (m.lastDiagnostic || 'referência ausente no modelo.') });
    } else if (status === 'validando') {
      errors.push({ type: 'medida', message: 'Medida "' + (m.displayName || m.name) + '" está sendo validada.' });
    } else if (status === 'pendente' || status === 'nao_validada') {
      errors.push({ type: 'medida', message: 'Medida "' + (m.displayName || m.name) + '" está pendente de validação.' });
    }
  });

  if (errors.length) {
    container.style.display = '';
    container.innerHTML = '<div class="model-errors-header"><svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg> ' + errors.length + ' erro(s) encontrados no modelo</div>' +
      '<div class="model-errors-list">' + errors.map(function(e) {
        var icon = e.type === 'coluna' ? '▦' : e.type === 'relacionamento' ? '⇄' : 'ƒx';
        return '<div class="model-error-item model-error-' + e.type + '"><span class="model-error-icon">' + icon + '</span><span>' + escapeHtml(e.message) + '</span></div>';
      }).join('') + '</div>';
  } else {
    container.style.display = 'none';
    container.innerHTML = '';
  }
}

function renderModelDesigner() {
  renderModelErrors();
  renderModelCardsGrid();
  renderModelResourceSelects();
  refreshVisualBuilder();
  renderModelColumnPicker();
  refreshRelationshipColumns();
  renderSelectedModelColumns();
  renderRelationshipList();
  renderMeasureList();
  updateModelStats();
}

function updateModelStats() {
  var tables = (Array.isArray(state.model && state.model.tables) ? state.model.tables : []);
  var selCols = (state.model && state.model.selectedColumns) || [];
  var rels = (state.model && state.model.relationships) || [];
  var meas = (state.model && state.model.measures) || [];
  var tableStats = $('#modelStatTables');
  var colStats = $('#modelStatCols');
  var relStats = $('#modelStatRels');
  var measStats = $('#modelStatMeas');
  var selColMeta = $('#modelSelColMeta');
  var relCount = $('#modelRelCount');
  var measCount = $('#modelMeasCount');
  // Total columns across all model tables from cache
  var totalCols = 0;
  var cache = state.modelColumnCache || {};
  tables.forEach(function(t) {
    var name = (typeof t === 'string' ? t : t.name);
    if (cache[name] && cache[name].length) totalCols += cache[name].length;
  });
  if (tableStats) tableStats.textContent = tables.length + ' tabelas';
  if (colStats) colStats.textContent = (totalCols || selCols.length) + ' colunas';
  if (relStats) relStats.textContent = rels.length + ' rel';
  if (measStats) measStats.textContent = meas.length + ' medidas';
  if (selColMeta) selColMeta.textContent = selCols.length ? selCols.length + ' colunas no modelo' : 'dimensoes do relatorio';
  if (relCount) relCount.textContent = rels.length ? rels.length + ' relacionamento(s)' : '';
  if (measCount) measCount.textContent = meas.length ? meas.length + ' medida(s)' : '';
}

function addSelectedModelColumns() {
  const table = $('#modelResourceSelect') && $('#modelResourceSelect').value;
  if (!table) return toast('Selecione uma tabela ou view.', 'error');
  const checked = $$('#modelColumnList [data-model-column]:checked').map((input) => input.dataset.modelColumn);
  if (!checked.length) return toast('Selecione pelo menos uma coluna.', 'error');
  state.model.selectedColumns = state.model.selectedColumns || [];
  checked.forEach((column) => {
    const exists = state.model.selectedColumns.some((item) => item.table === table && item.column === column);
    if (!exists) state.model.selectedColumns.push({ table, column, alias: table + '_' + column });
  });
  renderSelectedModelColumns();
  toast('Colunas adicionadas ao modelo.');
}

function addRelationship() {
  var fromTableEl = $('#relFromTable');
  var fromColumnEl = $('#relFromColumn');
  var toTableEl = $('#relToTable');
  var toColumnEl = $('#relToColumn');
  if (!fromTableEl || !fromColumnEl || !toTableEl || !toColumnEl) return toast('Erro ao acessar os campos do relacionamento. Recarregue a pagina.', 'error');
  var norm = normalizeRelationshipDirection(fromTableEl.value, fromColumnEl.value, toTableEl.value, toColumnEl.value);
  const rel = {
    fromTable: norm.fromTable,
    fromColumn: norm.fromColumn,
    toTable: norm.toTable,
    toColumn: norm.toColumn,
    joinType: $('#relJoinType').value || 'LEFT',
    cardinality: norm.cardinality,
    filterDirection: 'single',
    active: true,
    confidence: 'manual'
  };
  if (!rel.fromTable || !rel.fromColumn || !rel.toTable || !rel.toColumn) return toast('Preencha as duas tabelas/views e colunas.', 'error');
  if (rel.fromTable === rel.toTable && rel.fromColumn === rel.toColumn) return toast('O relacionamento precisa ligar campos diferentes.', 'error');
  state.model.relationships = state.model.relationships || [];
  state.model.relationships.push(rel);
  renderRelationshipList();
}


