/* ---------- DAX Measure Modal with autocomplete ---------- */
const DAX_FUNCTIONS = [
  'SUM','SUMX','AVERAGE','AVERAGEX','COUNT','COUNTA','COUNTROWS','COUNTBLANK','DISTINCTCOUNT',
  'MIN','MINX','MAX','MAXX','DIVIDE','CALCULATE','CALCULATETABLE','FILTER','ALL','ALLEXCEPT',
  'ALLSELECTED','VALUES','DISTINCT','RELATED','RELATEDTABLE','EARLIER','EARLIEST',
  'IF','SWITCH','AND','OR','NOT','TRUE','FALSE','BLANK','ISBLANK','IFERROR',
  'FORMAT','YEAR','MONTH','DAY','TODAY','NOW','DATE','DATEDIFF','DATEADD',
  'TOTALYTD','TOTALQTD','TOTALMTD','DATESYTD','DATESQTD','DATESMTD',
  'SAMEPERIODLASTYEAR','PARALLELPERIOD','PREVIOUSMONTH','PREVIOUSQUARTER','PREVIOUSYEAR',
  'NEXTMONTH','NEXTQUARTER','NEXTYEAR','STARTOFMONTH','ENDOFMONTH','STARTOFQUARTER','ENDOFQUARTER',
  'STARTOFYEAR','ENDOFYEAR','CALENDAR','CALENDARAUTO',
  'RANKX','TOPN','GENERATE','GENERATEALL','ADDCOLUMNS','SELECTCOLUMNS','SUMMARIZE','SUMMARIZECOLUMNS',
  'GROUPBY','CROSSJOIN','UNION','INTERSECT','EXCEPT','NATURALINNERJOIN','NATURALLEFTOUTERJOIN',
  'LOOKUPVALUE','TREATAS','USERELATIONSHIP','CROSSFILTER',
  'CONCATENATE','CONCATENATEX','LEFT','RIGHT','MID','LEN','UPPER','LOWER','TRIM','SUBSTITUTE',
  'SEARCH','FIND','EXACT','REPT','UNICHAR','COMBINEVALUES',
  'ROUND','ROUNDUP','ROUNDDOWN','INT','ABS','SIGN','SQRT','POWER','MOD','LOG','LN','EXP',
  'PRODUCT','PRODUCTX','MEDIAN','MEDIANX','PERCENTILE.INC','PERCENTILE.EXC',
  'VAR','RETURN','SELECTEDVALUE','HASONEVALUE','HASONEFILTER','ISFILTERED','ISCROSSFILTERED',
  'FIRSTDATE','LASTDATE','FIRSTNONBLANK','LASTNONBLANK','OPENINGBALANCEMONTH','CLOSINGBALANCEMONTH',
  'KEEPFILTERS','REMOVEFILTERS','ALLNOBLANKROW','DATATABLE','ROW','ERROR'
];

function formatDax(code) {
  code = code.replace(/\r\n?/g, '\n').trim();
  if (!code) return '';
  var strings = [];
  code = code.replace(/"(?:[^"\\]|\\.)*"/g, function(m) {
    var id = '\x01S' + strings.length + '\x01';
    strings.push(m);
    return id;
  });
  code = code.replace(/[ \t\n]+/g, ' ');
  var indent = '    ';
  var lines = [''];
  var parenDepth = 0;
  var braceDepth = 0;
  var line = 0;
  var atLineStart = true;
  for (var i = 0; i < code.length; i++) {
    var ch = code[i];
    if (atLineStart && ch === ' ') continue;
    if (ch === '(') {
      lines[line] += '(';
      parenDepth++;
      line++;
      lines[line] = indent.repeat(parenDepth + braceDepth);
      atLineStart = true;
    } else if (ch === ')') {
      var cur = lines[line].replace(/\s+$/, '');
      if (cur) { line++; lines[line] = ''; }
      parenDepth = Math.max(0, parenDepth - 1);
      lines[line] = indent.repeat(parenDepth + braceDepth) + ')';
      atLineStart = false;
    } else if (ch === '{') {
      lines[line] += '{';
      braceDepth++;
      atLineStart = false;
    } else if (ch === '}') {
      braceDepth = Math.max(0, braceDepth - 1);
      lines[line] += '}';
      atLineStart = false;
    } else if (ch === ',' && braceDepth === 0) {
      lines[line] += ',';
      line++;
      lines[line] = indent.repeat(parenDepth + braceDepth);
      atLineStart = true;
    } else if (ch === '\x01') {
      var end = code.indexOf('\x01', i + 1);
      if (end === -1) { lines[line] += ch; continue; }
      var ph = code.substring(i, end + 1);
      var idx = parseInt(ph.substring(2), 10);
      lines[line] += strings[idx] || ph;
      atLineStart = false;
      i = end;
    } else {
      lines[line] += ch;
      atLineStart = false;
    }
  }
  var result = lines.filter(function(l) { return l !== undefined; }).join('\n');
  for (var j = 0; j < strings.length; j++) {
    result = result.split('\x01S' + j + '\x01').join(strings[j]);
  }
  return result;
}

function extractTableFromDaxFormula(formula) {
  const tables = extractTablesFromDaxFormula(formula);
  return tables.length > 0 ? tables[0] : '';
}

function extractTablesFromDaxFormula(formula) {
  var text = String(formula || '');
  var tables = [];
  var seen = {};
  function cleanDaxTableName(name) {
    return String(name || '').trim().replace(/^['"]+|['"]+$/g, '').trim();
  }
  var colRe = /(?:'([^']+)'|([A-Za-z_À-ÿ][A-Za-z0-9_À-ÿ .-]*?))\s*\[\s*([^\]]+)\s*\]/g;
  var m;
  while ((m = colRe.exec(text))) {
    var tbl = cleanDaxTableName(m[1] || m[2] || '');
    if (tbl && !seen[tbl]) { seen[tbl] = true; tables.push(tbl); }
  }
  var rowRe = /COUNTROWS\s*\(\s*(?:'([^']+)'|([^\)]+?))\s*\)/gi;
  while ((m = rowRe.exec(text))) {
    var tbl = cleanDaxTableName(m[1] || m[2] || '');
    if (tbl && !seen[tbl]) { seen[tbl] = true; tables.push(tbl); }
  }
  var filteredIteratorRe = /(SUMX|AVERAGEX|COUNTX|MAXX|MINX|CONCATENATEX)\s*\(\s*FILTER\s*\(\s*(?:'([^']+)'|([^,\)]+))/gi;
  while ((m = filteredIteratorRe.exec(text))) {
    var filteredTbl = cleanDaxTableName(m[2] || m[3] || '');
    if (filteredTbl && !seen[filteredTbl]) { seen[filteredTbl] = true; tables.push(filteredTbl); }
  }
  var iteratorRe = /(SUMX|AVERAGEX|COUNTX|MAXX|MINX|CONCATENATEX)\s*\((?!\s*(?:FILTER|VALUES|DISTINCT|KEEPFILTERS)\s*\()\s*(?:'([^']+)'|([^,\)]+))/gi;
  while ((m = iteratorRe.exec(text))) {
    var tbl = cleanDaxTableName(m[2] || m[3] || '');
    if (tbl && !seen[tbl]) { seen[tbl] = true; tables.push(tbl); }
  }
  return tables;
}

function daxTableReferenceName(tableName) {
  const name = String(tableName || '').trim();
  if (!name) return '';
  if (/^[A-Za-z_À-ÿ][\wÀ-ÿ]*$/.test(name)) return name;
  return "'" + name.replace(/'/g, "''") + "'";
}

function populateDaxMeasureTableSelect(selected = '') {
  const sel = $('#daxMeasureTableSelect');
  if (!sel) return;
  const names = [];
  const add = (name) => {
    const value = String(name || '').trim();
    if (value && !names.some((item) => item.toLowerCase() === value.toLowerCase())) names.push(value);
  };
  ((state.model && state.model.tables) || []).forEach((item) => add(item && (item.name || item)));
  (state.resources || []).forEach((item) => add(item && (item.name || item)));
  ((state.model && state.model.measures) || []).forEach((item) => add(item && item.table));
  add(currentBuilderTable());
  sel.innerHTML = '<option value="">Detectar pela fórmula</option>' + names.map((name) => '<option value="' + escapeHtml(name) + '">' + escapeHtml(name) + '</option>').join('');
  const wanted = String(selected || '').trim();
  if (wanted) {
    const match = names.find((name) => name.toLowerCase() === wanted.toLowerCase());
    if (match) sel.value = match;
  }
}

function validateDaxFormula(formula) {
  if (!formula || !formula.trim()) return 'A fórmula não pode estar vazia.';
  var errors = [];
  var s = formula;
  // Check balanced parentheses
  var paren = 0;
  var brack = 0;
  var brace = 0;
  var inStr = false;
  for (var i = 0; i < s.length; i++) {
    var c = s[i];
    if (inStr) {
      if (c === '"' && (i === 0 || s[i-1] !== '\\')) inStr = false;
      continue;
    }
    if (c === '"') { inStr = true; continue; }
    if (c === '(') paren++;
    else if (c === ')') paren--;
    else if (c === '[') brack++;
    else if (c === ']') brack--;
    else if (c === '{') brace++;
    else if (c === '}') brace--;
    if (paren < 0) { errors.push('Parêntese fechado sem abertura correspondente.'); paren = 0; break; }
    if (brack < 0) { errors.push('Colchete fechado sem abertura correspondente.'); brack = 0; break; }
    if (brace < 0) { errors.push('Chave fechada sem abertura correspondente.'); brace = 0; break; }
  }
  if (inStr) errors.push('String literal não foi fechada (falta aspas duplas).');
  if (paren > 0) errors.push('Faltam ' + paren + ' parêntese(s) de fechamento.');
  if (brack > 0) errors.push('Faltam ' + brack + ' colchete(s) de fechamento.');
  if (brace > 0) errors.push('Faltam ' + brace + ' chave(s) de fechamento.');

  var measureNameSet = new Set();
  var iteratorColumnSet = daxIteratorRowColumnNamesClient(s);
  if (typeof state !== 'undefined' && state.model && Array.isArray(state.model.measures)) {
    state.model.measures.forEach(function(m) {
      if (m.name) measureNameSet.add(String(m.name).trim().toLowerCase());
      if (m.displayName) measureNameSet.add(String(m.displayName).trim().toLowerCase());
    });
  }

  var colRefRegex = /(?:('([^']+)'|([A-Za-z_À-ÿ0-9]+(?:\.[A-Za-z_À-ÿ0-9]+)*))\s*)?\[([^\]]+)\]/g;
  var match;
  while ((match = colRefRegex.exec(s)) !== null) {
    var tableName = (match[2] || match[3] || '').trim();
    var bracketName = (match[4] || '').trim().toLowerCase();
    if (!tableName) {
      if (!iteratorColumnSet.has(bracketName) && measureNameSet.size > 0 && !measureNameSet.has(bracketName)) {
        errors.push('Medida [' + match[4] + '] não foi encontrada no modelo. Verifique se o nome da medida salva está correto.');
      }
    }
  }
  return errors.length ? errors.join(' ') : '';
}

function daxIteratorRowColumnNamesClient(formula) {
  var text = String(formula || '');
  var names = new Set();
  function splitIteratorArgs(inner) {
    var args = [];
    var current = '';
    var paren = 0;
    var brace = 0;
    var single = false;
    var double = false;
    for (var idx = 0; idx < String(inner || '').length; idx++) {
      var currentChar = inner[idx];
      var previousChar = inner[idx - 1];
      if (currentChar === "'" && !double && previousChar !== '\\') single = !single;
      else if (currentChar === '"' && !single && previousChar !== '\\') double = !double;
      if (!single && !double) {
        if (currentChar === '(') paren++;
        else if (currentChar === ')') paren--;
        else if (currentChar === '{') brace++;
        else if (currentChar === '}') brace--;
        else if (currentChar === ',' && paren === 0 && brace === 0) {
          args.push(current.trim());
          current = '';
          continue;
        }
      }
      current += currentChar;
    }
    if (current.trim()) args.push(current.trim());
    return args;
  }
  var callRe = /(SUMX|AVERAGEX|COUNTX|MAXX|MINX|CONCATENATEX)\s*\(/gi;
  var call;
  while ((call = callRe.exec(text)) !== null) {
    var start = callRe.lastIndex;
    var pos = start;
    var depth = 1;
    var single = false;
    var double = false;
    while (pos < text.length && depth > 0) {
      var ch = text[pos];
      var prev = text[pos - 1];
      if (ch === "'" && !double && prev !== '\\') single = !single;
      else if (ch === '"' && !single && prev !== '\\') double = !double;
      else if (!single && !double && ch === '(') depth++;
      else if (!single && !double && ch === ')') depth--;
      pos++;
    }
    if (depth !== 0) continue;
    var args = splitIteratorArgs(text.slice(start, pos - 1));
    if (args.length < 2) continue;
    var rowExpression = args.slice(1).join(', ');
    var columnRe = /(^|[^A-Za-z0-9_À-ÿ\]'])\[\s*([^\]]+)\s*\]/g;
    var column;
    while ((column = columnRe.exec(rowExpression)) !== null) names.add(String(column[2] || '').trim().toLowerCase());
    callRe.lastIndex = pos;
  }
  return names;
}

function findDaxMeasureDefinitionSeparator(text) {
  const source = String(text || '');
  let singleQuoted = false;
  let doubleQuoted = false;
  let bracketDepth = 0;
  let parenDepth = 0;
  let braceDepth = 0;
  for (let index = 0; index < source.length; index += 1) {
    const char = source[index];
    const next = source[index + 1];
    if (singleQuoted) {
      if (char === "'" && next === "'") { index += 1; continue; }
      if (char === "'") singleQuoted = false;
      continue;
    }
    if (doubleQuoted) {
      if (char === '"' && next === '"') { index += 1; continue; }
      if (char === '"') doubleQuoted = false;
      continue;
    }
    if (char === "'") { singleQuoted = true; continue; }
    if (char === '"') { doubleQuoted = true; continue; }
    if (char === '[') { bracketDepth += 1; continue; }
    if (char === ']') { bracketDepth = Math.max(0, bracketDepth - 1); continue; }
    if (char === '(') { parenDepth += 1; continue; }
    if (char === ')') { parenDepth = Math.max(0, parenDepth - 1); continue; }
    if (char === '{') { braceDepth += 1; continue; }
    if (char === '}') { braceDepth = Math.max(0, braceDepth - 1); continue; }
    if (char === '=' && !bracketDepth && !parenDepth && !braceDepth) return index;
  }
  return -1;
}

function parseDaxMeasureDefinition(text, fallbackName) {
  const raw = String(text || '').trim();
  const fallback = String(fallbackName || '').trim();
  const eqIndex = findDaxMeasureDefinitionSeparator(raw);
  if (eqIndex > 0) {
    const left = raw.slice(0, eqIndex).trim();
    const right = raw.slice(eqIndex + 1).trim();
    const looksLikeMeasureName = left.length <= 128
      && left.indexOf('\n') === -1
      && !/[()[\]{}'"]/.test(left)
      && /^[A-Za-zÀ-ÿ0-9_ .-]+$/.test(left);
    if (looksLikeMeasureName && right) {
      return { name: left, formula: right, fullText: left + ' = ' + right };
    }
  }
  return { name: fallback, formula: raw, fullText: fallback ? fallback + ' = ' + raw : raw };
}

function setMeasureFormulaValidation(message, status) {
  const element = $('#measureFormulaValidationMessage');
  if (!element) return;
  const text = String(message || '').trim();
  element.hidden = !text;
  element.className = 'measure-formula-validation' + (status ? ' ' + status : '');
  element.textContent = text;
}

function openDaxMeasureInlineEditor(editIndex) {
  setMeasureFormulaValidation('', '');
  const measureTab = $('#ribbonTabMeasure');
  const measurePanel = $('#ribbonPanelMeasure');
  if (!measureTab || !measurePanel) return;
  const editIdx = editIndex !== undefined && editIndex !== null && !isNaN(Number(editIndex)) ? Number(editIndex) : -1;
  const measures = (state.model && state.model.measures) || [];
  const previous = editIdx >= 0 && measures[editIdx] ? measures[editIdx] : null;
  state.activeMeasureIndex = previous ? editIdx : -1;
  state.measureEditorOpen = true;

  $$('.builder-measure-row.selected').forEach(function(el) { el.classList.remove('selected'); });
  if (previous) {
    const row = document.querySelector('.builder-measure-row[data-builder-measure-index="' + editIdx + '"]');
    if (row) row.classList.add('selected');
  }

  const nameInput = $('#ribbonMeasureName');
  let formulaInput = $('#measureFormulaInput');
  const suggestionsDiv = $('#measureFormulaSuggestions');
  const formatEl = $('#ribbonMeasureFormat');
  const decimalsEl = $('#ribbonMeasureDecimals');
  const categoryEl = $('#ribbonMeasureCategory');
  const formulaBar = $('#measureFormulaBar');
  if (nameInput) nameInput.value = previous ? (previous.name || '') : '';
  // O usuario edita o DAX completo no mesmo campo, como no Power BI. Nome e
  // expressao continuam separados apenas internamente para manter o modelo salvo.
  if (formulaInput) formulaInput.value = previous
    ? ((previous.name || 'Medida') + ' =\n' + (previous.formula || ''))
    : 'Medida = ';
  if (formatEl) formatEl.value = previous ? (previous.format || '') : '';
  if (decimalsEl) decimalsEl.value = previous && previous.decimals != null ? previous.decimals : 2;
  if (categoryEl) categoryEl.value = previous ? (previous.dataCategory || '') : '';
  if (suggestionsDiv) suggestionsDiv.classList.remove('show');
  measureTab.hidden = false;
  updateVisualContextRibbon(selectedReportVisual());
  setMainRibbonTab('measure');
  if (formulaBar) formulaBar.hidden = false;
  positionMeasureFormulaBar();
  requestAnimationFrame(positionMeasureFormulaBar);

  const tableMap = {};
  (state.resources || []).forEach((resource) => {
    if (!resource || !resource.name) return;
    tableMap[resource.name] = (state.modelColumnCache && state.modelColumnCache[resource.name])
      ? state.modelColumnCache[resource.name].map((column) => column.name || column)
      : [];
  });
  if (state.model && state.model.tables) {
    state.model.tables.forEach((table) => {
      const tableName = table && (table.name || table);
      if (!tableName) return;
      if (!tableMap[tableName]) {
        tableMap[tableName] = table.columns && table.columns.length
          ? table.columns.map((column) => typeof column === 'string' ? column : column.name || column)
          : [];
      }
    });
  }
  const tableNames = Object.keys(tableMap);

  async function ensureColumnsFor(tableName) {
    if (tableMap[tableName] && tableMap[tableName].length) return;
    try {
      const data = await api('/api/tables/' + encodeURIComponent(tableName) + '/columns?ts=' + Date.now());
      const cols = (data.columns || []).map((column) => column.name || column);
      tableMap[tableName] = cols;
      if (!state.modelColumnCache) state.modelColumnCache = {};
      state.modelColumnCache[tableName] = normalizeColumnMetadataList(data.columns || []);
    } catch (e) { /* ignore */ }
  }

  function getWordAtCursor(textarea) {
    const pos = textarea.selectionStart;
    const text = textarea.value.substring(0, pos);
    const bracketMatch = text.match(/(?:'([^']+)'|([A-Za-zÀ-ÿ0-9_ .&-]+))\s*\[\s*([A-Za-zÀ-ÿ0-9_ .&-]*)$/);
    if (bracketMatch) return { type: 'column', table: String(bracketMatch[1] || bracketMatch[2] || '').trim(), partial: bracketMatch[3] || '' };
    const wordMatch = text.match(/([A-Za-zÀ-ÿ0-9_%]+)$/);
    if (wordMatch) return { type: 'word', partial: wordMatch[1] };
    if (text.match(/[\(\,]\s*$/)) return { type: 'word', partial: '' };
    return null;
  }

  function positionSuggestionsAtCursor() {
    if (!suggestionsDiv || !formulaInput) return;
    var text = formulaInput.value;
    var pos = formulaInput.selectionStart;
    var beforeCursor = text.substring(0, pos);
    var lastNewline = beforeCursor.lastIndexOf('\n');
    var lineText = beforeCursor.substring(lastNewline + 1);
    var measurer = document.getElementById('suggest-measurer');
    if (!measurer) {
      measurer = document.createElement('span');
      measurer.id = 'suggest-measurer';
      measurer.style.cssText = 'position:absolute;visibility:hidden;white-space:pre;font-family:\'Cascadia Code\',\'Fira Code\',\'Consolas\',\'Courier New\',monospace;font-size:13px;line-height:1.45;padding:0 10px;pointer-events:none;';
      suggestionsDiv.parentNode.appendChild(measurer);
    }
    measurer.textContent = lineText;
    var padLeft = 10;
    var leftPos = padLeft + measurer.offsetWidth;
    var maxLeft = (formulaInput.clientWidth || 300) - 240;
    suggestionsDiv.style.left = Math.max(padLeft, Math.min(leftPos, maxLeft)) + 'px';
  }

  function renderSuggestions(items, onPick) {
    if (!suggestionsDiv) return;
    if (!items.length) { suggestionsDiv.classList.remove('show'); return; }
    suggestionsDiv.innerHTML = '';
    suggestionsDiv.classList.add('show');
    items.slice(0, 40).forEach((item, index) => {
      const div = document.createElement('div');
      div.className = 'measure-autocomplete-item' + (index === 0 ? ' selected' : '');
      if (item.type === 'function') {
        div.innerHTML = '<span style="color:#7c3aed;font-weight:700;min-width:22px;">ƒx</span><span>' + escapeHtml(item.label) + '</span><small>' + escapeHtml(item.hint || 'Função DAX') + '</small>';
      } else if (item.type === 'table') {
        div.innerHTML = '<span style="color:#0ea5e9;min-width:22px;">▦</span><span>' + escapeHtml(item.label) + '</span><small>Tabela</small>';
      } else if (item.type === 'measure') {
        div.innerHTML = '<span style="color:#7c3aed;font-weight:800;min-width:22px;">ƒx</span><span>' + escapeHtml(item.label) + '</span><small>Medida</small>';
      } else {
        div.innerHTML = '<span style="color:#10b981;min-width:22px;">☰</span><span>' + escapeHtml(item.label) + '</span><small>Coluna</small>';
      }
      div.addEventListener('mousedown', (ev) => { ev.preventDefault(); onPick(item); });
      if (index === 0) div.dataset.selected = '1';
      suggestionsDiv.appendChild(div);
    });
    positionSuggestionsAtCursor();
  }

  function insertSuggestion(item) {
    if (!formulaInput) return;
    const pos = formulaInput.selectionStart;
    const text = formulaInput.value;
    const before = text.substring(0, pos);
    const after = text.substring(pos);
    if (item.type === 'column') {
      const bracketMatch = before.match(/(?:'([^']+)'|([A-Za-zÀ-ÿ0-9_ .&-]+))\s*\[\s*([A-Za-zÀ-ÿ0-9_ .&-]*)$/);
      if (bracketMatch) {
        const start = pos - String(bracketMatch[3] || '').length;
        formulaInput.value = text.substring(0, start) + item.label + ']' + after;
        formulaInput.selectionStart = formulaInput.selectionEnd = start + item.label.length + 1;
      }
    } else if (item.type === 'table') {
      const wordMatch = before.match(/([A-Za-zÀ-ÿ0-9_%]+)$/);
      const partial = wordMatch ? wordMatch[1].length : 0;
      const start = pos - partial;
      const insert = daxTableReferenceName(item.label) + '[';
      formulaInput.value = text.substring(0, start) + insert + after;
      formulaInput.selectionStart = formulaInput.selectionEnd = start + insert.length;
      ensureColumnsFor(item.label).then(() => handleInput());
    } else if (item.type === 'measure') {
      const wordMatch = before.match(/([A-Za-zÀ-ÿ0-9_%]+)$/);
      const partial = wordMatch ? wordMatch[1].length : 0;
      const start = pos - partial;
      const insert = '[' + item.label + ']';
      formulaInput.value = text.substring(0, start) + insert + after;
      formulaInput.selectionStart = formulaInput.selectionEnd = start + insert.length;
    } else {
      const wordMatch = before.match(/([A-Za-zÀ-ÿ0-9_%]+)$/);
      const partial = wordMatch ? wordMatch[1].length : 0;
      const start = pos - partial;
      const insert = item.label + '(';
      formulaInput.value = text.substring(0, start) + insert + after;
      formulaInput.selectionStart = formulaInput.selectionEnd = start + insert.length;
    }
    if (suggestionsDiv) suggestionsDiv.classList.remove('show');
    formulaInput.focus();
    formulaInput.dispatchEvent(new Event('input', { bubbles: true }));
  }

  function handleInput() {
    if (!formulaInput) return;
    const highlightEl = $('#measureFormulaHighlight');
    if (highlightEl) {
      try {
        highlightEl.innerHTML = highlightDax(formulaInput.value);
      } catch (e) {
        highlightEl.innerHTML = String(formulaInput.value).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
      }
    }
    const ctx = getWordAtCursor(formulaInput);
    if (!ctx) { if (suggestionsDiv) suggestionsDiv.classList.remove('show'); return; }
    if (ctx.type === 'column') {
      const cols = tableMap[ctx.table] || [];
      const partial = String(ctx.partial || '').toLowerCase();
      const filtered = cols.filter((column) => String(column).toLowerCase().includes(partial)).map((column) => ({ type: 'column', label: column }));
      if (!filtered.length && !partial) {
        ensureColumnsFor(ctx.table).then(() => renderSuggestions((tableMap[ctx.table] || []).map((column) => ({ type: 'column', label: column })), insertSuggestion));
      } else {
        renderSuggestions(filtered, insertSuggestion);
      }
      return;
    }
    const partial = String(ctx.partial || '').toLowerCase();
    let daxMatches = DAX_FUNCTIONS.filter((fn) => fn.toLowerCase().startsWith(partial)).map((fn) => ({ type: 'function', label: fn, hint: 'Função DAX' }));
    if (!partial) daxMatches = daxMatches.slice(0, 20);
    const tableMatches = tableNames.filter((table) => table.toLowerCase().includes(partial)).map((table) => ({ type: 'table', label: table }));
    const measureMatches = ((state.model && state.model.measures) || [])
      .filter((measure, index) => index !== editIdx && String(measure.name || '').toLowerCase().includes(partial))
      .map((measure) => ({ type: 'measure', label: measure.name, hint: measure.table || '' }));
    renderSuggestions([...measureMatches, ...tableMatches, ...daxMatches], insertSuggestion);
  }

  if (formulaInput) {
    const formulaValueBeforeClone = formulaInput.value || '';
    const newFormula = formulaInput.cloneNode(true);
    formulaInput.parentNode.replaceChild(newFormula, formulaInput);
    newFormula.value = formulaValueBeforeClone;
    formulaInput = newFormula;

    function autoResizeFormulaInput() {
      formulaInput.style.height = 'auto';
      var newHeight = Math.max(38, Math.min(formulaInput.scrollHeight, 280));
      formulaInput.style.height = newHeight + 'px';
    }
    autoResizeFormulaInput();

    function syncHighlightScroll() {
      var highlightEl = $('#measureFormulaHighlight');
      if (highlightEl) {
        highlightEl.scrollTop = formulaInput.scrollTop;
        highlightEl.scrollLeft = formulaInput.scrollLeft;
      }
    }

    formulaInput.addEventListener('input', function() {
      autoResizeFormulaInput();
      handleInput();
      syncHighlightScroll();
    });
    formulaInput.addEventListener('scroll', syncHighlightScroll);

    function getSelectedSuggestionIndex() {
      for (var i = 0; i < suggestionsDiv.children.length; i++) {
        if (suggestionsDiv.children[i].dataset.selected) return i;
      }
      return -1;
    }

    formulaInput.addEventListener('keydown', function(ev) {
      if (ev.key === 'Tab') {
        ev.preventDefault();
        var start = formulaInput.selectionStart;
        var end = formulaInput.selectionEnd;
        formulaInput.value = formulaInput.value.substring(0, start) + '    ' + formulaInput.value.substring(end);
        formulaInput.selectionStart = formulaInput.selectionEnd = start + 4;
        formulaInput.dispatchEvent(new Event('input', { bubbles: true }));
        return;
      }
      if (!suggestionsDiv || !suggestionsDiv.classList.contains('show')) return;
      var items = suggestionsDiv.children;
      var selectedIndex = getSelectedSuggestionIndex();
      if (ev.key === 'ArrowDown' || ev.key === 'ArrowUp') {
        ev.preventDefault();
        if (selectedIndex >= 0) {
          delete items[selectedIndex].dataset.selected;
          items[selectedIndex].classList.remove('selected');
        }
        var nextIndex = ev.key === 'ArrowDown' ? (selectedIndex + 1) % items.length : (selectedIndex <= 0 ? items.length - 1 : selectedIndex - 1);
        items[nextIndex].dataset.selected = '1';
        items[nextIndex].classList.add('selected');
        items[nextIndex].scrollIntoView({ block: 'nearest' });
      } else if (ev.key === 'Enter') {
        if (selectedIndex >= 0) {
          ev.preventDefault();
          items[selectedIndex].dispatchEvent(new MouseEvent('mousedown'));
        }
      } else if (ev.key === 'Escape') {
        suggestionsDiv.classList.remove('show');
      }
    });
    formulaInput.addEventListener('blur', function() { setTimeout(function() { if (suggestionsDiv) suggestionsDiv.classList.remove('show'); }, 180); });
    handleInput();
  }

  const saveBtn = $('#measureFormulaApplyBtn');
  if (saveBtn) {
    const newSaveBtn = saveBtn.cloneNode(true);
    saveBtn.parentNode.replaceChild(newSaveBtn, saveBtn);
    newSaveBtn.addEventListener('click', async () => {
      const parsed = parseDaxMeasureDefinition((formulaInput && formulaInput.value) || '', (nameInput && nameInput.value) || '');
      const name = parsed.name;
      const formula = parsed.formula;
      if (!name || !formula) return toast('Informe nome e fórmula da medida.', 'error');
      const duplicateIndex = ((state.model && state.model.measures) || []).findIndex((measure, index) => index !== editIdx && String(measure.name || '').trim().toLowerCase() === name.toLowerCase());
      if (duplicateIndex >= 0) return toast('Já existe uma medida com esse nome.', 'error');
      const formulaErr = validateDaxFormula(formula);
      if (formulaErr) return toast('Fórmula inválida: ' + formulaErr, 'error');
      state.model.measures = state.model.measures || [];
      const usedTables = extractTablesFromDaxFormula(formula);
      const nextMeasure = Object.assign({}, previous || {}, {
        name,
        displayName: previous && previous.displayName && previous.displayName !== previous.name ? previous.displayName : name,
        formula,
        table: usedTables[0] || (previous && previous.table) || currentBuilderTable(),
        tables: usedTables,
        format: formatEl ? formatEl.value : ((previous && previous.format) || ''),
        decimals: decimalsEl ? parseInt(decimalsEl.value) || 0 : ((previous && previous.decimals) || 2),
        dataCategory: categoryEl ? categoryEl.value : ((previous && previous.dataCategory) || ''),
        diagnosticStatus: 'validando',
        lastDiagnostic: '',
        lastValidatedAt: ''
      });
      const draftModel = JSON.parse(JSON.stringify(state.model || {}));
      draftModel.measures = Array.isArray(draftModel.measures) ? draftModel.measures : [];
      if (previous) draftModel.measures[editIdx] = nextMeasure;
      else draftModel.measures.push(nextMeasure);
      setMeasureFormulaValidation('Validando a medida com o mesmo compilador usado pelos visuais…', 'validating');
      newSaveBtn.disabled = true;
      try {
        const validation = await api('/api/model/measures/validate', {
          method: 'POST',
          body: JSON.stringify({ model: draftModel, measureName: name })
        });
        const diagnostic = validation && validation.diagnostic || {};
        nextMeasure.diagnosticStatus = diagnostic.status || 'ok';
        nextMeasure.lastDiagnostic = diagnostic.message || 'Medida válida para execução.';
        nextMeasure.lastValidatedAt = diagnostic.validatedAt || new Date().toISOString();
        setMeasureFormulaValidation('Medida válida. A fórmula foi compilada com sucesso.', 'valid');
      } catch (err) {
        setMeasureFormulaValidation(err.message || 'Não foi possível validar a medida.', 'invalid');
        toast(err.message || 'Não foi possível validar a medida.', 'error');
        return;
      } finally {
        newSaveBtn.disabled = false;
      }
      if (previous) {
        state.model.measures[editIdx] = nextMeasure;
        state.activeMeasureIndex = editIdx;
      } else {
        state.model.measures.push(nextMeasure);
        state.activeMeasureIndex = state.model.measures.length - 1;
      }
      renderBuilderFieldList();
      if (typeof renderMeasureList === 'function') renderMeasureList();
      openDaxMeasureInlineEditor(state.activeMeasureIndex);
      try {
        await saveModel();
        toast((previous ? 'Medida DAX atualizada: ' : 'Medida DAX criada: ') + name, 'success');
      } catch (err) {
        toast(err.message || 'Erro ao salvar modelo.', 'error');
      }
    });
  }

  const cancelBtn = $('#measureFormulaCancelBtn');
  if (cancelBtn) {
    const newCancelBtn = cancelBtn.cloneNode(true);
    cancelBtn.parentNode.replaceChild(newCancelBtn, cancelBtn);
    newCancelBtn.addEventListener('click', closeMeasureToolsRibbon);
  }

  if (formulaInput) {
    formulaInput.focus();
    if (!previous) {
      formulaInput.selectionStart = 0;
      formulaInput.selectionEnd = 'Medida'.length;
    }
  }
}

function openDaxMeasureModal(editIndex) {
  openDaxMeasureInlineEditor(editIndex);
  return;
  const modal = $('#daxMeasureModal');
  if (!modal) return;
  const nameInput = $('#daxMeasureName');
  const tableSelect = $('#daxMeasureTableSelect');
  let formulaInput = $('#daxMeasureFormula');
  const suggestionsDiv = $('#daxMeasureSuggestions');
  if (nameInput) nameInput.value = '';
  populateDaxMeasureTableSelect(currentBuilderTable());
  if (formulaInput) formulaInput.value = '';
  if (suggestionsDiv) suggestionsDiv.classList.remove('show');

  // If editing, pre-fill the fields
  if (editIndex !== undefined && state.model.measures && state.model.measures[editIndex]) {
    var m = state.model.measures[editIndex];
    if (nameInput) nameInput.value = m.name;
    populateDaxMeasureTableSelect(m.table || extractTableFromDaxFormula(m.formula || '') || currentBuilderTable());
    if (formulaInput) formulaInput.value = m.formula || '';
  }
  modal.dataset.editIndex = editIndex !== undefined ? String(editIndex) : '';
  modal.hidden = false;

  // Build table->columns map from resources
  const tableMap = {};
  (state.resources || []).forEach(r => {
    tableMap[r.name] = (state.modelColumnCache && state.modelColumnCache[r.name])
      ? state.modelColumnCache[r.name].map(c => c.name || c)
      : [];
  });
  // Also add model tables that have columns in semantic_model
  if (state.model && state.model.tables) {
    state.model.tables.forEach(t => {
      if (!tableMap[t.name] && t.columns && t.columns.length) {
        tableMap[t.name] = t.columns.map(c => typeof c === 'string' ? c : c.name || c);
      }
    });
  }
  const tableNames = Object.keys(tableMap);

  // Lazy-load columns for a table
  async function ensureColumnsFor(tableName) {
    if (tableMap[tableName] && tableMap[tableName].length) return;
    try {
      const data = await api('/api/tables/' + encodeURIComponent(tableName) + '/columns?ts=' + Date.now());
      const cols = (data.columns || []).map(c => c.name || c);
      tableMap[tableName] = cols;
      if (!state.modelColumnCache) state.modelColumnCache = {};
      state.modelColumnCache[tableName] = normalizeColumnMetadataList(data.columns || []);
    } catch (e) { /* ignore */ }
  }

  function getWordAtCursor(textarea) {
    const pos = textarea.selectionStart;
    const text = textarea.value.substring(0, pos);
    // Check if we're inside brackets: Table[col...
    const bracketMatch = text.match(/(?:'([^']+)'|([A-Za-zÀ-ÿ0-9_ .&-]+))\s*\[\s*([A-Za-zÀ-ÿ0-9_ .&-]*)$/);
    if (bracketMatch) {
      return { type: 'column', table: String(bracketMatch[1] || bracketMatch[2] || '').trim(), partial: bracketMatch[3] || '' };
    }
    // Check for partial word (table name or DAX function)
    const wordMatch = text.match(/([A-Za-zÀ-ÿ0-9_%]+)$/);
    if (wordMatch) {
      return { type: 'word', partial: wordMatch[1] };
    }
    // After opening paren, comma, or operator — show default suggestions
    const afterOpener = text.match(/[\(\,]\s*$/);
    if (afterOpener) {
      return { type: 'word', partial: '' };
    }
    return null;
  }

  function renderSuggestions(items, onPick) {
    if (!suggestionsDiv) return;
    if (!items.length) { suggestionsDiv.classList.remove('show'); return; }
    suggestionsDiv.innerHTML = '';
    suggestionsDiv.classList.add('show');
    items.slice(0, 30).forEach((item, i) => {
      const div = document.createElement('div');
      div.className = 'measure-autocomplete-item' + (i === 0 ? ' selected' : '');
      if (item.type === 'function') {
        div.innerHTML = '<span style="color: #7c3aed; font-weight: 600; font-size: 11px; min-width: 22px;">ƒx</span><span>' + escapeHtml(item.label) + '</span><small style="color:#94a3b8; margin-left:auto;">' + escapeHtml(item.hint || '') + '</small>';
      } else if (item.type === 'table') {
        div.innerHTML = '<span style="color: #0ea5e9; font-size: 11px; min-width: 22px;">▦</span><span>' + escapeHtml(item.label) + '</span><small style="color:#94a3b8; margin-left:auto;">Tabela</small>';
      } else if (item.type === 'measure') {
        div.innerHTML = '<span style="color: #7c3aed; font-weight: 700; font-size: 11px; min-width: 22px;">ƒx</span><span>' + escapeHtml(item.label) + '</span><small style="color:#94a3b8; margin-left:auto;">Medida</small>';
      } else {
        div.innerHTML = '<span style="color: #10b981; font-size: 11px; min-width: 22px;">☰</span><span>' + escapeHtml(item.label) + '</span><small style="color:#94a3b8; margin-left:auto;">Coluna</small>';
      }
      div.addEventListener('mouseenter', () => div.style.background = '#f1f5f9');
      div.addEventListener('mouseleave', () => div.style.background = '');
      div.addEventListener('mousedown', (ev) => { ev.preventDefault(); onPick(item); });
      if (i === 0) div.dataset.selected = '1';
      suggestionsDiv.appendChild(div);
    });
  }

  function insertSuggestion(item) {
    if (!formulaInput) return;
    const pos = formulaInput.selectionStart;
    const text = formulaInput.value;
    const before = text.substring(0, pos);
    const after = text.substring(pos);

    if (item.type === 'column') {
      // Replace partial column name after [
      const bracketMatch = before.match(/(?:'([^']+)'|([A-Za-zÀ-ÿ0-9_ .&-]+))\s*\[\s*([A-Za-zÀ-ÿ0-9_ .&-]*)$/);
      if (bracketMatch) {
        const start = pos - String(bracketMatch[3] || '').length;
        formulaInput.value = text.substring(0, start) + item.label + ']' + after;
        formulaInput.selectionStart = formulaInput.selectionEnd = start + item.label.length + 1;
      }
    } else if (item.type === 'table') {
      const wordMatch = before.match(/([A-Za-zÀ-ÿ0-9_%]+)$/);
      const partial = wordMatch ? wordMatch[1].length : 0;
      const start = pos - partial;
      const insert = daxTableReferenceName(item.label) + '[';
      formulaInput.value = text.substring(0, start) + insert + after;
      formulaInput.selectionStart = formulaInput.selectionEnd = start + insert.length;
      // Trigger column suggestions
      ensureColumnsFor(item.label).then(() => handleInput());
    } else if (item.type === 'measure') {
      const wordMatch = before.match(/([A-Za-zÀ-ÿ0-9_%]+)$/);
      const partial = wordMatch ? wordMatch[1].length : 0;
      const start = pos - partial;
      const insert = '[' + item.label + ']';
      formulaInput.value = text.substring(0, start) + insert + after;
      formulaInput.selectionStart = formulaInput.selectionEnd = start + insert.length;
    } else {
      // DAX function
      const wordMatch = before.match(/([A-Za-zÀ-ÿ0-9_%]+)$/);
      const partial = wordMatch ? wordMatch[1].length : 0;
      const start = pos - partial;
      const insert = item.label + '(';
      formulaInput.value = text.substring(0, start) + insert + after;
      formulaInput.selectionStart = formulaInput.selectionEnd = start + insert.length;
    }
    if (suggestionsDiv) suggestionsDiv.classList.remove('show');
    formulaInput.focus();
    formulaInput.dispatchEvent(new Event('input', { bubbles: true }));
  }

  function handleInput() {
    const ctx = getWordAtCursor(formulaInput);
    if (!ctx) { if (suggestionsDiv) suggestionsDiv.classList.remove('show'); return; }

    if (ctx.type === 'column') {
      const cols = tableMap[ctx.table] || [];
      const partial = (ctx.partial || '').toLowerCase();
      const filtered = cols.filter(c => c.toLowerCase().includes(partial)).map(c => ({ type: 'column', label: c }));
      if (!filtered.length && !partial) {
        // Try to load columns
        ensureColumnsFor(ctx.table).then(() => {
          const cols2 = tableMap[ctx.table] || [];
          const filtered2 = cols2.map(c => ({ type: 'column', label: c }));
          renderSuggestions(filtered2, insertSuggestion);
        });
      } else {
        renderSuggestions(filtered, insertSuggestion);
      }
    } else {
      const partial = ctx.partial.toLowerCase();
      // Mix DAX functions + table names
      let daxMatches = DAX_FUNCTIONS.filter(f => f.toLowerCase().startsWith(partial))
        .map(f => ({ type: 'function', label: f, hint: 'Função DAX' }));
      if (!partial) daxMatches = daxMatches.slice(0, 20);
      const tableMatches = tableNames.filter(t => t.toLowerCase().includes(partial))
        .map(t => ({ type: 'table', label: t }));
      const measureMatches = ((state.model && state.model.measures) || [])
        .filter(function(m) { return String(m.name || '').toLowerCase().includes(partial); })
        .map(function(m) { return { type: 'measure', label: m.name, hint: m.table || '' }; });
      const all = [...measureMatches, ...tableMatches, ...daxMatches];
      renderSuggestions(all, insertSuggestion);
    }
  }

  // Remove old listeners
  if (formulaInput) {
    const formulaValueBeforeClone = formulaInput.value || '';
    const newFormula = formulaInput.cloneNode(true);
    formulaInput.parentNode.replaceChild(newFormula, formulaInput);
    newFormula.value = formulaValueBeforeClone;
    formulaInput = newFormula;
    formulaInput.addEventListener('input', handleInput);
    newFormula.addEventListener('keydown', (ev) => {
      if (!suggestionsDiv || !suggestionsDiv.classList.contains('show')) return;
      const items = suggestionsDiv.children;
      let selIdx = -1;
      for (let i = 0; i < items.length; i++) { if (items[i].dataset.selected) { selIdx = i; break; } }
      if (ev.key === 'ArrowDown') {
        ev.preventDefault();
        if (selIdx >= 0) delete items[selIdx].dataset.selected;
        const next = (selIdx + 1) % items.length;
        items[next].dataset.selected = '1';
        items[next].style.background = '#f1f5f9';
        if (selIdx >= 0) items[selIdx].style.background = '';
        items[next].scrollIntoView({ block: 'nearest' });
      } else if (ev.key === 'ArrowUp') {
        ev.preventDefault();
        if (selIdx >= 0) delete items[selIdx].dataset.selected;
        const prev = selIdx <= 0 ? items.length - 1 : selIdx - 1;
        items[prev].dataset.selected = '1';
        items[prev].style.background = '#f1f5f9';
        if (selIdx >= 0) items[selIdx].style.background = '';
        items[prev].scrollIntoView({ block: 'nearest' });
      } else if (ev.key === 'Tab' || ev.key === 'Enter') {
        if (selIdx >= 0) {
          ev.preventDefault();
          items[selIdx].dispatchEvent(new MouseEvent('mousedown'));
        }
      } else if (ev.key === 'Escape') {
        suggestionsDiv.classList.remove('show');
      }
    });
    newFormula.addEventListener('blur', () => {
      setTimeout(() => { if (suggestionsDiv) suggestionsDiv.classList.remove('show'); }, 200);
    });
    // Syntax highlighting
    const highlightEl = $('#daxMeasureFormulaHighlight');
    if (highlightEl) {
      const doHighlight = () => {
        try {
          var safeHtml = highlightDax(newFormula.value);
          highlightEl.innerHTML = safeHtml;
        } catch (e) {
          highlightEl.innerHTML = String(newFormula.value).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
        }
      };
      newFormula.addEventListener('input', doHighlight);
      newFormula.addEventListener('scroll', () => { highlightEl.scrollTop = newFormula.scrollTop; highlightEl.scrollLeft = newFormula.scrollLeft; });
      doHighlight();
    }
  }

  // Save button
  const saveBtn = $('#daxMeasureSaveBtn');
  if (saveBtn) {
    const newSave = saveBtn.cloneNode(true);
    saveBtn.parentNode.replaceChild(newSave, saveBtn);
    newSave.addEventListener('click', () => {
      const nameVal = ($('#daxMeasureName') || {}).value;
      const formulaVal = ($('#daxMeasureFormula') || {}).value;
      const name = (nameVal || '').trim();
      const formula = (formulaVal || '').trim();
      if (!name || !formula) return toast('Informe nome e fórmula da medida.', 'error');
      var formulaErr = validateDaxFormula(formula);
      if (formulaErr) return toast('Fórmula inválida: ' + formulaErr, 'error');
      state.model.measures = state.model.measures || [];
      var editIdx = modal.dataset.editIndex !== '' ? Number(modal.dataset.editIndex) : -1;
      var usedTables = extractTablesFromDaxFormula(formula);
      var homeTable = (($('#daxMeasureTableSelect') && $('#daxMeasureTableSelect').value) || '').trim() || usedTables[0] || currentBuilderTable();
      var previous = editIdx >= 0 && state.model.measures[editIdx] ? state.model.measures[editIdx] : {};
      var nextMeasure = Object.assign({}, previous, {
        name,
        displayName: previous.displayName || name,
        formula,
        table: homeTable,
        tables: usedTables,
        diagnosticStatus: '',
        lastDiagnostic: ''
      });
      if (editIdx >= 0 && state.model.measures[editIdx]) {
        state.model.measures[editIdx] = nextMeasure;
        toast('Medida DAX atualizada: ' + name);
      } else {
        state.model.measures.push(nextMeasure);
        toast('Medida DAX criada: ' + name);
      }
      modal.hidden = true;
      renderBuilderFieldList();
      if (typeof renderMeasureList === 'function') renderMeasureList();
      saveModel().catch(function(err) { toast(err.message || 'Erro ao salvar modelo.', 'error'); });
    });
  }

  // Format button
  const formatBtn = $('#daxMeasureFormatBtn');
  if (formatBtn) {
    const newFormat = formatBtn.cloneNode(true);
    formatBtn.parentNode.replaceChild(newFormat, formatBtn);
    newFormat.addEventListener('click', () => {
      if (!formulaInput) return;
      const formatted = formatDax(formulaInput.value);
      if (formatted !== formulaInput.value) {
        formulaInput.value = formatted;
        formulaInput.dispatchEvent(new Event('input'));
      }
    });
  }

  if (nameInput) nameInput.focus();
}

function addMeasureTemplate(kind) {
  const name = $('#measureName');
  const formula = $('#measureFormula');
  if (!name || !formula) return;
  if (kind === 'sum') { name.value = name.value || 'Total'; formula.value = 'SUM(tabela[coluna])'; }
  else if (kind === 'ticket') { name.value = name.value || 'Ticket Medio'; formula.value = 'DIVIDE(SUM(vendas[valor_total]), DISTINCTCOUNT(vendas[id_pedido]))'; }
  else if (kind === 'percent') { name.value = name.value || 'Percentual'; formula.value = 'DIVIDE(SUM(vendas[valor]), SUM(vendas[valor_total]))'; }
  else if (kind === 'rank') { name.value = name.value || 'Ranking Produto'; formula.value = 'RANKX(ALL(produtos[produto]), SUM(vendas[valor]))'; }
  else if (kind === 'ytd') { name.value = name.value || 'Vendas YTD'; formula.value = 'CALCULATE(SUM(vendas[valor]), DATESYTD(Calendario[data]))'; }
  else if (kind === 'calc') { name.value = name.value || 'Vendas Filtradas'; formula.value = "CALCULATE(SUM(vendas[valor]), FILTER(vendas, vendas[status] = \"concluido\"))"; }
  else if (kind === 'concat') { name.value = name.value || 'Produto Categoria'; formula.value = 'CONCATENATE(CONCATENATE(produtos[produto], " - "), produtos[categoria])'; }
  else { name.value = name.value || 'Quantidade'; formula.value = 'COUNTROWS(tabela)'; }
  formula.focus();
}

function addMeasure() {
  const nameEl = $('#measureName');
  const formulaEl = $('#measureFormula');
  if (!nameEl || !formulaEl) return toast('Erro ao acessar os campos da medida. Recarregue a pagina.', 'error');
  const name = nameEl.value.trim();
  const formula = formulaEl.value.trim();
  if (!name || !formula) return toast('Informe nome e formula da medida.', 'error');
  var formulaErr = validateDaxFormula(formula);
  if (formulaErr) return toast('Fórmula inválida: ' + formulaErr, 'error');
  state.model.measures = state.model.measures || [];
  var usedTables = extractTablesFromDaxFormula(formula);
  state.model.measures.push({ name, displayName: name, formula, table: usedTables[0] || currentBuilderTable(), tables: usedTables });
  $('#measureName').value = '';
  $('#measureFormula').value = '';
  renderMeasureList();
  saveModel().catch(function(err) { toast(err.message || 'Erro ao salvar modelo.', 'error'); });
}

function highlightDax(text) {
  if (!text) return '';
  try {
    const esc = (s) => String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
    const daxSet = new Set(DAX_FUNCTIONS.map(f => f.toUpperCase()));
    const keywords = new Set(['IN','AND','OR','NOT','TRUE','FALSE','BLANK','LIKE']);
    const parts = [];
    const re = /\/\/[^\n]*|\/\*[\s\S]*?\*\/|"(?:[^"\\]|\\.)*"|'[A-Za-z_À-ÿ][\wÀ-ÿ.]*'|\[[\wÀ-ÿ.\s]+\]|\b\d+(?:\.\d+)?\b|\b[A-Z][A-Z_0-9]{2,}\b|[\s\S]/g;
    let m;
    while ((m = re.exec(text)) !== null) {
      const t = m[0];
      if (t.startsWith('//') || t.startsWith('/*')) {
        parts.push('<span style="color:#4b5563;font-style:italic">' + esc(t) + '</span>');
      } else if (t.startsWith('"') && t.endsWith('"')) {
        parts.push('<span style="color:#b91c1c;font-weight:600">' + esc(t) + '</span>');
      } else if (t.startsWith("'") && t.endsWith("'")) {
        parts.push('<span style="color:#0e7490;font-weight:700">' + esc(t) + '</span>');
      } else if (t.startsWith('[') && t.endsWith(']')) {
        parts.push('<span style="color:#047857;font-weight:600">' + esc(t) + '</span>');
      } else if (/^\d/.test(t)) {
        parts.push('<span style="color:#b45309;font-weight:600">' + esc(t) + '</span>');
      } else if (keywords.has(t.toUpperCase())) {
        parts.push('<span style="color:#6d28d9;font-weight:700">' + esc(t) + '</span>');
      } else if (/^[A-Z]/.test(t) && daxSet.has(t.toUpperCase())) {
        parts.push('<span style="color:#1e40af;font-weight:700">' + esc(t) + '</span>');
      } else {
        parts.push(esc(t));
      }
    }
    return parts.join('');
  } catch (e) {
    return String(text).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
  }
}
window.highlightDax = highlightDax;

function setupMeasureAutocomplete() {
  const input = $('#measureFormula');
  const list = $('#measureAutocomplete');
  if (!input || !list) return;
  if (input.dataset.autocompleteBound) return;
  input.dataset.autocompleteBound = '1';
  let selectedIdx = -1;

  updateHighlight();
  input.addEventListener('scroll', () => {
    const hl = $('#measureFormulaHighlight');
    if (hl) { hl.scrollTop = input.scrollTop; hl.scrollLeft = input.scrollLeft; }
  });

  function tableNames() {
    return (state.resources || []).map(r => r.name).filter(Boolean);
  }

  function measureNames() {
    return (state.model.measures || []).map(m => m.name).filter(Boolean);
  }

  async function columnNames(table) {
    const clean = String(table).replace(/^['"]|['"]$/g, '').trim();
    const res = (state.resources || []).find(r => r.name === clean);
    if (res && Array.isArray(res.columns)) return res.columns.map(c => c.name || c);
    if (state.modelColumnCache && state.modelColumnCache[clean]) return state.modelColumnCache[clean].map(c => c.name || c);
    try {
      const data = await api('/api/tables/' + encodeURIComponent(clean) + '/columns?ts=' + Date.now());
      const cols = (data.columns || []).map(c => c.name || c);
      if (!state.modelColumnCache) state.modelColumnCache = {};
      state.modelColumnCache[clean] = normalizeColumnMetadataList(data.columns || []);
      return cols;
    } catch (_) { return []; }
  }

  function getWordBeforeCursor() {
    const val = input.value;
    const pos = input.selectionStart || 0;
    const before = val.slice(0, pos);
    const match = before.match(/[a-zA-Z_À-ÿ][\wÀ-ÿ.'"[\]]*$/);
    return match ? match[0] : '';
  }

  function getContext() {
    const val = input.value;
    const pos = input.selectionStart || 0;
    const before = val.slice(0, pos);
    const bracket = before.lastIndexOf('[');
    const quote = before.lastIndexOf("'");
    const paren = before.lastIndexOf('(');
    const comma = before.lastIndexOf(',');
    const lastOp = Math.max(quote, paren, comma, before.lastIndexOf(' '));
    const word = getWordBeforeCursor();

    if (bracket > -1 && bracket > lastOp && word.endsWith(']') === false) {
      const openQuote = before.lastIndexOf("'", bracket);
      const tablePart = openQuote > -1 ? before.slice(openQuote + 1, bracket) : before.slice(0, bracket).split(/[\(\,\s]/).pop() || '';
      return { type: 'column', table: tablePart.replace(/^['"]|['"]$/g, '').trim(), word: word.replace(/.*\[/, '') };
    }
    if (quote > -1 && quote > lastOp) {
      const closeQuote = before.indexOf("'", quote + 1);
      if (closeQuote === -1 || closeQuote >= pos) {
        return { type: 'table', word: before.slice(quote + 1) };
      }
    }
    return { type: 'function', word: word };
  }

  function renderSuggestions(items, type) {
    list.innerHTML = '';
    if (!items.length) { list.classList.remove('show'); return; }
    items.forEach((item, idx) => {
      const div = document.createElement('div');
      div.className = 'measure-autocomplete-item' + (idx === 0 ? ' selected' : '');
      div.dataset.index = idx;
      div.dataset.type = type;
      div.textContent = type === 'function' ? item + '()' : item;
      if (type === 'function') {
        const s = document.createElement('small');
        s.textContent = 'função DAX';
        div.appendChild(s);
      } else if (type === 'table') {
        const s = document.createElement('small');
        s.textContent = 'tabela';
        div.appendChild(s);
      } else if (type === 'column') {
        const s = document.createElement('small');
        s.textContent = 'coluna';
        div.appendChild(s);
      } else if (type === 'measure') {
        const s = document.createElement('small');
        s.textContent = 'medida';
        div.appendChild(s);
      }
      div.addEventListener('click', () => insertSuggestion(item, type));
      div.addEventListener('mouseenter', () => {
        list.querySelectorAll('.selected').forEach(el => el.classList.remove('selected'));
        div.classList.add('selected');
        selectedIdx = idx;
      });
      list.appendChild(div);
    });
    selectedIdx = 0;
    list.classList.add('show');
  }

  function insertSuggestion(item, type) {
    const val = input.value;
    const pos = input.selectionStart || 0;
    const before = val.slice(0, pos);
    const after = val.slice(pos);
    const ctx = getContext();

    if (type === 'table') {
      const quoteIdx = before.lastIndexOf("'");
      const newBefore = before.slice(0, quoteIdx + 1) + item;
      const rest = after;
      const cursor = newBefore.length + 1;
      input.value = newBefore + "'" + rest;
      input.setSelectionRange(cursor, cursor);
    } else if (type === 'column') {
      const bracketIdx = before.lastIndexOf('[');
      const word = ctx.word;
      const newBefore = word.length ? before.slice(0, -word.length) + item : before + item;
      const rest = after;
      const cursor = newBefore.length + 1;
      input.value = newBefore + "]" + rest;
      input.setSelectionRange(cursor, cursor);
    } else if (type === 'function') {
      const word = ctx.word;
      const newBefore = word.length ? before.slice(0, -word.length) + item : before + item;
      input.value = newBefore + "(" + after;
      input.setSelectionRange(newBefore.length + 1, newBefore.length + 1);
    } else if (type === 'measure') {
      const word = ctx.word;
      const newBefore = word.length ? before.slice(0, -word.length) + "[" + item + "]" : before + "[" + item + "]";
      input.value = newBefore + after;
      input.setSelectionRange(newBefore.length, newBefore.length);
    }
    list.classList.remove('show');
    input.focus();
    updateHighlight();
  }

  function updateHighlight() {
    const highlight = $('#measureFormulaHighlight');
    if (highlight) {
      try {
        var safeHtml = window.highlightDax(input.value);
        highlight.innerHTML = safeHtml + '<br>';
      } catch (e) {
        highlight.innerHTML = String(input.value).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;') + '<br>';
      }
    }
  }

  input.addEventListener('input', async () => {
    updateHighlight();
    const ctx = getContext();
    const word = ctx.word.toLowerCase();

    if (ctx.type === 'table') {
      const names = tableNames();
      const filtered = names.filter(n => n.toLowerCase().includes(word));
      renderSuggestions(filtered, 'table');
    } else if (ctx.type === 'column') {
      const cols = await columnNames(ctx.table);
      const filtered = cols.filter(c => String(c).toLowerCase().includes(word));
      renderSuggestions(filtered, 'column');
    } else {
      const funcs = DAX_FUNCTIONS.filter(f => f.toLowerCase().includes(word));
      const measures = measureNames().filter(m => m.toLowerCase().includes(word));
      const tables = tableNames().filter(n => n.toLowerCase().includes(word));
      const all = [
        ...funcs.map(f => ({ name: f, type: 'function' })),
        ...measures.map(m => ({ name: m, type: 'measure' })),
        ...tables.map(t => ({ name: t, type: 'table' }))
      ];
      if (!word && all.length > 50) {
        renderSuggestions(DAX_FUNCTIONS.slice(0, 20).map(f => ({ name: f, type: 'function' })), 'function');
        return;
      }
      list.innerHTML = '';
      if (!all.length) { list.classList.remove('show'); return; }
      all.forEach((item, idx) => {
        const div = document.createElement('div');
        div.className = 'measure-autocomplete-item' + (idx === 0 ? ' selected' : '');
        div.dataset.index = idx;
        div.dataset.type = item.type;
        div.textContent = item.type === 'function' ? item.name + '()' : item.name;
        const s = document.createElement('small');
        s.textContent = item.type === 'function' ? 'função DAX' : item.type === 'measure' ? 'medida' : 'tabela';
        div.appendChild(s);
        div.addEventListener('click', () => insertSuggestion(item.name, item.type));
        div.addEventListener('mouseenter', () => {
          list.querySelectorAll('.selected').forEach(el => el.classList.remove('selected'));
          div.classList.add('selected');
          selectedIdx = idx;
        });
        list.appendChild(div);
      });
      selectedIdx = 0;
      list.classList.add('show');
    }
  });

  input.addEventListener('keydown', (ev) => {
    const items = list.querySelectorAll('.measure-autocomplete-item');
    if (!items.length || !list.classList.contains('show')) return;
    if (ev.key === 'ArrowDown') {
      ev.preventDefault();
      selectedIdx = Math.min(selectedIdx + 1, items.length - 1);
      items.forEach((el, idx) => el.classList.toggle('selected', idx === selectedIdx));
      if (items[selectedIdx]) items[selectedIdx].scrollIntoView({ block: 'nearest' });
    } else if (ev.key === 'ArrowUp') {
      ev.preventDefault();
      selectedIdx = Math.max(selectedIdx - 1, 0);
      items.forEach((el, idx) => el.classList.toggle('selected', idx === selectedIdx));
      if (items[selectedIdx]) items[selectedIdx].scrollIntoView({ block: 'nearest' });
    } else if (ev.key === 'Enter' || ev.key === 'Tab') {
      const selected = items[selectedIdx];
      if (selected) {
        ev.preventDefault();
        selected.click();
      }
    } else if (ev.key === 'Escape') {
      list.classList.remove('show');
    }
  });

  input.addEventListener('blur', () => {
    setTimeout(() => list.classList.remove('show'), 200);
  });
}

async function saveModel() {
  const data = await api('/api/model', {
    method: 'PUT',
    body: JSON.stringify({ model: state.model })
  });
  state.model = data.model || state.model;
  renderModelDesigner();
  if (data.warnings && data.warnings.length) {
    toast('Modelo salvo com avisos: ' + data.warnings.join('; '));
  } else {
    toast('Modelo salvo.');
  }
}

async function previewModel() {
  const data = await api('/api/model/preview', {
    method: 'POST',
    body: JSON.stringify({ model: state.model, limit: 200 })
  });
  state.modelPreviewRows = data.rows || [];
  var rows = state.modelPreviewRows;
  if (!rows.length) {
    toast('Nenhuma linha retornada pela prévia.', 'error');
    return;
  }
  var cols = Object.keys(rows[0] || {});
  var header = '<tr>' + cols.map(function(c) { return '<th>' + escapeHtml(c) + '</th>'; }).join('') + '</tr>';
  var body = rows.map(function(r) {
    return '<tr>' + cols.map(function(c) {
      var v = r[c];
      return '<td>' + escapeHtml(v != null ? String(v) : '') + '</td>';
    }).join('') + '</tr>';
  }).join('');
  var html = '<div style="margin-bottom:12px;display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:8px">' +
    '<span style="font-size:13px;font-weight:600">' + rows.length + ' linha(s) geradas pelo modelo</span>' +
    (rows.length ? '<button class="btn mini ghost" id="exportModelPreviewCsvBtn">Exportar CSV</button>' : '') +
    '</div>' +
    '<div style="max-height:65vh;overflow:auto;border:1px solid var(--line);border-radius:12px">' +
    '<table class="result-table" style="width:100%;border-collapse:collapse"><thead>' + header + '</thead><tbody>' + body + '</tbody></table>' +
    '</div>';
  var overlay = showSimpleModal(html, 'Prévia do modelo');
  overlay.className += ' model-preview-modal';
  var exportBtn = overlay.querySelector('#exportModelPreviewCsvBtn');
  if (exportBtn) exportBtn.addEventListener('click', function() { downloadCsv('modelo_bi_wa.csv', state.modelPreviewRows); });
  if (data.sql) state.lastModelSql = data.sql;
}

async function modelToSqlEditor() {
  const data = await api('/api/model/sql', {
    method: 'POST',
    body: JSON.stringify({ model: state.model, limit: DEFAULT_REPORT_LIMIT })
  });
  setActiveTab('sqlTab');
  if ($('#sqlEditor')) $('#sqlEditor').value = data.sql || '';
  if ($('#reportName') && !$('#reportName').value) $('#reportName').value = 'Relatorio do modelo BI WA';
  toast('SQL gerado no editor. Revise e salve o relatorio.');
}

function clearModel() {
  state.model = { tables: [], tablePositions: {}, selectedColumns: [], relationships: [], measures: [] };
  state.modelPreviewRows = [];
  renderModelDesigner();
}


async function ensureNativeCalendar() {
  const currentYear = new Date().getFullYear();
  const startYear = Math.max(2000, currentYear - 8);
  const endYear = currentYear + 8;
  const data = await api('/api/native/calendar/ensure', {
    method: 'POST',
    body: JSON.stringify({ startYear, endYear })
  });
  toast(data.message || 'Calendario criado/atualizado.');
  await loadTables();
  ensureModelTablesArray();
  if (!state.model.tables.some((item) => (typeof item === 'string' ? item : item.name) === 'Calendario')) {
    state.model.tables.push({ name: 'Calendario' });
  }
  renderTablesList();
  renderBuilderFields();
  renderConnectionsDesigner();
  toast('Calendario nativo disponível para relacionamentos por data.');
}


function renderTransformSourceSelect() {
  const select = $('#transformSourceSelect');
  if (!select) return;
  const previous = select.value || state.transform.source || '';
  const resources = (state.resources || []).filter((item) => item.source !== 'native' || item.name === 'Calendario');
  select.innerHTML = resources.length
    ? resources.map((item) => `<option value="${escapeHtml(item.name)}" ${item.name === previous ? 'selected' : ''}>${escapeHtml(item.name)} - ${escapeHtml(resourceBadge(item))}</option>`).join('')
    : '<option value="">Nenhuma tabela/view carregada</option>';
  if (previous && resources.some((item) => item.name === previous)) select.value = previous;
  state.transform.source = select.value || '';
  state.transform.steps = savedTransformStepsForSource(state.transform.source);
}

function savedTransformStepsForSource(source) {
  const imported = (state.importedTables || []).find((item) => item.name === source);
  const calculated = imported ? null : (state.transforms || []).find((item) => item.name === source && item.daxExpression);
  const steps = (imported || calculated) && Array.isArray((imported || calculated).steps) ? (imported || calculated).steps : [];
  return JSON.parse(JSON.stringify(steps));
}

function transformStepLabel(step) {
  const k = step.kind;
  if (k === 'selectColumns') return 'Colunas selecionadas: ' + (step.columns || []).join(', ');
  if (k === 'removeColumns') return 'Colunas removidas: ' + (step.columns || []).join(', ');
  if (k === 'renameColumn') return `Coluna renomeada: ${step.column} → ${step.newName}`;
  if (k === 'changeType') {
    var typeLabel = FORMAT_DATA_TYPE_LABELS[normalizeDataType(step.dataType)] || step.dataType;
    var formatInfo = step.format ? ' [' + step.format + ']' : '';
    return 'Tipo alterado: ' + step.column + ' = ' + typeLabel + formatInfo;
  }
  if (k === 'filterRows') {
    const values = String(step.value || '').split(',').map((v) => v.trim()).filter(Boolean);
    const valDisplay = values.length > 3 ? values.slice(0, 3).join(', ') + ' +' + (values.length - 3) + ' mais' : (step.value || '');
    return `Filtro: ${step.column} = ${valDisplay || '(sem valor)'}`;
  }
  if (k === 'filterDate') {
    return `Filtro de data: ${step.column} (${step.value || '...'} a ${step.value2 || '...'})`;
  }
  if (k === 'sortRows') return `Linhas ordenadas: ${step.column} ${step.direction || 'ASC'}`;
  if (k === 'replaceValues') return `Valor substituído: ${step.column} (${step.from} → ${step.to})`;
  if (k === 'fillValues') return `Vazios preenchidos: ${step.column} = ${step.value || ''}`;
  if (k === 'duplicateColumn') return `Coluna duplicada: ${step.column} → ${step.newName || 'Cópia'}`;
  if (k === 'splitColumn') return `Coluna dividida: ${step.column} por "${step.delimiter || ''}"`;
  if (k === 'formatText') return `Texto formatado: ${step.column} (${step.format || 'trim'})`;
  if (k === 'groupBy') return `Agrupado por: ${(step.groupColumns || step.columns || []).join(', ')}${(step.aggregations || []).length ? ' | ' + step.aggregations.map((a) => (a.func || 'SUM') + '(' + a.column + ') → ' + a.newName).join(', ') : ''}`;
  if (k === 'removeDuplicates') return 'Duplicados removidos' + ((step.columns || []).length ? ': ' + step.columns.join(', ') : '');
  if (k === 'mergeQueries') return `Consultas mescladas: ${step.source || 'outra consulta'} (${step.leftColumn || '?'} = ${step.rightColumn || '?'})`;
  if (k === 'appendQueries') return `Consulta acrescentada: ${step.source || 'outra consulta'}`;
  if (k === 'customColumn') return `Coluna personalizada: ${step.newName || step.column || 'nova coluna'} = ${step.expression || ''}`;
  if (k === 'daxColumn') return `Coluna DAX: ${step.newName || 'nova coluna'} = ${String(step.expression || '').replace(/^[^=]+=/, '').trim()}`;
  if (k === 'conditionalColumn') return `Coluna condicional: ${step.newName || 'nova coluna'} se ${step.column || '?'} ${step.operator || '='} ${step.value || ''}`;
  return k;
}

function transformStepIcon(kind) {
  const icons = {
    selectColumns: '▣', removeColumns: '−', renameColumn: '✎', changeType: 'T',
    filterRows: '⌕', filterDate: '📅', sortRows: '↕', replaceValues: '⇄', fillValues: '∅', duplicateColumn: '⧉', splitColumn: '⇤', formatText: 'Aa', groupBy: 'Σ', removeDuplicates: '◇', mergeQueries: '🔗', appendQueries: '➕', customColumn: 'ƒx', daxColumn: 'DAX', conditionalColumn: 'IF'
  };
  return icons[kind] || '•';
}

function renderTransformSteps() {
  const list = $('#transformStepsList');
  if (!list) return;
  const steps = state.transform.steps || [];
  const selected = state.transform.selectedStepIndex;
  const source = ($('#transformSourceSelect') && $('#transformSourceSelect').value) || state.transform.source || 'Fonte nao selecionada';
  list.className = 'steps-list';
  // Fonte
  let html = `<div class="step-compact ${selected === -1 ? 'selected' : ''}"><span class="step-compact-label">Fonte: <b>${escapeHtml(source)}</b></span><button type="button" class="step-compact-btn" data-preview-transform-source="1">Prévia</button></div>`;
  // Mostra filtro ativo da tabela (rowFilter) como etapa fixa
  const importedItem = (state.importedTables || []).find((t) => t.name === source);
  if (state.transform.previewTriggered && importedItem) {
    if (importedItem.rowFilter && importedItem.rowFilter.column && importedItem.rowFilter.values && importedItem.rowFilter.values.length) {
      const rf = importedItem.rowFilter;
      html += `<div class="step-compact" style="background:#eef5ff;border-color:#bcd0ea">
        <span class="step-compact-icon" style="color:#174ea6">⌕</span>
        <span class="step-compact-label" style="color:#174ea6">Filtro: <b>${escapeHtml(rf.column)}</b> (${rf.values.length} valor(es))</span>
        <button type="button" class="step-compact-btn danger" data-remove-row-filter title="Remover filtro">×</button>
      </div>`;
    }
    if (importedItem.dateFilter && importedItem.dateFilter.column) {
      const df = importedItem.dateFilter;
      html += `<div class="step-compact" style="background:#eef5ff;border-color:#bcd0ea">
        <span class="step-compact-icon" style="color:#174ea6">📅</span>
        <span class="step-compact-label" style="color:#174ea6">Filtro de Data: <b>${escapeHtml(df.column)}</b> (${escapeHtml(df.start || '...')} a ${escapeHtml(df.end || '...')})</span>
        <button type="button" class="step-compact-btn danger" data-remove-date-filter title="Remover filtro de data">×</button>
      </div>`;
    }
  }
  // Filtra etapas de formatação (changeType) - vão apenas para o histórico
  const nonFormatSteps = [];
  steps.forEach((step, idx) => {
    if (step.kind === 'changeType') return;
    nonFormatSteps.push({ step, idx });
  });
  if (!nonFormatSteps.length) {
    html += '<div class="empty-state small" style="padding:12px">Nenhuma etapa aplicada. Use as abas do painel superior para filtrar, ordenar e modelar os dados.</div>';
  } else {
    html += `<div class="step-compact-section">${nonFormatSteps.length} etapa(s) aplicada(s)</div>`;
    nonFormatSteps.forEach(({ step, idx }) => {
      const label = transformStepLabel(step);
      const icon = transformStepIcon(step.kind);
      html += `<div class="step-compact ${selected === idx ? 'selected' : ''}">
        <span class="step-compact-icon">${escapeHtml(icon)}</span>
        <span class="step-compact-label">${escapeHtml(label)}</span>
        <button type="button" class="step-compact-btn" data-preview-transform-step="${idx}" title="Ver prévia">Prévia</button>
        <button type="button" class="step-compact-btn" data-edit-transform-step="${idx}" title="Editar">✎</button>
        <button type="button" class="step-compact-btn danger" data-remove-transform-step="${idx}" title="Remover">×</button>
      </div>`;
    });
  }
  list.innerHTML = html;
  // Event bindings
  list.querySelectorAll('[data-preview-transform-source]').forEach((btn) => btn.addEventListener('click', () => {
    state.transform.selectedStepIndex = -1;
    renderTransformSteps();
    previewTransform({ stepIndex: -1 }).catch((err) => toast(err.message, 'error'));
  }));
  list.querySelectorAll('[data-preview-transform-step]').forEach((btn) => btn.addEventListener('click', () => {
    state.transform.selectedStepIndex = Number(btn.dataset.previewTransformStep);
    renderTransformSteps();
    previewTransform({ stepIndex: state.transform.selectedStepIndex }).catch((err) => toast(err.message, 'error'));
  }));
  list.querySelectorAll('[data-remove-transform-step]').forEach((btn) => btn.addEventListener('click', () => {
    const idx = Number(btn.dataset.removeTransformStep);
    state.transform.steps.splice(idx, 1);
    if (typeof state.transform.selectedStepIndex === 'number' && state.transform.selectedStepIndex >= state.transform.steps.length) state.transform.selectedStepIndex = null;
    renderTransformSteps();
    previewTransform().catch((err) => toast(err.message, 'error'));
  }));
  list.querySelectorAll('[data-edit-transform-step]').forEach((btn) => btn.addEventListener('click', () => {
    openTransformStepModal(state.transform.steps[Number(btn.dataset.editTransformStep)].kind, Number(btn.dataset.editTransformStep));
  }));
  // Duplo clique na etapa para editar
  list.querySelectorAll('.step-compact').forEach((el) => {
    const editBtn = el.querySelector('[data-edit-transform-step]');
    if (editBtn) {
      el.addEventListener('dblclick', (e) => {
        if (e.target.closest('button')) return;
        editBtn.click();
      });
    }
  });
  // Handler para remover rowFilter
  list.querySelectorAll('[data-remove-row-filter]').forEach((btn) => btn.addEventListener('click', async () => {
    const item = (state.importedTables || []).find((t) => t.name === source);
    if (!item) return;
    await api('/api/imported-tables/' + encodeURIComponent(item.name), { method: 'PUT', body: JSON.stringify({ sourceTable: item.sourceTable, name: item.name, rowFilter: null }) });
    toast('Filtro removido da tabela ' + item.name);
    await loadImportedTables();
    await loadTables();
    renderTransformSteps();
  }));
  // Duplo clique na etapa de filtro para editar
  list.querySelectorAll('[data-remove-row-filter]').forEach((btn) => {
    const el = btn.closest('.step-compact');
    if (el) el.addEventListener('dblclick', (e) => {
      if (e.target.closest('button')) return;
      const item = (state.importedTables || []).find((t) => t.name === source);
      if (item) openImportedTableFilterModal(item.name);
    });
  });
}

function renderSavedTransforms() {
  const el = $('#savedTransformsList');
  if (!el) return;
  if (!state.transforms.length) {
    el.className = 'steps-list empty-state';
    el.textContent = 'Nenhuma consulta salva.';
    return;
  }
  el.className = 'steps-list';
  el.innerHTML = state.transforms.map((item) => {
    const calculatedDax = Boolean(item.daxExpression);
    return `
      <div class="step-item saved-transform-item">
        <button type="button" class="step-title" ${calculatedDax ? 'data-edit-dax-transform' : 'data-load-transform'}="${escapeHtml(item.id)}"><b>${escapeHtml(item.name)}</b><br><small>${calculatedDax ? 'DAX • Tabela calculada' : 'Origem: ' + escapeHtml(item.source)}</small></button>
        ${calculatedDax ? `<button type="button" class="btn mini ghost" data-edit-dax-transform="${escapeHtml(item.id)}">Editar</button>` : ''}
        <button type="button" class="icon-btn" data-delete-transform="${escapeHtml(item.id)}" title="Excluir consulta">×</button>
      </div>`;
  }).join('');
  el.querySelectorAll('[data-edit-dax-transform]').forEach((btn) => btn.addEventListener('click', () => {
    const item = state.transforms.find((transform) => transform.id === btn.dataset.editDaxTransform);
    if (item) openNovaTabelaModal(item);
  }));
  el.querySelectorAll('[data-load-transform]').forEach((btn) => btn.addEventListener('click', () => {
    const item = state.transforms.find((t) => t.id === btn.dataset.loadTransform);
    if (!item) return;
    state.transform = { ...state.transform, id: item.id, name: item.name.replace(/^PQ:\s*/i, ''), source: item.source, steps: Array.isArray(item.steps) ? JSON.parse(JSON.stringify(item.steps)) : [], rows: [], sql: '', fields: [], selectedStepIndex: null, previewMode: 'full' };
    renderTransformSourceSelect();
    $('#transformSourceSelect').value = state.transform.source;
    renderTransformSteps();
    previewTransform().catch((err) => toast(err.message, 'error'));
  }));
  el.querySelectorAll('[data-delete-transform]').forEach((btn) => btn.addEventListener('click', async () => {
    if (!confirm('Excluir esta consulta transformada?')) return;
    await api('/api/transforms/' + encodeURIComponent(btn.dataset.deleteTransform), { method: 'DELETE' });
    await loadTransforms();
    await loadTables();
  }));
}

async function loadTransforms() {
  if (isOnlineMode()) return;
  const data = await api('/api/transforms?ts=' + Date.now());
  state.transforms = data.transforms || [];
  renderSavedTransforms();
}

function currentTransformPayload(options = {}) {
  let steps = state.transform.steps || [];
  if (typeof options.stepIndex === 'number') {
    if (options.stepIndex < 0) steps = [];
    else steps = steps.slice(0, options.stepIndex + 1);
  }
  return {
    id: state.transform.id || undefined,
    name: state.transform.name || 'Consulta',
    source: ($('#transformSourceSelect') && $('#transformSourceSelect').value) || state.transform.source,
    steps,
    limit: Number(($('#transformLimit') && $('#transformLimit').value) || 200)
  };
}

async function previewTransform(options = {}) {
  const payload = currentTransformPayload(options);
  if (!payload.source) throw new Error('Escolha uma tabela/view origem.');
  const meta = $('#transformMeta');
  const preview = $('#transformPreview');
  const stepLabel = typeof options.stepIndex === 'number'
    ? (options.stepIndex < 0 ? 'Fonte' : `Etapa ${options.stepIndex + 1}`)
    : 'Resultado final';
  if (meta) meta.textContent = `atualizando... ${stepLabel}`;
  if (preview) { preview.innerHTML = `<div class="empty-state">Aplicando prévia: ${escapeHtml(stepLabel)}...</div>`; preview.classList.remove('empty-state'); }
  const data = await api('/api/transforms/preview', { method: 'POST', body: JSON.stringify(payload), timeoutMs: 20000 });
  state.transform.rows = data.rows || [];
  state.transform.fields = data.fields || [];
  state.transform.sql = data.sql || '';
  if ($('#transformSqlPreview')) $('#transformSqlPreview').value = state.transform.sql;
  if (meta) meta.textContent = `${stepLabel} | ${state.transform.rows.length} linha(s) | ${state.transform.fields.length} coluna(s) | engine: ${data.cacheEngine || 'mysql'}`;
  if (preview) {
    if (state.transform.rows.length) {
      var columnFormats = data.columnFormats && typeof data.columnFormats === 'object' && !Array.isArray(data.columnFormats) && Object.keys(data.columnFormats).length ? data.columnFormats : null;
      var transformVisual = { preserveRawFormatting: !columnFormats };
      if (columnFormats) transformVisual.columnFormats = columnFormats;
      preview.innerHTML = tableHtml(state.transform.rows, transformVisual);
      preview.classList.remove('empty-state');
    } else {
      const msg = data.message || 'Sem linhas para mostrar.';
      preview.innerHTML = `<div class="empty-state">${escapeHtml(msg)}</div>`;
      preview.classList.remove('empty-state');
    }
  }
  // Revela filtro ativo na barra de etapas apos a primeira previa
  if (!state.transform.previewTriggered) {
    state.transform.previewTriggered = true;
    renderTransformSteps();
  }
}


async function saveTransform() {
  const source = ($('#transformSourceSelect') && $('#transformSourceSelect').value) || state.transform.source;
  const isCalendar = source === 'Calendario';
  const item = isCalendar ? { name: 'Calendario', sourceTable: 'Calendario', note: '', rowFilter: null, dateFilter: null } : (state.importedTables || []).find((t) => t.name === source);
  const calculated = item ? null : (state.transforms || []).find((transform) => transform.name === source && transform.daxExpression);
  if (!item && !calculated) return toast('Selecione uma tabela importada ou calculada DAX para aplicar etapas.', 'error');
  const steps = state.transform.steps || [];
  const savedItem = item || calculated;
  if (!steps.length && !(Array.isArray(savedItem.steps) && savedItem.steps.length)) return toast('Adicione pelo menos uma etapa antes de salvar.', 'error');
  if (calculated) {
    const data = await api('/api/transforms', {
      method: 'POST',
      body: JSON.stringify({ ...calculated, steps })
    });
    toast('Etapas aplicadas na tabela ' + calculated.name + ' (' + steps.length + ' etapa(s))');
    invalidateModelColumnCache(calculated.name, source);
    await loadTransforms();
    await loadTables();
    state.transform.steps = data.transform && Array.isArray(data.transform.steps) ? JSON.parse(JSON.stringify(data.transform.steps)) : savedTransformStepsForSource(source);
    state.transform.id = '';
    state.transform.name = '';
    renderTransformSteps();
    const builderTable = ($('#builderTableSelect') && $('#builderTableSelect').value) || '';
    if (builderTable === source) {
      await loadBuilderColumns(builderTable);
      scheduleVisualAutoUpdate('transform-save');
    }
    return;
  }
  const payload = {
    sourceTable: item.sourceTable,
    name: item.name,
    note: item.note || '',
    rowFilter: item.rowFilter || null,
    dateFilter: item.dateFilter || null,
    steps
  };
  await api('/api/imported-tables/' + encodeURIComponent(item.name), {
    method: 'PUT',
    body: JSON.stringify(payload)
  });
  toast('Etapas aplicadas na tabela ' + item.name + ' (' + steps.length + ' etapa(s))');
  invalidateModelColumnCache(item.name, item.sourceTable, source);
  // Remove consultas transformadas antigas que usam esta tabela como origem
  const oldTransforms = (state.transforms || []).filter((t) => t.source === item.name);
  for (const t of oldTransforms) {
    try { await api('/api/transforms/' + encodeURIComponent(t.id || t.name), { method: 'DELETE' }); } catch (e) { /* ignora */ }
  }
  await loadImportedTables();
  await loadTransforms();
  await loadTables();
  // Recarrega steps da tabela recem-salva para manter no editor
  const updatedItem = (state.importedTables || []).find((t) => t.name === source);
  state.transform.steps = (updatedItem && Array.isArray(updatedItem.steps)) ? updatedItem.steps.slice() : [];
  state.transform.id = '';
  state.transform.name = '';
  renderTransformSteps();
  const builderTable = ($('#builderTableSelect') && $('#builderTableSelect').value) || '';
  if (builderTable === source || builderTable === item.name) {
    await loadBuilderColumns(builderTable);
    scheduleVisualAutoUpdate('transform-save');
  }
}

function clearTransformEditor() {
  state.transform = { id: '', name: '', source: ($('#transformSourceSelect') && $('#transformSourceSelect').value) || '', steps: [], rows: [], sql: '', fields: [], editingStep: null, selectedStepIndex: null, previewMode: 'full', previewTriggered: false };
  if ($('#transformSqlPreview')) $('#transformSqlPreview').value = '';
  if ($('#transformPreview')) { $('#transformPreview').innerHTML = '<div class="empty-state">Selecione uma origem e adicione etapas para ver a prévia.</div>'; $('#transformPreview').classList.add('empty-state'); }
  if ($('#transformMeta')) $('#transformMeta').textContent = 'aguardando';
  renderTransformSteps();
}

function openNovaTabelaModal(item) {
  const modal = $('#novaTabelaModal');
  if (!modal) return;
  const editing = item && item.daxExpression ? item : null;
  const input = $('#novaTabelaDaxFormula');
  const result = $('#novaTabelaDaxResult');
  const createBtn = $('#novaTabelaDaxCreateBtn');
  const title = $('#novaTabelaDaxTitle');
  modal.dataset.editingTransformId = editing ? editing.id : '';
  if (title) title.textContent = editing ? 'Editar tabela DAX' : 'Nova tabela DAX';
  if (input) {
    input.value = editing ? editing.daxExpression : '';
    input.dataset.testedFormula = '';
  }
  if (result) {
    result.className = 'transform-dax-test-result';
    result.textContent = 'Digite o código e valide antes de criar a tabela.';
  }
  if (createBtn) createBtn.disabled = true;
  modal.classList.remove('hidden');
  setupNovaTabelaDaxEditor();
  if (input) {
    input.dispatchEvent(new Event('input', { bubbles: true }));
    setTimeout(() => input.focus(), 40);
  }
}

function closeNovaTabelaModal() {
  const modal = $('#novaTabelaModal');
  if (modal) modal.classList.add('hidden');
  const suggestions = $('#novaTabelaDaxSuggestions');
  if (suggestions) suggestions.classList.remove('show');
}

function switchNovaTabelaTab(tab) {
  const modal = $('#novaTabelaModal');
  if (!modal) return;
  modal.querySelectorAll('.nova-tabela-tab').forEach((t) => t.classList.toggle('active', t.dataset.novaTab === tab));
  modal.querySelectorAll('.nova-tabela-panel').forEach((p) => p.classList.toggle('hidden', p.id !== ('novaTab' + tab.charAt(0).toUpperCase() + tab.slice(1))));
}

function renderNovaSalvarPreview() {
  const preview = $('#novaSalvarStepsPreview');
  if (!preview) return;
  const steps = state.transform.steps || [];
  const source = ($('#transformSourceSelect') && $('#transformSourceSelect').value) || state.transform.source;
  if (!steps.length) {
    preview.textContent = 'Nenhuma etapa aplicada. Adicione etapas de transformacao antes de salvar.';
    return;
  }
  preview.innerHTML = `Origem: <b>${escapeHtml(source || '?')}</b> | ${steps.length} etapa(s): ${steps.map((s) => transformStepLabel(s)).join(', ')}`;
  const nameInput = $('#novaSalvarQueryName');
  if (nameInput && !nameInput.value.trim()) nameInput.value = (source || 'consulta') + '_transformada';
}

function renderNovaPgTables() {
  const list = $('#novaPgTablesList');
  if (!list) return;
  list.className = 'empty-state';
  const caches = (state.pgCache && state.pgCache.caches) || [];
  const tables = caches.filter((c) => c && c.exists).sort((a, b) => (a.sourceTable || a.name || '').localeCompare(b.sourceTable || b.name || ''));
  if (!tables.length) {
    list.textContent = 'Nenhuma tabela no cache PostgreSQL. Configure o cache em Configuracoes.';
    return;
  }
  list.className = '';
  list.innerHTML = tables.map((t) => {
    const label = t.sourceTable || t.name || t.table || '?';
    const rowText = Number(t.rowCount || 0).toLocaleString('pt-BR') + ' linhas';
    return '<div style="display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px solid #eee"><span><b>' + escapeHtml(label) + '</b> <small style="color:var(--muted)">' + rowText + (t.syncedAt ? ' | ' + new Date(t.syncedAt).toLocaleDateString() : '') + '</small></span><button class="btn mini ghost" data-nova-use-pg="' + escapeHtml(label) + '">Usar</button></div>';
  }).join('');
  list.querySelectorAll('[data-nova-use-pg]').forEach((btn) => btn.addEventListener('click', () => {
    const name = btn.dataset.novaUsePg;
    if ($('#transformSourceSelect')) {
      $('#transformSourceSelect').value = name;
      state.transform.source = name;
      state.transform.steps = [];
      state.transform.selectedStepIndex = -1;
      state.transform.previewTriggered = false;
      $('#transformSourceSelect').dispatchEvent(new Event('change'));
    }
    closeNovaTabelaModal();
    toast('Tabela PostgreSQL selecionada: ' + name);
  }));
}

function setupNovaTabelaDaxEditor() {
  const input = $('#novaTabelaDaxFormula');
  const highlight = $('#novaTabelaDaxHighlight');
  const suggestions = $('#novaTabelaDaxSuggestions');
  if (!input || !suggestions || input.dataset.daxBound) return;
  input.dataset.daxBound = '1';
  let selectedIndex = 0;

  function syncHighlight() {
    if (!highlight) return;
    try { highlight.innerHTML = window.highlightDax(input.value) + '<br>'; }
    catch (err) { highlight.textContent = input.value; }
    highlight.scrollTop = input.scrollTop;
    highlight.scrollLeft = input.scrollLeft;
  }

  function contextAtCursor() {
    const before = input.value.slice(0, input.selectionStart || 0);
    const column = before.match(/(?:'([^']+)'|([^'\s=,+*/()]+))\[([^\]]*)$/);
    if (column) return { type: 'column', table: column[1] || column[2] || '', word: column[3] || '', start: before.length - (column[3] || '').length };
    const table = before.match(/'([^']*)$/);
    if (table) return { type: 'table', word: table[1] || '', start: before.length - (table[1] || '').length - 1 };
    const word = before.match(/[A-Za-zÀ-ÿ_][A-Za-zÀ-ÿ0-9_]*$/);
    return { type: 'general', word: word ? word[0] : '', start: word ? before.length - word[0].length : before.length };
  }

  function insertSuggestion(item) {
    const cursor = input.selectionStart || 0;
    const ctx = contextAtCursor();
    let inserted = item.name;
    let replaceEnd = cursor;
    if (item.type === 'function') inserted = item.name + '(';
    else if (item.type === 'table') inserted = daxTableReferenceName(item.name) + '[';
    else if (item.type === 'column') {
      inserted = item.name + ']';
      // Evita duplicar o colchete quando a sugestao e inserida antes de um ]
      // que ja existe no editor (por exemplo, Recebimento[Conversao KG]]).
      if (input.value.slice(cursor).startsWith(']')) replaceEnd += 1;
    }
    input.setRangeText(inserted, ctx.start, replaceEnd, 'end');
    suggestions.classList.remove('show');
    input.focus();
    input.dispatchEvent(new Event('input', { bubbles: true }));
  }

  function renderSuggestions(items) {
    const unique = [];
    const seen = new Set();
    items.forEach((item) => {
      const key = item.type + '|' + String(item.name).toLocaleLowerCase('pt-BR');
      if (seen.has(key)) return;
      seen.add(key);
      unique.push(item);
    });
    suggestions.innerHTML = '';
    if (!unique.length) { suggestions.classList.remove('show'); return; }
    selectedIndex = 0;
    unique.slice(0, 40).forEach((item, index) => {
      const row = document.createElement('div');
      row.className = 'measure-autocomplete-item' + (index === 0 ? ' selected' : '');
      row.innerHTML = `<span>${escapeHtml(item.type === 'function' ? item.name + '()' : item.name)}</span><small>${item.type === 'function' ? 'função DAX' : item.type === 'column' ? 'coluna' : 'tabela'}</small>`;
      row.addEventListener('mousedown', (event) => { event.preventDefault(); insertSuggestion(item); });
      suggestions.appendChild(row);
    });
    suggestions.classList.add('show');
  }

  async function updateSuggestions() {
    const ctx = contextAtCursor();
    const word = String(ctx.word || '').toLocaleLowerCase('pt-BR');
    if (ctx.type === 'column') {
      let columns = [];
      try { columns = await columnsForTransformSource(ctx.table); } catch (err) { columns = []; }
      renderSuggestions(columns.filter((name) => String(name).toLocaleLowerCase('pt-BR').includes(word)).map((name) => ({ type: 'column', name: String(name) })));
      return;
    }
    const tableNames = [...(state.resources || []).map((item) => item.name), ...(state.transforms || []).map((item) => item.name)].filter(Boolean);
    if (ctx.type === 'table') {
      renderSuggestions(tableNames.filter((name) => String(name).toLocaleLowerCase('pt-BR').includes(word)).map((name) => ({ type: 'table', name })));
      return;
    }
    if (!word) { suggestions.classList.remove('show'); return; }
    const functions = DAX_FUNCTIONS.filter((name) => !word || name.toLowerCase().includes(word)).map((name) => ({ type: 'function', name }));
    const tables = word ? tableNames.filter((name) => String(name).toLocaleLowerCase('pt-BR').includes(word)).map((name) => ({ type: 'table', name })) : [];
    renderSuggestions(functions.slice(0, word ? 30 : 18).concat(tables));
  }

  input.addEventListener('input', () => {
    syncHighlight();
    updateSuggestions().catch(() => {});
    input.dataset.testedFormula = '';
    const createBtn = $('#novaTabelaDaxCreateBtn');
    const result = $('#novaTabelaDaxResult');
    if (createBtn) createBtn.disabled = true;
    if (result) { result.className = 'transform-dax-test-result'; result.textContent = 'Digite o código e valide antes de criar a tabela.'; }
  });
  input.addEventListener('scroll', syncHighlight);
  input.addEventListener('keydown', (event) => {
    if (!suggestions.classList.contains('show')) return;
    const rows = Array.from(suggestions.querySelectorAll('.measure-autocomplete-item'));
    if (!rows.length) return;
    if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
      event.preventDefault();
      selectedIndex = (selectedIndex + (event.key === 'ArrowDown' ? 1 : -1) + rows.length) % rows.length;
      rows.forEach((row, index) => row.classList.toggle('selected', index === selectedIndex));
      rows[selectedIndex].scrollIntoView({ block: 'nearest' });
    } else if (event.key === 'Enter' && !event.shiftKey) {
      event.preventDefault();
      rows[selectedIndex].dispatchEvent(new MouseEvent('mousedown'));
    } else if (event.key === 'Escape') suggestions.classList.remove('show');
  });
  input.addEventListener('blur', () => setTimeout(() => suggestions.classList.remove('show'), 180));
  syncHighlight();
}

function showNovaTabelaDaxError(err) {
  const result = $('#novaTabelaDaxResult');
  const createBtn = $('#novaTabelaDaxCreateBtn');
  if (createBtn) createBtn.disabled = true;
  if (result) {
    result.className = 'transform-dax-test-result error';
    result.textContent = err && err.message ? err.message : 'Código DAX inválido.';
  }
}

async function testarNovaTabelaDax() {
  const input = $('#novaTabelaDaxFormula');
  const result = $('#novaTabelaDaxResult');
  const createBtn = $('#novaTabelaDaxCreateBtn');
  const formula = String(input && input.value || '').trim();
  if (!formula) throw new Error('Digite o código da nova tabela DAX.');
  if (result) {
    result.className = 'transform-dax-test-result';
    result.textContent = 'Validando no PostgreSQL...';
  }
  if (createBtn) createBtn.disabled = true;
  const data = await api('/api/transforms/dax-table/test', {
    method: 'POST',
    body: JSON.stringify({ formula, limit: 8 }),
    timeoutMs: 25000
  });
  if (input) input.dataset.testedFormula = formula;
  if (createBtn) createBtn.disabled = false;
  const tableName = data.definition && data.definition.name || 'Tabela DAX';
  const columns = Array.isArray(data.columns) ? data.columns.length : 0;
  const rows = data.preview && Array.isArray(data.preview.rows) ? data.preview.rows.length : 0;
  if (result) {
    result.className = 'transform-dax-test-result success';
    result.textContent = `Código válido. ${tableName}: ${columns} coluna(s), ${rows} linha(s) verificadas no PostgreSQL.`;
  }
  return data;
}

async function criarTabelaDaxDoModal() {
  const modal = $('#novaTabelaModal');
  const input = $('#novaTabelaDaxFormula');
  const createBtn = $('#novaTabelaDaxCreateBtn');
  const formula = String(input && input.value || '').trim();
  if (!formula) return showNovaTabelaDaxError(new Error('Digite o código da nova tabela DAX.'));
  if (!input || input.dataset.testedFormula !== formula) return showNovaTabelaDaxError(new Error('Valide o código novamente antes de criar a tabela.'));
  const editingId = String(modal && modal.dataset.editingTransformId || '').trim();
  const editingTransform = editingId ? (state.transforms || []).find((item) => item.id === editingId) : null;
  try {
    if (createBtn) { createBtn.disabled = true; createBtn.textContent = 'Criando...'; }
    const data = await api('/api/transforms', {
      method: 'POST',
      body: JSON.stringify({ id: editingId || undefined, daxExpression: formula, steps: editingTransform && Array.isArray(editingTransform.steps) ? editingTransform.steps : [] }),
      timeoutMs: 30000
    });
    toast('Tabela DAX salva: ' + data.transform.name);
    closeNovaTabelaModal();
    await loadTransforms();
    await loadTables();
    invalidateModelColumnCache(data.transform.name);
    renderTransformSourceSelect();
    if ($('#transformSourceSelect')) $('#transformSourceSelect').value = data.transform.name;
    state.transform.source = data.transform.name;
    state.transform.steps = Array.isArray(data.transform.steps) ? JSON.parse(JSON.stringify(data.transform.steps)) : [];
    state.transform.selectedStepIndex = -1;
    state.transform.previewTriggered = false;
    renderTransformSteps();
    previewTransform({ stepIndex: -1 }).catch((err) => toast(err.message, 'error'));
  } catch (err) {
    showNovaTabelaDaxError(err);
    toast(err.message || 'Erro ao criar tabela DAX', 'error');
  } finally {
    if (createBtn) { createBtn.textContent = 'Criar tabela'; createBtn.disabled = !input || input.dataset.testedFormula !== String(input.value || '').trim(); }
  }
}

async function salvarQueryDoModal() {
  const name = ($('#novaSalvarQueryName') && $('#novaSalvarQueryName').value || '').trim();
  if (!name) return toast('Informe o nome da consulta.', 'error');
  const payload = currentTransformPayload();
  if (!payload.source) return toast('Selecione uma origem antes de salvar.', 'error');
  if (!payload.steps.length) return toast('Adicione etapas antes de salvar.', 'error');
  payload.name = name;
  delete payload.limit;
  try {
    const data = await api('/api/transforms', { method: 'POST', body: JSON.stringify(payload), timeoutMs: 20000 });
    toast('Consulta salva: ' + data.transform.name);
    closeNovaTabelaModal();
    await loadTransforms();
    await loadTables();
    renderTransformSourceSelect();
  } catch (err) {
    toast(err.message || 'Erro ao salvar consulta', 'error');
  }
}

function availableColumnsForTransform() {
  const resource = getResource(($('#transformSourceSelect') && $('#transformSourceSelect').value) || state.transform.source);
  // Usa colunas já carregadas do criador visual quando possível.
  if (resource && state.modelColumnCache && state.modelColumnCache[resource.name]) return state.modelColumnCache[resource.name];
  return (state.builderColumns || []).map((c) => c.name || c).filter(Boolean);
}

async function ensureTransformColumnsLoaded() {
  const source = ($('#transformSourceSelect') && $('#transformSourceSelect').value) || state.transform.source;
  if (!source) return [];
  if (!state.modelColumnCache[source]) {
    try {
      const data = await api('/api/tables/' + encodeURIComponent(source) + '/columns?ts=' + Date.now());
      const cols = normalizeColumnMetadataList(data.columns || []);
      if (cols.length) {
        state.modelColumnCache[source] = cols;
      }
    } catch (err) {
      // nao cacheia em caso de erro, para tentar novamente na proxima chamada
    }
  }
  return state.modelColumnCache[source] || [];
}


function transformSourceOptions(selected = '') {
  const items = [...(state.resources || []), ...(state.transforms || []).map((t) => ({ name: t.name, source: 'transform', type: 'transform' }))];
  const seen = new Set();
  return items.filter((item) => item && item.name && !seen.has(item.name) && seen.add(item.name)).map((item) => {
    const label = item.source === 'transform' || item.type === 'transform' ? `Consulta: ${item.name}` : `${item.type === 'view' ? 'View' : 'Tabela'}: ${item.name}`;
    return `<option value="${escapeHtml(item.name)}" ${selected === item.name ? 'selected' : ''}>${escapeHtml(label)}</option>`;
  }).join('');
}

async function columnsForTransformSource(source) {
  const name = String(source || '').trim();
  if (!name) return [];
  if (!state.modelColumnCache[name]) {
    try {
      const data = await api('/api/tables/' + encodeURIComponent(name) + '/columns?ts=' + Date.now());
      state.modelColumnCache[name] = normalizeColumnMetadataList(data.columns || []);
    } catch (err) {
      state.modelColumnCache[name] = [];
    }
  }
  return columnNames(state.modelColumnCache[name] || []);
}

function optionList(columns, selected = '') {
  return (columns || []).map((c) => `<option value="${escapeHtml(c)}" ${selected === c ? 'selected' : ''}>${escapeHtml(c)}</option>`).join('');
}

async function updateMergeAppendColumnControls(form, step = {}) {
  if (!form) return;
  const rightSourceEl = form.querySelector('[name="source"]');
  const rightColumnEl = form.querySelector('[name="rightColumn"]');
  const rightColumnsEl = form.querySelector('[data-right-columns-box]');
  const source = rightSourceEl ? rightSourceEl.value : (step.source || step.rightSource || '');
  const cols = await columnsForTransformSource(source);
  if (rightColumnEl) rightColumnEl.innerHTML = optionList(cols, step.rightColumn || '');
  if (rightColumnsEl) {
    const selected = new Set(Array.isArray(step.columns) ? step.columns : String(step.columns || step.rightColumns || '').split(',').map((x) => x.trim()).filter(Boolean));
    rightColumnsEl.innerHTML = cols.map((c) => `<label class="check-label compact-check"><input type="checkbox" name="rightColumns" value="${escapeHtml(c)}" ${selected.has(c) ? 'checked' : ''}> ${escapeHtml(c)}</label>`).join('') || '<div class="empty-state">Selecione uma origem para carregar as colunas.</div>';
  }
}

async function openTransformStepModal(kind, editIndex = null) {
  let columns = [];
  try { columns = await ensureTransformColumnsLoaded(); } catch (err) { columns = []; }
  // Garante que colunas sao sempre strings
  columns = columns.map((c) => String(c && (c.name || c.Field || c) || c || '')).filter(Boolean);
  const modal = $('#transformStepModal');
  const form = $('#transformStepForm');
  const title = $('#transformStepTitle');
  if (!modal || !form) return;
  state.transform.editingStep = { kind, index: editIndex };
  const step = editIndex !== null ? (state.transform.steps[editIndex] || { kind }) : { kind };
  const colOptions = columns.map((c) => `<option value="${escapeHtml(c)}">${escapeHtml(c)}</option>`).join('');
  function multi(name, selected = []) {
    const set = new Set(selected || []);
    return `<div class="transform-column-checks">${columns.map((c) => `<label class="check-label"><input type="checkbox" name="${name}" value="${escapeHtml(c)}" ${set.has(c) ? 'checked' : ''}> ${escapeHtml(c)}</label>`).join('')}</div>`;
  }
  const labels = { selectColumns: 'Selecionar colunas', removeColumns: 'Remover colunas', renameColumn: 'Renomear coluna', changeType: 'Alterar tipo', filterRows: 'Filtrar linhas', filterDate: 'Filtrar data', sortRows: 'Ordenar', replaceValues: 'Substituir valores', fillValues: 'Preencher vazios', duplicateColumn: 'Duplicar coluna', splitColumn: 'Dividir coluna', formatText: 'Formatar texto', groupBy: 'Agrupar por', removeDuplicates: 'Remover duplicados', mergeQueries: 'Mesclar consultas', appendQueries: 'Acrescentar consultas', customColumn: 'Coluna personalizada', daxColumn: 'Coluna calculada DAX', conditionalColumn: 'Coluna condicional' };
  if (title) title.textContent = labels[kind] || 'Adicionar etapa';
  if (kind === 'selectColumns' || kind === 'removeColumns' || kind === 'removeDuplicates') {
    form.innerHTML = `<label>Colunas</label>${multi('columns', step.columns || [])}`;
  } else if (kind === 'renameColumn') {
    form.innerHTML = `<label>Coluna<select name="column">${colOptions}</select></label><label>Novo nome<input name="newName" value="${escapeHtml(step.newName || '')}" placeholder="Novo nome da coluna"></label>`;
  } else if (kind === 'changeType') {
    form.innerHTML = `<label>Coluna<select name="column">${colOptions}</select></label><label>Novo tipo<select name="dataType"><option value="texto">Texto</option><option value="decimal">Número Decimal Fixo</option><option value="inteiro">Número Inteiro</option><option value="datetime">Data/Hora</option><option value="data">Data</option><option value="hora">Hora</option><option value="bool">True/False</option><option value="binario">Binário</option></select></label>`;
  } else if (kind === 'filterRows') {
    form.innerHTML = `<label>Coluna<select name="column">${colOptions}</select></label>
      <label>Operador<select name="operator"><option value="=">igual (marcar valores)</option><option value="contains">contém</option><option value=">=">maior ou igual</option><option value="<=">menor ou igual</option><option value=">">maior</option><option value="<">menor</option><option value="between">entre</option><option value="blank">vazio</option><option value="notblank">não vazio</option></select></label>
      <div name="filterValuesBox"><div class="empty-state small">Selecione uma coluna para carregar os valores.</div></div>`;
    // Carrega valores distintos ao selecionar coluna
    form.querySelector('[name="column"]').addEventListener('change', () => loadFilterDistinctValues(form, step));
    form.querySelector('[name="operator"]').addEventListener('change', () => loadFilterDistinctValues(form, step));
    // Carrega valores iniciais se coluna ja estiver selecionada
    setTimeout(() => { if (form.querySelector('[name="column"]').value) loadFilterDistinctValues(form, step); }, 50);
  } else if (kind === 'filterDate') {
    form.innerHTML = `<div class="lock-box small-note">Filtre datas a partir de um período. Deixe em branco caso não queira limitar o início ou o fim.</div><label>Coluna<select name="column">${colOptions}</select></label>
      <label>Data Inicial (a partir de)<input type="date" name="value" value="${escapeHtml(step.value || '')}"></label>
      <label>Data Final (até)<input type="date" name="value2" value="${escapeHtml(step.value2 || '')}"></label>`;
  } else if (kind === 'sortRows') {
    form.innerHTML = `<label>Coluna<select name="column">${colOptions}</select></label><label>Direção<select name="direction"><option value="ASC">Crescente</option><option value="DESC">Decrescente</option></select></label>`;
  } else if (kind === 'replaceValues') {
    form.innerHTML = `<label>Coluna<select name="column">${colOptions}</select></label><label>Localizar<input name="from" value="${escapeHtml(step.from || '')}"></label><label>Substituir por<input name="to" value="${escapeHtml(step.to || '')}"></label>`;
  } else if (kind === 'fillValues') {
    form.innerHTML = `<div class="lock-box small-note"><b>Modelagem reversivel no PostgreSQL.</b> Preenche valores nulos ou em branco sem alterar a tabela fisica e sem solicitar atualizacao do MySQL.</div><label>Coluna<select name="column">${colOptions}</select></label><label>Valor para preencher<input name="value" value="${escapeHtml(step.value || '')}" placeholder="Ex: Sem cadastro, 0, 1 ou hoje"></label>`;
  } else if (kind === 'duplicateColumn') {
    form.innerHTML = `<label>Coluna<select name="column">${colOptions}</select></label><label>Nome da cópia<input name="newName" value="${escapeHtml(step.newName || '')}" placeholder="Ex: Cliente Original"></label>`;
  } else if (kind === 'splitColumn') {
    form.innerHTML = `<div class="lock-box small-note">Divide uma coluna em duas usando delimitador. Exemplo: hífen, barra ou espaço.</div><label>Coluna<select name="column">${colOptions}</select></label><label>Delimitador<input name="delimiter" value="${escapeHtml(step.delimiter || '')}" placeholder="Ex: -"></label><label>Nome da primeira parte<input name="newName1" value="${escapeHtml(step.newName1 || '')}" placeholder="Ex: Código"></label><label>Nome da segunda parte<input name="newName2" value="${escapeHtml(step.newName2 || '')}" placeholder="Ex: Descrição"></label><label class="check-label"><input type="checkbox" name="removeOriginal" ${step.removeOriginal ? 'checked' : ''}> Remover coluna original da saída</label>`;
  } else if (kind === 'formatText') {
    form.innerHTML = `<label>Coluna<select name="column">${colOptions}</select></label><label>Formato<select name="format"><option value="trim">Remover espaços extras</option><option value="upper">Maiúsculas</option><option value="lower">Minúsculas</option><option value="trimupper">Remover espaços + maiúsculas</option><option value="trimlower">Remover espaços + minúsculas</option></select></label>`;
  } else if (kind === 'groupBy') {
    const agg = (step.aggregations && step.aggregations[0]) || {};
    form.innerHTML = `<div class="lock-box small-note">Agrupa linhas no estilo Power Query. Use apenas colunas numéricas para soma/média quando fizer sentido.</div><label>Colunas de agrupamento</label>${multi('columns', step.groupColumns || step.columns || [])}<label>Coluna para agregar<select name="aggColumn">${colOptions}</select></label><label>Operação<select name="aggFunc"><option value="SUM">Soma</option><option value="AVG">Média</option><option value="MIN">Mínimo</option><option value="MAX">Máximo</option><option value="COUNT">Contagem</option><option value="COUNTDISTINCT">Contagem distinta</option></select></label><label>Nome da nova coluna agregada<input name="aggName" value="${escapeHtml(agg.newName || '')}" placeholder="Ex: Total Valor"></label>`;
    const aggCol = form.querySelector('[name="aggColumn"]'); if (aggCol && agg.column) aggCol.value = agg.column;
    const aggFunc = form.querySelector('[name="aggFunc"]'); if (aggFunc && agg.func) aggFunc.value = agg.func;
  } else if (kind === 'mergeQueries') {
    const selectedSource = step.source || step.rightSource || '';
    form.innerHTML = `
      <div class="lock-box small-note">Mesclar consultas funciona como o Power Query: a consulta atual é ligada a outra tabela/view/consulta usando colunas correspondentes.</div>
      <label>Coluna da consulta atual<select name="leftColumn">${colOptions}</select></label>
      <label>Consulta/tabela para mesclar<select name="source">${transformSourceOptions(selectedSource)}</select></label>
      <label>Coluna da outra consulta<select name="rightColumn"></select></label>
      <label>Tipo de junção<select name="joinType"><option value="LEFT">Left outer - manter consulta atual</option><option value="INNER">Inner - somente correspondentes</option><option value="RIGHT">Right outer - manter outra consulta</option></select></label>
      <label>Colunas da outra consulta para trazer</label><div data-right-columns-box class="transform-column-checks compact-checks"></div>`;
    const src = form.querySelector('[name="source"]');
    if (src) src.addEventListener('change', () => updateMergeAppendColumnControls(form, step).catch((err) => toast(err.message, 'error')));
    updateMergeAppendColumnControls(form, step).catch((err) => toast(err.message, 'error'));
  } else if (kind === 'appendQueries') {
    form.innerHTML = `
      <div class="lock-box small-note">Acrescentar consultas empilha linhas usando UNION ALL. As colunas com o mesmo nome são mantidas; colunas ausentes ficam em branco.</div>
      <label>Consulta/tabela para acrescentar<select name="source">${transformSourceOptions(step.source || step.appendSource || '')}</select></label>`;
  } else if (kind === 'daxColumn') {
    const defaultFormula = step.expression || (step.newName ? step.newName + ' = ' : 'Nova coluna = ');
    form.innerHTML = `
      <div class="lock-box small-note"><b>Calculada pelo BI WA no PostgreSQL.</b> Nao altera nem solicita atualizacao do MySQL. Digite uma unica formula no formato <b>Nome da coluna = formula DAX</b>.</div>
      <div class="transform-dax-editor">
        <label>Formula da coluna DAX</label>
        <div class="measure-editor-container">
          <div id="transformDaxFormulaHighlight" class="measure-formula-highlight" aria-hidden="true"></div>
          <textarea id="transformDaxFormula" name="expression" rows="8" autocomplete="off" spellcheck="false" placeholder="Chave = 'Faturamento'[Empresa] & 'Faturamento'[Código Produto]">${escapeHtml(defaultFormula)}</textarea>
        </div>
        <div id="transformDaxSuggestions" class="measure-autocomplete-list"></div>
      </div>
      <div class="actions"><button id="testTransformDaxBtn" class="btn ghost" type="button">Testar codigo</button></div>
      <div id="transformDaxTestResult" class="transform-dax-test-result">Teste a formula antes de aplicar a etapa.</div>`;
    setupTransformDaxEditor();
    const testBtn = form.querySelector('#testTransformDaxBtn');
    if (testBtn) testBtn.addEventListener('click', () => testTransformDaxColumn().catch((err) => showTransformDaxTestError(err)));
  } else if (kind === 'customColumn') {
    form.innerHTML = `
      <div class="lock-box small-note">Crie uma coluna calculada sem alterar o MySQL. Use colunas entre colchetes. Exemplos: <b>[Quantidade] * [Valor]</b>, <b>[Produto] & " - " & [Marca]</b>, <b>YEAR([Data])</b>.</div>
      <label>Nome da nova coluna<input name="newName" value="${escapeHtml(step.newName || '')}" placeholder="Ex: Valor com desconto"></label>
      <label>Expressão<textarea name="expression" rows="5" placeholder="Ex: [Valor Total] * 0.9">${escapeHtml(step.expression || '')}</textarea></label>
      <label>Tipo da nova coluna<select name="dataType"><option value="texto">Texto</option><option value="decimal">Número Decimal Fixo</option><option value="inteiro">Número Inteiro</option><option value="datetime">Data/Hora</option><option value="data">Data</option><option value="hora">Hora</option><option value="bool">True/False</option><option value="binario">Binário</option></select></label>`;
  } else if (kind === 'conditionalColumn') {
    form.innerHTML = `
      <div class="lock-box small-note">Crie uma coluna IF/THEN/ELSE no estilo Power Query. Para usar uma coluna como resultado, escreva o nome entre colchetes, por exemplo <b>[Produto]</b>.</div>
      <label>Nome da nova coluna<input name="newName" value="${escapeHtml(step.newName || '')}" placeholder="Ex: Faixa de venda"></label>
      <label>Coluna da condição<select name="column">${colOptions}</select></label>
      <label>Operador<select name="operator"><option value="=">igual</option><option value="contains">contém</option><option value=">=">maior ou igual</option><option value="<=">menor ou igual</option><option value=">">maior</option><option value="<">menor</option><option value="between">entre</option><option value="blank">vazio</option><option value="notblank">não vazio</option></select></label>
      <label>Valor da condição<input name="value" value="${escapeHtml(step.value || '')}"></label>
      <label>Valor final, para entre<input name="value2" value="${escapeHtml(step.value2 || '')}"></label>
      <label>Resultado se verdadeiro<input name="trueValue" value="${escapeHtml(step.trueValue || '')}" placeholder="Ex: Alto ou [Coluna]"></label>
      <label>Resultado se falso<input name="falseValue" value="${escapeHtml(step.falseValue || '')}" placeholder="Ex: Baixo"></label>
      <label>Tipo da nova coluna<select name="dataType"><option value="texto">Texto</option><option value="decimal">Número Decimal Fixo</option><option value="inteiro">Número Inteiro</option><option value="datetime">Data/Hora</option><option value="data">Data</option><option value="hora">Hora</option><option value="bool">True/False</option><option value="binario">Binário</option></select></label>`;
  }
  ['column','operator','direction','dataType','leftColumn','rightColumn','joinType','source','format'].forEach((name) => { const el = form.querySelector(`[name="${name}"]`); if (el && step[name]) el.value = step[name]; });
  modal.classList.remove('hidden');
}

function showTransformDaxTestError(err) {
  const result = $('#transformDaxTestResult');
  if (!result) return;
  result.className = 'transform-dax-test-result error';
  result.textContent = err && err.message ? err.message : 'Formula DAX invalida.';
}

function setupTransformDaxEditor() {
  const input = $('#transformDaxFormula');
  const highlight = $('#transformDaxFormulaHighlight');
  const suggestions = $('#transformDaxSuggestions');
  if (!input || !suggestions || input.dataset.daxBound) return;
  input.dataset.daxBound = '1';
  let selectedIndex = 0;

  function syncHighlight() {
    if (!highlight) return;
    try { highlight.innerHTML = window.highlightDax(input.value) + '<br>'; }
    catch (err) { highlight.textContent = input.value; }
    highlight.scrollTop = input.scrollTop;
    highlight.scrollLeft = input.scrollLeft;
  }

  function contextAtCursor() {
    const before = input.value.slice(0, input.selectionStart || 0);
    const column = before.match(/(?:'([^']+)'|([^'\s=,+*/()]+))\[([^\]]*)$/);
    if (column) return { type: 'column', table: column[1] || column[2] || '', word: column[3] || '', start: before.length - (column[3] || '').length };
    const table = before.match(/'([^']*)$/);
    if (table) return { type: 'table', word: table[1] || '', start: before.length - (table[1] || '').length - 1 };
    const word = before.match(/[A-Za-zÀ-ÿ_][A-Za-zÀ-ÿ0-9_]*$/);
    return { type: 'general', word: word ? word[0] : '', start: word ? before.length - word[0].length : before.length };
  }

  function insertSuggestion(item) {
    const cursor = input.selectionStart || 0;
    const ctx = contextAtCursor();
    let inserted = item.name;
    let start = ctx.start;
    let replaceEnd = cursor;
    if (item.type === 'function') inserted = item.name + '(';
    if (item.type === 'table') inserted = daxTableReferenceName(item.name) + '[';
    if (item.type === 'column') {
      inserted = item.name + ']';
      if (input.value.slice(cursor).startsWith(']')) replaceEnd += 1;
    }
    input.setRangeText(inserted, start, replaceEnd, 'end');
    suggestions.classList.remove('show');
    input.focus();
    input.dispatchEvent(new Event('input', { bubbles: true }));
  }

  function render(items) {
    suggestions.innerHTML = '';
    const unique = [];
    const seen = new Set();
    items.forEach((item) => {
      const key = item.type + '|' + String(item.name).toLowerCase();
      if (seen.has(key)) return;
      seen.add(key);
      unique.push(item);
    });
    if (!unique.length) { suggestions.classList.remove('show'); return; }
    selectedIndex = 0;
    unique.slice(0, 40).forEach((item, index) => {
      const row = document.createElement('div');
      row.className = 'measure-autocomplete-item' + (index === 0 ? ' selected' : '');
      row.innerHTML = `<span>${escapeHtml(item.type === 'function' ? item.name + '()' : item.name)}</span><small>${item.type === 'function' ? 'funcao DAX' : item.type === 'column' ? 'coluna' : 'tabela'}</small>`;
      row.addEventListener('mousedown', (event) => { event.preventDefault(); insertSuggestion(item); });
      suggestions.appendChild(row);
    });
    suggestions.classList.add('show');
  }

  async function updateSuggestions() {
    const ctx = contextAtCursor();
    const word = String(ctx.word || '').toLocaleLowerCase('pt-BR');
    if (ctx.type === 'column') {
      let columns = [];
      try { columns = await columnsForTransformSource(ctx.table); } catch (err) { columns = []; }
      return render(columns.filter((name) => String(name).toLocaleLowerCase('pt-BR').includes(word)).map((name) => ({ type: 'column', name: String(name) })));
    }
    const tables = (state.resources || []).map((item) => item.name).filter(Boolean);
    if (ctx.type === 'table') return render(tables.filter((name) => String(name).toLocaleLowerCase('pt-BR').includes(word)).map((name) => ({ type: 'table', name })));
    const functions = DAX_FUNCTIONS.filter((name) => !word || name.toLowerCase().includes(word)).map((name) => ({ type: 'function', name }));
    const tableItems = tables.filter((name) => word && String(name).toLocaleLowerCase('pt-BR').includes(word)).map((name) => ({ type: 'table', name }));
    render(functions.slice(0, word ? 30 : 18).concat(tableItems));
  }

  input.addEventListener('input', () => {
    syncHighlight();
    updateSuggestions().catch(() => {});
    input.dataset.testedFormula = '';
    const result = $('#transformDaxTestResult');
    if (result) { result.className = 'transform-dax-test-result'; result.textContent = 'Teste a formula antes de aplicar a etapa.'; }
  });
  input.addEventListener('scroll', syncHighlight);
  input.addEventListener('keydown', (event) => {
    if (!suggestions.classList.contains('show')) return;
    const rows = Array.from(suggestions.querySelectorAll('.measure-autocomplete-item'));
    if (!rows.length) return;
    if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
      event.preventDefault();
      selectedIndex = (selectedIndex + (event.key === 'ArrowDown' ? 1 : -1) + rows.length) % rows.length;
      rows.forEach((row, index) => row.classList.toggle('selected', index === selectedIndex));
      rows[selectedIndex].scrollIntoView({ block: 'nearest' });
    } else if (event.key === 'Enter' && !event.shiftKey) {
      event.preventDefault();
      rows[selectedIndex].dispatchEvent(new MouseEvent('mousedown'));
    } else if (event.key === 'Escape') suggestions.classList.remove('show');
  });
  input.addEventListener('blur', () => setTimeout(() => suggestions.classList.remove('show'), 180));
  syncHighlight();
}

async function testTransformDaxColumn() {
  const source = ($('#transformSourceSelect') && $('#transformSourceSelect').value) || state.transform.source;
  const input = $('#transformDaxFormula');
  const result = $('#transformDaxTestResult');
  if (!source || !input || !String(input.value || '').trim()) throw new Error('Selecione a tabela e digite a formula DAX.');
  if (result) { result.className = 'transform-dax-test-result'; result.textContent = 'Testando somente no PostgreSQL...'; }
  const data = await api('/api/transforms/modeling/test', {
    method: 'POST',
    body: JSON.stringify({ source, formula: input.value, steps: state.transform.steps || [], limit: 8 }),
    timeoutMs: 20000
  });
  input.dataset.testedFormula = input.value;
  const name = data.definition && data.definition.name || 'Nova coluna';
  const values = data.preview && Array.isArray(data.preview.rows) ? data.preview.rows.map((row) => row[name]).slice(0, 5) : [];
  if (result) {
    result.className = 'transform-dax-test-result success';
    result.textContent = `Codigo valido. ${name}: ${values.map((value) => value == null ? '(vazio)' : String(value)).join(' | ')}`;
  }
  return data;
}

function closeTransformStepModal() {
  const modal = $('#transformStepModal');
  if (modal) modal.classList.add('hidden');
}

async function loadFilterDistinctValues(form, step) {
  const box = form.querySelector('[name="filterValuesBox"]');
  if (!box) return;
  const column = form.querySelector('[name="column"]') && form.querySelector('[name="column"]').value;
  const operator = form.querySelector('[name="operator"]') && form.querySelector('[name="operator"]').value;
  if (!column) { box.innerHTML = '<div class="empty-state small">Selecione uma coluna para carregar os valores.</div>'; return; }
  // Apenas para operador "=" mostra checkbox list
  if (operator !== '=') {
    box.innerHTML = `<label>Valor<input name="value" value="${escapeHtml(step.value || '')}"></label><label>Valor final, para entre<input name="value2" value="${escapeHtml(step.value2 || '')}"></label>`;
    return;
  }
  box.innerHTML = '<div class="empty-state small">Carregando valores distintos...</div>';
  try {
    const source = ($('#transformSourceSelect') && $('#transformSourceSelect').value) || state.transform.source;
    const data = await api('/api/tables/' + encodeURIComponent(source) + '/values/' + encodeURIComponent(column) + '?limit=2000&ts=' + Date.now() + '&skipRowFilter=1');
    const values = Array.isArray(data.values) ? data.values : [];
    if (!values.length) { box.innerHTML = '<div class="empty-state small">Nenhum valor encontrado nesta coluna.</div>'; return; }
    const selected = new Set(String(step.value || '').split(',').map((s) => s.trim()).filter(Boolean));
    // Mostra TODOS os valores, mas marca apenas os que foram selecionados
    const allChecked = selected.size === 0;
    const selectedCount = allChecked ? values.length : selected.size;
    box.innerHTML = `
      <div class="filter-values-bar"><span class="transform-values-label">${values.length} valor(es) | ${selectedCount} selecionado(s)</span><span class="actions"><button type="button" class="btn ghost mini" data-filter-select-all>Todos</button><button type="button" class="btn ghost mini" data-filter-deselect-all>Nenhum</button></span></div>
      <input type="text" class="filter-values-search" placeholder="Pesquisar valor..." autocomplete="off">
      <div class="filter-values-list">${values.map((v) => {
        const val = String(v ?? '');
        const display = val.length > 60 ? val.slice(0, 57) + '...' : val;
        // Marca apenas se foi explicitamente selecionado OU se nenhum filtro existe (nova etapa)
        const checked = (allChecked || selected.has(val)) ? 'checked' : '';
        return `<label class="check-label filter-value-item"><input type="checkbox" name="filterValue" value="${escapeHtml(val)}" ${checked}> ${escapeHtml(display)}</label>`;
      }).join('')}</div>`;
    box.querySelector('[data-filter-select-all]').addEventListener('click', () => {
      box.querySelectorAll('[name="filterValue"]').forEach((cb) => cb.checked = true);
      updateSelectedCount();
    });
    box.querySelector('[data-filter-deselect-all]').addEventListener('click', () => {
      box.querySelectorAll('[name="filterValue"]').forEach((cb) => cb.checked = false);
      updateSelectedCount();
    });
    const searchInput = box.querySelector('.filter-values-search');
    if (searchInput) {
      searchInput.addEventListener('input', () => {
        const q = searchInput.value.toLowerCase();
        box.querySelectorAll('.filter-value-item').forEach((item) => {
          item.style.display = q ? (item.textContent.toLowerCase().includes(q) ? '' : 'none') : '';
        });
      });
    }
    // Atualiza contador ao marcar/desmarcar
    function updateSelectedCount() {
      const selectedNow = box.querySelectorAll('[name="filterValue"]:checked').length;
      const labelEl = box.querySelector('.transform-values-label');
      if (labelEl) labelEl.textContent = `${values.length} valor(es) | ${selectedNow} selecionado(s)`;
    }
    box.querySelectorAll('[name="filterValue"]').forEach((cb) => {
      cb.addEventListener('change', updateSelectedCount);
    });
  } catch (err) {
    box.innerHTML = `<div class="error-box">Erro ao carregar valores: ${escapeHtml(err.message || 'erro desconhecido')}</div>`;
  }
}

async function applyTransformStepFromModal() {
  const ctx = state.transform.editingStep;
  const form = $('#transformStepForm');
  if (!ctx || !form) return;
  const step = ctx.index !== null && ctx.index !== undefined && state.transform.steps[ctx.index]
    ? Object.assign({}, state.transform.steps[ctx.index])
    : { kind: ctx.kind };
  const checks = Array.from(form.querySelectorAll('input[name="columns"]:checked')).map((el) => el.value);
  if (checks.length) step.columns = checks;
  const rightChecks = Array.from(form.querySelectorAll('input[name="rightColumns"]:checked')).map((el) => el.value);
  if (rightChecks.length) step.columns = rightChecks;
  const removeOriginalEl = form.querySelector('[name="removeOriginal"]');
  if (removeOriginalEl) step.removeOriginal = removeOriginalEl.checked;
  if (step.kind === 'groupBy') {
    step.groupColumns = checks;
    const aggColumn = form.querySelector('[name="aggColumn"]');
    const aggFunc = form.querySelector('[name="aggFunc"]');
    const aggName = form.querySelector('[name="aggName"]');
    step.aggregations = [{ column: aggColumn ? aggColumn.value : '', func: aggFunc ? aggFunc.value : 'SUM', newName: aggName ? aggName.value : '' }];
  }
  ['column','newName','dataType','operator','value2','direction','from','to','source','leftColumn','rightColumn','joinType','expression','trueValue','falseValue','delimiter','newName1','newName2','format'].forEach((name) => {
    const el = form.querySelector(`[name="${name}"]`);
    if (el) step[name] = el.value;
  });
  // Coleta valores marcados no checkbox list (operador "=")
  if (step.kind === 'filterRows' && step.operator === '=') {
    const checked = Array.from(form.querySelectorAll('[name="filterValue"]:checked')).map((cb) => cb.value);
    const total = form.querySelectorAll('[name="filterValue"]').length;
    if (checked.length === 0) return toast('Selecione pelo menos um valor para filtrar.', 'error');
    // Se todos estao marcados, o filtro nao precisa ser aplicado
    if (checked.length === total) return toast('Todos os valores estao marcados — nenhum filtro necessario.', 'error');
    step.value = checked.join(',');
  } else {
    const valueEl = form.querySelector('[name="value"]');
    if (valueEl) step.value = valueEl.value;
  }
  if (['selectColumns','removeColumns'].includes(step.kind) && !(step.columns || []).length) return toast('Selecione pelo menos uma coluna.', 'error');
  if (step.kind === 'mergeQueries' && (!step.source || !step.leftColumn || !step.rightColumn)) return toast('Informe origem e colunas para mesclar.', 'error');
  if (step.kind === 'appendQueries' && !step.source) return toast('Informe a consulta/tabela para acrescentar.', 'error');
  if (step.kind === 'duplicateColumn' && (!step.column || !step.newName)) return toast('Informe a coluna e o nome da cópia.', 'error');
  if (step.kind === 'splitColumn' && (!step.column || !step.delimiter || !step.newName1 || !step.newName2)) return toast('Informe coluna, delimitador e nomes de saída.', 'error');
  if (step.kind === 'formatText' && (!step.column || !step.format)) return toast('Informe coluna e formato de texto.', 'error');
  if (step.kind === 'fillValues' && (!step.column)) return toast('Informe a coluna para preencher.', 'error');
  if (step.kind === 'groupBy' && (!(step.groupColumns || []).length || !(step.aggregations || [])[0] || !step.aggregations[0].column || !step.aggregations[0].newName)) return toast('Informe colunas de agrupamento e uma agregação.', 'error');
  if (step.kind === 'daxColumn') {
    if (!step.expression) return toast('Digite a formula da coluna DAX.', 'error');
    const tested = await testTransformDaxColumn();
    step.newName = tested.definition.name;
    step.expression = tested.definition.formula;
  }
  if (step.kind === 'customColumn' && (!step.newName || !step.expression)) return toast('Informe nome e expressão da coluna personalizada.', 'error');
  if (step.kind === 'conditionalColumn' && (!step.newName || !step.column)) return toast('Informe nome e coluna da condição.', 'error');
  if (ctx.index !== null && ctx.index !== undefined) {
    if (step.kind === 'changeType' && !step.appliedAt) step.appliedAt = (state.transform.steps[ctx.index] && state.transform.steps[ctx.index].appliedAt) || new Date().toISOString();
    state.transform.steps[ctx.index] = step;
    state.transform.selectedStepIndex = ctx.index;
  } else {
    if (step.kind === 'changeType' && !step.appliedAt) step.appliedAt = new Date().toISOString();
    state.transform.steps.push(step);
    state.transform.selectedStepIndex = state.transform.steps.length - 1;
  }
  closeTransformStepModal();
  renderTransformSteps();
  previewTransform().catch((err) => toast(err.message, 'error'));
}

var FORMAT_STYLES = {
  inteiro: [
    { value: '', label: 'Geral' },
    { value: 'R$ #,##0', label: 'Moeda' },
    { value: '#,##0.00', label: 'Número Decimal' },
    { value: '#,##0', label: 'Número Inteiro' },
    { value: '0%', label: 'Porcentagem' },
    { value: '0.00E+00', label: 'Científico' }
  ],
  decimal: [
    { value: '', label: 'Geral' },
    { value: 'R$ #,##0.00', label: 'Moeda' },
    { value: '#,##0.00', label: 'Número Decimal' },
    { value: '#,##0', label: 'Número Inteiro' },
    { value: '0.00%', label: 'Porcentagem' },
    { value: '0.00E+00', label: 'Científico' }
  ],
  datetime: [
    { value: '', label: 'Geral' },
    { value: 'dd/MM/yyyy', label: 'Data Abreviada' },
    { value: 'dd/MM/yyyy HH:mm', label: 'Data/Hora' },
    { value: 'dd/MM/yyyy HH:mm:ss', label: 'Data/Hora (com segundos)' },
    { value: 'HH:mm:ss', label: 'Hora' }
  ],
  data: [
    { value: '', label: 'Geral' },
    { value: 'dd/MM/yyyy', label: 'Data Abreviada' },
    { value: 'MM/yyyy', label: 'Mês/Ano' },
    { value: 'MMMM yyyy', label: 'Mês por Extenso' },
    { value: 'yyyy-MM-dd', label: 'ISO' }
  ],
  hora: [
    { value: '', label: 'Geral' },
    { value: 'HH:mm', label: 'Hora (24h)' },
    { value: 'HH:mm:ss', label: 'Hora (24h com segundos)' },
    { value: 'hh:mm tt', label: 'Hora (12h)' },
    { value: 'hh:mm:ss tt', label: 'Hora (12h com segundos)' }
  ],
  texto: [
    { value: '', label: 'Geral' },
    { value: 'upper', label: 'MAIÚSCULAS' },
    { value: 'lower', label: 'minúsculas' },
    { value: 'trim', label: 'Remover espaços' }
  ],
  bool: [
    { value: '', label: 'Geral' },
    { value: 'truefalse', label: 'True / False' },
    { value: 'verdadeirofalso', label: 'Verdadeiro / Falso' },
    { value: 'simnao', label: 'Sim / Não' },
    { value: '10', label: '1 / 0' },
    { value: 'ativoinativo', label: 'Ativo / Inativo' }
  ],
  binario: [
    { value: '', label: 'Geral' }
  ]
};

function normalizeDataType(dt) {
  var key = String(dt || '').toLowerCase().trim();
  var aliases = {
    'int': 'inteiro', 'integer': 'inteiro', 'inteiro': 'inteiro', 'bigint': 'inteiro', 'smallint': 'inteiro', 'tinyint': 'inteiro', 'mediumint': 'inteiro',
    'decimal': 'decimal', 'numeric': 'decimal', 'double': 'decimal', 'float': 'decimal', 'real': 'decimal', 'numero': 'decimal', 'number': 'decimal', 'dec': 'decimal',
    'datetime': 'datetime', 'timestamp': 'datetime', 'timestamptz': 'datetime',
    'date': 'data', 'data': 'data',
    'time': 'hora', 'hora': 'hora',
    'varchar': 'texto', 'text': 'texto', 'texto': 'texto', 'char': 'texto', 'string': 'texto', 'enum': 'texto', 'set': 'texto', 'longtext': 'texto', 'mediumtext': 'texto',
    'boolean': 'bool', 'bool': 'bool', 'tinyint(1)': 'bool', 'bit': 'bool',
    'binary': 'binario', 'binario': 'binario', 'blob': 'binario', 'bytea': 'binario', 'varbinary': 'binario', 'mediumblob': 'binario', 'longblob': 'binario'
  };
  return aliases[key] || key;
}

var DISPLAY_TYPE_MAP = {
  inteiro: 'Número Inteiro', decimal: 'Número Decimal Fixo', datetime: 'Data/Hora',
  data: 'Data', hora: 'Hora', texto: 'Texto', bool: 'True/False', binario: 'Binário'
};

function displayColumnType(col) {
  if (!col) return '';
  var raw = String(col.dataType || col.columnType || col.type || '').split('(')[0].trim().toLowerCase();
  if (!raw) return '';
  var normalized = normalizeDataType(raw);
  return DISPLAY_TYPE_MAP[normalized] || raw.toUpperCase();
}

function buildColumnFormatMapFromSteps(steps) {
  var map = {};
  (steps || []).forEach(function (step) {
    if (step.kind === 'changeType' && step.column) {
      var rawFmt = String(step.format || '').trim();
      var fmt = rawFmt.toLowerCase();
      var type = normalizeDataType(step.dataType);
      var info = { decimals: 2, prefix: '', suffix: '', type: type };

      if (type === 'inteiro' || type === 'decimal') {
        if (fmt && fmt !== 'geral') {
          var dotMatch = fmt.match(/\.(\d+)/);
          if (dotMatch) {
            info.decimals = dotMatch[1].length;
          } else {
            info.decimals = 0;
          }
          if (fmt.indexOf('r$') >= 0) info.prefix = 'R$ ';
          if (fmt.indexOf('%') >= 0) info.suffix = '%';
          if (/e\+00/i.test(fmt)) info.scientific = true;
        } else {
          info.decimals = type === 'inteiro' ? 0 : 2;
        }
      }

      if (type === 'datetime' || type === 'data' || type === 'hora') {
        info.dateType = type;
        info.dateFormat = rawFmt || (type === 'datetime' ? 'dd/MM/yyyy HH:mm' : type === 'data' ? 'dd/MM/yyyy' : 'HH:mm');
      }

      if (type === 'bool') {
        info.boolType = true;
        info.boolFormat = fmt || 'truefalse';
      }

      if (type === 'texto') {
        info.isText = true;
      }

      if (type === 'binario') {
        info.isBinary = true;
      }

      map[step.column] = info;
    }
  });
  return map;
}

function buildColumnFormatMapFromColumns(columns) {
  var map = {};
  (columns || []).forEach(function(col) {
    var name = String(col && (col.name || col.Field) || '').trim();
    if (!name) return;
    var rawType = String(col && (col.dataType || col.columnType || col.type || col.Type) || '').trim();
    var type = normalizeDataType(rawType.split('(')[0]);
    var info = { type: type, prefix: '', suffix: '' };
    if (type === 'inteiro') {
      info.decimals = 0;
    } else if (type === 'decimal') {
      var scaleMatch = rawType.match(/\(\s*\d+\s*,\s*(\d+)\s*\)/);
      info.decimals = scaleMatch ? Number(scaleMatch[1]) : 2;
    } else if (type === 'datetime' || type === 'data' || type === 'hora') {
      info.dateType = type;
      info.dateFormat = type === 'datetime' ? 'dd/MM/yyyy HH:mm' : (type === 'data' ? 'dd/MM/yyyy' : 'HH:mm');
    } else if (type === 'bool') {
      info.boolType = true;
      info.boolFormat = 'truefalse';
    } else if (type === 'texto') {
      info.isText = true;
    } else if (type === 'binario') {
      info.isBinary = true;
    } else {
      return;
    }
    map[name] = info;
  });
  return map;
}

function renderFormatPanelColumns() {
  var select = $('#formatColumnSelect');
  if (!select) return;
  var columns = [];
  try { columns = availableColumnsForTransform(); } catch (e) { columns = []; }
  columns = columns.map(function (c) { return String(c && (c.name || c.Field || c) || c || ''); }).filter(Boolean);
  var previous = select.value;
  select.innerHTML = '<option value="">Selecione...</option>' +
    columns.map(function (c) { return '<option value="' + escapeHtml(c) + '"' + (c === previous ? ' selected' : '') + '>' + escapeHtml(c) + '</option>'; }).join('');
}

function updateFormatStyleSelect() {
  var typeSelect = $('#formatDataTypeSelect');
  var styleSelect = $('#formatStyleSelect');
  if (!typeSelect || !styleSelect) return;
  var type = typeSelect.value;
  var styles = FORMAT_STYLES[type] || [];
  var previous = styleSelect.value;
  styleSelect.innerHTML = styles.length
    ? styles.map(function (s) { return '<option value="' + escapeHtml(s.value) + '"' + (s.value === previous ? ' selected' : '') + '>' + escapeHtml(s.label) + '</option>'; }).join('')
    : '<option value="">Selecione um tipo primeiro...</option>';
}

function applyFormatToColumn() {
  var column = ($('#formatColumnSelect') && $('#formatColumnSelect').value);
  var dataType = ($('#formatDataTypeSelect') && $('#formatDataTypeSelect').value);
  var format = ($('#formatStyleSelect') && $('#formatStyleSelect').value);

  if (!column) return toast('Selecione uma coluna.', 'error');
  if (!dataType) return toast('Selecione um tipo de dados.', 'error');

  var typeEl = $('#formatDataTypeSelect').querySelector('option:checked');
  var typeLabel = typeEl ? typeEl.textContent : dataType;

  var existingIdx = -1;
  (state.transform.steps || []).forEach(function (step, idx) {
    if (step.kind === 'changeType' && step.column === column) {
      existingIdx = idx;
    }
  });

  var step = { kind: 'changeType', column: column, dataType: dataType, appliedAt: new Date().toISOString() };
  if (format !== undefined && format !== null && format !== '') step.format = format;

  if (existingIdx >= 0) {
    step.appliedAt = (state.transform.steps[existingIdx].appliedAt || step.appliedAt);
    state.transform.steps[existingIdx] = step;
    state.transform.selectedStepIndex = existingIdx;
    toast('Formatação atualizada: ' + column + ' (' + typeLabel + ')' + (format ? ', formato: ' + format : ''));
  } else {
    state.transform.steps.push(step);
    state.transform.selectedStepIndex = state.transform.steps.length - 1;
    toast('Formatação aplicada: ' + column + ' (' + typeLabel + ')' + (format ? ', formato: ' + format : ''));
  }

  renderTransformSteps();
  previewTransform().catch(function (err) { toast(err.message, 'error'); });
}

function activateTransformRibbonTab(tabName, options) {
  var config = options || {};
  var tabs = Array.from(document.querySelectorAll('[data-transform-ribbon-tab]'));
  var panels = Array.from(document.querySelectorAll('[data-transform-ribbon-panel]'));
  if (!tabs.length || !panels.length) return;

  var target = tabs.find(function (tab) { return tab.dataset.transformRibbonTab === tabName; }) || tabs[0];
  var activeName = target.dataset.transformRibbonTab;

  tabs.forEach(function (tab) {
    var active = tab === target;
    tab.classList.toggle('active', active);
    tab.setAttribute('aria-selected', active ? 'true' : 'false');
    tab.setAttribute('tabindex', active ? '0' : '-1');
  });
  panels.forEach(function (panel) {
    var active = panel.dataset.transformRibbonPanel === activeName;
    panel.classList.toggle('active', active);
    panel.hidden = !active;
  });

  if (config.focus) target.focus();
}

function initTransformRibbon() {
  var tabs = Array.from(document.querySelectorAll('[data-transform-ribbon-tab]'));
  if (!tabs.length) return;

  tabs.forEach(function (tab, index) {
    tab.addEventListener('click', function () {
      activateTransformRibbonTab(tab.dataset.transformRibbonTab);
    });
    tab.addEventListener('keydown', function (event) {
      var nextIndex = index;
      if (event.key === 'ArrowRight') nextIndex = (index + 1) % tabs.length;
      else if (event.key === 'ArrowLeft') nextIndex = (index - 1 + tabs.length) % tabs.length;
      else if (event.key === 'Home') nextIndex = 0;
      else if (event.key === 'End') nextIndex = tabs.length - 1;
      else return;
      event.preventDefault();
      activateTransformRibbonTab(tabs[nextIndex].dataset.transformRibbonTab, { focus: true });
    });
  });

  var selected = tabs.find(function (tab) { return tab.getAttribute('aria-selected') === 'true'; }) || tabs[0];
  activateTransformRibbonTab(selected.dataset.transformRibbonTab);
}

function initFormatPanel() {
  var panel = $('#transformFormatPanel');
  var toggleBtn = $('#toggleFormatPanelBtn');
  if (!panel) return;

  if (toggleBtn) {
    toggleBtn.addEventListener('click', function () {
      var collapsed = panel.classList.toggle('collapsed');
      toggleBtn.textContent = collapsed ? '+' : '\u2212';
      toggleBtn.title = collapsed ? 'Expandir painel de formatação' : 'Recolher painel de formatação';
    });
  }

  var typeSelect = $('#formatDataTypeSelect');
  if (typeSelect) {
    typeSelect.addEventListener('change', updateFormatStyleSelect);
  }

  var applyBtn = $('#applyFormatBtn');
  if (applyBtn) {
    applyBtn.addEventListener('click', applyFormatToColumn);
  }

  var historyBtn = $('#formatHistoryBtn');
  if (historyBtn) {
    historyBtn.addEventListener('click', openFormatHistoryModal);
  }
}

var FORMAT_DATA_TYPE_LABELS = {
  inteiro: 'Número Inteiro', decimal: 'Número Decimal Fixo', datetime: 'Data/Hora',
  data: 'Data', hora: 'Hora', texto: 'Texto', bool: 'True/False', binario: 'Binário'
};

function openFormatHistoryModal() {
  var modal = $('#formatHistoryModal');
  var body = $('#formatHistoryBody');
  if (!modal || !body) return;

  var formatSteps = [];
  (state.transform.steps || []).forEach(function (step, idx) {
    if (step.kind === 'changeType' && step.column) {
      formatSteps.push({ step: step, index: idx });
    }
  });

  if (!formatSteps.length) {
    body.innerHTML = '<div class="empty-state">Nenhuma formatação de coluna aplicada até o momento. Use o painel "Formatação de coluna" para definir tipos e formatos.</div>';
  } else {
    var rows = formatSteps.map(function (entry, i) {
      var step = entry.step;
      var typeLabel = FORMAT_DATA_TYPE_LABELS[normalizeDataType(step.dataType)] || step.dataType || '—';
      var formatLabel = step.format || '';
      var appliedAt = step.appliedAt ? new Date(step.appliedAt).toLocaleString('pt-BR') : '—';
      return '<tr>' +
        '<td><span class="hist-col">' + escapeHtml(step.column) + '</span></td>' +
        '<td><span class="hist-type">' + escapeHtml(typeLabel) + '</span></td>' +
        '<td><span class="hist-format">' + escapeHtml(formatLabel) + '</span></td>' +
        '<td><span class="hist-time" style="font-size:11px;color:var(--muted);white-space:nowrap">' + escapeHtml(appliedAt) + '</span></td>' +
        '<td><button class="btn ghost danger undo-format-btn" data-step-index="' + entry.index + '" data-step-column="' + escapeHtml(step.column) + '">Desfazer</button></td>' +
        '</tr>';
    }).join('');

    body.innerHTML = '<table class="format-history-table"><thead><tr><th>Coluna</th><th>Tipo de dados</th><th>Formato</th><th>Data/Hora</th><th></th></tr></thead><tbody>' + rows + '</tbody></table>';

    var undoButtons = body.querySelectorAll('.undo-format-btn');
    undoButtons.forEach(function (btn) {
      btn.addEventListener('click', function () {
        var stepIndex = parseInt(btn.dataset.stepIndex, 10);
        var colName = btn.dataset.stepColumn;
        undoFormatStep(stepIndex, colName);
      });
    });
  }

  modal.classList.remove('hidden');
}

function closeFormatHistoryModal() {
  var modal = $('#formatHistoryModal');
  if (modal) modal.classList.add('hidden');
}

function undoFormatStep(stepIndex, colName) {
  if (stepIndex < 0 || stepIndex >= (state.transform.steps || []).length) return;
  state.transform.steps.splice(stepIndex, 1);
  renderTransformSteps();
  renderFormatPanelColumns();
  openFormatHistoryModal();
  previewTransform().catch(function (err) { toast(err.message, 'error'); });
  toast('Formatação de "' + colName + '" desfeita.', 'info');
}


function mysqlResourcesForInsert() {
  return (state.mysqlResources || []).filter((item) => item && (item.source === 'mysql' || item.source === 'manual' || item.type === 'view') && !item.nativeCalendar && item.source !== 'transform' && item.source !== 'mysql-import');
}

function suggestedAliasFromSource(name) {
  return String(name || '')
    .replace(/^[a-z]+_/i, '')
    .replace(/[_\-]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .replace(/\b\w/g, (m) => m.toUpperCase())
    .replace(/\s+/g, '_') || String(name || 'Tabela');
}

async function loadMysqlResourcesForInsert() {
  try {
    const data = await api('/api/tables?scope=mysql&ts=' + Date.now());
    state.mysqlResources = Array.isArray(data.resources) ? data.resources : [];
  } catch (err) {
    state.mysqlResources = [];
  }
}

async function loadImportedTables() {
  try {
    const data = await api('/api/imported-tables?ts=' + Date.now());
    state.importedTables = Array.isArray(data.imported) ? data.imported : [];
  } catch (err) {
    state.importedTables = [];
  }
  try {
    const manData = await api('/api/manual-tables?ts=' + Date.now());
    if (manData && Array.isArray(manData.tables)) {
      manData.tables.forEach(function(mt) {
        if (!state.importedTables.some(function(i) { return String(i.name || '').toLowerCase() === String(mt.name || '').toLowerCase(); })) {
          state.importedTables.push({ name: mt.name, sourceTable: mt.name, manual: true, note: 'Tabela manual (PG)', rowFilter: null, dateFilter: null, steps: [], incrementalColumn: null });
        }
      });
    }
  } catch (err) {}
  try { renderTransformSteps(); } catch (e) { /* ignora */ }
  renderInsertDataPanel();
}

async function loadHiddenTables() {
  try {
    const data = await api('/api/hidden-tables?ts=' + Date.now());
    state.hiddenTables = Array.isArray(data.hidden) ? data.hidden : [];
  } catch (err) {
    state.hiddenTables = [];
  }
  renderInsertDataPanel();
}

async function loadPostgresCachePanel() {
  try {
    const data = await api('/api/postgres-cache/diagnostics?ts=' + Date.now(), { timeoutMs: 12000 });
    state.pgCache = {
      available: Boolean(data.available),
      enabled: Boolean(data.enabled),
      connected: Boolean(data.connected),
      error: data.error || '',
      config: data.config || {},
      caches: Array.isArray(data.caches) ? data.caches : []
    };
    // Atualiza o dashboard somente com a data em que o cache recebeu dados novos ou alterados.
    const caches = state.pgCache.caches || [];
    let latestDataUpdateAt = null;
    for (const c of caches) {
      if (c.lastDataUpdateAt) {
        const d = new Date(c.lastDataUpdateAt);
        if (!isNaN(d.getTime()) && (!latestDataUpdateAt || d > latestDataUpdateAt)) {
          latestDataUpdateAt = d;
        }
      }
    }
    if (latestDataUpdateAt) {
      state.dashboardLastUpdated = latestDataUpdateAt.toISOString();
      setDashboardLastUpdate();
    }
    if (data.lastCycleCompletedAt) {
      state.lastCycleCompletedAt = data.lastCycleCompletedAt;
      var cycleMs = new Date(data.lastCycleCompletedAt).getTime();
      if (cycleMs && Number.isFinite(cycleMs) && (!latestDataUpdateAt || cycleMs > latestDataUpdateAt.getTime())) {
        state.dashboardLastUpdated = data.lastCycleCompletedAt;
        setDashboardLastUpdate();
      }
    }
  } catch (err) {
    state.pgCache = { available: false, enabled: false, connected: false, error: err.message, caches: [] };
  }
  renderInsertDataPanel();
}

function pgCacheStatusForTable(name) {
  const key = String(name || '').toLowerCase();
  const caches = state.pgCache && state.pgCache.caches || [];
  let cache = caches.find((item) => String(item.sourceTable || '').toLowerCase() === key || String(item.physicalTable || '').toLowerCase() === key);
  if (cache) return cache;
  const imported = (state.importedTables || []).find((item) => String(item.name || '').toLowerCase() === key);
  if (imported && imported.sourceTable) {
    const srcKey = String(imported.sourceTable).toLowerCase();
    cache = caches.find((item) => String(item.sourceTable || '').toLowerCase() === srcKey || String(item.physicalTable || '').toLowerCase() === srcKey);
  }
  return cache || null;
}

function renderPgCacheStatusMini(name) {
  const pg = state.pgCache || {};
  if (!pg.available) return '';
  if (!pg.enabled) return '<small class="cache-status muted">PostgreSQL cache desativado</small>';
  if (!pg.connected) return `<small class="cache-status danger">PostgreSQL desconectado${pg.error ? ': ' + escapeHtml(pg.error) : ''}</small>`;
  const cache = pgCacheStatusForTable(name);
  if (!cache || !cache.exists) return '<small class="cache-status muted">Cache PostgreSQL ainda não sincronizado</small>';
  const synced = cache.syncedAt ? formatDateTimePtBr(cache.syncedAt) : 'sem data';
  const rows = Number(cache.rowCount || 0).toLocaleString('pt-BR');
  const mode = cache.syncMode ? ' • ' + escapeHtml(cache.syncMode) : '';
  const col = cache.syncColumn ? ' • ' + escapeHtml(cache.syncColumn) : '';
  return `<small class="cache-status ok">Cache PostgreSQL: ${rows} linhas • ${escapeHtml(synced)}${mode}${col}</small>`;
}

function renderPgCacheRowCount(name) {
  const cache = pgCacheStatusForTable(name);
  if (!cache || !cache.exists || !cache.rowCount) return '';
  const rows = Number(cache.rowCount).toLocaleString('pt-BR');
  return `<span class="row-count-badge">${rows} linhas</span>`;
}

function renderMysqlStatusBadge() {
  if (state.dashboardOnline) {
    return `<span class="mysql-status-badge online" title="MySQL conectado - recebendo novos dados para atualizar o PostgreSQL">● Online</span>`;
  }
  return `<span class="mysql-status-badge offline" title="MySQL indisponível - app funcional pelo PostgreSQL, sem receber novos dados">● Offline</span>`;
}

function openCardPopover(anchor, name) {
  closeCardPopover();
  var isManual = anchor.dataset.cardManual === '1';
  var item = null;
  if (isManual) {
    item = (state.resources || []).find(function(r) { return r.name === name && r.manual; }) || { name: name, manual: true };
  } else {
    item = (state.importedTables || []).find(function(t) { return t.name === name; });
  }
  if (!item) return;
  var popover = document.createElement('div');
  popover.className = 'card-action-popover open';
  popover.dataset.cardPopover = name;
  var items;
  if (isManual) {
    items = [
      { label: 'Abrir tabela', icon: '⊞', action: function() { setActiveTab('tableTab'); selectTable(name).catch(function(err) { toast(err.message, 'error'); }); }, cls: '' },
      { label: 'Editar dados', icon: '✐', action: function() { editManualTableData(name).catch(function(err) { toast(err.message, 'error'); }); }, cls: '' },
      { label: 'Renomear', icon: '✎', action: function() { renameManualTable(name).catch(function(err) { toast(err.message, 'error'); }); }, cls: '' },
      { divider: true },
      { label: 'Excluir tabela', icon: '🗑', action: function() { deleteManualTable(name).catch(function(err) { toast(err.message, 'error'); }); }, cls: 'danger' }
    ];
  } else {
    items = [
      { label: 'Abrir tabela', icon: '⊞', action: function() { setActiveTab('tableTab'); selectTable(name).catch(function(err) { toast(err.message, 'error'); }); }, cls: '' },
      { label: 'Incremental', icon: '↻', action: function() { openImportedTableIncrementalModal(name); }, cls: '' },
      { label: 'Editar nome', icon: '✎', action: function() { startEditImportedTable(name); }, cls: '' },
      { divider: true },
      { label: 'Atualizar cache', icon: '⇈', action: function() { syncPostgresCacheForTable(name, 'incremental').catch(function(err) { toast(err.message, 'error'); }); }, cls: '' },
      { label: 'Recarregar completo', icon: '⟳', action: function() { syncPostgresCacheForTable(name, 'full').catch(function(err) { toast(err.message, 'error'); }); }, cls: '' },
      { label: 'Limpar cache', icon: '✕', action: function() { clearPostgresCacheForTable(name).catch(function(err) { toast(err.message, 'error'); }); }, cls: '' },
      { divider: true },
      { label: 'Remover do app', icon: '🗑', action: function() { removeImportedTable(name).catch(function(err) { toast(err.message, 'error'); }); }, cls: 'danger' }
    ];
  }
  popover.innerHTML = items.map(function(it) {
    if (it.divider) return '<div class="popover-divider"></div>';
    return '<button class="popover-item ' + it.cls + '">' + (it.icon ? '<span class="popover-icon">' + it.icon + '</span>' : '') + escapeHtml(it.label) + '</button>';
  }).join('');
  document.body.appendChild(popover);
  var rect = anchor.getBoundingClientRect();
  var popRect = popover.getBoundingClientRect();
  var top = rect.bottom + 4;
  var left = rect.left + rect.width - popRect.width;
  if (left < 8) left = rect.left;
  if (top + popRect.height > window.innerHeight - 8) top = rect.top - popRect.height - 4;
  if (left + popRect.width > window.innerWidth - 8) left = window.innerWidth - popRect.width - 8;
  popover.style.top = Math.max(4, top) + 'px';
  popover.style.left = Math.max(4, left) + 'px';
  var backdrop = document.createElement('div');
  backdrop.className = 'popover-backdrop open';
  backdrop.addEventListener('click', closeCardPopover);
  document.body.appendChild(backdrop);
  popover.querySelectorAll('.popover-item').forEach(function(btn, i) {
    var actionItems = items.filter(function(it) { return !it.divider; });
    var actionItem = actionItems[i];
    btn.addEventListener('click', function(ev) {
      ev.stopPropagation();
      if (actionItem && actionItem.action) actionItem.action();
      closeCardPopover();
    });
  });
  popover._backdrop = backdrop;
}

async function deleteManualTable(name) {
  if (!can('schemaChanges')) return toast('Exclusao de tabelas esta bloqueada em Configuracao.', 'error');
  if (!confirm('Excluir permanentemente a tabela manual "' + name + '" e todos os seus dados?')) return;
  await api('/api/tables/' + encodeURIComponent(name), { method: 'DELETE' });
  toast('Tabela manual excluida: ' + name);
  await loadTables();
  await loadImportedTables();
  await loadModel();
  loadManualCards();
  renderAlterTableSelect();
  if (state.selectedTable === name) { state.selectedTable = ''; state.selectedResource = null; state.columns = []; state.rows = []; renderTablesList(); }
}

async function editManualTableData(name) {
  if (!can('tableWrites')) return toast('Edicao de dados esta bloqueada em Configuracao.', 'error');
  var data = await api('/api/tables/' + encodeURIComponent(name) + '/data');
  var allColumns = data.columns || [];
  var primaryKeyColumns = allColumns.filter(function(col) { return col.columnKey === 'PRI' || col.key === 'PRI'; });
  var visibleCols = allColumns.filter(function(col) { return !((col.columnKey === 'PRI' || col.key === 'PRI') && /auto_increment/i.test(col.extra || '')); });
  var sourceRows = data.rows || [];
  var rows = sourceRows.map(function(row) {
    return visibleCols.map(function(col) {
      var v = row[col.name];
      if (v == null) return '';
      return formatCellForGrid(String(v), col.dataType || col.columnType || 'text');
    });
  });
  state.manualGrid = {
    columns: visibleCols.map(function(col) { return { name: col.name, type: mapPgTypeToManual(col.dataType || col.columnType || 'text'), format: '' }; }),
    rows: rows.length ? rows : [],
    rowKeys: sourceRows.map(function(row) {
      var key = {};
      primaryKeyColumns.forEach(function(col) { key[col.name] = row[col.name]; });
      return Object.keys(key).length ? key : null;
    })
  };
  openManualTableModal(name);
}

function mapPgTypeToManual(pgType) {
  var t = String(pgType || '').toLowerCase();
  if (/int|integer|serial|bigint|smallint/i.test(t)) return 'inteiro';
  if (/decimal|numeric|double|float|real/i.test(t)) return 'decimal';
  if (/timestamp|datetime/i.test(t)) return 'datetime';
  if (/date/i.test(t)) return 'data';
  if (/time/i.test(t)) return 'hora';
  if (/bool|boolean/i.test(t)) return 'bool';
  if (/json|jsonb/i.test(t)) return 'texto';
  return 'texto';
}

async function renameManualTable(oldName) {
  if (!can('schemaChanges')) return toast('Alteracao de tabelas esta bloqueada em Configuracao.', 'error');
  var newName = prompt('Novo nome para a tabela:', oldName);
  if (!newName || newName.trim() === oldName || !newName.trim()) return;
  newName = newName.trim();
  await api('/api/tables/' + encodeURIComponent(oldName) + '/rename', { method: 'PATCH', body: JSON.stringify({ name: newName }) });
  toast('Tabela renomeada: ' + oldName + ' → ' + newName);
  invalidateModelColumnCache(oldName, newName);
  await loadTables();
  await loadImportedTables();
  await loadModel();
  renderAlterTableSelect();
  if (state.selectedTable === oldName) { state.selectedTable = newName; await selectTable(newName); }
}

function closeCardPopover() {
  const existing = document.querySelector('.card-action-popover.open');
  if (existing) {
    if (existing._backdrop) existing._backdrop.remove();
    existing.remove();
  }
  const backdrop = document.querySelector('.popover-backdrop.open');
  if (backdrop) backdrop.remove();
}

// Close popover on escape key
document.addEventListener('keydown', (ev) => {
  if (ev.key === 'Escape') closeCardPopover();
});

function refreshCardMysqlStatus() {
  const list = $('#importedTablesList');
  if (!list || !list.querySelector('.imported-table-card')) return;
  const badges = list.querySelectorAll('.mysql-status-badge');
  if (!badges.length) return;
  const html = renderMysqlStatusBadge();
  badges.forEach((badge) => {
    badge.outerHTML = html;
  });
}

function updateSyncProgressBar() {
  const panel = $('#insertDataLayout');
  if (!panel) return;
  const existing = panel.querySelector('.sync-progress-area');
  if (existing) existing.remove();
  const progressBar = state.syncProgress && state.syncProgress.cacheType === 'pg' ? renderSyncProgressBar() : '';
  if (progressBar) {
    const div = document.createElement('div');
    div.className = 'sync-progress-area';
    div.innerHTML = progressBar;
    panel.insertBefore(div, panel.firstChild);
  }
}

function renderInsertDataPanel() {
  loadManualCards();
  renderInsertDataPanelInner();
  if (!state._firstInsertRender) {
    state._firstInsertRender = true;
    setTimeout(function() { loadManualCards(); }, 400);
    setTimeout(function() { loadManualCards(); }, 1500);
    setTimeout(function() { loadManualCards(); }, 4000);
  }
}

async function loadManualCards() {
  try {
    var data = await api('/api/manual-tables?ts=' + Date.now());
    if (!data || !Array.isArray(data.tables)) return;
    state._manualTables = data.tables;
    renderInsertDataPanelInner();
  } catch (e) {}
}

function renderInsertDataPanelInner() {
  const select = $('#insertSourceTableSelect');
  if (select) {
    const resources = mysqlResourcesForInsert();
    select.innerHTML = resources.length
      ? resources.map((item) => `<option value="${escapeHtml(item.physicalName || item.name)}">${escapeHtml(item.name)}${item.type === 'view' ? ' (view)' : ''}</option>`).join('')
      : '<option value="">Nenhuma tabela MySQL carregada</option>';
    const alias = $('#insertAliasInput');
    if (alias && !alias.value.trim() && select.value) alias.value = suggestedAliasFromSource(select.value);
  }
  const panel = $('#insertDataLayout');
  if (panel) {
    const existing = panel.querySelector('.sync-progress-area');
    if (existing) existing.remove();
    const progressBar = state.syncProgress && state.syncProgress.cacheType === 'pg' ? renderSyncProgressBar() : '';
    if (progressBar) {
      const div = document.createElement('div');
      div.className = 'sync-progress-area';
      div.innerHTML = progressBar;
      panel.insertBefore(div, panel.firstChild);
    }
  }
  const list = $('#importedTablesList');
  if (list) {
    var manualItems = [];
    if (state._manualTables && state._manualTables.length) {
      manualItems = state._manualTables.map(function(mt) { return { name: mt.name, sourceTable: mt.name, manual: true, note: 'Tabela manual (PG)', rowFilter: null, dateFilter: null, steps: [], incrementalColumn: null }; });
    }
    var allItems = state.importedTables.concat(manualItems.filter(function(m) { return !state.importedTables.some(function(i) { return String(i.name || '').toLowerCase() === String(m.name || '').toLowerCase(); }); }));
    if (!allItems.length) {
      list.className = 'imported-tables-grid empty-state';
      list.textContent = 'Nenhuma tabela inserida. Selecione uma tabela MySQL e clique em Trazer para o app.';
    } else {
      list.className = 'imported-tables-grid';
      const bs = state.batchSync || {};
      list.innerHTML = allItems.map((item) => {
        var rowCount = renderPgCacheRowCount(item.name);
        var mysqlBadge = item.manual ? '' : renderMysqlStatusBadge();
        var cacheStatus = item.manual ? '' : renderPgCacheStatusMini(item.name);
        var incrementalInfo = item.incrementalColumn
          ? `<small>Inc: <b>${escapeHtml(item.incrementalColumn)}</b></small>`
          : '';
        var filterInfo = item.rowFilter && item.rowFilter.column
          ? `<small>Filtro: ${escapeHtml(item.rowFilter.column)}</small>`
          : '';
        var accentClass = item.name === 'Calendario' ? 'card-accent-calendar' : (item.manual ? 'card-accent-manual' : 'card-accent-table');
        var isSyncing = !item.manual && bs.running && bs.currentName === item.name;
        var isDone = !item.manual && bs.success && bs.success.includes(item.name);
        var isError = !item.manual && bs.errors && bs.errors.includes(item.name);
        var statusClass = accentClass;
        if (isSyncing) { statusClass += ' syncing'; }
        else if (isDone) { statusClass += ' sync-done'; }
        else if (isError) { statusClass += ' sync-error'; }
        var sourceLabel = item.manual ? '<small class="source-label" style="color:#f97316;font-weight:600">Tabela manual</small>' : `<small class="source-label">${escapeHtml(item.sourceTable)}</small>`;
        return `<div class="imported-table-card ${statusClass}" data-card-name="${escapeHtml(item.name)}">
          <div class="card-body">
            <strong>${escapeHtml(item.name)} ${mysqlBadge} ${rowCount}</strong>
            <div class="card-meta">
              ${sourceLabel}
              ${incrementalInfo}
              ${filterInfo}
            </div>
            ${cacheStatus}
          </div>
          ${isSyncing ? `<div class="card-sync-spinner"></div>` : (item.name === 'Calendario' ? '' : `<button class="card-actions-btn" data-card-menu="${escapeHtml(item.name)}" data-card-manual="${item.manual ? '1' : '0'}" title="Acoes">⋮</button>`)}
        </div>`;
      }).join('');
      list.querySelectorAll('[data-card-name]').forEach((card) => {
        card.addEventListener('click', (ev) => {
          if (ev.target.closest('.card-actions-btn')) return;
          const name = card.dataset.cardName;
          const btn = card.querySelector('.card-actions-btn');
          if (btn) openCardPopover(btn, name);
        });
      });
      list.querySelectorAll('[data-card-menu]').forEach((btn) => {
        btn.addEventListener('click', (ev) => {
          ev.stopPropagation();
          openCardPopover(btn, btn.dataset.cardMenu);
        });
      });
    }
  }
  // Batch sync status in header
  const statusEl = $('#batchSyncStatus');
  const syncBtn = $('#batchSyncAllBtn');
  if (statusEl && syncBtn) {
    const bs = state.batchSync;
    if (bs && bs.running && !bs.cancelled) {
      statusEl.style.display = 'inline-flex';
      syncBtn.textContent = 'Cancelar';
      syncBtn.className = 'btn mini danger';
      syncBtn.disabled = false;
      const pct = bs.total > 0 ? Math.round((bs.current / bs.total) * 100) : 0;
      statusEl.className = 'batch-sync-status';
      statusEl.innerHTML = `<div class="batch-spinner"></div> ${bs.current}/${bs.total} · ${bs.currentName || '...'} (${pct}%)`;
    } else if (bs && !bs.running && bs.total > 0) {
      statusEl.style.display = 'inline-flex';
      syncBtn.textContent = 'Atualizar';
      syncBtn.className = 'btn mini primary';
      syncBtn.disabled = false;
      const errs = bs.errors.length;
      statusEl.className = 'batch-sync-status' + (errs > 0 ? ' batch-error' : ' batch-done');
      statusEl.innerHTML = `<span>${errs > 0 ? '⚠' : '✓'}</span> ${bs.success.length}/${bs.total} concluído${errs > 0 ? ' · ' + errs + ' erro(s)' : ''}`;
    } else {
      statusEl.style.display = 'none';
      syncBtn.textContent = 'Atualizar';
      syncBtn.className = 'btn mini primary';
      syncBtn.disabled = false;
    }
  }
  const hiddenList = $('#hiddenTablesList');
  if (hiddenList) {
    if (!state.hiddenTables.length) {
      hiddenList.className = 'imported-tables-list empty-state';
      hiddenList.textContent = 'Nenhuma tabela removida do app.';
    } else {
      hiddenList.className = 'imported-tables-list';
      hiddenList.innerHTML = state.hiddenTables.map((item) => `
        <div class="imported-table-card hidden-table-card">
          <div>
            <strong>${escapeHtml(item.name)}</strong>
            <small>${escapeHtml(item.type || 'tabela')} removida do app</small>
          </div>
          <div class="imported-card-actions">
            <button class="btn mini secondary" data-restore-hidden-table="${escapeHtml(item.name)}">Restaurar</button>
          </div>
        </div>
      `).join('');
      hiddenList.querySelectorAll('[data-restore-hidden-table]').forEach((btn) => {
        btn.addEventListener('click', () => restoreHiddenTable(btn.dataset.restoreHiddenTable).catch((err) => toast(err.message, 'error')));
      });
    }
  }
  const status = $('#insertDataStatus');
  if (status) {
    const pg = state.pgCache || {};
    const pgCaches = Array.isArray(pg.caches) ? pg.caches.filter((item) => item && item.exists).length : 0;
    const pgText = pg.connected ? ` | PostgreSQL conectado | ${pgCaches} cache(s)` : (pg.enabled ? ' | PostgreSQL pendente' : ' | cache PG desativado');
    status.textContent = `${state.importedTables.length || 0} inseridas | ${state.hiddenTables.length || 0} removidas do app${pgText}`;
  }
  const updateBtn = $('#updateImportedTableBtn');
  if (updateBtn) {
    updateBtn.disabled = !state.importedTableEditName;
    updateBtn.textContent = state.importedTableEditName ? 'Atualizar nome' : 'Atualizar nome';
    updateBtn.title = state.importedTableEditName ? ('Atualizar tabela inserida: ' + state.importedTableEditName) : 'Clique em Editar nome em uma tabela inserida para atualizar.';
  }
}

function startEditImportedTable(name) {
  const item = (state.importedTables || []).find((row) => row.name === name || String(row.name || '').toLowerCase() === String(name || '').toLowerCase());
  if (!item) return toast('Tabela inserida nao encontrada.', 'error');
  state.importedTableEditName = item.name;
  const select = $('#insertSourceTableSelect');
  if (select) select.value = item.sourceTable;
  if ($('#insertAliasInput')) $('#insertAliasInput').value = item.name;
  if ($('#insertNoteInput')) $('#insertNoteInput').value = item.note || '';
  renderInsertDataPanel();
  const target = $('#insertColumnsPreview');
  if (target) {
    target.className = 'insert-columns-preview empty-state';
    target.textContent = 'Clique em Prévia colunas para revisar os campos, se necessário.';
  }
  toast('Edite o nome no app e clique em Atualizar nome.');
}

function clearImportedTableEdit() {
  state.importedTableEditName = '';
  const alias = $('#insertAliasInput');
  const select = $('#insertSourceTableSelect');
  if (alias && select && select.value) alias.value = suggestedAliasFromSource(select.value);
  renderInsertDataPanel();
}


async function syncPostgresCacheForTable(name, mode = 'incremental', skipConfirm) {
  if (!name) return;
  if (state.syncProgress && state.syncProgress.table === name && (state.syncProgress.status === 'copying' || state.syncProgress.status === 'indexing')) {
    toast('Sincronizacao ja em andamento para ' + name + '. Aguarde a conclusao.', 'warning');
    return;
  }
  const full = String(mode || '').toLowerCase() === 'full';
  if (full && !skipConfirm && !confirm('Recarregar o cache completo de "' + name + '"? O MySQL não será alterado, mas a sincronização pode demorar.')) return;
  state.syncProgress = { table: name, cacheType: 'pg', percent: 0, rowsCopied: 0, totalRows: 0, status: 'copying' };
  renderTableResult();
  renderInsertDataPanel();
  let pollTimer = null;
  try {
    const syncPromise = api('/api/postgres-cache/' + encodeURIComponent(name) + '/sync', {
      method: 'POST',
      timeoutMs: 60 * 60 * 1000,
      body: JSON.stringify({ mode: full ? 'full' : 'incremental' })
    });
    pollTimer = setInterval(async () => {
      try {
        const p = await api('/api/postgres-cache/progress?table=' + encodeURIComponent(name), { timeoutMs: 5000 });
        if (p && p.progress) {
          state.syncProgress = {
            table: name, cacheType: 'pg',
            percent: p.progress.percent || 0,
            rowsCopied: p.progress.rowsCopied || 0,
            totalRows: p.progress.totalRows || 0,
            status: p.progress.phase || p.progress.status || 'copying',
            phase: p.progress.phase || '',
            subPhase: p.progress.subPhase || '',
            subPercent: p.progress.subPercent || 0
          };
          renderTableResult();
          updateSyncProgressBar();
        }
      } catch (e) { /* ignora erros de poll */ }
    }, 600);
    const data = await syncPromise;
    if (pollTimer) { clearInterval(pollTimer); pollTimer = null; }
    state.syncProgress = { table: name, cacheType: 'pg', percent: 100, rowsCopied: data.rowCount || 0, totalRows: data.rowCount || 0, status: 'done' };
    renderTableResult();
    renderInsertDataPanel();
    const rows = data.changedRows !== undefined ? data.changedRows : data.rowCount;
    toast('Cache PostgreSQL atualizado: ' + name + ' (' + Number(rows || 0).toLocaleString('pt-BR') + ' linhas processadas)');
    await loadPostgresCachePanel();
    return true;
  } catch (err) {
    if (pollTimer) { clearInterval(pollTimer); pollTimer = null; }
    state.syncProgress = { table: name, cacheType: 'pg', percent: 0, rowsCopied: 0, totalRows: 0, status: 'error' };
    renderTableResult();
    renderInsertDataPanel();
    toast(err.message || String(err), 'error');
    return false;
  } finally {
    if (pollTimer) { clearInterval(pollTimer); pollTimer = null; }
    state.syncProgress = null;
    renderTableResult();
    renderInsertDataPanel();
  }
}

async function clearPostgresCacheForTable(name) {
  if (!name) return;
  if (!confirm('Limpar o cache PostgreSQL de "' + name + '"? O MySQL original não será alterado.')) return;
  await api('/api/postgres-cache/' + encodeURIComponent(name), { method: 'DELETE', timeoutMs: 30000 });
  toast('Cache PostgreSQL limpo: ' + name);
  await loadPostgresCachePanel();
}

async function updateAllImportedTables() {
  const tables = state.importedTables || [];
  if (!tables.length) return toast('Nenhuma tabela inserida para atualizar.', 'warning');
  if (state.batchSync && state.batchSync.running) return toast('Ja existe uma atualizacao em andamento.', 'warning');
  state.batchSync = { running: true, total: tables.length, current: 0, currentName: '', success: [], errors: [], cancelled: false };
  renderInsertDataPanel();
  for (let i = 0; i < tables.length; i++) {
    if (state.batchSync.cancelled) break;
    const name = tables[i].name;
    if (!name) continue;
    state.batchSync.current = i + 1;
    state.batchSync.currentName = name;
    renderInsertDataPanel();
    const ok = await syncPostgresCacheForTable(name, 'full', true);
    if (state.batchSync.cancelled) break;
    if (ok) {
      state.batchSync.success.push(name);
    } else {
      state.batchSync.errors.push(name);
    }
    state.batchSync.currentName = '';
    renderInsertDataPanel();
  }
  const wasCancelled = state.batchSync.cancelled;
  state.batchSync.running = false;
  renderInsertDataPanel();
  const totalSuccess = state.batchSync.success.length;
  const totalErrors = state.batchSync.errors.length;
  if (wasCancelled) {
    toast('Atualizacao cancelada. ' + totalSuccess + ' concluida(s), ' + totalErrors + ' erro(s).', 'warning');
  } else if (totalErrors > 0) {
    toast('Atualizacao concluida: ' + totalSuccess + ' ok, ' + totalErrors + ' erro(s).', 'warning');
  } else {
    toast('Todas as ' + totalSuccess + ' tabela(s) atualizada(s) com sucesso.', 'success');
  }
  state.batchSync = null;
  renderInsertDataPanel();
}

function cancelBatchSync() {
  if (state.batchSync && state.batchSync.running) {
    state.batchSync.cancelled = true;
    renderInsertDataPanel();
  }
}

async function openImportedTableIncrementalModal(tableName) {
  const item = (state.importedTables || []).find((row) => row.name === tableName);
  if (!item) return toast('Tabela nao encontrada.', 'error');
  let columns = [];
  try { columns = await ensureTransformColumnsLoadedFor(item.name); } catch (err) { columns = []; }
  columns = columns.map((c) => String(c && (c.name || c.Field || c) || c || '')).filter(Boolean);
  if (!columns.length) return toast('Nao foi possivel carregar as colunas da tabela.', 'error');
  const selectedCol = item.incrementalColumn || '';
  const html = `
    <div class="modal-card filter-imported-modal-card" style="max-height:85vh;overflow:auto">
      <button class="modal-close" id="closeIncrementalModalBtn" type="button">×</button>
      <p class="eyebrow">Atualizacao incremental</p>
      <h3>${escapeHtml(item.name)}</h3>
      <p class="sub">Selecione uma coluna numerica ou de data que sera usada como referencia para a atualizacao incremental. A cada sincronizacao, apenas linhas com valores maiores do que o ultimo maximo serao importadas.</p>
      <label>Coluna incremental<select id="incrementalColumn">${columns.map((c) => `<option value="${escapeHtml(c)}" ${c === selectedCol ? 'selected' : ''}>${escapeHtml(c)}</option>`).join('')}</select></label>
      <div class="actions right" style="margin-top:12px">
        <button class="btn secondary" id="clearIncrementalBtn">Remover incremental</button>
        <button class="btn primary" id="saveIncrementalBtn">Salvar</button>
      </div>
    </div>`;
  const backdrop = document.createElement('div');
  backdrop.className = 'modal';
  backdrop.innerHTML = html;
  document.body.appendChild(backdrop);
  const close = () => backdrop.remove();
  backdrop.querySelector('#closeIncrementalModalBtn').addEventListener('click', close);
  backdrop.addEventListener('click', (e) => { if (e.target === backdrop) close(); });

  backdrop.querySelector('#clearIncrementalBtn').addEventListener('click', async () => {
    try {
      await api('/api/imported-tables/' + encodeURIComponent(item.name), { method: 'PUT', body: JSON.stringify({ sourceTable: item.sourceTable, name: item.name, incrementalColumn: null }) });
      toast('Incremental removido da tabela ' + item.name);
      close();
      await loadImportedTables();
    } catch (err) { toast(err.message, 'error'); }
  });

  backdrop.querySelector('#saveIncrementalBtn').addEventListener('click', async () => {
    const col = backdrop.querySelector('#incrementalColumn').value;
    if (!col) return toast('Selecione uma coluna.', 'error');
    try {
      await api('/api/imported-tables/' + encodeURIComponent(item.name), { method: 'PUT', body: JSON.stringify({ sourceTable: item.sourceTable, name: item.name, incrementalColumn: col }) });
      toast('Incremental salvo: ' + item.name + ' — coluna ' + col);
      close();
      await loadImportedTables();
    } catch (err) { toast(err.message, 'error'); }
  });
}

async function openImportedTableFilterModal(tableName) {
  const item = (state.importedTables || []).find((row) => row.name === tableName);
  if (!item) return toast('Tabela nao encontrada.', 'error');
  // Carrega colunas da tabela
  let columns = [];
  try { columns = await ensureTransformColumnsLoadedFor(item.name); } catch (err) { columns = []; }
  columns = columns.map((c) => String(c && (c.name || c.Field || c) || c || '')).filter(Boolean);
  if (!columns.length) return toast('Nao foi possivel carregar as colunas da tabela.', 'error');
  const rowFilter = item.rowFilter || { column: '', values: [] };
  const selectedCol = rowFilter.column || '';
  const selectedValues = new Set((rowFilter.values || []).map(String));
  const html = `
    <div class="modal-card filter-imported-modal-card" style="max-height:85vh;overflow:auto">
      <button class="modal-close" id="closeFilterImportedModalBtn" type="button">×</button>
      <p class="eyebrow">Filtro de linhas da tabela</p>
      <h3>${escapeHtml(item.name)}</h3>
      <p class="sub">Selecione a coluna e desmarque os valores que NAO devem aparecer no app.</p>
      <label>Coluna<select id="filterImportedColumn">${columns.map((c) => `<option value="${escapeHtml(c)}" ${c === selectedCol ? 'selected' : ''}>${escapeHtml(c)}</option>`).join('')}</select></label>
      <div id="filterImportedValuesBox"><div class="empty-state small">Selecione uma coluna para carregar os valores.</div></div>
      <div class="actions right" style="margin-top:12px">
        <button class="btn secondary" id="clearFilterImportedBtn">Remover filtro</button>
        <button class="btn primary" id="saveFilterImportedBtn">Salvar filtro</button>
      </div>
    </div>`;
  const backdrop = document.createElement('div');
  backdrop.className = 'modal';
  backdrop.innerHTML = html;
  document.body.appendChild(backdrop);
  const close = () => backdrop.remove();
  backdrop.querySelector('#closeFilterImportedModalBtn').addEventListener('click', close);
  backdrop.addEventListener('click', (e) => { if (e.target === backdrop) close(); });

  async function loadValues() {
    const col = backdrop.querySelector('#filterImportedColumn').value;
    const box = backdrop.querySelector('#filterImportedValuesBox');
    if (!col) { box.innerHTML = '<div class="empty-state small">Selecione uma coluna para carregar os valores.</div>'; return; }
    box.innerHTML = '<div class="empty-state small">Carregando valores...</div>';
    try {
      const data = await api('/api/tables/' + encodeURIComponent(item.name) + '/values/' + encodeURIComponent(col) + '?limit=2000&ts=' + Date.now() + '&skipRowFilter=1');
      const values = Array.isArray(data.values) ? data.values : [];
      if (!values.length) { box.innerHTML = '<div class="empty-state small">Nenhum valor encontrado.</div>'; return; }
      box.innerHTML = `
        <div class="filter-values-bar"><span class="transform-values-label">${values.length} valor(es)</span><span class="actions"><button type="button" class="btn ghost mini" id="filterImportSelectAll">Todos</button><button type="button" class="btn ghost mini" id="filterImportDeselectAll">Nenhum</button></span></div>
        <input type="text" class="filter-values-search" placeholder="Pesquisar valor..." autocomplete="off">
        <div class="filter-values-list">${values.map((v) => {
          const val = String(v ?? '');
          const display = val.length > 60 ? val.slice(0, 57) + '...' : val;
          const checked = selectedValues.has(val) || selectedValues.size === 0 ? 'checked' : '';
          return `<label class="check-label filter-value-item"><input type="checkbox" name="filterImportValue" value="${escapeHtml(val)}" ${checked}> ${escapeHtml(display)}</label>`;
        }).join('')}</div>`;
      box.querySelector('#filterImportSelectAll').addEventListener('click', () => box.querySelectorAll('[name="filterImportValue"]').forEach((cb) => cb.checked = true));
      box.querySelector('#filterImportDeselectAll').addEventListener('click', () => box.querySelectorAll('[name="filterImportValue"]').forEach((cb) => cb.checked = false));
      const search = box.querySelector('.filter-values-search');
      if (search) search.addEventListener('input', () => {
        const q = search.value.toLowerCase();
        box.querySelectorAll('.filter-value-item').forEach((el) => { el.style.display = q ? (el.textContent.toLowerCase().includes(q) ? '' : 'none') : ''; });
      });
    } catch (err) {
      box.innerHTML = `<div class="error-box">Erro: ${escapeHtml(err.message || 'desconhecido')}</div>`;
    }
  }

  backdrop.querySelector('#filterImportedColumn').addEventListener('change', loadValues);
  if (selectedCol) setTimeout(loadValues, 50);

  backdrop.querySelector('#clearFilterImportedBtn').addEventListener('click', async () => {
    await api('/api/imported-tables/' + encodeURIComponent(item.name), { method: 'PUT', body: JSON.stringify({ sourceTable: item.sourceTable, name: item.name, rowFilter: null }) });
    toast('Filtro removido da tabela ' + item.name);
    close();
    await loadImportedTables();
  });

  backdrop.querySelector('#saveFilterImportedBtn').addEventListener('click', async () => {
    const col = backdrop.querySelector('#filterImportedColumn').value;
    if (!col) return toast('Selecione uma coluna.', 'error');
    const checked = Array.from(backdrop.querySelectorAll('[name="filterImportValue"]:checked')).map((cb) => cb.value);
    if (!checked.length) return toast('Selecione pelo menos um valor.', 'error');
    const total = backdrop.querySelectorAll('[name="filterImportValue"]').length;
    if (checked.length === total) return toast('Todos os valores estao marcados — o filtro nao tera efeito. Use Remover filtro para limpar.', 'error');
    await api('/api/imported-tables/' + encodeURIComponent(item.name), { method: 'PUT', body: JSON.stringify({ sourceTable: item.sourceTable, name: item.name, rowFilter: { column: col, values: checked } }) });
    toast('Filtro salvo: ' + item.name + ' — ' + col + ' (' + checked.length + ' valor(es))');
    close();
    await loadImportedTables();
  });
}

async function ensureTransformColumnsLoadedFor(tableName) {
  if (!tableName) return [];
  if (!state.modelColumnCache[tableName]) {
    try {
      const data = await api('/api/tables/' + encodeURIComponent(tableName) + '/columns?ts=' + Date.now());
      const cols = normalizeColumnMetadataList(data.columns || []);
      if (cols.length) {
        state.modelColumnCache[tableName] = cols;
      }
    } catch (err) {
      // nao cacheia em caso de erro, para tentar novamente na proxima chamada
    }
  }
  return state.modelColumnCache[tableName] || [];
}

async function updateImportedTableFromForm() {
  const oldName = state.importedTableEditName;
  const sourceTable = $('#insertSourceTableSelect') && $('#insertSourceTableSelect').value;
  const name = $('#insertAliasInput') && $('#insertAliasInput').value;
  const note = $('#insertNoteInput') && $('#insertNoteInput').value;
  if (!oldName) return toast('Clique em Editar nome em uma tabela ja inserida antes de atualizar.', 'error');
  if (!sourceTable) return toast('Selecione a tabela do MySQL.', 'error');
  if (!String(name || '').trim()) return toast('Informe o novo nome da tabela no app.', 'error');
  const data = await api('/api/imported-tables/' + encodeURIComponent(oldName), { method: 'PUT', body: JSON.stringify({ sourceTable, name, note }) });
  toast('Tabela atualizada no app: ' + (data.previousName || oldName) + ' -> ' + name);
  state.importedTableEditName = '';
  if ($('#insertNoteInput')) $('#insertNoteInput').value = '';
  await loadTables({ force: true });
  await loadMysqlResourcesForInsert();
  await loadImportedTables();
  await loadPostgresCachePanel().catch(() => {});
  renderBuilderResourceSelect();
  renderTablesList();
}

async function previewInsertColumns() {
  const source = $('#insertSourceTableSelect') && $('#insertSourceTableSelect').value;
  const target = $('#insertColumnsPreview');
  if (!source) return toast('Selecione uma tabela do MySQL.', 'error');
  if (target) {
    target.className = 'insert-columns-preview empty-state';
    target.textContent = 'Carregando somente metadados das colunas...';
  }
  try {
    const data = await api('/api/tables/' + encodeURIComponent(source) + '/columns?metadataOnly=1&ts=' + Date.now());
    const cols = Array.isArray(data.columns) ? data.columns : [];
    if (target) {
      target.className = 'insert-columns-preview';
      target.innerHTML = cols.length ? cols.map((col) => `<span class="column-chip"><b>${escapeHtml(col.name)}</b><small>${escapeHtml(displayColumnType(col))}</small></span>`).join('') : '<span class="meta">Sem colunas encontradas.</span>';
    }
  } catch (err) {
    if (target) {
      target.className = 'insert-columns-preview empty-state error-state';
      target.innerHTML = `<div><b>Não foi possível carregar a prévia das colunas.</b><br><span class="meta">${escapeHtml(err.message || 'Erro ao consultar metadados.')}</span><br><button class="btn mini ghost" type="button" id="retryInsertColumnsBtn">Tentar novamente</button></div>`;
      const retry = $('#retryInsertColumnsBtn');
      if (retry) retry.addEventListener('click', () => previewInsertColumns().catch((e) => toast(e.message, 'error')));
    }
    throw err;
  }
}

async function saveImportedTableFromForm() {
  const sourceTable = $('#insertSourceTableSelect') && $('#insertSourceTableSelect').value;
  const name = $('#insertAliasInput') && $('#insertAliasInput').value;
  const note = $('#insertNoteInput') && $('#insertNoteInput').value;
  if (!sourceTable) return toast('Selecione uma tabela do MySQL.', 'error');
  if (!String(name || '').trim()) return toast('Informe o nome da tabela no app.', 'error');
  const overlay = showImportOverlay(name);
  try {
    const resp = await api('/api/imported-tables', { method: 'POST', body: JSON.stringify({ sourceTable, name, note }) });
    state.importedTableEditName = '';
    if ($('#insertNoteInput')) $('#insertNoteInput').value = '';
    let syncHadError = false;
    if (resp.pgCacheSync === 'started') {
      const pollMs = 600;
      const maxTimeoutMs = 2 * 60 * 60 * 1000;
      const startTime = Date.now();
      let pgEmptyPolls = 0;
      await new Promise((r) => setTimeout(r, 1500));
      let done = false;
      while (!done) {
        if (Date.now() - startTime > maxTimeoutMs) {
          updateImportOverlayError(name, 'Sincronizacao ultrapassou 2 horas. Os dados podem estar parcialmente carregados. Use "Recarregar completo" no painel Inserir Dados.');
          syncHadError = true;
          break;
        }
        await new Promise((r) => setTimeout(r, pollMs));
        try {
          const pg = await api('/api/postgres-cache/progress?table=' + encodeURIComponent(name), { timeoutMs: 5000 });
          if (pg && pg.progress) {
            pgEmptyPolls = 0;
            if (pg.progress.status === 'done' || pg.progress.percent >= 100) {
              updateImportOverlayProgress(name, 100, pg.progress.rowsCopied || 0, pg.progress.totalRows || 0); done = true;
            } else if (pg.progress.status === 'error') {
              updateImportOverlayError(name, pg.progress.error || 'Erro na sincronizacao PostgreSQL'); syncHadError = true; done = true;
            } else {
              updateImportOverlayProgress(name, Math.max(0, pg.progress.percent || 0), pg.progress.rowsCopied || 0, pg.progress.totalRows || 0);
            }
          } else {
            pgEmptyPolls++;
            if (pgEmptyPolls >= 5) { done = true; }
          }
        } catch (err) { /* ignore poll errors */ }
      }
    }
    await loadTables();
    await loadImportedTables();
    await loadPostgresCachePanel().catch(() => {});
    renderBuilderResourceSelect();
    renderTablesList();
    if (!syncHadError) updateImportOverlayDone(name);
    if (resp.autoHidden) toast('Tabela MySQL "' + resp.autoHidden + '" foi ocultada automaticamente pois voce usou esse nome.', 'ok');
  } catch (err) {
    updateImportOverlayError(name, err.message || 'Erro ao importar tabela');
    throw err;
  }
}

function showImportOverlay(name) {
  const existing = $('#importOverlay');
  if (existing) existing.remove();
  const overlay = document.createElement('div');
  overlay.id = 'importOverlay';
  overlay.className = 'modal-backdrop';
  overlay.style.cssText = 'display:flex;align-items:center;justify-content:center;z-index:9999';
  overlay.innerHTML = '<div style="background:var(--card-bg,#fff);border-radius:16px;padding:40px;text-align:center;max-width:400px;box-shadow:0 8px 32px rgba(0,0,0,.15)">'
    + '<div class="spinner" style="width:40px;height:40px;border:4px solid var(--line,#e0e0e0);border-top-color:var(--brand,#3366ff);border-radius:50%;animation:spin .8s linear infinite;margin:0 auto 16px"></div>'
    + '<p style="font-size:16px;font-weight:600;margin:0 0 4px">Importando tabela</p>'
    + '<p style="color:var(--meta,#888);margin:0 0 12px;font-size:13px" id="importOverlayMsg">Copiando <b>' + escapeHtml(name) + '</b> para o banco de dados do app...</p>'
    + '<div style="background:var(--line,#e0e0e0);border-radius:8px;height:8px;overflow:hidden;width:100%">'
    + '<div id="importOverlayBar" style="background:var(--brand,#3366ff);height:100%;width:0%;border-radius:8px;transition:width .3s ease"></div></div>'
    + '<p style="color:var(--meta,#888);margin:8px 0 0;font-size:12px" id="importOverlayPct">0%</p>'
    + '</div>';
  document.body.appendChild(overlay);
  return overlay;
}

function updateImportOverlayProgress(name, pct, rowsCopied, totalRows) {
  const bar = $('#importOverlayBar');
  const pctEl = $('#importOverlayPct');
  const msg = $('#importOverlayMsg');
  if (bar) bar.style.width = Math.min(100, Math.max(0, Number(pct) || 0)) + '%';
  if (pctEl) pctEl.textContent = Math.min(100, Math.max(0, Number(pct) || 0)) + '%';
  if (msg && rowsCopied > 0) {
    const total = totalRows > 0 ? ' de ' + Number(totalRows).toLocaleString('pt-BR') : '';
    msg.innerHTML = 'Copiados <b>' + Number(rowsCopied).toLocaleString('pt-BR') + '</b>' + total + ' registros de <b>' + escapeHtml(name) + '</b>';
  }
}

function updateImportOverlayDone(name) {
  const bar = $('#importOverlayBar');
  const pctEl = $('#importOverlayPct');
  const msg = $('#importOverlayMsg');
  const spinner = document.querySelector('#importOverlay .spinner');
  if (spinner) spinner.style.display = 'none';
  if (bar) { bar.style.width = '100%'; bar.style.background = 'var(--success,#22c55e)'; }
  if (pctEl) pctEl.textContent = '100%';
  if (msg) msg.innerHTML = '<span style="color:var(--success,#22c55e)">&#10003;</span> Tabela <b>' + escapeHtml(name) + '</b> importada com sucesso!';
  setTimeout(hideImportOverlay, 1800);
}

function updateImportOverlayError(name, errorMsg) {
  const spinner = document.querySelector('#importOverlay .spinner');
  if (spinner) spinner.style.display = 'none';
  const bar = $('#importOverlayBar');
  if (bar) { bar.style.width = '100%'; bar.style.background = 'var(--danger,#dc2626)'; }
  const pctEl = $('#importOverlayPct');
  if (pctEl) pctEl.textContent = 'Erro';
  const msg = $('#importOverlayMsg');
  if (msg) msg.innerHTML = '<span style="color:var(--danger,#dc2626)">&#10007;</span> Erro ao importar <b>' + escapeHtml(name) + '</b>: ' + escapeHtml(errorMsg || '');
  setTimeout(hideImportOverlay, 4000);
}

function hideImportOverlay() {
  const overlay = $('#importOverlay');
  if (overlay) overlay.remove();
}

async function removeImportedTable(name) {
  if (!name) return;
  await api('/api/imported-tables/' + encodeURIComponent(name), { method: 'DELETE' });
  if (String(state.importedTableEditName || '').toLowerCase() === String(name || '').toLowerCase()) state.importedTableEditName = '';
  toast('Tabela removida do app: ' + name);
  await loadTables();
  await loadImportedTables();
  renderTablesList();
}


async function hideMysqlTableFromApp() {
  const sourceTable = $('#insertSourceTableSelect') && $('#insertSourceTableSelect').value;
  if (!sourceTable) return toast('Selecione a tabela/view do MySQL para remover do app.', 'error');
  const ok = confirm('Remover \"' + sourceTable + '\" apenas do BI WA?\n\nEla continuara no MySQL, mas nao aparecera no app nem sera carregada.');
  if (!ok) return;
  const data = await api('/api/hidden-tables', { method: 'POST', body: JSON.stringify({ sourceTable }) });
  toast('Tabela removida do app: ' + sourceTable + (data.removedAliases ? ' | aliases removidos: ' + data.removedAliases : ''));
  try { localStorage.removeItem(TABLES_CACHE_KEY); } catch (err) {}
  if (state.selectedTable && String(state.selectedTable).toLowerCase() === String(sourceTable).toLowerCase()) {
    state.selectedTable = null;
    state.columns = [];
    state.rows = [];
    state.tableRows = [];
    state.tablePage = { offset: 0, limit: 100, hasMore: false, total: null, totalKnown: false };
    state.tableSort = { field: '', direction: 'ASC' };
    state.tableFilters = [];
    state.tableQuickSearch = '';
    state.tableColumnFormats = null;
    state.selectedResource = null;
    state.selectedRow = null;
  }
  await loadTables({ force: true });
  await loadImportedTables();
  await loadHiddenTables();
  renderBuilderResourceSelect();
  renderTablesList();
}

async function restoreHiddenTable(name) {
  if (!name) return;
  await api('/api/hidden-tables/' + encodeURIComponent(name), { method: 'DELETE' });
  toast('Tabela restaurada no app: ' + name);
  try { localStorage.removeItem(TABLES_CACHE_KEY); } catch (err) {}
  await loadTables({ force: true });
  await loadMysqlResourcesForInsert();
  await loadHiddenTables();
  renderInsertDataPanel();
  renderTablesList();
}

