  on('#previewInsertColumnsBtn', 'click', () => previewInsertColumns().catch((err) => toast(err.message, 'error')));
  on('#saveImportedTableBtn', 'click', () => saveImportedTableFromForm().catch((err) => toast(err.message, 'error')));
