function bindSocketEvents() {
  if (!socket || socket._biwaBound) return;
  socket._biwaBound = true;
  socket.on('connect', () => { subscribeDashboard(); });
  socket.on('dashboard:update', (payload) => {
    if (state.dashboardPaused) return;
    if (payload && payload.subscriptionId && payload.subscriptionId !== state.dashboardActiveSubscriptionId) return;
    if (payload && payload.realtimeMode) {
      state.dashboardRealtimeStatus = state.dashboardRealtimeStatus || {};
      state.dashboardRealtimeStatus.mode = payload.realtimeMode;
      state.dashboardRealtimeStatus.realtimeEventMarker = payload.realtimeMarker || state.dashboardRealtimeStatus.realtimeEventMarker || null;
    }
    if (payload && typeof payload.mysqlAvailable === 'boolean') applyMysqlConnectionStatus(payload.mysqlAvailable);
    const updatedReportIds = [];
    for (const item of payload.items || []) {
      updatedReportIds.push(item.reportId);
      if (item.ok) {
        state.dashboard[item.reportId] = {
          rows: item.result.rows || [],
          fields: item.result.fields || [],
          visualResults: item.result.visualResults || [],
          generatedAt: payload.generatedAt,
          cached: Boolean(item.cached || item.result.cached),
          cacheEngine: item.result.cacheEngine || '',
          cacheSummary: item.result.cacheSummary || null,
          cacheCoverage: item.result.cacheCoverage || null,
          cacheAgeMs: item.result.cacheAgeMs || 0,
          lastDataSyncAt: normalizeDashboardLastUpdate(
            item.lastPgSyncAt
            || item.result.cacheCoverage && (item.result.cacheCoverage.lastDataUpdateAt || item.result.cacheCoverage.lastSyncAt)
          ),
          runtimeFilterSignature: state.dashboardSubscriptionRuntimeSignatures[item.reportId] || '',
          reportDefinitionSignature: reportRuntimeDefinitionSignature(
            (state.reports || []).find((report) => String(report.id) === String(item.reportId)),
            activeOnlineReportPageId((state.reports || []).find((report) => String(report.id) === String(item.reportId)))
          )
        };
        if (state.dashboard[item.reportId].lastDataSyncAt) {
          rememberDashboardReportLastUpdate(item.reportId, state.dashboard[item.reportId].lastDataSyncAt);
        }
      } else {
        state.dashboard[item.reportId] = { error: item.error || 'Erro ao atualizar' };
      }
    }
    saveDashboardCache();
    if (onlinePortalModeEnabled()) {
      var activeReportLastUpdated = dashboardReportLastUpdated(state.onlineActiveReportId);
      if (activeReportLastUpdated) setDashboardReportLastUpdate(state.onlineActiveReportId, activeReportLastUpdated);
    } else {
      var latestMoment = dashboardLastUpdateMoment();
      for (var ri = 0; ri < updatedReportIds.length; ri++) {
        var rid = updatedReportIds[ri];
        var result = state.dashboard[rid];
        if (result && result.lastDataSyncAt) {
          var dm = new Date(result.lastDataSyncAt).getTime();
          if (dm && Number.isFinite(dm) && dm > latestMoment) latestMoment = dm;
        }
      }
      if (latestMoment > dashboardLastUpdateMoment()) {
        state.dashboardLastUpdated = new Date(latestMoment).toISOString();
        setDashboardLastUpdate();
      }
    }
    setDashboardOnlineStatus(state.dashboardOnline);
    refreshDashboardAfterDataChange(updatedReportIds);
  });
  socket.on('dashboard:connectionStatus', (payload) => {
    if (!payload) return;
    if (typeof payload.mysqlAvailable === 'boolean') applyMysqlConnectionStatus(payload.mysqlAvailable);
    if (payload.lastCycleCompletedAt) {
      state.lastCycleCompletedAt = payload.lastCycleCompletedAt;
    }
    if (payload.lastPgSyncAt && !onlinePortalModeEnabled()) {
      state.lastPgSyncAt = normalizeDashboardLastUpdate(payload.lastPgSyncAt) || state.lastPgSyncAt || null;
    }
  });
  socket.on('dashboard:cacheInvalidated', (payload) => {
    invalidateFilterOptionsClientCache();
    loadRealtimeStatus().then(() => {
      if (!state.dashboardPaused && !document.hidden) subscribeDashboard();
      setDashboardOnlineStatus(state.dashboardOnline);
    }).catch(() => {});
  });
  socket.on('dashboard:error', (payload) => toast(payload.error || 'Erro no dashboard', 'error'));
  socket.on('disconnect', () => {
    state.dashboardActiveSubscriptionId = '';
    state.dashboardSubscribeSignature = '';
    applyMysqlConnectionStatus(false);
  });
  socket.on('connect_error', () => applyMysqlConnectionStatus(false));
}

document.addEventListener('visibilitychange', () => {
  if (document.hidden) {
    unsubscribeDashboard();
    return;
  }
  checkHealth().catch(() => {});
  if (!state.dashboardPaused) subscribeDashboard();
});

async function boot() {
  bindEvents();
  try {
    await api('/api/public-config?ts=' + Date.now(), { timeoutMs: 5000 });
  } catch (err) {}
  try {
    await bootAfterAuth();
  } catch (err) {
    showLoginScreen('Informe usuário e senha para acessar.');
  }
}

async function bootAfterAuth() {
  // A conexão do Socket.IO pode concluir antes de relatórios/modelo estarem
  // hidratados. Nesse intervalo uma assinatura usaria estado parcial e
  // dispararia os três relatórios durante o próprio boot.
  state.dashboardRuntimeReady = false;
  renderAlterTableSelect();
  addDesignerColumn();
  await loadConfig();
  connectSocket();
  if (!socket) applyMysqlConnectionStatus(false);
  await loadRealtimeStatus();
  if (!isOnlineMode()) clearReportEditor();
  await checkHealth();
  startHealthMonitor();
  // Relatorios tambem em paralelo com model/tables
  var reportsPromise = loadReports();
  if (!isOnlineMode()) {
    // Dispara carregamentos em paralelo para acelerar a inicializacao
    var tablePromise = loadTables();
    var modelPromise = loadModel();
    var importPromise = loadImportedTables().catch(function(){});
    // Carregamentos nao-criticos em background (nao bloqueiam a tela)
    loadMysqlResourcesForInsert().catch(function(){});
    loadHiddenTables().catch(function(){});
    loadPostgresCachePanel().catch(function(){});
    loadTransforms().catch(function(err){ console.error(err); });
    try {
      await tablePromise;
    } catch (err) {
      state.resourcesError = err.message || String(err);
      renderTablesList();
    }
    await importPromise;
    renderInsertDataPanel();
    renderTransformSourceSelect();
    try {
      await modelPromise;
    } catch (err) {
      toast('Modelo não carregado: ' + (err.message || String(err)), 'error');
    }
    refreshVisualBuilder().catch(function(err) {
      var el = document.getElementById('builderFieldList');
      if (el) {
        el.className = 'field-list powerbi-field-list empty-state';
        el.textContent = err.message || String(err);
      }
    });
  }
  await reportsPromise;
  renderOnlineUsersList();
  state.dashboardRuntimeReady = true;
  if (state.activeTabId === 'dashboardTab' && !state.dashboardPaused) subscribeDashboard();
}

function setupTableInteractivity() {
  const page = $('#reportPage');
  if (!page || page.dataset.tableInteractivityBound === '1') return;
  page.dataset.tableInteractivityBound = '1';

  let resizingCol = null;
  let startX = 0;
  let startWidth = 0;
  let activeVisualForResize = null;
  let colName = '';

  page.addEventListener('click', (ev) => {
    const sortButton = ev.target.closest('[data-visual-table-sort-field]');
    if (!sortButton) return;
    const frame = sortButton.closest('.visual-frame');
    if (!frame || !frame.dataset.visualId) return;
    const visual = state.reportVisuals.find((item) => item.id === frame.dataset.visualId);
    const field = sortButton.dataset.visualTableSortField || '';
    if (!visual || !field) return;
    ev.preventDefault();
    ev.stopPropagation();
    const currentStyle = normalizeVisualStyle(visual.style);
    const nextDirection = currentStyle.sortColumn === field && currentStyle.sortDirection !== 'DESC' ? 'DESC' : 'ASC';
    const tableWrap = sortButton.closest('.visual-table-wrap');
    const scrollLeft = tableWrap ? tableWrap.scrollLeft : 0;
    const scrollTop = tableWrap ? tableWrap.scrollTop : 0;
    visual.style = { ...currentStyle, sortColumn: field, sortDirection: nextDirection };
    state.activeVisualId = visual.id;
    renderReportPageVisuals();
    requestAnimationFrame(() => {
      const nextFrame = Array.from(page.querySelectorAll('.visual-frame')).find((item) => item.dataset.visualId === visual.id);
      const nextWrap = nextFrame && nextFrame.querySelector('.visual-table-wrap');
      if (nextWrap) {
        nextWrap.scrollLeft = scrollLeft;
        nextWrap.scrollTop = scrollTop;
      }
    });
  });

  page.addEventListener('mousedown', (ev) => {
    if (ev.button !== 0) return;
    const grip = ev.target.closest('.col-resize-handle');
    if (!grip) return;
    const th = grip.closest('th');
    const frame = grip.closest('.visual-frame');
    if (!th || !frame || !frame.dataset.visualId) return;

    ev.preventDefault();
    ev.stopPropagation();

    colName = th.dataset.col;
    if (!colName) return;

    activeVisualForResize = state.reportVisuals.find(v => v.id === frame.dataset.visualId);
    if (!activeVisualForResize) return;

    resizingCol = th;
    startX = ev.clientX;
    const z = state.reportCanvasZoom || 1;
    const table = th.closest('table');
    const headers = Array.from(th.parentElement.children);
    const colgroup = table && table.querySelector('colgroup');
    activeVisualForResize.style = normalizeVisualStyle(activeVisualForResize.style);
    const workingColumnWidths = {};
    headers.forEach((header, index) => {
      const headerColumn = header.dataset.col;
      if (!headerColumn) return;
      workingColumnWidths[headerColumn] = visualStyleColumnWidth(activeVisualForResize.style, headerColumn)
        ?? Math.max(32, Math.round(header.offsetWidth));
      if (colgroup && colgroup.children[index]) {
        colgroup.children[index].style.width = workingColumnWidths[headerColumn] + 'px';
      }
    });
    const applyExactTableWidth = () => {
      if (!table) return;
      const exactWidth = headers.reduce((total, header) => total + Number(workingColumnWidths[header.dataset.col] || 0), 0);
      table.classList.add('table-fixed');
      table.style.width = exactWidth + 'px';
      table.style.minWidth = exactWidth + 'px';
      table.style.maxWidth = exactWidth + 'px';
    };
    applyExactTableWidth();
    startWidth = workingColumnWidths[colName] || th.offsetWidth;

    const move = (e) => {
      if (!resizingCol) return;
      const nextWidth = Math.max(32, startWidth + (e.clientX - startX) / z);
      
      const table = resizingCol.closest('table');
      const colgroup = table.querySelector('colgroup');
      if (colgroup) {
         const headers = Array.from(th.parentElement.children);
         const idx = headers.indexOf(th);
         if (idx >= 0 && colgroup.children[idx]) {
            colgroup.children[idx].style.width = nextWidth + 'px';
            workingColumnWidths[colName] = Math.round(nextWidth);
            applyExactTableWidth();
         }
      }
    };

    const up = (e) => {
      window.removeEventListener('mousemove', move);
      window.removeEventListener('mouseup', up);
      if (!resizingCol) return;
      
      const finalWidth = Math.max(32, startWidth + (e.clientX - startX) / z);
      if (!activeVisualForResize.style) activeVisualForResize.style = defaultVisualStyle();
      if (!activeVisualForResize.style.columnWidths) activeVisualForResize.style.columnWidths = {};
      const persistedWidth = Math.round(finalWidth);
      const fieldRef = String(th.dataset.fieldRef || '').trim();
      activeVisualForResize.style.columnWidths[colName] = persistedWidth;
      if (fieldRef) {
        activeVisualForResize.style.columnWidths[fieldRef] = persistedWidth;
        const fields = normalizeSelectedFields(activeVisualForResize.selectedFields);
        const fieldIndex = fields.findIndex(function(field) { return visualFieldRef(field) === fieldRef; });
        if (fieldIndex >= 0) {
          fields[fieldIndex].width = persistedWidth;
          activeVisualForResize.selectedFields = fields;
        }
      }
      
      resizingCol = null;
      activeVisualForResize = null;
      
      renderReportPageVisuals();
      if (can('reportEditing')) saveReport();
    };

    window.addEventListener('mousemove', move);
    window.addEventListener('mouseup', up);
  });

  let draggedCol = null;
  let draggedColVisual = null;

  page.addEventListener('dragstart', (ev) => {
    if (ev.target.closest('.table-sort-btn, .col-resize-handle')) {
      ev.preventDefault();
      return;
    }
    const th = ev.target.closest('th[draggable="true"]');
    if (!th) return;
    const frame = th.closest('.visual-frame');
    if (!frame || !frame.dataset.visualId) return;
    
    draggedCol = th.dataset.col;
    draggedColVisual = state.reportVisuals.find(v => v.id === frame.dataset.visualId);
    
    if (draggedCol) {
      ev.dataTransfer.effectAllowed = 'move';
      ev.dataTransfer.setData('text/biwa-table-col', draggedCol);
      setTimeout(() => th.classList.add('drag-source'), 0);
    }
  });

  page.addEventListener('dragover', (ev) => {
    const th = ev.target.closest('th[data-col]');
    if (!th || !draggedCol || !draggedColVisual) return;
    
    const frame = th.closest('.visual-frame');
    if (!frame || frame.dataset.visualId !== draggedColVisual.id) return;

    ev.preventDefault();
    ev.dataTransfer.dropEffect = 'move';
    
    Array.from(frame.querySelectorAll('th')).forEach(el => el.classList.remove('drag-over-left', 'drag-over-right'));
    
    const rect = th.getBoundingClientRect();
    const mid = rect.left + rect.width / 2;
    if (ev.clientX < mid) {
      th.classList.add('drag-over-left');
    } else {
      th.classList.add('drag-over-right');
    }
  });

  page.addEventListener('dragleave', (ev) => {
    const th = ev.target.closest('th');
    if (th) th.classList.remove('drag-over-left', 'drag-over-right');
  });

  page.addEventListener('dragend', (ev) => {
    const th = ev.target.closest('th');
    if (th) th.classList.remove('drag-source');
    page.querySelectorAll('th').forEach(el => el.classList.remove('drag-over-left', 'drag-over-right'));
    draggedCol = null;
    draggedColVisual = null;
  });

  page.addEventListener('drop', (ev) => {
    const colId = ev.dataTransfer.getData('text/biwa-table-col');
    if (!colId) return;

    const th = ev.target.closest('th[data-col]');
    if (!th || !draggedColVisual) return;

    const frame = th.closest('.visual-frame');
    if (!frame || frame.dataset.visualId !== draggedColVisual.id) return;
    
    ev.preventDefault();
    ev.stopPropagation();
    
    const targetCol = th.dataset.col;
    if (targetCol === colId) return;

    const rect = th.getBoundingClientRect();
    const mid = rect.left + rect.width / 2;
    const insertAfter = ev.clientX >= mid;

    const tr = th.closest('tr');
    let currentOrder = Array.from(tr.querySelectorAll('th[data-col]')).map(el => el.dataset.col);
    
    currentOrder = currentOrder.filter(c => c !== colId);
    
    const targetIdx = currentOrder.indexOf(targetCol);
    if (targetIdx !== -1) {
      currentOrder.splice(insertAfter ? targetIdx + 1 : targetIdx, 0, colId);
    } else {
      currentOrder.push(colId);
    }

    if (!draggedColVisual.style) draggedColVisual.style = defaultVisualStyle();
    draggedColVisual.style.columnOrder = currentOrder;

    renderReportPageVisuals();
    saveReport();
  });
}


async function renderHistoryTab() {
  const el = $('#historyContent');
  if (!el) return;
  el.innerHTML = '<div class="empty-state">Carregando historico...</div>';
  try {
    const pgCaches = await api('/api/postgres-cache/diagnostics', { timeoutMs: 10000 });
    const caches = (pgCaches && pgCaches.caches) || (pgCaches && Array.isArray(pgCaches) ? pgCaches : []);
    const pg = pgCaches || {};

    var html = '<div class="history-grid">';
    var monitoredCaches = Array.isArray(caches) ? caches.filter(function(c) { return c.exists && String(c.syncMode || '').toLowerCase() !== 'manual' && String(c.sourceTable || '').toLowerCase() !== 'calendario'; }) : [];
    html += '<div class="panel"><div class="panel-head"><h3>Cache PostgreSQL</h3><span class="meta">';
    html += pg.connected ? 'Conectado' : 'Desconectado';
    html += ' | ' + monitoredCaches.length + ' tabelas monitoradas';
    if (pg.lastCycleCompletedAt) {
      html += ' | <strong>Ultima att. completa: ' + formatDateTimePtBr(pg.lastCycleCompletedAt) + '</strong>';
    }
    html += '</span></div>';
    if (Array.isArray(caches) && caches.length) {
      html += '<div class="history-table-wrap"><table class="data-table"><thead><tr><th>Tabela</th><th>Linhas</th><th>+Increm.</th><th>Modo</th><th>Coluna Sync</th><th>Ultima Sinc.</th><th></th></tr></thead><tbody>';
      caches.filter(function(c) { return c.exists; }).forEach(function(c) {
        var isManual = String(c.syncMode || '').toLowerCase() === 'manual';
        var synced = isManual ? '-' : (c.syncedAt ? formatDateTimePtBr(c.syncedAt) : '-');
        var changed = Number(c.lastChangedRows || 0);
        var changedText = isManual ? '-' : (changed > 0 ? '+' + changed.toLocaleString('pt-BR') : '-');
        var changedColor = isManual ? 'var(--muted)' : (changed > 0 ? 'var(--brand,#1f6feb)' : 'var(--muted)');
        html += '<tr><td><b>' + escapeHtml(c.sourceTable || c.physicalTable || '-') + '</b></td>';
        html += '<td>' + Number(c.rowCount || 0).toLocaleString('pt-BR') + '</td>';
        html += '<td style="color:' + changedColor + '">' + changedText + '</td>';
        html += '<td>' + escapeHtml(c.syncMode || '-') + '</td>';
        html += '<td>' + escapeHtml(isManual ? '-' : (c.syncColumn || '-')) + '</td>';
        html += '<td>' + escapeHtml(synced) + '</td>';
        html += '<td><button class="btn mini ghost table-detail-btn" data-table="' + escapeHtml(c.sourceTable || '') + '" title="Detalhes">...</button></td></tr>';
      });
      html += '</tbody></table></div>';
    } else {
      html += '<div class="empty-state small">Nenhum cache PostgreSQL encontrado.</div>';
    }
    html += '</div>';
    html += '</div>';
    el.innerHTML = html;
    // Bind detail buttons
    el.querySelectorAll('.table-detail-btn').forEach(function(btn) {
      btn.addEventListener('click', function() {
        var tableName = btn.dataset.table;
        showTableCacheDetail(tableName).catch(function(err) { toast(err.message, 'error'); });
      });
    });
  } catch (err) {
    el.innerHTML = '<div class="error-box">Erro ao carregar historico: ' + escapeHtml(err.message || String(err)) + '</div>';
  }
}

function showSimpleModal(innerHTML, title) {
  var overlay = document.createElement('div');
  overlay.className = 'simple-modal-overlay';
  overlay.innerHTML = '<div class="simple-modal"><div class="simple-modal-head"><b>' + escapeHtml(title || '') + '</b><button class="simple-modal-close">&times;</button></div><div class="simple-modal-body">' + innerHTML + '</div></div>';
  document.body.appendChild(overlay);
  overlay.querySelector('.simple-modal-close').addEventListener('click', function() { overlay.remove(); });
  overlay.addEventListener('click', function(e) { if (e.target === overlay) overlay.remove(); });
  return overlay;
}

function showRelationshipsModal() {
  var rels = state.model.relationships || [];
  var resources = connectionRelationshipResources();
  var tableOpts = resources.map(function(r) { return '<option value="' + escapeHtml(r.name) + '">' + escapeHtml(r.name) + '</option>'; }).join('');

  var html = '<div style="background:#f8fbff;border:1px solid #d9e5f6;border-radius:12px;padding:14px;margin-bottom:16px">' +
    '<b style="display:block;margin-bottom:10px;font-size:14px">+ Novo relacionamento</b>' +
    '<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px">' +
    '<label style="font-size:12px;font-weight:600">Origem<select id="modalConnFromTable" style="width:100%;margin-top:2px">' + tableOpts + '</select></label>' +
    '<label style="font-size:12px;font-weight:600">Coluna origem<select id="modalConnFromColumn" style="width:100%;margin-top:2px"><option value="">Selecione...</option></select></label>' +
    '<label style="font-size:12px;font-weight:600">Destino<select id="modalConnToTable" style="width:100%;margin-top:2px">' + tableOpts + '</select></label>' +
    '<label style="font-size:12px;font-weight:600">Coluna destino<select id="modalConnToColumn" style="width:100%;margin-top:2px"><option value="">Selecione...</option></select></label>' +
    '<label style="font-size:12px;font-weight:600">Cardinalidade<select id="modalConnCardinality" style="width:100%;margin-top:2px"><option value="many-to-one">*:1  (Muitos p/ Um)</option><option value="one-to-one">1:1  (Um p/ Um)</option><option value="one-to-many">1:*  (Um p/ Muitos)</option><option value="many-to-many">*:*  (Muitos p/ Muitos)</option></select></label>' +
    '<label style="font-size:12px;font-weight:600">Filtro<select id="modalConnFilterDirection" style="width:100%;margin-top:2px"><option value="single">Unico</option><option value="both">Ambos</option></select></label>' +
    '</div>' +
    '<button id="modalAddRelationshipBtn" class="btn primary" style="width:100%;margin-top:10px;padding:8px;font-weight:700">Adicionar relacionamento</button>' +
    '</div>';

  if (rels.length) {
    html += '<b style="display:block;margin-bottom:8px;font-size:13px">Relacionamentos (' + rels.length + ')</b>' +
      '<div style="display:grid;gap:6px;max-height:35vh;overflow:auto">' + rels.map(function(rel, idx) {
        return '<div style="display:flex;align-items:center;gap:8px;padding:8px 10px;background:#fbfdff;border:1px solid #e3eaf3;border-radius:8px;font-size:12px">' +
          '<span style="flex:1;min-width:0"><b>' + escapeHtml(rel.fromTable) + '</b> <span style="color:#65748b">[' + escapeHtml(rel.fromColumn) + ']</span> <span style="color:#1f6feb;font-weight:700">&rarr;</span> <b>' + escapeHtml(rel.toTable) + '</b> <span style="color:#65748b">[' + escapeHtml(rel.toColumn) + ']</span> <small style="color:#94a3b8">' + escapeHtml(rel.cardinality || '*:1') + '</small></span>' +
          '<button class="btn mini ghost" data-modal-edit-rel="' + idx + '" style="flex-shrink:0">Editar</button>' +
          '<button class="btn mini ghost" data-modal-remove-rel="' + idx + '" style="flex-shrink:0;color:#d33">Remover</button>' +
          '</div>';
      }).join('') + '</div>';
  } else {
    html += '<div class="empty-state">Nenhum relacionamento. Crie um acima.</div>';
  }

  var overlay = showSimpleModal(html, 'Relacionamentos (' + rels.length + ')');

  // Setup column dropdowns
  function setupModalColumnSelect(tableId, colId) {
    var tableEl = overlay.querySelector('#' + tableId);
    var colEl = overlay.querySelector('#' + colId);
    if (!tableEl || !colEl) return;
    tableEl.addEventListener('change', async function() {
      var table = tableEl.value;
      if (!table) { colEl.innerHTML = '<option value="">Selecione a tabela primeiro</option>'; return; }
      try {
        var columns = await loadModelColumns(table);
        colEl.innerHTML = columns.map(function(c) { return '<option value="' + escapeHtml(c.name) + '">' + escapeHtml(c.name) + ' - ' + escapeHtml(displayColumnType(c)) + '</option>'; }).join('');
      } catch(e) { colEl.innerHTML = '<option value="">Erro ao carregar</option>'; }
    });
  }
  setupModalColumnSelect('modalConnFromTable', 'modalConnFromColumn');
  setupModalColumnSelect('modalConnToTable', 'modalConnToColumn');

  // Add relationship
  var addBtn = overlay.querySelector('#modalAddRelationshipBtn');
  if (addBtn) addBtn.addEventListener('click', function() {
    var ft = overlay.querySelector('#modalConnFromTable').value;
    var fc = overlay.querySelector('#modalConnFromColumn').value;
    var tt = overlay.querySelector('#modalConnToTable').value;
    var tc = overlay.querySelector('#modalConnToColumn').value;
    if (!ft || !fc || !tt || !tc) return toast('Preencha todos os campos.', 'error');
    if (ft === tt && fc === tc) return toast('O relacionamento precisa ligar campos diferentes.', 'error');
    var norm = normalizeRelationshipDirection(ft, fc, tt, tc);
    var exists = (state.model.relationships || []).some(function(rel) {
      return rel.fromTable === norm.fromTable && rel.fromColumn === norm.fromColumn && rel.toTable === norm.toTable && rel.toColumn === norm.toColumn;
    });
    if (exists) return toast('Esse relacionamento ja existe.', 'error');
    state.model.relationships = state.model.relationships || [];
    state.model.relationships.push({
      fromTable: norm.fromTable, fromColumn: norm.fromColumn,
      toTable: norm.toTable, toColumn: norm.toColumn,
      joinType: 'LEFT',
      cardinality: norm.cardinality,
      filterDirection: overlay.querySelector('#modalConnFilterDirection').value || 'single',
      active: true, confidence: 'manual'
    });
    ensureModelTablesArray();
    [norm.fromTable, norm.toTable].forEach(function(name) {
      if (!state.model.tables.some(function(item) { return (typeof item === 'string' ? item : item.name) === name; })) state.model.tables.push({ name: name });
    });
    renderConnectionsDesigner();
    renderRelationshipList();
    overlay.remove();
    showRelationshipsModal();
  });

  // Edit relationship
  overlay.querySelectorAll('[data-modal-edit-rel]').forEach(function(btn) {
    btn.addEventListener('click', function() {
      var idx = Number(btn.dataset.modalEditRel);
      var rel = state.model.relationships[idx];
      if (!rel) return;
      overlay.remove();
      editRelationship(idx);
    });
  });

  // Remove relationship
  overlay.querySelectorAll('[data-modal-remove-rel]').forEach(function(btn) {
    btn.addEventListener('click', function() {
      state.model.relationships.splice(Number(btn.dataset.modalRemoveRel), 1);
      renderConnectionsDesigner();
      renderRelationshipList();
      overlay.remove();
      showRelationshipsModal();
    });
  });
}

async function showEventsModal() {
  try {
    var data = await api('/api/audit?limit=100', { timeoutMs: 10000 });
    var audits = Array.isArray(data.items) ? data.items : [];
    var html = '<div class="history-table-wrap" style="max-height:60vh"><table class="data-table"><thead><tr><th>Data</th><th>Evento</th><th>Detalhes</th></tr></thead><tbody>';
    if (audits.length) {
      audits.forEach(function(a) {
        var dt = a.at ? formatDateTimePtBr(a.at) : '-';
        var details = a.details && typeof a.details === 'object' ? Object.entries(a.details).map(function(e) { return escapeHtml(e[0]) + ': ' + escapeHtml(String(e[1])); }).join(', ') : '';
        html += '<tr><td>' + escapeHtml(dt) + '</td><td>' + escapeHtml(a.event || '') + '</td><td style="font-size:11px;color:var(--muted)">' + details + '</td></tr>';
      });
    } else {
      html += '<tr><td colspan="3">Nenhum evento registrado.</td></tr>';
    }
    html += '</tbody></table></div>';
    showSimpleModal(html, 'Ultimos Eventos');
  } catch (err) {
    toast('Erro ao carregar eventos: ' + (err.message || String(err)), 'error');
  }
}

async function showTableCacheDetail(tableName) {
  if (!tableName) return;
  try {
    var status = await api('/api/postgres-cache/' + encodeURIComponent(tableName) + '/status', { timeoutMs: 10000 });
    var cache = status.cache || {};
    var html = '<div style="max-height:70vh;overflow:auto"><h3 style="margin:0 0 12px">' + escapeHtml(tableName) + '</h3>';
    html += '<table class="data-table"><tbody>';
    html += '<tr><td><b>Linhas</b></td><td>' + Number(cache.rowCount || 0).toLocaleString('pt-BR') + '</td></tr>';
    html += '<tr><td><b>Ultimo incremental</b></td><td>' + (Number(cache.lastChangedRows || 0) > 0 ? '+' + Number(cache.lastChangedRows).toLocaleString('pt-BR') + ' linhas' : 'Nenhum') + '</td></tr>';
    html += '<tr><td><b>Modo</b></td><td>' + escapeHtml(cache.syncMode || '-') + '</td></tr>';
    html += '<tr><td><b>Estrategia</b></td><td>' + escapeHtml(cache.syncStrategy || '-') + '</td></tr>';
    html += '<tr><td><b>Coluna sync</b></td><td>' + escapeHtml(cache.syncColumn || '-') + '</td></tr>';
    html += '<tr><td><b>Ultimos dados recebidos</b></td><td>' + escapeHtml(cache.lastDataUpdateAt ? formatDateTimePtBr(cache.lastDataUpdateAt) : '-') + '</td></tr>';
    html += '<tr><td><b>Ultima verificacao</b></td><td>' + escapeHtml(cache.syncedAt ? formatDateTimePtBr(cache.syncedAt) : '-') + '</td></tr>';
    html += '<tr><td><b>Tabela PG</b></td><td><code>' + escapeHtml(cache.cacheTable || '-') + '</code></td></tr>';
    html += '</tbody></table>';

    var syncLogEvents = [];
    try {
      var logRes = await api('/api/postgres-cache/' + encodeURIComponent(tableName) + '/sync-log?limit=20', { timeoutMs: 8000 });
      syncLogEvents = logRes.events || [];
    } catch (e) {}

    if (syncLogEvents.length) {
      html += '<h4 style="margin:16px 0 8px">Historico de sincronizacoes</h4>';
      html += '<div style="max-height:200px;overflow:auto"><table class="data-table"><thead><tr><th>Data</th><th>Modo</th><th>Total</th><th>+Novas</th><th>Coluna</th></tr></thead><tbody>';
      syncLogEvents.forEach(function(ev) {
        var dt = ev.syncedAt ? formatDateTimePtBr(ev.syncedAt) : '-';
        var changed = Number(ev.changedRows || 0);
        var changedText = changed > 0 ? '<span style="color:var(--brand,#1f6feb);font-weight:600">+' + changed.toLocaleString('pt-BR') + '</span>' : '<span style="color:var(--muted)">-</span>';
        html += '<tr>';
        html += '<td style="white-space:nowrap;font-size:12px">' + escapeHtml(dt) + '</td>';
        html += '<td>' + escapeHtml(ev.syncStrategy || ev.syncMode || '-') + '</td>';
        html += '<td>' + Number(ev.rowCount || 0).toLocaleString('pt-BR') + '</td>';
        html += '<td>' + changedText + '</td>';
        html += '<td style="font-size:12px">' + escapeHtml(ev.syncColumn || '-') + '</td>';
        html += '</tr>';
      });
      html += '</tbody></table></div>';
    }

    html += '<div style="margin-top:12px"><button class="btn secondary" id="detailSyncNowBtn">Sincronizar agora (incremental)</button>';
    html += ' <button class="btn ghost" id="detailSyncFullBtn">Recarregar completo</button></div>';
    html += '</div>';
    var overlay = showSimpleModal(html, 'Detalhes: ' + escapeHtml(tableName));
    if (overlay) {
      var syncBtn = overlay.querySelector('#detailSyncNowBtn');
      if (syncBtn) syncBtn.addEventListener('click', function() {
        syncPostgresCacheForTable(tableName, 'incremental').catch(function(err) { toast(err.message, 'error'); });
      });
      var fullBtn = overlay.querySelector('#detailSyncFullBtn');
      if (fullBtn) fullBtn.addEventListener('click', function() {
        syncPostgresCacheForTable(tableName, 'full').catch(function(err) { toast(err.message, 'error'); });
      });
    }
  } catch (err) {
    toast('Erro ao carregar detalhes: ' + (err.message || String(err)), 'error');
  }
}

