var ONLINE_ICON_ALIASES = {
  chart: 'analytics', table: 'reports', pie: 'analytics', map: 'logistics', kpi: 'goals',
  filter: 'operations', settings: 'operations', user: 'customers', home: 'administrative',
  report: 'reports', link: 'dashboard'
};
var onlineIconPickerReportId = '';
var onlineDashboardDragReportId = '';
var onlineDashboardMenuReportId = '';
var onlineDashboardRenameReportId = '';

function getOnlineCustom() {
  return state.onlineCustom || ONLINE_CUSTOM_DEFAULTS;
}

function setOnlineCustom(custom) {
  state.onlineCustom = custom;
  return custom;
}

function loadOnlineCustomFromStateOrDefaults() {
  if (!state.onlineCustom) {
    state.onlineCustom = JSON.parse(JSON.stringify(ONLINE_CUSTOM_DEFAULTS));
  }
  return state.onlineCustom;
}

async function loadOnlineCustomization() {
  try {
    var data = await api('/api/online-customization', { method: 'GET', timeoutMs: 8000 });
    if (data && data.customization) {
      state.onlineCustom = data.customization;
    } else {
      loadOnlineCustomFromStateOrDefaults();
    }
  } catch (e) {
    if (state.config && state.config.settings && state.config.settings.onlineCustomization) {
      state.onlineCustom = state.config.settings.onlineCustomization;
    } else {
      loadOnlineCustomFromStateOrDefaults();
    }
  }
  return state.onlineCustom;
}

async function saveOnlineCustomization() {
  syncOnlineCustomFromControls();
  try {
    await api('/api/online-customization', {
      method: 'POST',
      body: JSON.stringify({ customization: state.onlineCustom })
    });
    toast('Personalizacao Online salva com sucesso!', 'success');
  } catch (err) {
    toast('Erro ao salvar: ' + (err.message || String(err)), 'error');
  }
}

function resetOnlineCustomization() {
  state.onlineCustom = JSON.parse(JSON.stringify(ONLINE_CUSTOM_DEFAULTS));
  applyOnlineCustomToControls();
  renderOnlinePages();
  renderOnlinePreview();
  toast('Personalizacao redefinida para o padrao.');
}

function syncOnlineCustomFromControls() {
  var c = loadOnlineCustomFromStateOrDefaults();
  if (!c.brand) c.brand = {};
  if (!c.theme) c.theme = {};
  if (!c.layout) c.layout = {};

  var el = function(id) { return document.getElementById(id); };

  c.brand.name = (el('onlineBrandName') && el('onlineBrandName').value) || c.brand.name || 'BI WA';
  c.brand.subtitle = (el('onlineBrandSubtitle') && el('onlineBrandSubtitle').value) || c.brand.subtitle || 'Portal de dashboards';
  c.brand.subtitleFontSize = Math.max(8, Math.min(32, Number(el('onlineBrandSubtitleFontSize') && el('onlineBrandSubtitleFontSize').value) || Number(c.brand.subtitleFontSize) || 12));
  if (el('onlineBrandLogo')) c.brand.logo = String(el('onlineBrandLogo').value || '').trim();

  c.theme.primaryColor = (el('onlinePrimaryColor') && el('onlinePrimaryColor').value) || c.theme.primaryColor;
  c.theme.bgColor = (el('onlineBgColor') && el('onlineBgColor').value) || c.theme.bgColor;
  c.theme.sidebarBg = (el('onlineSidebarBg') && el('onlineSidebarBg').value) || c.theme.sidebarBg;
  c.theme.sidebarText = (el('onlineSidebarText') && el('onlineSidebarText').value) || c.theme.sidebarText;
  c.theme.sidebarActiveBg = (el('onlineSidebarActiveBg') && el('onlineSidebarActiveBg').value) || c.theme.sidebarActiveBg;
  c.theme.accentColor = (el('onlineAccentColor') && el('onlineAccentColor').value) || c.theme.accentColor;
  c.theme.headerBg = (el('onlineHeaderBg') && el('onlineHeaderBg').value) || c.theme.headerBg || c.theme.sidebarBg;
  c.theme.headerText = (el('onlineHeaderText') && el('onlineHeaderText').value) || c.theme.headerText || c.theme.sidebarText;
  c.theme.fontFamily = (el('onlineFontFamily') && el('onlineFontFamily').value) || c.theme.fontFamily;

  c.layout.showHeader = true;
  c.layout.headerTitle = (el('onlineHeaderTitle') && el('onlineHeaderTitle').value) || c.layout.headerTitle || 'BI WA Online';
  c.layout.headerFontFamily = (el('onlineHeaderFontFamily') && el('onlineHeaderFontFamily').value) || c.layout.headerFontFamily || 'inherit';
  c.layout.headerFontSize = Math.max(14, Math.min(36, Number(el('onlineHeaderFontSize') && el('onlineHeaderFontSize').value) || Number(c.layout.headerFontSize) || 23));
  var legacyHeaderBold = typeof c.layout.headerBold === 'boolean' ? c.layout.headerBold : c.layout.headerTitleStyle !== 'normal';
  c.layout.headerBold = el('onlineHeaderBold') ? el('onlineHeaderBold').checked : legacyHeaderBold;
  c.layout.headerItalic = el('onlineHeaderItalic') ? el('onlineHeaderItalic').checked : c.layout.headerItalic === true;
  c.layout.headerUnderline = el('onlineHeaderUnderline') ? el('onlineHeaderUnderline').checked : c.layout.headerUnderline === true;
  c.layout.headerTitleStyle = c.layout.headerBold ? 'bold' : 'normal';
  c.layout.showFooter = true;
  c.layout.footerText = c.layout.footerText || '© {year} BI WA';
  c.layout.sidebarWidth = Number(el('onlineSidebarWidth') && el('onlineSidebarWidth').value) || c.layout.sidebarWidth || 260;

  return c;
}

function applyOnlineCustomToControls() {
  var c = loadOnlineCustomFromStateOrDefaults();
  var el = function(id) { return document.getElementById(id); };
  var setVal = function(id, val) { var e = el(id); if (e && val !== undefined) e.value = val; };
  var setCheck = function(id, val) { var e = el(id); if (e) e.checked = Boolean(val); };

  setVal('onlineBrandName', c.brand && c.brand.name);
  setVal('onlineBrandSubtitle', c.brand && c.brand.subtitle);
  setVal('onlineBrandSubtitleFontSize', c.brand && c.brand.subtitleFontSize || 12);
  setVal('onlineBrandLogo', c.brand && c.brand.logo);
  setVal('onlinePrimaryColor', c.theme && c.theme.primaryColor);
  setVal('onlineBgColor', c.theme && c.theme.bgColor);
  setVal('onlineSidebarBg', c.theme && c.theme.sidebarBg);
  setVal('onlineSidebarText', c.theme && c.theme.sidebarText);
  setVal('onlineSidebarActiveBg', c.theme && c.theme.sidebarActiveBg);
  setVal('onlineAccentColor', c.theme && c.theme.accentColor);
  setVal('onlineHeaderBg', c.theme && c.theme.headerBg || c.theme && c.theme.sidebarBg);
  setVal('onlineHeaderText', c.theme && c.theme.headerText || c.theme && c.theme.sidebarText);
  setVal('onlineFontFamily', c.theme && c.theme.fontFamily);
  setVal('onlineHeaderTitle', c.layout && c.layout.headerTitle);
  setVal('onlineHeaderFontFamily', c.layout && c.layout.headerFontFamily || 'inherit');
  setVal('onlineHeaderFontSize', c.layout && c.layout.headerFontSize || 23);
  setCheck('onlineHeaderBold', c.layout && typeof c.layout.headerBold === 'boolean' ? c.layout.headerBold : !(c.layout && c.layout.headerTitleStyle === 'normal'));
  setCheck('onlineHeaderItalic', c.layout && c.layout.headerItalic === true);
  setCheck('onlineHeaderUnderline', c.layout && c.layout.headerUnderline === true);
  setVal('onlineFooterText', c.layout && c.layout.footerText);
  setVal('onlineSidebarWidth', c.layout && c.layout.sidebarWidth);
  var logoPreview = el('onlineBrandLogoPreview');
  if (logoPreview) {
    logoPreview.src = c.brand && c.brand.logo || '';
    logoPreview.hidden = !(c.brand && c.brand.logo);
  }
}

function addOnlinePage() {
  var labelEl = document.getElementById('onlinePageLabel');
  var iconEl = document.getElementById('onlinePageIcon');
  var reportEl = document.getElementById('onlinePageReport');
  var label = (labelEl && labelEl.value || '').trim();
  if (!label) { toast('Informe um nome para a pagina.', 'error'); return; }

  var c = loadOnlineCustomFromStateOrDefaults();
  if (!Array.isArray(c.pages)) c.pages = [];
  var maxOrder = c.pages.reduce(function(max, p) { return Math.max(max, p.order || 0); }, 0);
  c.pages.push({
    id: 'opg_' + Date.now(),
    label: label,
    icon: (iconEl && iconEl.value) || 'dashboard',
    reportId: (reportEl && reportEl.value) || '',
    order: maxOrder + 1
  });

  if (labelEl) labelEl.value = '';
  renderOnlinePages();
  renderOnlinePreview();
}

function removeOnlinePage(pageId) {
  var c = loadOnlineCustomFromStateOrDefaults();
  if (!Array.isArray(c.pages)) return;
  c.pages = c.pages.filter(function(p) { return p.id !== pageId; });
  // Reindex order
  c.pages.forEach(function(p, i) { p.order = i + 1; });
  renderOnlinePages();
  renderOnlinePreview();
}

function moveOnlinePage(pageId, direction) {
  var c = loadOnlineCustomFromStateOrDefaults();
  if (!Array.isArray(c.pages)) return;
  var idx = c.pages.findIndex(function(p) { return p.id === pageId; });
  if (idx < 0) return;
  var newIdx = idx + direction;
  if (newIdx < 0 || newIdx >= c.pages.length) return;
  var tmp = c.pages[idx];
  c.pages[idx] = c.pages[newIdx];
  c.pages[newIdx] = tmp;
  c.pages.forEach(function(p, i) { p.order = i + 1; });
  renderOnlinePages();
  renderOnlinePreview();
}

function getOnlineIconDefinition(icon) {
  var raw = String(icon || 'dashboard');
  var resolved = ONLINE_ICON_ALIASES[raw] || raw;
  return ONLINE_ICON_LIBRARY.find(function(item) { return item.id === resolved; }) || ONLINE_ICON_LIBRARY[0];
}

function getOnlineIconSvg(icon) {
  var definition = getOnlineIconDefinition(icon);
  return '<svg class="online-area-icon" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">' + definition.svg + '</svg>';
}

function defaultOnlineIconForReport(report) {
  var name = String(report && report.name || '').toLocaleLowerCase('pt-BR');
  if (/venda|fatur|receita/.test(name)) return 'sales';
  if (/finan|contáb|contab|caixa|custo/.test(name)) return 'finance';
  if (/admin/.test(name)) return 'administrative';
  if (/comercial/.test(name)) return 'commercial';
  if (/cliente|crm/.test(name)) return 'customers';
  if (/produto|catálogo|catalogo/.test(name)) return 'products';
  if (/estoque|inventário|inventario/.test(name)) return 'inventory';
  if (/logística|logistica|frota|entrega/.test(name)) return 'logistics';
  if (/compra|fornecedor/.test(name)) return 'purchasing';
  if (/opera|produção|producao/.test(name)) return 'operations';
  if (/rh|pessoal|colaborador/.test(name)) return 'hr';
  if (/marketing|campanha/.test(name)) return 'marketing';
  if (/meta|kpi|indicador/.test(name)) return 'goals';
  if (/agenda|calendário|calendario/.test(name)) return 'calendar';
  if (/atendimento|suporte/.test(name)) return 'support';
  if (/segurança|seguranca|auditoria/.test(name)) return 'security';
  if (/análise|analise|analytics/.test(name)) return 'analytics';
  if (/relatório|relatorio/.test(name)) return 'reports';
  return 'dashboard';
}

function ensureOnlineDashboardConfig(reportId) {
  var custom = loadOnlineCustomFromStateOrDefaults();
  if (!Array.isArray(custom.pages)) custom.pages = [];
  var id = String(reportId || '');
  var report = (state.reports || []).find(function(item) { return String(item.id) === id; });
  var config = custom.pages.find(function(item) { return String(item && item.reportId || '') === id; });
  if (!config) {
    var navigation = onlineNavigationItems(custom, { includeHidden: true });
    config = {
      id: 'online_report_' + id,
      reportId: id,
      label: String(report && report.name || 'Relatório'),
      icon: defaultOnlineIconForReport(report),
      order: navigation.length + 1
    };
    custom.pages.push(config);
  }
  if (!config.label) config.label = String(report && report.name || 'Relatório');
  if (!config.icon) config.icon = defaultOnlineIconForReport(report);
  return config;
}

function setOnlineDashboardIcon(reportId, icon) {
  var config = ensureOnlineDashboardConfig(reportId);
  config.icon = getOnlineIconDefinition(icon).id;
  onlineIconPickerReportId = '';
  onlineDashboardMenuReportId = '';
  renderOnlinePages();
  renderOnlinePreview();
  updateDashboardReportCardIcon(reportId, config.icon);
}

function renameOnlineDashboard(reportId, label) {
  var nextLabel = String(label || '').trim().slice(0, 60);
  if (!nextLabel) {
    toast('Informe um nome para o dashboard.', 'error');
    return false;
  }
  ensureOnlineDashboardConfig(reportId).label = nextLabel;
  onlineDashboardRenameReportId = '';
  onlineDashboardMenuReportId = '';
  renderOnlinePages();
  renderOnlinePreview();
  return true;
}

function setOnlineDashboardHidden(reportId, hidden) {
  var config = ensureOnlineDashboardConfig(reportId);
  config.hidden = Boolean(hidden);
  if (config.hidden && String(state.onlineActiveReportId || '') === String(reportId || '')) {
    state.onlineActiveReportId = '';
  }
  onlineDashboardMenuReportId = '';
  onlineDashboardRenameReportId = '';
  onlineIconPickerReportId = '';
  renderOnlinePages();
  renderOnlinePreview();
}

function reorderOnlineDashboards(sourceReportId, targetReportId, placeAfter) {
  var sourceId = String(sourceReportId || '');
  var targetId = String(targetReportId || '');
  if (!sourceId || !targetId || sourceId === targetId) return;
  var custom = loadOnlineCustomFromStateOrDefaults();
  var ids = onlineNavigationItems(custom, { includeHidden: true }).map(function(item) { return item.id; });
  var sourceIndex = ids.indexOf(sourceId);
  if (sourceIndex < 0) return;
  ids.splice(sourceIndex, 1);
  var targetIndex = ids.indexOf(targetId);
  if (targetIndex < 0) return;
  ids.splice(targetIndex + (placeAfter ? 1 : 0), 0, sourceId);
  ids.forEach(function(reportId, index) {
    ensureOnlineDashboardConfig(reportId).order = index + 1;
  });
  renderOnlinePages();
  renderOnlinePreview();
}

function bindOnlineDashboardNavigationEditor(listEl) {
  listEl.querySelectorAll('[data-online-dashboard-drag]').forEach(function(handle) {
    handle.addEventListener('dragstart', function(event) {
      onlineDashboardDragReportId = String(handle.dataset.onlineDashboardDrag || '');
      if (event.dataTransfer) {
        event.dataTransfer.effectAllowed = 'move';
        event.dataTransfer.setData('text/plain', onlineDashboardDragReportId);
      }
      var card = handle.closest('[data-online-dashboard-card]');
      if (card) card.classList.add('dragging');
    });
    handle.addEventListener('dragend', function() {
      onlineDashboardDragReportId = '';
      listEl.querySelectorAll('[data-online-dashboard-card]').forEach(function(card) {
        card.classList.remove('dragging', 'drag-over-before', 'drag-over-after');
      });
    });
  });
  listEl.querySelectorAll('[data-online-dashboard-card]').forEach(function(card) {
    card.addEventListener('dragover', function(event) {
      if (!onlineDashboardDragReportId || onlineDashboardDragReportId === String(card.dataset.onlineDashboardCard || '')) return;
      event.preventDefault();
      var rect = card.getBoundingClientRect();
      var after = event.clientY > rect.top + rect.height / 2;
      card.classList.toggle('drag-over-before', !after);
      card.classList.toggle('drag-over-after', after);
    });
    card.addEventListener('dragleave', function(event) {
      if (event.relatedTarget && card.contains(event.relatedTarget)) return;
      card.classList.remove('drag-over-before', 'drag-over-after');
    });
    card.addEventListener('drop', function(event) {
      event.preventDefault();
      var rect = card.getBoundingClientRect();
      var after = event.clientY > rect.top + rect.height / 2;
      var sourceId = onlineDashboardDragReportId || (event.dataTransfer && event.dataTransfer.getData('text/plain'));
      reorderOnlineDashboards(sourceId, card.dataset.onlineDashboardCard, after);
    });
  });
  listEl.querySelectorAll('[data-online-icon-picker]').forEach(function(button) {
    button.addEventListener('click', function() {
      var reportId = String(button.dataset.onlineIconPicker || '');
      onlineIconPickerReportId = onlineIconPickerReportId === reportId ? '' : reportId;
      onlineDashboardMenuReportId = '';
      onlineDashboardRenameReportId = '';
      renderOnlinePages();
    });
  });
  listEl.querySelectorAll('[data-online-dashboard-menu]').forEach(function(button) {
    button.addEventListener('click', function(event) {
      event.preventDefault();
      event.stopPropagation();
      var reportId = String(button.dataset.onlineDashboardMenu || '');
      onlineDashboardMenuReportId = onlineDashboardMenuReportId === reportId ? '' : reportId;
      onlineIconPickerReportId = '';
      onlineDashboardRenameReportId = '';
      renderOnlinePages();
    });
  });
  listEl.querySelectorAll('[data-online-menu-action="icon"]').forEach(function(button) {
    button.addEventListener('click', function(event) {
      event.stopPropagation();
      onlineIconPickerReportId = String(button.dataset.reportId || '');
      onlineDashboardMenuReportId = '';
      onlineDashboardRenameReportId = '';
      renderOnlinePages();
    });
  });
  listEl.querySelectorAll('[data-online-menu-action="rename"]').forEach(function(button) {
    button.addEventListener('click', function(event) {
      event.stopPropagation();
      onlineDashboardRenameReportId = String(button.dataset.reportId || '');
      onlineDashboardMenuReportId = '';
      onlineIconPickerReportId = '';
      renderOnlinePages();
      setTimeout(function() {
        var input = listEl.querySelector('[data-online-dashboard-rename-input]');
        if (input) { input.focus(); input.select(); }
      }, 0);
    });
  });
  listEl.querySelectorAll('[data-online-menu-action="hidden"]').forEach(function(button) {
    button.addEventListener('click', function(event) {
      event.stopPropagation();
      setOnlineDashboardHidden(button.dataset.reportId, button.getAttribute('aria-pressed') !== 'true');
    });
  });
  listEl.querySelectorAll('[data-online-dashboard-rename-save]').forEach(function(button) {
    button.addEventListener('click', function() {
      var reportId = button.dataset.onlineDashboardRenameSave;
      var input = listEl.querySelector('[data-online-dashboard-rename-input="' + CSS.escape(reportId) + '"]');
      renameOnlineDashboard(reportId, input && input.value);
    });
  });
  listEl.querySelectorAll('[data-online-dashboard-rename-cancel]').forEach(function(button) {
    button.addEventListener('click', function() {
      onlineDashboardRenameReportId = '';
      renderOnlinePages();
    });
  });
  listEl.querySelectorAll('[data-online-dashboard-rename-input]').forEach(function(input) {
    input.addEventListener('keydown', function(event) {
      if (event.key === 'Enter') {
        event.preventDefault();
        renameOnlineDashboard(input.dataset.onlineDashboardRenameInput, input.value);
      } else if (event.key === 'Escape') {
        onlineDashboardRenameReportId = '';
        renderOnlinePages();
      }
    });
  });
  listEl.querySelectorAll('[data-online-icon-choice]').forEach(function(button) {
    button.addEventListener('click', function() {
      setOnlineDashboardIcon(button.dataset.reportId, button.dataset.onlineIconChoice);
    });
  });
  if (document.documentElement.dataset.onlineDashboardMenuDismissBound !== '1') {
    document.documentElement.dataset.onlineDashboardMenuDismissBound = '1';
    document.addEventListener('click', function(event) {
      if (!onlineDashboardMenuReportId || event.target.closest('[data-online-dashboard-card]')) return;
      onlineDashboardMenuReportId = '';
      renderOnlinePages();
    });
    document.addEventListener('keydown', function(event) {
      if (event.key !== 'Escape' || (!onlineDashboardMenuReportId && !onlineDashboardRenameReportId && !onlineIconPickerReportId)) return;
      onlineDashboardMenuReportId = '';
      onlineDashboardRenameReportId = '';
      onlineIconPickerReportId = '';
      renderOnlinePages();
    });
  }
}

function renderOnlinePages() {
  var listEl = document.getElementById('onlinePagesList');
  if (!listEl) return;
  var navigation = onlineNavigationItems(loadOnlineCustomFromStateOrDefaults(), { includeHidden: true });
  if (!navigation.length) {
    listEl.innerHTML = '<div class="empty-state">Nenhum relatório criado. Os dashboards aparecerão aqui automaticamente.</div>';
    return;
  }
  listEl.innerHTML = navigation.map(function(item, index) {
    var pages = onlineReportPages(item.report).length;
    var pickerOpen = onlineIconPickerReportId === item.id;
    var menuOpen = onlineDashboardMenuReportId === item.id;
    var renameOpen = onlineDashboardRenameReportId === item.id;
    var hidden = Boolean(item.hidden);
    var selectedIcon = getOnlineIconDefinition(item.icon).id;
    return '<div class="online-dashboard-navigation-card' + (pickerOpen ? ' icon-picker-open' : '') + (menuOpen ? ' menu-open' : '') + (renameOpen ? ' rename-open' : '') + (hidden ? ' hidden-dashboard' : '') + '" data-online-dashboard-card="' + escapeHtml(item.id) + '">' +
      '<div class="online-dashboard-navigation-row">' +
        '<button type="button" class="online-dashboard-drag-handle" draggable="true" data-online-dashboard-drag="' + escapeHtml(item.id) + '" title="Arraste para alterar a ordem" aria-label="Arrastar ' + escapeHtml(item.label) + '"><span></span><span></span><span></span><span></span><span></span><span></span></button>' +
        '<span class="online-dashboard-order" title="Posição na navegação">' + (index + 1) + '</span>' +
        '<span class="online-dashboard-icon-preview">' + getOnlineIconSvg(item.icon) + '</span>' +
        '<span class="online-dashboard-copy"><span class="online-dashboard-title-row"><b>' + escapeHtml(item.label) + '</b>' + (hidden ? '<em>Oculto</em>' : '') + '</span><small>' + pages + ' página(s)</small></span>' +
        '<button type="button" class="online-dashboard-more" data-online-dashboard-menu="' + escapeHtml(item.id) + '" aria-expanded="' + (menuOpen ? 'true' : 'false') + '" aria-label="Mais opções para ' + escapeHtml(item.label) + '" title="Mais opções"><span></span><span></span><span></span></button>' +
      '</div>' +
      (menuOpen ? '<div class="online-dashboard-card-menu" role="menu">' +
        '<button type="button" class="online-dashboard-menu-action" data-online-menu-action="icon" data-report-id="' + escapeHtml(item.id) + '" role="menuitem"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 20h9"/><path d="M16.5 3.5a2.1 2.1 0 0 1 3 3L8 18l-4 1 1-4z"/></svg><span>Alterar ícone</span></button>' +
        '<button type="button" class="online-dashboard-menu-action" data-online-menu-action="rename" data-report-id="' + escapeHtml(item.id) + '" role="menuitem"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 20h4l11-11a2.8 2.8 0 0 0-4-4L4 16z"/><path d="m13.5 6.5 4 4"/></svg><span>Renomear dashboard</span></button>' +
        '<div class="online-dashboard-menu-divider"></div>' +
        '<button type="button" class="online-dashboard-menu-action online-dashboard-hidden-action" data-online-menu-action="hidden" data-report-id="' + escapeHtml(item.id) + '" aria-pressed="' + (hidden ? 'true' : 'false') + '" role="menuitem"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 3l18 18"/><path d="M10.6 10.7a2 2 0 0 0 2.7 2.7"/><path d="M9.9 4.2A10.6 10.6 0 0 1 12 4c5.5 0 9 5 9 8a8.2 8.2 0 0 1-2 3.6"/><path d="M6.6 6.6C4.3 8 3 10.2 3 12c0 3 3.5 8 9 8a9.8 9.8 0 0 0 3.4-.6"/></svg><span class="online-dashboard-menu-copy"><b>Ocultar dashboard</b><small>Ocultar para todos os usuários</small></span><i class="online-dashboard-switch" aria-hidden="true"></i></button>' +
      '</div>' : '') +
      (renameOpen ? '<div class="online-dashboard-rename-editor"><label>Nome no portal<input type="text" maxlength="60" value="' + escapeHtml(item.label) + '" data-online-dashboard-rename-input="' + escapeHtml(item.id) + '"></label><div class="online-dashboard-rename-actions"><button type="button" data-online-dashboard-rename-cancel="' + escapeHtml(item.id) + '">Cancelar</button><button type="button" class="primary" data-online-dashboard-rename-save="' + escapeHtml(item.id) + '">Salvar</button></div></div>' : '') +
      (pickerOpen ? '<div class="online-dashboard-icon-picker"><div class="online-dashboard-icon-picker-head"><b>Escolha uma área</b><small>Ícones padronizados do portal</small></div><div class="online-dashboard-icon-grid">' + ONLINE_ICON_LIBRARY.map(function(icon) { return '<button type="button" class="online-dashboard-icon-option' + (icon.id === selectedIcon ? ' selected' : '') + '" data-online-icon-choice="' + escapeHtml(icon.id) + '" data-report-id="' + escapeHtml(item.id) + '" title="' + escapeHtml(icon.label) + '">' + getOnlineIconSvg(icon.id) + '<span>' + escapeHtml(icon.label) + '</span></button>'; }).join('') + '</div></div>' : '') +
    '</div>';
  }).join('');
  bindOnlineDashboardNavigationEditor(listEl);
}

function renderOnlinePreview() {
  syncOnlineCustomFromControls();
  var c = state.onlineCustom;
  if (!c) return;
  var frame = document.getElementById('onlinePreviewFrame');
  if (!frame) return;
  var navigation = onlineNavigationItems(c);
  var first = navigation[0];
  var report = first && first.report;
  var pages = report ? onlineReportPages(report) : [normalizeReportPage({ id: 'page_1', name: 'Página 1' }, 0)];
  var resetIcon = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 11a8 8 0 1 1-2.34-5.66L20 7.68"/><path d="M20 3v4.68h-4.68"/></svg>';
  var filterIcon = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 5h18l-7 8v5l-4 2v-7z"/></svg>';
  var previewHeaderFontSize = Math.max(9, Math.round(Math.max(14, Math.min(36, Number(c.layout.headerFontSize) || 23)) * .65));
  var previewLegacyHeaderStyle = c.layout.headerTitleStyle;
  var previewHeaderBold = typeof c.layout.headerBold === 'boolean' ? c.layout.headerBold : previewLegacyHeaderStyle !== 'normal';
  var previewConfiguredFont = String(c.layout.headerFontFamily || 'inherit');
  var previewHeaderFont = previewConfiguredFont === 'inherit' ? c.theme.fontFamily : previewConfiguredFont;
  frame.style.fontFamily = c.theme.fontFamily;
  frame.style.background = c.theme.bgColor;
  frame.innerHTML = '<div class="online-preview-portal-sidebar" style="background:' + escapeHtml(c.theme.sidebarBg) + ';color:' + escapeHtml(c.theme.sidebarText) + ';width:' + Math.max(150, Math.min(230, Number(c.layout.sidebarWidth || 260) * .72)) + 'px">' +
    '<div class="online-preview-portal-brand"><strong>' + escapeHtml(c.brand.name || 'BI WA') + '</strong><span>☰</span></div>' +
    '<div class="online-preview-portal-logo">' + (c.brand.logo ? '<img src="' + escapeHtml(c.brand.logo) + '" alt="Logo" />' : '<span>Logo</span>') + '</div>' +
    '<div class="online-preview-portal-subtitle" style="font-size:' + Math.max(7, Math.round((Number(c.brand.subtitleFontSize) || 12) * .67)) + 'px">' + escapeHtml(c.brand.subtitle || 'Portal de dashboards') + '</div>' +
    '<div class="online-preview-portal-nav">' + (navigation.length ? navigation.map(function(item, index) { return '<div class="online-preview-nav-item' + (index === 0 ? ' active' : '') + '" style="' + (index === 0 ? 'background:' + escapeHtml(c.theme.sidebarActiveBg) : '') + '"><span class="online-preview-nav-icon">' + getOnlineIconSvg(item.icon) + '</span><span>' + escapeHtml(item.label) + '</span></div>'; }).join('') : '<small>Nenhum dashboard</small>') + '</div>' +
    '<div class="online-preview-portal-powered">Powered by WA Soluções</div></div>' +
    '<div class="online-preview-portal-main"><div class="online-preview-portal-header" style="background:' + escapeHtml(c.theme.headerBg || c.theme.sidebarBg) + ';color:' + escapeHtml(c.theme.headerText || c.theme.sidebarText) + '"><strong class="online-preview-portal-title" style="font-family:' + escapeHtml(previewHeaderFont) + ';font-size:' + previewHeaderFontSize + 'px;font-weight:' + (previewHeaderBold ? 900 : 600) + ';font-style:' + (c.layout.headerItalic === true ? 'italic' : 'normal') + ';text-decoration:' + (c.layout.headerUnderline === true ? 'underline' : 'none') + '">' + escapeHtml(first && first.label || report && report.name || 'DASHBOARDS') + '</strong><div class="online-preview-portal-actions"><button type="button" class="online-preview-portal-reset" tabindex="-1" aria-hidden="true">' + resetIcon + '</button><button type="button" class="online-preview-portal-filter" tabindex="-1" aria-hidden="true">' + filterIcon + '<span>Filtros</span></button><label class="online-preview-portal-page"><span>Página</span><select tabindex="-1">' + pages.map(function(page) { return '<option>' + escapeHtml(page.name) + '</option>'; }).join('') + '</select></label><b class="online-preview-portal-status">Online - aguardando</b><span class="online-preview-user-avatar">' + escapeHtml(userAvatarInitials()) + '</span></div></div>' +
    '<div class="online-preview-portal-filters"><strong>Filtros aplicados:</strong><span>período atual</span></div><div class="online-preview-content"><div class="online-preview-placeholder"><svg viewBox="0 0 24 24" width="48" height="48" fill="none" stroke="currentColor" stroke-width="1.5" opacity="0.3"><circle cx="12" cy="12" r="10"/><path d="M2 12h20"/><path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"/></svg><p>Área de Dashboards</p><small>O relatório selecionado aparecerá aqui</small></div></div>' +
    '<div class="online-preview-footer">' + escapeHtml(onlineFooterText(c.layout)) + '</div></div>';
}

function readOnlineLogoFile(file) {
  if (!file) return;
  if (!String(file.type || '').startsWith('image/')) return toast('Selecione um arquivo de imagem.', 'error');
  if (file.size > 700 * 1024) return toast('A logo deve ter no máximo 700 KB.', 'error');
  var reader = new FileReader();
  reader.onload = function() {
    var hidden = document.getElementById('onlineBrandLogo');
    if (hidden) hidden.value = String(reader.result || '');
    var custom = loadOnlineCustomFromStateOrDefaults();
    custom.brand = custom.brand || {};
    custom.brand.logo = String(reader.result || '');
    applyOnlineCustomToControls();
    renderOnlinePreview();
  };
  reader.onerror = function() { toast('Não foi possível importar a logo.', 'error'); };
  reader.readAsDataURL(file);
}

function populateOnlineReportSelect() {
  var sel = document.getElementById('onlinePageReport');
  if (!sel) return;
  var reports = Array.isArray(state.reports) ? state.reports : [];
  sel.innerHTML = '<option value="">Sem relatorio vinculado</option>' +
    reports.map(function(r) {
      return '<option value="' + escapeHtml(r.id) + '">' + escapeHtml(r.name || r.id) + '</option>';
    }).join('');
}

function setupOnlineBuilderEvents() {
  var el = function(id) { return document.getElementById(id); };
  var layout = el('onlineBuilderLayout');
  if (layout && layout.dataset.onlineBuilderEventsBound === '1') return;
  if (layout) layout.dataset.onlineBuilderEventsBound = '1';

  if (el('saveOnlineCustomBtn')) {
    el('saveOnlineCustomBtn').addEventListener('click', function() { saveOnlineCustomization(); });
  }
  if (el('resetOnlineCustomBtn')) {
    el('resetOnlineCustomBtn').addEventListener('click', function() { resetOnlineCustomization(); });
  }
  if (el('previewOnlineBtn2')) {
    el('previewOnlineBtn2').addEventListener('click', async function() {
      await saveOnlineCustomization();
      await openOnlinePortalPreview(state.onlineActiveReportId, 'onlineTab');
    });
  }
  if (el('addOnlinePageBtn')) {
    el('addOnlinePageBtn').addEventListener('click', function() { addOnlinePage(); });
  }
  if (el('onlineBrandLogoFile')) {
    el('onlineBrandLogoFile').addEventListener('change', function() { readOnlineLogoFile(el('onlineBrandLogoFile').files && el('onlineBrandLogoFile').files[0]); });
  }
  if (el('onlineBrandLogoRemove')) {
    el('onlineBrandLogoRemove').addEventListener('click', function() {
      if (el('onlineBrandLogo')) el('onlineBrandLogo').value = '';
      if (el('onlineBrandLogoFile')) el('onlineBrandLogoFile').value = '';
      syncOnlineCustomFromControls();
      applyOnlineCustomToControls();
      renderOnlinePreview();
    });
  }

  // Live preview on color/input changes
  var liveInputs = [
    'onlinePrimaryColor','onlineBgColor','onlineSidebarBg','onlineSidebarText',
    'onlineSidebarActiveBg','onlineAccentColor','onlineHeaderBg','onlineHeaderText','onlineHeaderFontFamily','onlineHeaderFontSize',
    'onlineHeaderBold','onlineHeaderItalic','onlineHeaderUnderline',
    'onlineFontFamily','onlineBrandName','onlineBrandSubtitle','onlineBrandSubtitleFontSize','onlineHeaderTitle',
    'onlineSidebarWidth'
  ];
  liveInputs.forEach(function(id) {
    var input = el(id);
    if (input) {
      input.addEventListener('input', function() { renderOnlinePreview(); });
      input.addEventListener('change', function() { renderOnlinePreview(); });
    }
  });
}

async function renderOnlineBuilder() {
  var layout = document.getElementById('onlineBuilderLayout');
  if (!layout) return;

  await loadOnlineCustomization();
  populateOnlineReportSelect();
  applyOnlineCustomToControls();
  renderOnlinePages();
  renderOnlinePreview();
  setupOnlineBuilderEvents();
}

boot().catch((err) => {
  toast(err.message, 'error');
  console.error(err);
});
